-- Check whether a CFrame is inside safe playable map bounds for local recovery (from oyee hoye.lua)
local function isSafePlayableCF(cf)
    if not cf then return false end
    local pos = cf.Position
    if pos.X ~= pos.X or pos.Y ~= pos.Y or pos.Z ~= pos.Z then return false end
    if math.abs(pos.X) == math.huge or math.abs(pos.Y) == math.huge or math.abs(pos.Z) == math.huge then return false end
    local voidFloor = OriginalFPDH + 28
    if pos.Y <= voidFloor or pos.Y > 60000 or pos.Y < -10000 then return false end
    if math.abs(pos.Y - 85000) < 5000 then return false end
    if pos.Magnitude > 150000 then return false end
    return true
end

-- Distinguish true lethal void / Reanim & Limb-Remover dumps from hidden underground rooms or skyboxes!
-- Rejects FallenPartsDestroyHeight kill zone, sky-dumps, NaN/Inf, and extreme fling velocities.
local function isLethalVoidCF(cf, velocity)
    if not cf then return true end
    local pos = cf.Position
    if pos.X ~= pos.X or pos.Y ~= pos.Y or pos.Z ~= pos.Z then return true end
    if math.abs(pos.X) == math.huge or math.abs(pos.Y) == math.huge or math.abs(pos.Z) == math.huge then return true end
    if pos.Magnitude > 150000 or pos.Y > 60000 or pos.Y < -10000 then return true end
    if math.abs(pos.Y - 85000) < 5000 then return true end
    local vy = velocity and velocity.Y or 0
    if velocity then
        if velocity.X ~= velocity.X or velocity.Y ~= velocity.Y or velocity.Z ~= velocity.Z then return true end
        if velocity.Magnitude > 750 or vy < -220 then return true end
    end
    if pos.Y <= (OriginalFPDH + 25) then return true end
    if pos.Y <= (OriginalFPDH + 90) and vy < -45 then return true end
    return false
end

local findFallbackSafeCF, WeldSeekingTarget
WeldSeekingTarget = false
do
    local CachedSpawnLocation = nil
    local LastSpawnScanTick = 0
    -- Seed LastKnownSafeCF immediately on startup & respawn so we never lack a valid origin CFrame
    pcall(function()
        local ch = LP and LP.Character
        local rt = ch and ch:FindFirstChild("HumanoidRootPart")
        if rt and isSafePlayableCF(rt.CFrame) then
            LastKnownSafeCF = rt.CFrame
        end
        if LP then
            LP.CharacterAdded:Connect(function(newChar)
                -- Immediately clear stale pre-respawn snap caches so Anti-Bring / Anti-Fling NEVER rubberband you back!
                WeldSeekingTarget = false
                deflectBusy = false
                pcall(function() LP.ReplicationFocus = nil end)
                if moveState then moveState.lastTeleportTick = tick() end
                if Anti then
                    if Anti.Bring then
                        Anti.Bring.lastCF = nil
                        Anti.Bring.lastChar = newChar
                    end
                    if Anti.FlingShield then
                        Anti.FlingShield.preStepCF = nil
                        Anti.FlingShield.lastChar = newChar
                    end
                end
                task.spawn(function()
                    local r = newChar:WaitForChild("HumanoidRootPart", 4)
                    local h = newChar:FindFirstChildOfClass("Humanoid") or newChar:WaitForChild("Humanoid", 4)
                    if moveState then moveState.lastTeleportTick = tick() end
                    if r and r.Parent then
                        if not (OwnerAdminState and OwnerAdminState.isFrozenByOwner) then
                            for _, bp in ipairs(newChar:GetDescendants()) do
                                if bp:IsA("BasePart") and bp.Anchored then
                                    pcall(function() bp.Anchored = false end)
                                end
                            end
                            if sethiddenproperty then
                                pcall(function() sethiddenproperty(r, "PhysicsRepRootPart", nil) end)
                                pcall(function() sethiddenproperty(r, "PhysicsRepRootRef", nil) end)
                            end
                            pcall(function()
                                r.AssemblyLinearVelocity = Vector3.zero
                                r.AssemblyAngularVelocity = Vector3.zero
                            end)
                        end
                        if isSafePlayableCF(r.CFrame) then
                            LastKnownSafeCF = r.CFrame
                            if Anti and Anti.Bring then Anti.Bring.lastCF = r.CFrame; Anti.Bring.lastChar = newChar end
                            if Anti and Anti.FlingShield then Anti.FlingShield.preStepCF = r.CFrame; Anti.FlingShield.lastChar = newChar end
                        end
                    end
                    if h and h.Parent and not (OwnerAdminState and OwnerAdminState.isFrozenByOwner) then
                        pcall(function()
                            h.PlatformStand = false
                            h.Sit = false
                            h.AutoRotate = true
                            if h.Health > 0 then
                                h:ChangeState(Enum.HumanoidStateType.GettingUp)
                                h:ChangeState(Enum.HumanoidStateType.Running)
                            end
                        end)
                    end
                end)
            end)
        end
    end)
    findFallbackSafeCF = function()
        if isSafePlayableCF(LastKnownSafeCF) then
            return LastKnownSafeCF
        end
        local myRoot = LP and LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
        if myRoot and isSafePlayableCF(myRoot.CFrame) then
            return myRoot.CFrame
        end
        if not (CachedSpawnLocation and CachedSpawnLocation.Parent) and (tick() - LastSpawnScanTick > 15.0) then
            LastSpawnScanTick = tick()
            CachedSpawnLocation = workspace:FindFirstChildWhichIsA("SpawnLocation", true)
        end
        local spawnPart = CachedSpawnLocation
        if spawnPart and spawnPart.Parent and isSafePlayableCF(spawnPart.CFrame) then
            return spawnPart.CFrame + Vector3.new(0, 4, 0)
        end
        -- NEVER fallback to a random server player's CFrame (which caused unexpected teleports to random players!)
        return CFrame.new(0, 35, 0)
    end
end

local Anti, moveState, AnimCopySys, EmoteHub, RewindSys, CocaSkyDestroyer, hookTargetRespawn, removeOverheadTagForUser, updateOverheadNameTags
local recoverCharacterState, safeReturnFromVoid, syncAllActiveIndicators

local StateManager = {}

function StateManager:StopAllAnimations()
    for _, track in ipairs(PlayedAnims) do
        pcall(function() track:Stop(0) end)
        pcall(function() track:Destroy() end)
    end
    PlayedAnims = {}
end

function StateManager:ResetPhysics(character)
    if not character then return end
    local isReanimActive = (_G.CocaSkyDestroyer and (_G.CocaSkyDestroyer.isAnyActive() or _G.CocaSkyDestroyer.is_reanimated()))
        or (_G._AngoorZenApi and type(_G._AngoorZenApi.is_reanimated) == "function" and _G._AngoorZenApi.is_reanimated())
        or (_G._reanimAPI and type(_G._reanimAPI.is_reanimated) == "function" and _G._reanimAPI.is_reanimated())
    local activeRealChar = (isReanimActive and _G._AngoorZenApi and type(_G._AngoorZenApi.get_real_character) == "function" and _G._AngoorZenApi.get_real_character())
        or (isReanimActive and _G.CocaSkyDestroyer and type(_G.CocaSkyDestroyer.get_real_character) == "function" and _G.CocaSkyDestroyer.get_real_character())
        or nil
    if isReanimActive and activeRealChar and character == activeRealChar then
        if LP and LP.Character and LP.Character ~= activeRealChar then
            character = LP.Character
        else
            return
        end
    end
    local root = character:FindFirstChild("HumanoidRootPart")
    if root then
        if sethiddenproperty then
            pcall(function() sethiddenproperty(root, "PhysicsRepRootPart", nil) end)
            pcall(function() sethiddenproperty(root, "PhysicsRepRootRef", nil) end)
        end
        root.Anchored = false
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
    end
    pcall(function() LP.ReplicationFocus = nil end)
    local keepNoclip = (moveState and moveState.noclip) == true
    local keepNoTouch = (Anti and Anti.Kill and Anti.Kill.enabled) == true
    local hiddenMap = type(_G.hiddenBodyParts) == "table" and _G.hiddenBodyParts or nil
    for _, part in ipairs(character:GetDescendants()) do
        if part:IsA("BasePart") then
            part.Anchored = false
            part.Massless = false
            part.CanTouch = not keepNoTouch
            part.CanQuery = true
            pcall(function() part.CustomPhysicalProperties = nil end)
            if not isReanimActive and not (moveState and moveState.Vanish and moveState.Vanish.selfActive) then
                pcall(function() part.LocalTransparencyModifier = 0 end)
                if part.Name ~= "HumanoidRootPart" and not (hiddenMap and hiddenMap[part.Name]) then
                    if part.Transparency >= 0.95 and (
                        part.Name == "Head" or part.Name == "Torso" or part.Name == "UpperTorso" or part.Name == "LowerTorso"
                        or part.Name:find("Arm") or part.Name:find("Hand") or part.Name:find("Leg") or part.Name:find("Foot")
                        or part.Name == "Handle"
                    ) then
                        pcall(function() part.Transparency = 0 end)
                    end
                end
            end
            if part.Name == "HumanoidRootPart" or part.Name == "Torso" or part.Name == "UpperTorso" or part.Name == "LowerTorso" or part.Name == "Head" then
                part.CanCollide = not keepNoclip
            end
        elseif part:IsA("Decal") and not isReanimActive and not (moveState and moveState.Vanish and moveState.Vanish.selfActive) then
            if part.Name == "face" and part.Transparency >= 0.95 then
                pcall(function() part.Transparency = 0 end)
            end
        elseif part:IsA("Motor6D") and not isReanimActive then
            pcall(function() part.Enabled = true end)
        end
    end
end

function StateManager:StopFling(skipReturn)
    local wasActive = FlingActive
    local savedOrigin = FlingOriginCF
    if FlingConn then FlingConn:Disconnect(); FlingConn = nil end
    if self.FlingStepConn then self.FlingStepConn:Disconnect(); self.FlingStepConn = nil end
    if LP.Character then
        local myRoot = LP.Character:FindFirstChild("HumanoidRootPart")
        if myRoot and sethiddenproperty then
            pcall(function() sethiddenproperty(myRoot, "PhysicsRepRootPart", nil) end)
            pcall(function() sethiddenproperty(myRoot, "PhysicsRepRootRef", nil) end)
        end
        for _, part in ipairs(LP.Character:GetDescendants()) do
            if part:IsA("BasePart") then
                pcall(function() part.CustomPhysicalProperties = nil end)
                pcall(function() part.LocalTransparencyModifier = 0 end)
            end
        end
    end
    pcall(function() LP.ReplicationFocus = nil end)
    FlingActive = false
    FlingOriginCF = nil
    if FlingSidePanel then FlingSidePanel.Visible = false end
    local currentCam = workspace.CurrentCamera
    if currentCam and (FlingCamType or FlingCamSubject) then
        pcall(function()
            currentCam.CameraType = FlingCamType or Enum.CameraType.Custom
            local myHum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
            currentCam.CameraSubject = myHum or FlingCamSubject
        end)
    end
    FlingCamType = nil
    FlingCamSubject = nil
    FlingCamCF = nil
    if wasActive and not skipReturn and LP.Character then
        LastVoidActionEnd = tick()
        safeReturnFromVoid(LP.Character, savedOrigin)
    elseif wasActive and skipReturn and LP.Character then
        self:ResetPhysics(LP.Character)
    end
    if syncAllActiveIndicators then pcall(syncAllActiveIndicators) end
end

function StateManager:Cleanup(keepTarget, switchingWeld)
    if moveState and moveState.Vanish and moveState.Vanish.selfActive then
        pcall(function() moveState.Vanish:StopSelfVanish(true) end)
    end
    if _G.CocaBangActive and type(_G.stopCocaBangLock) == "function" then
        pcall(_G.stopCocaBangLock)
    end
    if _G.CocaCopierActive and type(_G.stopCocaCopier) == "function" then
        pcall(_G.stopCocaCopier)
    end
    if RewindSys and RewindSys.rewinding and (RewindSys.Stop or RewindSys.StopRewind) then
        pcall(function() (RewindSys.Stop or RewindSys.StopRewind)(RewindSys) end)
    end
    if moveState and (moveState.fly or moveState.flyLanding) and moveState.stopFlyImmediate then
        pcall(moveState.stopFlyImmediate)
    end
    if CurrentWeld then
        pcall(function() CurrentWeld:Destroy(switchingWeld) end)
        CurrentWeld = nil
    end
    self:StopAllAnimations()
    self:StopFling(switchingWeld)
    if OriginalCameraSubject then
        pcall(function()
            local currentCam = workspace.CurrentCamera
            if currentCam then
                local myHum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
                currentCam.CameraSubject = myHum or OriginalCameraSubject
                currentCam.CameraType = Enum.CameraType.Custom
            end
        end)
        OriginalCameraSubject = nil
    end
    if LP.Character and not switchingWeld then
        self:ResetPhysics(LP.Character)
        local root = LP.Character:FindFirstChild("HumanoidRootPart")
        if root and not isSafePlayableCF(root.CFrame) then
            safeReturnFromVoid(LP.Character, LastKnownSafeCF)
        else
            recoverCharacterState(LP.Character, root and root.CFrame or LastKnownSafeCF)
        end
    end
    if not keepTarget then CurrentTarget = nil end
end

local function forcePhysicsState(hum)
    if not hum then return end
    pcall(function()
        if not hum:GetStateEnabled(Enum.HumanoidStateType.Physics) then
            hum:SetStateEnabled(Enum.HumanoidStateType.Physics, true)
        end
        if hum:GetState() ~= Enum.HumanoidStateType.Physics then
            hum:ChangeState(Enum.HumanoidStateType.Physics)
        end
    end)
end

local loadPlayableAnim, resolveCatalogOrAnimUri
do
    local ANIM_VERIFY_TIME = 0.10
    local ANIM_MAX_ATTEMPTS = 2
    local ResolvedCatalogAnimCache = {}

    resolveCatalogOrAnimUri = function(cleanDigits)
        if cleanDigits == "" then return nil end
        if ResolvedCatalogAnimCache[cleanDigits] then
            return ResolvedCatalogAnimCache[cleanDigits]
        end
        pcall(function()
            if typeof(game.GetObjects) == "function" then
                local objs = game:GetObjects("rbxassetid://" .. cleanDigits)
                if objs and #objs > 0 then
                    local first = objs[1]
                    if first:IsA("Animation") and first.AnimationId ~= "" then
                        ResolvedCatalogAnimCache[cleanDigits] = first.AnimationId
                    elseif first:IsA("KeyframeSequence") then
                        pcall(function()
                            local ksp = game:GetService("KeyframeSequenceProvider")
                            local hashUri = ksp and ksp:RegisterKeyframeSequence(first)
                            if hashUri and tostring(hashUri) ~= "" then
                                ResolvedCatalogAnimCache[cleanDigits] = tostring(hashUri)
                            end
                        end)
                    else
                        local innerAnim = first:FindFirstChildWhichIsA("Animation", true)
                        if innerAnim and innerAnim.AnimationId ~= "" then
                            ResolvedCatalogAnimCache[cleanDigits] = innerAnim.AnimationId
                        else
                            local innerKfs = first:FindFirstChildWhichIsA("KeyframeSequence", true)
                            if innerKfs then
                                pcall(function()
                                    local ksp = game:GetService("KeyframeSequenceProvider")
                                    local hashUri = ksp and ksp:RegisterKeyframeSequence(innerKfs)
                                    if hashUri and tostring(hashUri) ~= "" then
                                        ResolvedCatalogAnimCache[cleanDigits] = tostring(hashUri)
                                    end
                                end)
                            else
                                for _, desc in ipairs(first:GetDescendants()) do
                                    if (desc:IsA("StringValue") or desc:IsA("NumberValue") or desc:IsA("IntValue")) and tostring(desc.Value):find("%d%d%d%d%d+") then
                                        local digits = tostring(desc.Value):match("(%d%d%d%d%d+)")
                                        if digits then
                                            ResolvedCatalogAnimCache[cleanDigits] = "rbxassetid://" .. digits
                                            break
                                        end
                                    end
                                end
                            end
                        end
                    end
                    pcall(function() first:Destroy() end)
                end
            end
        end)
        if not ResolvedCatalogAnimCache[cleanDigits] then
            ResolvedCatalogAnimCache[cleanDigits] = "rbxassetid://" .. cleanDigits
        end
        return ResolvedCatalogAnimCache[cleanDigits]
    end

    -- Pre-warm Wall Rizz Pose (90735295463164), Bang (116235062592344), FF LOL (129709531895539) & FF Push Up (73630423562709) for 0.00ms instant weld playback
    task.spawn(function()
        pcall(resolveCatalogOrAnimUri, "90735295463164")
        pcall(resolveCatalogOrAnimUri, "116235062592344")
        pcall(resolveCatalogOrAnimUri, "129709531895539")
        pcall(resolveCatalogOrAnimUri, "73630423562709")
        -- Pre-warm Roblox Catalog Poop Emotes & Goon Emote for 0.00ms instant weld playback
        pcall(resolveCatalogOrAnimUri, "110110691026962")
        pcall(resolveCatalogOrAnimUri, "138645486924614")
        pcall(resolveCatalogOrAnimUri, "81414049491981")
        pcall(resolveCatalogOrAnimUri, "136828069054505")
        pcall(resolveCatalogOrAnimUri, "98982064034152")
        pcall(resolveCatalogOrAnimUri, "124127012123232")
    end)

    local function tryPlayOnce(Animator, animId, hum, priority, verifyPlayable)
        local cleanDigits = tostring(animId or ""):gsub("%D", "")
        if cleanDigits == "" then return nil, nil, false, nil end
        local resolvedUri = resolveCatalogOrAnimUri(cleanDigits) or ("rbxassetid://" .. cleanDigits)
        local anim = Instance.new("Animation")
        anim.AnimationId = resolvedUri
        local okLoad, track = pcall(function() return Animator:LoadAnimation(anim) end)
        if (not okLoad or not track) and resolvedUri ~= ("rbxassetid://" .. cleanDigits) then
            anim.AnimationId = "rbxassetid://" .. cleanDigits
            okLoad, track = pcall(function() return Animator:LoadAnimation(anim) end)
        end
        if not okLoad or not track then
            pcall(function() anim:Destroy() end)
            return nil, nil, false, nil
        end
        local pri = priority or Enum.AnimationPriority.Action4
        pcall(function() track.Priority = pri end)
        pcall(function() track.Looped = true end)
        pcall(function() track:AdjustSpeed(1) end)
        forcePhysicsState(hum)
        local okPlay = pcall(function() track:Play(0, 1.0, 1.0) end)
        if not okPlay then
            pcall(function() track:Stop(0) end)
            pcall(function() track:Destroy() end)
            pcall(function() anim:Destroy() end)
            return nil, nil, false, nil
        end
        if verifyPlayable then
            local len = 0
            pcall(function() len = track.Length or 0 end)
            if len <= 0 then
                local t0 = os.clock()
                while (os.clock() - t0) < ANIM_VERIFY_TIME do
                    RunService.Heartbeat:Wait()
                    local stillPlaying = false
                    pcall(function()
                        len = track.Length or 0
                        stillPlaying = track.IsPlaying
                    end)
                    if len > 0 then break end
                    if not stillPlaying then break end
                end
            end
            if len <= 0 then
                pcall(function() track:Stop(0) end)
                pcall(function() track:Destroy() end)
                pcall(function() anim:Destroy() end)
                return nil, nil, false, nil
            end
        end
        return track, anim, true, cleanDigits
    end

    loadPlayableAnim = function(Animator, animId, fallbacks, hum, priority)
        if not Animator or not animId then return nil, nil, nil end
        local cands = {}
        local seen = {}
        local function addCand(v)
            local s = tostring(v or ""):gsub("%D", "")
            if s ~= "" and not seen[s] then
                seen[s] = true
                cands[#cands + 1] = s
            end
        end
        addCand(animId)
        for _, f in ipairs(fallbacks or {}) do addCand(f) end
        local totalCands = #cands
        for idx, id in ipairs(cands) do
            -- Verify track.Length > 0 whenever fallback candidates exist so unplayable catalog/rig IDs automatically fall back!
            local shouldVerify = (totalCands > 1) and (idx < totalCands)
            for attempt = 1, (shouldVerify and 1 or ANIM_MAX_ATTEMPTS) do
                local track, anim, ok, cleanId = tryPlayOnce(Animator, id, hum, priority, shouldVerify)
                if ok then return track, anim, cleanId end
                if anim then pcall(function() anim:Destroy() end) end
                if attempt < ANIM_MAX_ATTEMPTS and not shouldVerify then RunService.Heartbeat:Wait() end
            end
        end
        return nil, nil, nil
    end
end

local AnimateWasDisabled = false

local function stopDefaultTracks(c)
    local hum = c and c:FindFirstChildOfClass("Humanoid")
    if not hum then return end
    local animator = hum:FindFirstChildOfClass("Animator")
    if animator then
        local ok, tracks = pcall(function() return animator:GetPlayingAnimationTracks() end)
        if ok and tracks then
            for _, t in ipairs(tracks) do
                if not IsCocoBeaconTrack[t] then
                    pcall(function() t:Stop(0) end); pcall(function() t:Destroy() end)
                end
            end
        end
    end
end

local function killAnimate(c)
    if not c then return end
    local animate = c:FindFirstChild("Animate")
    if animate and not animate.Disabled then
        animate.Disabled = true
        AnimateWasDisabled = true
    end
    stopDefaultTracks(c)
end

local function restoreAnimate(c)
    if not AnimateWasDisabled then return end
    if c then
        local animate = c:FindFirstChild("Animate")
        if animate then animate.Disabled = false end
    end
    AnimateWasDisabled = false
end

recoverCharacterState = function(char, safeCF)
    local isReanimActive = (_G.CocaSkyDestroyer and (_G.CocaSkyDestroyer.isAnyActive() or _G.CocaSkyDestroyer.is_reanimated()))
        or (_G._AngoorZenApi and type(_G._AngoorZenApi.is_reanimated) == "function" and _G._AngoorZenApi.is_reanimated())
        or (_G._reanimAPI and type(_G._reanimAPI.is_reanimated) == "function" and _G._reanimAPI.is_reanimated())
    local activeRealChar = (isReanimActive and _G._AngoorZenApi and type(_G._AngoorZenApi.get_real_character) == "function" and _G._AngoorZenApi.get_real_character())
        or (isReanimActive and _G.CocaSkyDestroyer and type(_G.CocaSkyDestroyer.get_real_character) == "function" and _G.CocaSkyDestroyer.get_real_character())
        or nil
    char = char or (LP and LP.Character)
    if isReanimActive and activeRealChar and char == activeRealChar then
        if LP and LP.Character and LP.Character ~= activeRealChar then
            char = LP.Character
        else
            return
        end
    end
    if not char then return end
    local isReanimClone = isReanimActive and (char == LP.Character or char.Name == "CocaReanimation" or char.Name == "ReanimationClone")
    local root = char:FindFirstChild("HumanoidRootPart")
    local hum  = char:FindFirstChildOfClass("Humanoid")
    pcall(function() LP.ReplicationFocus = nil end)
    if root then
        if sethiddenproperty then
            pcall(function() sethiddenproperty(root, "PhysicsRepRootPart", nil) end)
            pcall(function() sethiddenproperty(root, "PhysicsRepRootRef", nil) end)
        end
        root.Anchored = false
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero

        local targetCF = nil
        if isSafePlayableCF(safeCF) then
            targetCF = safeCF
        elseif isSafePlayableCF(root.CFrame) then
            targetCF = root.CFrame
        else
            targetCF = findFallbackSafeCF()
        end

        if targetCF then
            local pos = targetCF.Position
            local _, yYaw, _ = targetCF:ToEulerAnglesYXZ()
            local uprightCF = CFrame.new(pos) * CFrame.Angles(0, yYaw, 0)
            root.CFrame = uprightCF
            if isReanimActive and _G._AngoorZenApi and type(_G._AngoorZenApi.sync_now) == "function" then
                pcall(_G._AngoorZenApi.sync_now, true)
            elseif isReanimActive and _G.CocaSkyDestroyer and type(_G.CocaSkyDestroyer.sync_now) == "function" then
                pcall(_G.CocaSkyDestroyer.sync_now, true)
            end
        end
    end
    local keepNoclip = (moveState and moveState.noclip) == true
    local keepNoTouch = (Anti and Anti.Kill and Anti.Kill.enabled) == true
    local hiddenMap = type(_G.hiddenBodyParts) == "table" and _G.hiddenBodyParts or nil
    for _, part in ipairs(char:GetDescendants()) do
        if part:IsA("BasePart") then
            part.Anchored = false
            part.Massless = false
            part.CanTouch = not keepNoTouch
            part.CanQuery = true
            pcall(function() part.CustomPhysicalProperties = nil end)
            if (not isReanimActive or isReanimClone) and not (moveState and moveState.Vanish and moveState.Vanish.selfActive) then
                if not (hiddenMap and hiddenMap[part.Name]) then
                    pcall(function() part.LocalTransparencyModifier = 0 end)
                end
                if part.Name ~= "HumanoidRootPart" and not (hiddenMap and hiddenMap[part.Name]) then
                    if part.Transparency >= 0.95 and (
                        part.Name == "Head" or part.Name == "Torso" or part.Name == "UpperTorso" or part.Name == "LowerTorso"
                        or part.Name:find("Arm") or part.Name:find("Hand") or part.Name:find("Leg") or part.Name:find("Foot")
                        or part.Name == "Handle"
                    ) then
                        pcall(function() part.Transparency = 0 end)
                    end
                end
            end
            if part.Name == "HumanoidRootPart" or part.Name == "Torso" or part.Name == "UpperTorso" or part.Name == "LowerTorso" or part.Name == "Head" then
                part.CanCollide = not keepNoclip
            end
        elseif part:IsA("Decal") and (not isReanimActive or isReanimClone) and not (moveState and moveState.Vanish and moveState.Vanish.selfActive) then
            if part.Name == "face" and part.Transparency >= 0.95 and not (hiddenMap and hiddenMap["Head"]) then
                pcall(function() part.Transparency = 0 end)
            end
        elseif part:IsA("Motor6D") and (not isReanimActive or isReanimClone) then
            pcall(function()
                part.Enabled = true
                part.Transform = CFrame.identity
            end)
        end
    end
    if moveState and moveState.restoreFlyJoints then
        pcall(function() moveState.restoreFlyJoints(char) end)
    end
    stopDefaultTracks(char)
    local animate = char:FindFirstChild("Animate")
    if animate and animate.Disabled and CurrentWeld == nil and not WeldSeekingTarget and not (moveState and (moveState.fly or moveState.flyLanding)) and (not isReanimActive or isReanimClone) then
        pcall(function() animate.Disabled = false end)
        pcall(function() animate.Enabled = true end)
    end
    AnimateWasDisabled = false
    if EmoteHub and EmoteHub.EnsureActivePackAlive and CurrentWeld == nil and not WeldSeekingTarget and not (moveState and (moveState.fly or moveState.flyLanding)) then
        task.defer(function()
            if char and char.Parent and CurrentWeld == nil and not WeldSeekingTarget then
                pcall(function() EmoteHub:EnsureActivePackAlive(char) end)
            end
        end)
    end
    if hum and hum.Health > 0 then
        pcall(function()
            if not hum:GetStateEnabled(Enum.HumanoidStateType.Running) then hum:SetStateEnabled(Enum.HumanoidStateType.Running, true) end
            if not hum:GetStateEnabled(Enum.HumanoidStateType.Jumping) then hum:SetStateEnabled(Enum.HumanoidStateType.Jumping, true) end
            if not hum:GetStateEnabled(Enum.HumanoidStateType.Freefall) then hum:SetStateEnabled(Enum.HumanoidStateType.Freefall, true) end
            if not hum:GetStateEnabled(Enum.HumanoidStateType.Landed) then hum:SetStateEnabled(Enum.HumanoidStateType.Landed, true) end
            if not hum:GetStateEnabled(Enum.HumanoidStateType.GettingUp) then hum:SetStateEnabled(Enum.HumanoidStateType.GettingUp, true) end
            if hum.PlatformStand then hum.PlatformStand = false end
            if hum.Sit then hum.Sit = false end
            if not hum.AutoRotate then hum.AutoRotate = true end
            local curSt = hum:GetState()
            if curSt == Enum.HumanoidStateType.PlatformStanding
                or curSt == Enum.HumanoidStateType.Ragdoll
                or curSt == Enum.HumanoidStateType.FallingDown
                or curSt == Enum.HumanoidStateType.Seated
                or curSt == Enum.HumanoidStateType.Physics
                or curSt == Enum.HumanoidStateType.Dead then
                hum:ChangeState(Enum.HumanoidStateType.GettingUp)
                hum:ChangeState(Enum.HumanoidStateType.Running)
            end
        end)
    end
    local currentCam = workspace.CurrentCamera
    if currentCam and hum and not SpectatingTarget and not FlingActive then
        pcall(function()
            currentCam.CameraType = Enum.CameraType.Custom
            currentCam.CameraSubject = hum
        end)
    end
end

-- Multi-frame anchored void rescue: aborts immediately if CurrentWeld, WeldSeekingTarget, or FlingActive is running so it NEVER fights target connections!
local RescueGeneration = 0

-- Multi-frame anchored void rescue from oyee hoye.lua: guarantees the server & client physics engine
-- never rubberband or trap the local player in the void after throwing/flinging/unwelding a target.
safeReturnFromVoid = function(char, preferredCF)
    char = char or (LP and LP.Character)
    if not char then return end
    if CurrentWeld ~= nil or WeldSeekingTarget or FlingActive or _G.CocaBangActive or _G.CocaCopierActive or (AnimCopySys and AnimCopySys.active) or (OwnerAdminState and OwnerAdminState.formationMode) then
        return
    end
    local root = char:FindFirstChild("HumanoidRootPart") or char:FindFirstChildWhichIsA("BasePart")
    local hum  = char:FindFirstChildOfClass("Humanoid")
    local resolvedCF = isSafePlayableCF(preferredCF) and preferredCF
        or ((root and isSafePlayableCF(root.CFrame)) and root.CFrame or findFallbackSafeCF())
    local pos = resolvedCF.Position
    local _, yYaw, _ = resolvedCF:ToEulerAnglesYXZ()
    -- Anti-stuck geometry clearance: if destination is embedded inside a solid wall/floor/ceiling, nudge upward cleanly
    pcall(function()
        local ovParams = OverlapParams.new()
        ovParams.FilterType = Enum.RaycastFilterType.Exclude
        ovParams.FilterDescendantsInstances = { char }
        local probePos = pos + Vector3.new(0, 1.2, 0)
        for attempt = 1, 4 do
            local hits = workspace:GetPartBoundsInBox(CFrame.new(probePos), Vector3.new(1.8, 3.2, 1.8), ovParams)
            local blocked = false
            for _, hp in ipairs(hits) do
                if hp and hp:IsA("BasePart") and hp.CanCollide and not hp:IsDescendantOf(char) then
                    blocked = true
                    break
                end
            end
            if not blocked then
                pos = probePos - Vector3.new(0, 1.2, 0)
                break
            end
            probePos = probePos + Vector3.new(0, 3.2, 0)
        end
    end)
    local cleanCF = CFrame.new(pos + Vector3.new(0, 1.2, 0)) * CFrame.Angles(0, yYaw, 0)

    recoverCharacterState(char, cleanCF)
    if not root or not root.Parent then return end

    RescueGeneration = RescueGeneration + 1
    local myRescueGen = RescueGeneration

    task.spawn(function()
        local okRescue = pcall(function()
            root.Anchored = true
            for _ = 1, 4 do
                if not root.Parent or char ~= LP.Character or myRescueGen ~= RescueGeneration or CurrentWeld ~= nil or WeldSeekingTarget or FlingActive or _G.CocaBangActive or _G.CocaCopierActive or (AnimCopySys and AnimCopySys.active) then
                    break
                end
                root.AssemblyLinearVelocity = Vector3.zero
                root.AssemblyAngularVelocity = Vector3.zero
                root.CFrame = cleanCF
                RunService.Heartbeat:Wait()
            end
            if root.Parent then
                root.Anchored = false
                if myRescueGen == RescueGeneration and CurrentWeld == nil and not WeldSeekingTarget and not FlingActive and not _G.CocaBangActive and not _G.CocaCopierActive and not (AnimCopySys and AnimCopySys.active) then
                    root.AssemblyLinearVelocity = Vector3.zero
                    root.AssemblyLinearVelocity = Vector3.zero
                    root.AssemblyAngularVelocity = Vector3.zero
                    root.CFrame = cleanCF
                end
            end
            if myRescueGen == RescueGeneration and CurrentWeld == nil and not WeldSeekingTarget and not FlingActive and not _G.CocaBangActive and not _G.CocaCopierActive and not (AnimCopySys and AnimCopySys.active) then
                if hum and hum.Parent and hum.Health > 0 then
                    hum.PlatformStand = false
                    hum.Sit = false
                    hum.AutoRotate = true
                    hum:ChangeState(Enum.HumanoidStateType.GettingUp)
                    hum:ChangeState(Enum.HumanoidStateType.Running)
                end
                local currentCam = workspace.CurrentCamera
                if currentCam and hum and not SpectatingTarget then
                    currentCam.CameraType = Enum.CameraType.Custom
                    currentCam.CameraSubject = hum
                end
            end
        end)
        -- Guaranteed unanchor failsafe so root is NEVER left anchored if rescue aborted or threw!
        if root and root.Parent and not (OwnerAdminState and OwnerAdminState.isFrozenByOwner) then
            pcall(function() root.Anchored = false end)
        end
        local reanimStillOn = (_G.CocaSkyDestroyer and (_G.CocaSkyDestroyer.isAnyActive() or _G.CocaSkyDestroyer.is_reanimated()))
            or (_G._AngoorZenApi and type(_G._AngoorZenApi.is_reanimated) == "function" and _G._AngoorZenApi.is_reanimated())
        if not reanimStillOn and not (Anti and Anti.Void and Anti.Void.enabled) and not (Anti and Anti.Kill and Anti.Kill.enabled) and not WeldIntent.active and CurrentWeld == nil and not WeldSeekingTarget and not FlingActive then
            pcall(function() workspace.FallenPartsDestroyHeight = OriginalFPDH end)
        end
    end)
end

-- Continuously record LastKnownSafeCF when on safe ground (throttled to 7Hz) & instant auto-rescue/self-heal if stranded in void or invisible
do
    local lastSafeSampleTick = 0
    RunService.Heartbeat:Connect(function()
        if FlingActive or WeldIntent.active or CurrentWeld ~= nil or WeldSeekingTarget or (AnimCopySys and AnimCopySys.active) or (moveState and moveState.Vanish and moveState.Vanish.selfActive) or _G.CocaBangActive or _G.CocaCopierActive or (OwnerAdminState and OwnerAdminState.formationMode) or (_G.CocaSkyDestroyer and (_G.CocaSkyDestroyer.isAnyActive() or _G.CocaSkyDestroyer.is_reanimated())) or (_G._AngoorZenApi and type(_G._AngoorZenApi.is_reanimated) == "function" and _G._AngoorZenApi.is_reanimated()) then return end
        local now = os.clock()
        local inVoidWindow = (Anti and Anti.Void and Anti.Void.enabled) or (tick() - LastVoidActionEnd < 6.0)
        if not inVoidWindow and (now - lastSafeSampleTick < 0.15) then return end

        local char = LP.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        local hum  = char and char:FindFirstChildOfClass("Humanoid")
        if not root or not hum or hum.Health <= 0 then return end

        local pos = root.Position
        local voidFloor = math.min(OriginalFPDH + 22, -260)
        if pos.Y <= voidFloor or math.abs(pos.Y - 85000) < 3500 or pos.Magnitude > 250000 or pos.X ~= pos.X then
            if inVoidWindow or math.abs(pos.Y - 85000) < 3500 or pos.Y <= math.min(OriginalFPDH + 5, -450) then
                safeReturnFromVoid(char, LastKnownSafeCF)
            end
        elseif now - lastSafeSampleTick >= 0.15 then
            lastSafeSampleTick = now
            local head = char:FindFirstChild("Head")
            if head and head:IsA("BasePart") and head.LocalTransparencyModifier > 0.5 then
                for _, p in ipairs(char:GetChildren()) do
                    if p:IsA("BasePart") then
                        pcall(function() p.LocalTransparencyModifier = 0 end)
                    end
                end
            end
            if not (moveState and (moveState.fly or moveState.flyLanding)) then
                if hum.PlatformStand then
                    pcall(function()
                        hum.PlatformStand = false
                        hum.AutoRotate = true
                        hum:ChangeState(Enum.HumanoidStateType.GettingUp)
                        hum:ChangeState(Enum.HumanoidStateType.Running)
                    end)
                end
                local animScr = char:FindFirstChild("Animate")
                if animScr and animScr.Disabled then
                    pcall(function() animScr.Disabled = false end)
                end
            end
            local vel = root.AssemblyLinearVelocity.Magnitude
            local isGrounded = (hum.FloorMaterial ~= Enum.Material.Air) or (LastKnownSafeCF == nil)
            if isSafePlayableCF(root.CFrame) and vel < 95 and isGrounded then
                local _, yYaw, _ = root.CFrame:ToEulerAnglesYXZ()
                LastKnownSafeCF = CFrame.new(pos) * CFrame.Angles(0, yYaw, 0)
            end
        end
    end)
end

local stopWeld -- forward declaration
local findPlayerCharacterAnywhere
local pickTargetRef
local getFlatYawCFrame
local getBestTargetCFrame
local streamAndTeleportToTarget
local markIntentionalTeleport

-- ============================================================================
-- 🛡️ REANIMATION & INVISIBILITY ROBUSTNESS HELPERS (0.00ms ZERO-DELAY AWARE)
--   • Detects & filters desynced HumanoidRootParts (from FE Invisibility, Vanish,
--     or fling reanimations where root is sent to sky Y=85000 or underground Y=-185)
--   • Automatically resolves live reanimation clone rigs & netless physics bodies
--     so the weld NEVER detaches or swings your character away into the void/sky!
-- ============================================================================
local isRefPartValid
local isCharacterNetlessReanimated
local findTargetReanimModel
local isLocalCharAliveOrReanimated
local isValidTargetWorldCF
local findPlayerVoiceTagAnchor
local getVoiceTagHeightDropY

local function getSafeVoidFloorY()
    local fpdh = (OriginalFPDH and OriginalFPDH == OriginalFPDH and OriginalFPDH > -10000 and OriginalFPDH) or -500
    return fpdh + 25
end

local function isPartInSafeWorldBounds(p)
    if not (p and p.Parent and p:IsA("BasePart")) then return false, nil end
    local okCF, cf = pcall(function() return p.CFrame end)
    if not okCF or not cf then return false, nil end
    local okV, vel = pcall(function() return p.AssemblyLinearVelocity end)
    if isLethalVoidCF(cf, okV and vel or nil) then return false, nil end
    local pos = cf.Position
    if pos.Y <= getSafeVoidFloorY() then return false, nil end
    if math.abs(pos.Y - 85000) < 5000 then return false, nil end
    if okV and vel and (vel.Magnitude > 650 or vel.Y < -200) then return false, nil end
    return true, pos
end

-- Detects when a target using Reanim / Limb Remover throws their Head (or a limb) off their body toward the void!
-- Catches detached/falling Heads on Frame 0 (before they ever hit FallenPartsDestroyHeight) so you stay locked
-- right where the player is standing on the map instead of getting teleported into the void with their Head!
local function isPartDetachedOrThrown(part, char)
    if not (part and part.Parent and part:IsA("BasePart")) then return true end
    local okB, pos = isPartInSafeWorldBounds(part)
    if not okB or not pos then return true end
    local okV, vel = pcall(function() return part.AssemblyLinearVelocity end)
    local m = char or part:FindFirstAncestorOfClass("Model")
    if m and part.Name ~= "HumanoidRootPart" then
        local hrp = m:FindFirstChild("HumanoidRootPart")
        local torso = m:FindFirstChild("UpperTorso") or m:FindFirstChild("Torso") or m:FindFirstChild("LowerTorso")
        local bodyAnchor = nil
        local bodyPos = nil
        if hrp and hrp ~= part then
            local okH, hPos = isPartInSafeWorldBounds(hrp)
            if okH and hPos then
                local okHV, hVel = pcall(function() return hrp.AssemblyLinearVelocity end)
                if not (okHV and hVel and (hVel.Y < -85 or hVel.Magnitude > 220)) then
                    bodyAnchor, bodyPos = hrp, hPos
                end
            end
        end
        if not bodyAnchor and torso and torso ~= part then
            local okT, tPos = isPartInSafeWorldBounds(torso)
            if okT and tPos then
                local okTV, tVel = pcall(function() return torso.AssemblyLinearVelocity end)
                if not (okTV and tVel and (tVel.Y < -85 or tVel.Magnitude > 220)) then
                    bodyAnchor, bodyPos = torso, tPos
                end
            end
        end
        if bodyAnchor and bodyPos then
            -- If Head/limb separated >5.5 studs from the player's safe body, or dropped below their body, it was thrown/removed!
            if (pos - bodyPos).Magnitude > 5.5 then
                return true
            end
            if part.Name == "Head" and pos.Y < (bodyPos.Y - 3.0) then
                return true
            end
        end
        -- Also reject a Head/limb plunging downward fast even if HRP is already missing
        if okV and vel and (vel.Y < -85 or vel.Magnitude > 260) then
            return true
        end
    end
    return false
end

-- 🎙️ VOICE TAG ANCHOR RESOLVER (Reanim & Limb-Remover Void-Proof!)
-- Locates the EXACT BasePart where the target player's Roblox Voice Chat tag (BillboardGui / AudioEmitter)
-- is visibly rendered — NOT their real body (HumanoidRootPart / Torso / limbs), which Reanimation or
-- Limb Remover scripts frequently drop into the void or desync away from their visible head/voice tag!
local VoiceTagAnchorCache = {} -- [userId] = { part = BasePart, model = Model, checkedAt = number, deepAt = number }

local function resolvePartFromBillboardAdornee(adornee)
    if not adornee or not adornee.Parent then return nil, nil end
    if adornee:IsA("BasePart") then
        if isPartInSafeWorldBounds(adornee) then
            return adornee, adornee:FindFirstAncestorOfClass("Model")
        end
        return nil, nil
    elseif adornee:IsA("Attachment") then
        local parentPart = adornee.Parent
        if parentPart and parentPart:IsA("BasePart") and isPartInSafeWorldBounds(parentPart) then
            return parentPart, parentPart:FindFirstAncestorOfClass("Model")
        end
        return nil, nil
    elseif adornee:IsA("Model") then
        local h = adornee:FindFirstChild("Head") or adornee:FindFirstChild("head", true)
        if h and h:IsA("BasePart") and isPartInSafeWorldBounds(h) then
            return h, adornee
        end
        local prim = adornee.PrimaryPart
        if prim and prim:IsA("BasePart") and isPartInSafeWorldBounds(prim) then
            return prim, adornee
        end
        local t = adornee:FindFirstChild("UpperTorso") or adornee:FindFirstChild("Torso") or adornee:FindFirstChild("HumanoidRootPart")
        if t and t:IsA("BasePart") and isPartInSafeWorldBounds(t) then
            return t, adornee
        end
    end
    return nil, nil
end

findPlayerVoiceTagAnchor = function(targetPlr, fallbackChar)
    if not targetPlr or targetPlr == LP then return nil, nil end
    local uid = targetPlr.UserId
    local now = os.clock()
    local cached = VoiceTagAnchorCache[uid]
    if cached and cached.part and cached.part.Parent and (now - (cached.checkedAt or 0)) < 0.14 then
        if isPartInSafeWorldBounds(cached.part) then
            return cached.part, cached.model or cached.part:FindFirstAncestorOfClass("Model")
        end
    end

    local uidStr = tostring(uid)
    local bubbleName = "BubbleChat_" .. uidStr
    local foundPart, foundModel = nil, nil

    -- 1. O(1) direct lookup in Roblox's CoreGui Voice / BubbleChat containers (ExperienceChat + legacy BubbleChat)
    local cg = CoreGui
    if not cg then pcall(function() cg = game:GetService("CoreGui") end) end
    if cg then
        pcall(function()
            local directContainers = {}
            local expChat = cg:FindFirstChild("ExperienceChat")
            if expChat then
                local bc = expChat:FindFirstChild("bubbleChat") or expChat:FindFirstChild("BubbleChat")
                if bc then directContainers[#directContainers + 1] = bc end
                directContainers[#directContainers + 1] = expChat
            end
            local legacyBC = cg:FindFirstChild("BubbleChat")
            if legacyBC then directContainers[#directContainers + 1] = legacyBC end
            local rGui = cg:FindFirstChild("RobloxGui")
            if rGui then
                local rBC = rGui:FindFirstChild("BubbleChat")
                if rBC then directContainers[#directContainers + 1] = rBC end
                local rVC = rGui:FindFirstChild("VoiceChat")
                if rVC then directContainers[#directContainers + 1] = rVC end
            end

            for i = 1, #directContainers do
                local container = directContainers[i]
                local bbg = container:FindFirstChild(bubbleName)
                if bbg and bbg:IsA("BillboardGui") and bbg.Enabled ~= false then
                    local ad = bbg.Adornee or bbg.Parent
                    local p, m = resolvePartFromBillboardAdornee(ad)
                    if p then
                        foundPart, foundModel = p, m
                        return
                    end
                end
            end

            -- 2. Throttled scan inside ExperienceChat / BubbleChat / VoiceChat containers (max every 0.35s per target)
            if not foundPart and (not cached or (now - (cached.deepAt or 0)) >= 0.35) then
                if not cached then
                    cached = {}
                    VoiceTagAnchorCache[uid] = cached
                end
                cached.deepAt = now
                for i = 1, #directContainers do
                    local container = directContainers[i]
                    for _, desc in ipairs(container:GetDescendants()) do
                        if desc:IsA("BillboardGui") and desc.Enabled ~= false then
                            local dName = desc.Name
                            if not dName:find("CocoOverheadTag", 1, true) and (dName == bubbleName or dName:find(uidStr, 1, true)) then
                                local ad = desc.Adornee or desc.Parent
                                local p, m = resolvePartFromBillboardAdornee(ad)
                                if p then
                                    foundPart, foundModel = p, m
                                    return
                                end
                            end
                        end
                    end
                end
            end
        end)
    end

    -- 3. Check Roblox Voice Chat AudioEmitter inside target character or reanim model
    if not foundPart then
        local ch = fallbackChar or targetPlr.Character
        if ch and ch.Parent then
            pcall(function()
                local emitter = ch:FindFirstChildWhichIsA("AudioEmitter", true)
                if emitter and emitter.Parent then
                    local ep = emitter.Parent:IsA("BasePart") and emitter.Parent or (emitter.Parent:IsA("Attachment") and emitter.Parent.Parent)
                    if ep and ep:IsA("BasePart") and isPartInSafeWorldBounds(ep) then
                        foundPart, foundModel = ep, ep:FindFirstAncestorOfClass("Model") or ch
                    end
                end
            end)
        end
    end

    -- 4. Roblox's default Voice Tag host is ALWAYS Head (never real body HRP/Torso which Limb Remover / Reanim voids)
    if not foundPart then
        local ch = fallbackChar or targetPlr.Character
        if ch and ch.Parent then
            local head = ch:FindFirstChild("Head") or ch:FindFirstChild("head", true)
            if head and head:IsA("BasePart") and isPartInSafeWorldBounds(head) then
                foundPart, foundModel = head, ch
            end
        end
    end

    if not foundPart and findTargetReanimModel then
        local rModel = findTargetReanimModel(targetPlr)
        if rModel and rModel.Parent then
            local rHead = rModel:FindFirstChild("Head") or rModel:FindFirstChild("head", true)
            if rHead and rHead:IsA("BasePart") and isPartInSafeWorldBounds(rHead) then
                foundPart, foundModel = rHead, rModel
            end
        end
    end

    if foundPart then
        VoiceTagAnchorCache[uid] = {
            part = foundPart,
            model = foundModel,
            checkedAt = now,
            deepAt = cached and cached.deepAt or now,
        }
        return foundPart, foundModel
    end

    return nil, nil
end

-- Compensate vertical height cleanly so:
--   1. Head presets (facebang, headsit, goon, poop) ALWAYS stay at exact Head height even if anchored to HRP/Torso/VoiceTag
--   2. Torso presets stay at exact Torso/Pelvis height when anchored to Head (Voice Tag)
getVoiceTagHeightDropY = function(targetPart, targetChar, refMode, presetKey)
    if not targetPart or not targetPart:IsA("BasePart") then return 0 end
    if presetKey == "rizz" or presetKey == "goon" or presetKey == "poop" then
        return 0
    end
    local scaleY = 1.0
    local hum = targetChar and targetChar:FindFirstChildOfClass("Humanoid")
    if hum then
        local bhs = hum:FindFirstChild("BodyHeightScale")
        if bhs and bhs:IsA("NumberValue") and bhs.Value > 0.2 and bhs.Value < 4.5 then
            scaleY = bhs.Value
        end
    end
    if scaleY == 1.0 then
        local hd = targetChar and targetChar:FindFirstChild("Head")
        if hd and hd:IsA("BasePart") and hd.Size.Y > 0.25 and hd.Size.Y < 4.0 then
            scaleY = hd.Size.Y
        elseif targetPart.Name == "Head" and targetPart.Size.Y > 0.25 and targetPart.Size.Y < 4.0 then
            scaleY = targetPart.Size.Y
        end
    end
    local isHeadPreset = (refMode == "head" or presetKey == "facebang" or presetKey == "headsit")
    if isHeadPreset then
        if targetPart.Name == "Head" then
            return 0
        elseif targetPart.Name == "UpperTorso" then
            return 1.05 * scaleY
        elseif targetPart.Name == "LowerTorso" then
            return 1.95 * scaleY
        else
            -- HumanoidRootPart / Torso / generic Voice Tag anchor: lift up to exact Head level!
            return 1.5 * scaleY
        end
    end
    if targetPart.Name == "Head" then
        return -1.5 * scaleY
    end
    return 0
end

isValidTargetWorldCF = function(cf)
    if not cf then return false end
    local pos = cf.Position
    if pos.X ~= pos.X or pos.Y ~= pos.Y or pos.Z ~= pos.Z then return false end
    if math.abs(pos.X) == math.huge or math.abs(pos.Y) == math.huge or math.abs(pos.Z) == math.huge then return false end
    if pos.Magnitude < 0.5 or pos.Magnitude > 150000 then return false end
    if math.abs(pos.Y - 85000) < 5000 then return false end
    if isLethalVoidCF and isLethalVoidCF(cf) then return false end
    return true
end

isLocalCharAliveOrReanimated = function(char, hum)
    char = char or (LP and LP.Character)
    if not (char and char.Parent) then return false end
    hum = hum or char:FindFirstChildOfClass("Humanoid")
    if hum and hum.Health > 0 then return true end
    if (_G._AngoorZenApi and type(_G._AngoorZenApi.is_reanimated) == "function" and _G._AngoorZenApi.is_reanimated())
        or (_G.CocaSkyDestroyer and (_G.CocaSkyDestroyer.isAnyActive() or _G.CocaSkyDestroyer.is_reanimated()))
        or (moveState and moveState.Vanish and moveState.Vanish.selfActive) then
        return true
    end
    if isCharacterNetlessReanimated and isCharacterNetlessReanimated(char) then
        return true
    end
    return false
end

-- Voice-Tag & Void-Proof reference part validator:
-- Rejects any part in void/sky-dump/fling OR desynced >6 studs away from the player's visible Voice Tag / Head!
isRefPartValid = function(part, char, targetPlr)
    local okBounds, pos = isPartInSafeWorldBounds(part)
    if not okBounds or not pos then return false end
    if char and not part:IsDescendantOf(char) then
        -- Allow valid Voice Tag adornee even if it belongs to a reanim rig model
        local plr = targetPlr or Players:GetPlayerFromCharacter(char)
        local vPart = plr and findPlayerVoiceTagAnchor(plr, char)
        if not (vPart and vPart == part) then
            return false
        end
    end
    local plr = targetPlr or (char and Players:GetPlayerFromCharacter(char))
    if plr and plr ~= LP then
        local vPart = findPlayerVoiceTagAnchor(plr, char)
        if vPart and vPart ~= part and vPart.Parent then
            local okV, vPos = isPartInSafeWorldBounds(vPart)
            if okV and vPos and (pos - vPos).Magnitude > 6.0 then
                return false
            end
        end
    end
    if isPartDetachedOrThrown(part, char) then
        return false
    end
    if char and part.Name == "HumanoidRootPart" then
        local headOrUpper = char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso") or char:FindFirstChild("Head")
        local okUpper, upperPos = isPartInSafeWorldBounds(headOrUpper)
        if okUpper and not isPartDetachedOrThrown(headOrUpper, char) and (pos - upperPos).Magnitude > 6.0 then
            return false
        end
    end
    return true
end

isCharacterNetlessReanimated = function(char)
    if not (char and char.Parent) then return false end
    local cands = {
        char:FindFirstChild("UpperTorso"),
        char:FindFirstChild("Torso"),
        char:FindFirstChild("Head"),
        char:FindFirstChild("LowerTorso"),
        char.PrimaryPart,
    }
    for _, part in ipairs(cands) do
        if part and part:IsA("BasePart") and isRefPartValid(part, char) then
            return true
        end
    end
    return false
end

local function isLocalOwnedModel(m)
    if not m then return true end
    if LP and m == LP.Character then return true end
    local mName = m.Name
    if mName == "CocaReanimation" or mName == "AngoorReanimation" or mName == "CocoVanishGhost" or mName == "ReanimationClone" then
        return true
    end
    if _G._AngoorZenApi then
        if type(_G._AngoorZenApi.get_real_character) == "function" and m == _G._AngoorZenApi.get_real_character() then return true end
        if type(_G._AngoorZenApi.get_clone) == "function" and m == _G._AngoorZenApi.get_clone() then return true end
    end
    if _G.CocaSkyDestroyer then
        if type(_G.CocaSkyDestroyer.get_real_character) == "function" and m == _G.CocaSkyDestroyer.get_real_character() then return true end
        if type(_G.CocaSkyDestroyer.get_clone_character) == "function" and m == _G.CocaSkyDestroyer.get_clone_character() then return true end
    end
    if moveState and moveState.Vanish and m == moveState.Vanish.ghostModel then return true end
    if AnimCopySys and AnimCopySys.savedOutfitChar == m then return true end
    return false
end

-- Client-side target visibility restorer: prevents Poppercam / TransparencyController / replicator glitches
-- from turning the other player invisible on your screen when welding or reanimating!
local lastTargetVisRestore = setmetatable({}, { __mode = "k" })
local function ensureTargetVisibleOnClient(targetPlr, targetChar)
    if not targetChar or not targetChar.Parent then return end
    if targetPlr and moveState and moveState.Vanish and moveState.Vanish.vanishedTargets and moveState.Vanish.vanishedTargets[targetPlr.UserId] then
        return
    end
    local now = os.clock()
    if lastTargetVisRestore[targetChar] and (now - lastTargetVisRestore[targetChar]) < 0.18 then
        return
    end
    lastTargetVisRestore[targetChar] = now
    for _, obj in ipairs(targetChar:GetChildren()) do
        if obj:IsA("BasePart") and obj.Name ~= "HumanoidRootPart" then
            if obj.LocalTransparencyModifier > 0.01 then
                pcall(function() obj.LocalTransparencyModifier = 0 end)
            end
        elseif obj:IsA("Accessory") then
            local h = obj:FindFirstChild("Handle")
            if h and h:IsA("BasePart") and h.LocalTransparencyModifier > 0.01 then
                pcall(function() h.LocalTransparencyModifier = 0 end)
            end
        end
    end
end

findTargetReanimModel = function(targetPlr)
    if not targetPlr or targetPlr == LP then return nil end
    local tName = targetPlr.Name
    local tDisp = targetPlr.DisplayName or tName
    -- Never search local-only client clone names ("CocaReanimation", "CocoVanishGhost", "ReanimationClone")
    local candidates = {
        tName .. "_Reanim",
        tName .. "Reanim",
        tName .. "_Fake",
        tName .. "Clone",
        tName .. "Rig",
        tName .. "_Clone",
        tName .. " Dummy",
        tName .. "_Ghost",
        tDisp .. "_Fake",
        tDisp .. "_Clone",
    }

    for _, cName in ipairs(candidates) do
        local m = workspace:FindFirstChild(cName) or (workspace.CurrentCamera and workspace.CurrentCamera:FindFirstChild(cName))
        if m and m:IsA("Model") and not isLocalOwnedModel(m) then
            local ref = m:FindFirstChild("UpperTorso") or m:FindFirstChild("Torso") or m:FindFirstChild("Head") or m:FindFirstChild("HumanoidRootPart") or m.PrimaryPart
            if ref and ref:IsA("BasePart") and isRefPartValid(ref, m) then
                return m
            end
        end
    end

    local direct = workspace:FindFirstChild(tName)
    if direct and direct:IsA("Model") and not isLocalOwnedModel(direct) and direct ~= targetPlr.Character then
        local ref = direct:FindFirstChild("UpperTorso") or direct:FindFirstChild("Torso") or direct:FindFirstChild("Head") or direct:FindFirstChild("HumanoidRootPart") or direct.PrimaryPart
        if ref and ref:IsA("BasePart") and isRefPartValid(ref, direct) then
            return direct
        end
    end

    for _, fName in ipairs({ "Characters", "Players", "Entities", "Live", "Units", "Ingame", "Chars" }) do
        local f = workspace:FindFirstChild(fName)
        local found = f and f:FindFirstChild(tName)
        if found and found:IsA("Model") and not isLocalOwnedModel(found) and found ~= targetPlr.Character then
            local ref = found:FindFirstChild("UpperTorso") or found:FindFirstChild("Torso") or found:FindFirstChild("Head") or found:FindFirstChild("HumanoidRootPart") or found.PrimaryPart
            if ref and ref:IsA("BasePart") and isRefPartValid(ref, found) then
                return found
            end
        end
    end

    return nil
end

-- ═══════════════════════════════════════════════════════════════════════════════
-- ⚡ ZERO-DELAY WELD & OMNIPRESENT TARGET CATCH-UP ENGINE (LINE-BY-LINE AUDITED)
--   • Eliminated PhysicsRepRootPart double-transform bug (which sent players to 2x
--     world coordinates / random places on the map when setting Root.CFrame)
--   • Uses upright root yaw (`getFlatYawCFrame`) + exact anatomical anchor points
--     so head-nods or torso tilts during animations never swing your character away
--   • Eliminated stale `WorldPivot` false-nearest trap so Auto-Nearest ALWAYS locks
--     onto real streamed-in players near you, while unstreamed targets are swept
--     and caught up to anywhere on the map!
-- ═══════════════════════════════════════════════════════════════════════════════
-- Careful Anatomical Character-to-Character Height & Scale Solver (0.00ms Zero-Delay)
--   • Measures both LocalCharacter and TargetCharacter rig geometry (HipHeight, RootPart/Torso/UpperTorso/LowerTorso/Head
--     dimensions, BodyHeightScale, and live reference part offsets across R15, R6, tall, short, chibi, and plushie avatars)
--   • Specifically calibrates "rizz" (Wall Rizz Pose / Kabedon Wall Lean – Catalog ID 90735295463164) so your character's
--     leaning shoulder/hand/gaze height aligns accurately with the other character's head & upper torso without clipping!
local function getCharacterAnatomyMetrics(char, hum, refPart)
    if not char then return 3.0, 1.5, 1.0, 0.0 end
    hum = hum or char:FindFirstChildOfClass("Humanoid")
    local hrp = char:FindFirstChild("HumanoidRootPart") or (hum and hum.RootPart) or refPart
    local head = char:FindFirstChild("Head")
    local upperTorso = char:FindFirstChild("UpperTorso")
    local lowerTorso = char:FindFirstChild("LowerTorso")
    local torso = char:FindFirstChild("Torso") or upperTorso

    -- 1. Rig vertical scale factor (handles R15 BodyHeightScale, chibi/plushie packages, and custom scaled rigs)
    local scaleY = 1.0
    if hum then
        local bhs = hum:FindFirstChild("BodyHeightScale")
        if bhs and bhs:IsA("NumberValue") and bhs.Value > 0.15 and bhs.Value < 5.0 then
            scaleY = bhs.Value
        end
    end
    if scaleY == 1.0 and torso and torso:IsA("BasePart") then
        local baseTorsoY = (torso.Name == "UpperTorso") and 1.6 or 2.0
        local ratio = torso.Size.Y / baseTorsoY
        if ratio > 0.25 and ratio < 4.5 then
            scaleY = ratio
        end
    end

    -- 2. Standing Root/Pelvis center height above ground (feet-to-root)
    local rootToGround = 3.0 * scaleY
    if hum then
        local hipH = hum.HipHeight or 0
        if hum.RigType == Enum.HumanoidRigType.R15 then
            local rSizeY = (hrp and hrp:IsA("BasePart") and hrp.Size.Y) or (2.0 * scaleY)
            if hipH > 0.05 then
                rootToGround = hipH + (rSizeY * 0.5)
            end
        else
            local leg = char:FindFirstChild("Right Leg") or char:FindFirstChild("Left Leg")
            local legY = (leg and leg:IsA("BasePart") and leg.Size.Y) or (2.0 * scaleY)
            local tSizeY = (torso and torso:IsA("BasePart") and torso.Size.Y) or (2.0 * scaleY)
            rootToGround = legY + (tSizeY * 0.5) + math.max(0, hipH)
        end
    end

    -- 3. Anatomical vertical span from ReferencePart (HRP / Torso / UpperTorso / LowerTorso) to Head center
    local headSizeY = (head and head:IsA("BasePart") and head.Size.Y) or (1.0 * scaleY)
    local torsoSpanY = 1.0 * scaleY
    if upperTorso and upperTorso:IsA("BasePart") then
        local utY = upperTorso.Size.Y
        local ltY = (lowerTorso and lowerTorso:IsA("BasePart") and lowerTorso.Size.Y) or (0.4 * scaleY)
        torsoSpanY = (utY + ltY) * 0.5
    elseif torso and torso:IsA("BasePart") then
        torsoSpanY = torso.Size.Y * 0.5
    end
    local anatomicalRootToHead = torsoSpanY + (headSizeY * 0.5)

    -- Compensate if refPart is UpperTorso, LowerTorso, or Head rather than HumanoidRootPart/Torso center
    local refToRootY = 0.0
    local anchorPart = refPart or hrp or torso
    if anchorPart and anchorPart:IsA("BasePart") then
        if anchorPart.Name == "UpperTorso" then
            refToRootY = -0.42 * scaleY
        elseif anchorPart.Name == "LowerTorso" then
            refToRootY = 0.55 * scaleY
        elseif anchorPart.Name == "Head" then
            refToRootY = -anatomicalRootToHead
        elseif hrp and anchorPart ~= hrp and hrp:IsA("BasePart") then
            local dy = hrp.Position.Y - anchorPart.Position.Y
            if math.abs(dy) < 2.8 then
                refToRootY = dy
            end
        end
    end

    local refToHead = anatomicalRootToHead + refToRootY
    if head and head:IsA("BasePart") and anchorPart and anchorPart:IsA("BasePart") and anchorPart ~= head then
        local upVec = anchorPart.CFrame.UpVector
        if upVec.Y > 0.65 then
            local liveDY = head.Position.Y - anchorPart.Position.Y
            if liveDY > 0.15 and liveDY < 6.5 then
                -- Blend 70% stable anatomical rig size + 30% live upright head position to prevent animation bobbing jitter
                refToHead = (refToHead * 0.70) + (liveDY * 0.30)
            end
        end
    end

    return rootToGround, refToHead, scaleY, refToRootY
end

local computeDynamicHeightWeld = function(myChar, myHum, myRoot, targetChar, targetHum, targetPart, refMode, presetKey)
    if not (myChar and targetChar and targetPart) then
        return 0, 1.0, 1.0, 0
    end
    local useAuto = (V and V.AutoHeight ~= false) or (presetKey == "rizz")
    if not useAuto then
        return 0, 1.0, 1.0, 0
    end

    local myRootToGround, myRootToHead, myScaleY, _ = getCharacterAnatomyMetrics(myChar, myHum, myRoot)
    local tRootToGround, tRefToHead, tScaleY, tRefToRootY = getCharacterAnatomyMetrics(targetChar, targetHum, targetPart)

    local autoY = 0.0
    local autoZ = 0.0

    if presetKey == "rizz" then
        -- Wall Rizz Pose (Kabedon / Wall Lean - ID 90735295463164):
        -- Align our character's Kabedon upper-torso/shoulder/head lean directly with the target character's head & face height,
        -- while respecting the floor plane so our character never sinks deep underground or floats above the target.
        local headEyeAlignY = (tRefToHead - myRootToHead) + (0.08 * myScaleY)
        local floorStandAlignY = tRefToRootY + (myRootToGround - tRootToGround)
        if tRootToGround < myRootToGround - 0.15 or tRefToHead < myRootToHead - 0.10 then
            -- Target is shorter / chibi / smaller than us: lower our character to match their head/shoulder Kabedon zone,
            -- clamped smoothly so legs don't bury deep below the floor
            local minFloorSafeY = floorStandAlignY - (0.78 * myScaleY)
            autoY = math.max(headEyeAlignY, minFloorSafeY)
        elseif tRootToGround > myRootToGround + 0.15 or tRefToHead > myRootToHead + 0.10 then
            -- Target is taller than us (or we are shorter/chibi): raise our character to align our Wall Rizz pose with their head/chest
            autoY = headEyeAlignY
        else
            -- Similar height rigs: compensate any UpperTorso/HRP reference difference + subtle eye-contact alignment
            autoY = (headEyeAlignY * 0.75) + (floorStandAlignY * 0.25)
        end
        autoY = math.clamp(autoY, -2.6, 3.2)
        autoZ = math.clamp((tScaleY - 1.0) * -0.22, -0.45, 0.28)
    elseif refMode == "head" or presetKey == "facebang" or presetKey == "headsit" or presetKey == "goon" or presetKey == "poop" then
        -- Head-referenced presets: adapt vertical offset to local vs target scale difference (0 when both are 1.0)
        autoY = math.clamp((tScaleY - myScaleY) * 0.85, -1.8, 2.2)
    elseif presetKey == "kiss" or presetKey == "hug" or presetKey == "headpat" then
        -- Upper-body face-to-face presets: align head/chest level between rigs
        local headDiff = (tRefToHead - myRootToHead)
        autoY = math.clamp(headDiff, -2.2, 2.6)
    else
        -- Pelvis/Torso presets (backshots, chootlelo, backpack): align pelvis/torso center
        local pelvisDiff = tRefToRootY + ((tScaleY - myScaleY) * 0.45)
        autoY = math.clamp(pelvisDiff, -1.8, 2.2)
    end

    if V then
        local prevY = V.LastAutoY or autoY
        if math.abs(autoY - prevY) > 2.5 then
            V.LastAutoY = autoY
        else
            V.LastAutoY = prevY + (autoY - prevY) * 0.45
        end
        autoY = V.LastAutoY
    end

    return autoY, myScaleY, tScaleY, autoZ
end

-- Detect if a JointInstance / WeldConstraint / Constraint / SeatWeld is carrying another player on OUR character
-- (so starting a troll or running Anti-Attach / Anti-Seat NEVER drops or throws a player we are carrying!)
local function isCarriedPlayerJoint(obj, myChar)
    if not obj or not myChar then return false end
    local myHum = myChar:FindFirstChildOfClass("Humanoid")
    local otherPart = nil
    local myPart = nil
    if obj:IsA("JointInstance") or obj:IsA("WeldConstraint") then
        local p0, p1 = obj.Part0, obj.Part1
        local p0Mine = p0 and p0:IsDescendantOf(myChar)
        local p1Mine = p1 and p1:IsDescendantOf(myChar)
        if p0Mine and p1 and not p1Mine then
            myPart, otherPart = p0, p1
        elseif p1Mine and p0 and not p0Mine then
            myPart, otherPart = p1, p0
        else
            return false
        end
    elseif obj:IsA("Constraint") then
        local a0, a1 = obj.Attachment0, obj.Attachment1
        local a0Mine = a0 and a0:IsDescendantOf(myChar)
        local a1Mine = a1 and a1:IsDescendantOf(myChar)
        if a0Mine and a1 and not a1Mine then
            myPart, otherPart = a0.Parent, a1.Parent
        elseif a1Mine and a0 and not a0Mine then
            myPart, otherPart = a1.Parent, a0.Parent
        else
            return false
        end
    else
        return false
    end
    if not otherPart then return false end
    -- 1. If a Seat inside OUR character is seating another player, preserve that carry SeatWeld
    if (obj:IsA("SeatWeld") or obj.Name == "SeatWeld") and myPart and myPart:IsDescendantOf(myChar) and (myPart:IsA("Seat") or myPart:IsA("VehicleSeat")) then
        return true
    end
    -- 2. Resolve whether otherPart belongs to another player character
    local otherChar = otherPart:FindFirstAncestorOfClass("Model")
    local otherPlr = otherChar and Players:GetPlayerFromCharacter(otherChar) or nil
    if not otherPlr or otherPlr == LP then return false end
    -- 3. Direct parenting inside our character or seated on a seat inside our character
    if otherChar:IsDescendantOf(myChar) then return true end
    local otherHum = otherChar:FindFirstChildOfClass("Humanoid")
    if otherHum and otherHum.SeatPart and otherHum.SeatPart:IsDescendantOf(myChar) then
        return true
    end
    -- 4. Tracked via Carry/Interact ProximityPrompt or Carry UI button
    if OwnerAdminState and OwnerAdminState.isPlayerInCarrySet and OwnerAdminState.isPlayerInCarrySet(otherPlr.UserId) then
        return true
    end
    -- 5. Physical carry heuristic: WE are not sitting, while the attached player is PlatformStanding / Sitting / Physics on us
    if otherHum and (not myHum or not myHum.Sit) then
        local okSt, oSt = pcall(function() return otherHum:GetState() end)
        if otherHum.PlatformStand or otherHum.Sit or (okSt and (oSt == Enum.HumanoidStateType.Physics or oSt == Enum.HumanoidStateType.Seated or oSt == Enum.HumanoidStateType.PlatformStanding)) then
            return true
        end
    end
    -- 6. Weld/Constraint explicitly named with carry/piggyback/hold/hug keywords
    local jName = tostring(obj.Name or ""):lower()
    if jName:find("carry", 1, true) or jName:find("piggy", 1, true) or jName:find("hug", 1, true)
        or jName:find("hold", 1, true) or jName:find("shoulder", 1, true) or jName:find("cradle", 1, true)
        or jName:find("bridal", 1, true) or jName:find("partner", 1, true) then
        return true
    end
    return false
end

local function hasCarriedPlayerAttached(myChar)
    if not myChar then return false end
    for _, part in ipairs(myChar:GetDescendants()) do
        if part:IsA("BasePart") then
            local okJ, joints = pcall(function() return part:GetJoints() end)
            if okJ and joints then
                for _, j in ipairs(joints) do
                    if isCarriedPlayerJoint(j, myChar) then
                        return true
                    end
                end
            end
        elseif part:IsA("Constraint") and isCarriedPlayerJoint(part, myChar) then
            return true
        end
    end
    return false
end

OwnerAdminState.isCarriedPlayerJoint = isCarriedPlayerJoint
OwnerAdminState.hasCarriedPlayerAttached = hasCarriedPlayerAttached

-- Sever any workspace SeatWeld / VehicleSeat weld or foreign joint holding our character before teleporting/welding
-- (Preserves carry welds/seats where WE are carrying another player!)
local function breakAllSeatsAndExternalJoints(char, hum, root)
    if not char then return end
    hum = hum or char:FindFirstChildOfClass("Humanoid")
    root = root or char:FindFirstChild("HumanoidRootPart")
    pcall(function()
        if hum then
            local seatPart = hum.SeatPart
            if seatPart and seatPart:IsA("BasePart") and not seatPart:IsDescendantOf(char) then
                pcall(function() seatPart.CanTouch = false end)
                for _, ch in ipairs(seatPart:GetChildren()) do
                    if (ch:IsA("JointInstance") or ch:IsA("WeldConstraint") or ch.Name == "SeatWeld") and not isCarriedPlayerJoint(ch, char) then
                        pcall(function() ch:Destroy() end)
                    end
                end
                task.delay(0.45, function()
                    if seatPart and seatPart.Parent and not (Anti and Anti.SeatTrap and Anti.SeatTrap.enabled) then
                        pcall(function() seatPart.CanTouch = true end)
                    end
                end)
            end
            if hum.Sit then hum.Sit = false end
        end
        for _, part in ipairs(char:GetDescendants()) do
            if part:IsA("BasePart") then
                local okJ, joints = pcall(function() return part:GetJoints() end)
                if okJ and joints then
                    for _, j in ipairs(joints) do
                        if (j:IsA("JointInstance") or j:IsA("WeldConstraint")) and not isCarriedPlayerJoint(j, char) then
                            local p0, p1 = j.Part0, j.Part1
                            local p0Mine = p0 and p0:IsDescendantOf(char)
                            local p1Mine = p1 and p1:IsDescendantOf(char)
                            if (p0Mine and p1 and not p1Mine) or (p1Mine and p0 and not p0Mine) or j.Name == "SeatWeld" then
                                pcall(function() j:Destroy() end)
                            end
                        end
                    end
                end
            elseif (part:IsA("SeatWeld") or part.Name == "SeatWeld") and not isCarriedPlayerJoint(part, char) then
                pcall(function() part:Destroy() end)
            end
        end
    end)
end

-- Build server sweep points (Spawns, Seats, VehicleSeats, Map Models) for catching up to unstreamed players
local getServerSweepPoints
do
local CachedSweepPoints = {}
local LastSweepBuildTick = 0
getServerSweepPoints = function()
    local now = tick()
    if #CachedSweepPoints > 0 and (now - LastSweepBuildTick) < 8.0 then
        return CachedSweepPoints
    end
    LastSweepBuildTick = now
    local pts = {}
    pcall(function()
        for _, obj in ipairs(workspace:GetDescendants()) do
            if obj:IsA("SpawnLocation") or obj:IsA("Seat") or obj:IsA("VehicleSeat") then
                if not isLethalVoidCF(obj.CFrame) then
                    pts[#pts + 1] = obj.CFrame
                end
            end
        end
    end)
    for _, child in ipairs(workspace:GetChildren()) do
        if child:IsA("Model") and child ~= LP.Character and not Players:GetPlayerFromCharacter(child) then
            local okP, pCF = pcall(function() return child:GetPivot() end)
            if okP and pCF and pCF.Position.Magnitude > 10 and pCF.Position.Magnitude < 100000 and not isLethalVoidCF(pCF) then
                pts[#pts + 1] = pCF
            end
        elseif child:IsA("BasePart") and child.Position.Magnitude > 50 and child.Position.Magnitude < 100000 and not isLethalVoidCF(child.CFrame) then
            pts[#pts + 1] = child.CFrame
        end
    end
    CachedSweepPoints = pts
    return pts
end
end -- end getServerSweepPoints scope

-- ═══════════════════════════════════════════════════════════════════════════════
-- ⚡ EXACT OYEE HOYE.LUA NO-DELAY WELD ENGINE + 0.00ms ZERO-DELAY MULTI-PHASE LOCK
--   • Transplanted directly from oyee hoye.lua (L582–1261)
--   • Uses exact `Root.CFrame = TargetPart.CFrame * localOffset` + `PhysicsRepRootPart`
--     + `PhysicsRepRootRef` + `LP.ReplicationFocus = TargetPart`
--   • Zero-Delay Multi-Stage Lock: Frame-0 Synchronous + BindToRenderStep (PreCam &
--     Character+1) + RunService.Stepped + RunService.RenderStepped + RunService.Heartbeat
--   • Full Reanimation Sync (`_G._AngoorZenApi` & `_G.CocaSkyDestroyer`)
--   • Verified `loadPlayableAnim` (0.15s IsPlaying verification) so animations NEVER flicker!
-- ═══════════════════════════════════════════════════════════════════════════════
local function syncAllActiveReanimRoots(attachCF, primaryRoot)
    local tNow = os.clock()
    local netlessVel = Vector3.new(0, 25.05, 0) + Vector3.new(math.sin(tNow * 30) * 0.025, 0, math.cos(tNow * 30) * 0.025)
    local zApi = _G._AngoorZenApi
    if zApi and type(zApi.is_reanimated) == "function" and type(zApi.get_real_character) == "function" then
        local okR, isReanim = pcall(zApi.is_reanimated)
        if okR and isReanim then
            local okC, realChar = pcall(zApi.get_real_character)
            local realRoot = okC and realChar and realChar:FindFirstChild("HumanoidRootPart")
            if realRoot and realRoot ~= primaryRoot and realRoot.Parent then
                realRoot.Anchored = false
                realRoot.CanCollide = false
                realRoot.CFrame = attachCF
                realRoot.AssemblyLinearVelocity = netlessVel
                realRoot.AssemblyAngularVelocity = Vector3.zero
            end
            if type(zApi.sync_now) == "function" then
                pcall(zApi.sync_now, true)
            end
        end
    end
    local skyApi = _G.CocaSkyDestroyer
    if skyApi and type(skyApi.is_reanimated) == "function" and type(skyApi.get_real_character) == "function" then
        local okS, isSkyReanim = pcall(skyApi.is_reanimated)
        if okS and isSkyReanim then
            local okSC, skyRealChar = pcall(skyApi.get_real_character)
            local skyRealRoot = okSC and skyRealChar and skyRealChar:FindFirstChild("HumanoidRootPart")
            if skyRealRoot and skyRealRoot ~= primaryRoot and skyRealRoot.Parent then
                skyRealRoot.Anchored = false
                skyRealRoot.CanCollide = false
                skyRealRoot.CFrame = attachCF
                skyRealRoot.AssemblyLinearVelocity = netlessVel
                skyRealRoot.AssemblyAngularVelocity = Vector3.zero
            end
            if type(skyApi.sync_now) == "function" then
                pcall(skyApi.sync_now, true)
            end
        end
    end
end
_G.CocoSyncReanimRoots = syncAllActiveReanimRoots

local function WeldTo(TargetPart, Offset, Speaker, AnimationId, Osc, AnimFallbacks, TargetPlayer, RefMode, PreSeekSafeCF, PresetKey)
    local Character = Speaker.Character
    if not Character then return nil end
    local Root = Character:FindFirstChild("HumanoidRootPart") or Character:FindFirstChildWhichIsA("BasePart")
    local Humanoid = Character:FindFirstChildWhichIsA("Humanoid")
    if not Root or not Humanoid or not isLocalCharAliveOrReanimated(Character, Humanoid) then return nil end

    if type(_G.stopCocaBangLock) == "function" then
        pcall(_G.stopCocaBangLock)
    end
    if type(_G.stopCocaCopier) == "function" then
        pcall(_G.stopCocaCopier)
    end

    RescueGeneration = RescueGeneration + 1
    Root.Anchored = false
    breakAllSeatsAndExternalJoints(Character, Humanoid, Root)

    local TargetChar = (TargetPart and TargetPart.Parent) or (TargetPlayer and findPlayerCharacterAnywhere(TargetPlayer))
    local TargetHum  = TargetChar and TargetChar:FindFirstChildOfClass("Humanoid")
    local lastSafeCF = (PreSeekSafeCF and typeof(PreSeekSafeCF) == "CFrame" and isSafePlayableCF(PreSeekSafeCF) and PreSeekSafeCF)
        or (isSafePlayableCF(Root.CFrame) and Root.CFrame)
        or (isSafePlayableCF(LastKnownSafeCF) and LastKnownSafeCF)
        or findFallbackSafeCF()
    local targetUid  = TargetPlayer and TargetPlayer.UserId or nil
    local targetName = TargetPlayer and TargetPlayer.Name or "Target"
    local targetDisp = (TargetPlayer and TargetPlayer.DisplayName) or targetName
    local targetAge  = (TargetPlayer and tostring(TargetPlayer.AccountAge or "—") .. "d") or "—"

    local Weld = { destroyed = false, presetKey = PresetKey }
    CurrentWeld = Weld

    -- Cleanse any active Emote / Procedural Pack Motor6D C0 overrides so animations never conflict
    pcall(function()
        if EmoteHub then
            if EmoteHub.jerkActive and EmoteHub.StopJerk and PresetKey ~= "jerk" and PresetKey ~= "goon" then
                EmoteHub:StopJerk()
            end
            if EmoteHub.currentEmoteTrack and EmoteHub.StopEmote then
                EmoteHub:StopEmote()
            end
            if EmoteHub.procSavedMotors then
                for m, origC0 in pairs(EmoteHub.procSavedMotors) do
                    if m and m.Parent then pcall(function() m.C0 = origC0 end) end
                end
                table.clear(EmoteHub.procSavedMotors)
            end
        end
        if moveState and moveState.restoreFlyJoints then
            moveState.restoreFlyJoints(Character)
        end
        for _, d in ipairs(Character:GetDescendants()) do
            if d:IsA("Motor6D") then
                d.Enabled = true
                d.Transform = CFrame.identity
            end
        end
    end)

    local savedPackNameForRestore = (EmoteHub and (EmoteHub.currentPackName or EmoteHub.activePackName)) or nil
    local savedPackObjForRestore  = (EmoteHub and (EmoteHub.currentPack or EmoteHub.activePack)) or nil
    pcall(function() workspace.FallenPartsDestroyHeight = 0/0 end)
    pcall(function() Humanoid.Sit = false end)
    pcall(function() Humanoid.PlatformStand = true end)
    pcall(function() Humanoid.AutoRotate = false end)
    forcePhysicsState(Humanoid)
    if AnimationId ~= nil then
        killAnimate(Character)
    end

    -- Exact oyee hoye.lua animation loader (runs asynchronously so Frame-0 CFrame lock is 0.00ms,
    -- and uses ANIM_VERIFY_TIME = 0.15 so animations NEVER flicker or restart 60x/sec!)
    local AnimTrack, AnimInstance = nil, nil
    local animAttempts = 0
    local animLoading = false
    local function ensureAnim(force)
        if not AnimationId or Weld.destroyed or animLoading then return end
        if AnimTrack and not force then
            local ip = false
            pcall(function() ip = AnimTrack.IsPlaying end)
            if ip then
                pcall(function() AnimTrack:AdjustSpeed(math.clamp(V.Speed or 1.0, 0.2, 6.0)) end)
                if (PresetKey == "jerk" or PresetKey == "goon") and Humanoid.RigType == Enum.HumanoidRigType.R6 then
                    pcall(function()
                        if AnimTrack.TimePosition > 0.72 or AnimTrack.TimePosition < 0.52 then
                            AnimTrack.TimePosition = 0.58
                        end
                    end)
                end
                return
            end
        end
        animAttempts = animAttempts + 1
        if not force and animAttempts % 12 ~= 0 and AnimTrack then return end
        animLoading = true
        task.spawn(function()
            pcall(function()
                if Weld.destroyed or not Character or not Character.Parent then return end
                local Animator = Character:FindFirstChildWhichIsA("Animator", true)
                if not Animator and Humanoid then
                    Animator = Instance.new("Animator")
                    Animator.Parent = Humanoid
                end
                if not Animator then return end
                local track, anim = loadPlayableAnim(Animator, AnimationId, AnimFallbacks, Humanoid)
                if Weld.destroyed then
                    if track then pcall(function() track:Stop(0); track:Destroy() end) end
                    if anim then pcall(function() anim:Destroy() end) end
                    return
                end
                if track then
                    if AnimTrack and AnimTrack ~= track then
                        pcall(function() AnimTrack:Stop(0); AnimTrack:Destroy() end)
                    end
                    if AnimInstance and AnimInstance ~= anim then
                        pcall(function() AnimInstance:Destroy() end)
                    end
                    pcall(function() track:AdjustSpeed(math.clamp(V.Speed or 1.0, 0.2, 6.0)) end)
                    AnimTrack = track
                    AnimInstance = anim
                end
            end)
            animLoading = false
        end)
    end
    ensureAnim(true)

    -- Zero-Delay Cached Phase Noclip (from second file + Reanimation realChar support: zero per-frame GetDescendants lag!)
    local weldCachedParts = {}
    local WeldDescConn = nil
    local function rebuildWeldPartsCache(charObj)
        table.clear(weldCachedParts)
        if WeldDescConn then WeldDescConn:Disconnect(); WeldDescConn = nil end
        if not charObj then return end
        local carryingNow = hasCarriedPlayerAttached(charObj)
        for _, v in ipairs(charObj:GetDescendants()) do
            if v:IsA("BasePart") then
                weldCachedParts[#weldCachedParts + 1] = v
                v.CanCollide = false
                v.CanTouch = false
                v.CanQuery = false
                local keepMass = carryingNow and (v.Name == "HumanoidRootPart" or v.Name == "Torso" or v.Name == "LowerTorso" or v.Name == "UpperTorso")
                v.Massless = not keepMass
                v.Anchored = false
            elseif (v:IsA("SeatWeld") or v.Name == "SeatWeld") and not isCarriedPlayerJoint(v, charObj) then
                pcall(function() v:Destroy() end)
            end
        end
        local zApi = _G._AngoorZenApi
        if zApi and type(zApi.is_reanimated) == "function" and zApi.is_reanimated() and type(zApi.get_real_character) == "function" then
            local rCh = zApi.get_real_character()
            if rCh and rCh ~= charObj and rCh.Parent then
                for _, rp in ipairs(rCh:GetDescendants()) do
                    if rp:IsA("BasePart") then
                        weldCachedParts[#weldCachedParts + 1] = rp
                        rp.CanCollide = false
                        rp.CanTouch = false
                        rp.CanQuery = false
                        rp.Massless = true
                        rp.Anchored = false
                    end
                end
            end
        end
        WeldDescConn = charObj.DescendantAdded:Connect(function(v)
            if Weld.destroyed then return end
            if v:IsA("BasePart") then
                weldCachedParts[#weldCachedParts + 1] = v
                v.CanCollide = false
                v.CanTouch = false
                v.CanQuery = false
                v.Massless = true
                v.Anchored = false
            elseif v:IsA("Tool") then
                for _, tp in ipairs(v:GetDescendants()) do
                    if tp:IsA("BasePart") then
                        weldCachedParts[#weldCachedParts + 1] = tp
                        tp.CanCollide = false
                        tp.CanTouch = false
                        tp.CanQuery = false
                        tp.Massless = true
                        tp.Anchored = false
                    end
                end
            elseif (v:IsA("SeatWeld") or v.Name == "SeatWeld") and not isCarriedPlayerJoint(v, charObj) then
                pcall(function() v:Destroy() end)
            end
        end)
    end
    rebuildWeldPartsCache(Character)

    local carryCheckTick = 0
    local isCarryingCached = hasCarriedPlayerAttached(Character)
    local function applyPhaseNoclip()
        if not Character or not Character.Parent then return end
        local nowC = os.clock()
        if nowC - carryCheckTick > 0.35 then
            carryCheckTick = nowC
            isCarryingCached = hasCarriedPlayerAttached(Character)
        end
        for i = 1, #weldCachedParts do
            local v = weldCachedParts[i]
            if v and v.Parent then
                if v.CanCollide then v.CanCollide = false end
                if v.CanTouch then v.CanTouch = false end
                if v.CanQuery then v.CanQuery = false end
                local keepMass = isCarryingCached and (v.Name == "HumanoidRootPart" or v.Name == "Torso" or v.Name == "LowerTorso" or v.Name == "UpperTorso")
                if keepMass then
                    if v.Massless then v.Massless = false end
                else
                    if not v.Massless then v.Massless = true end
                end
                if v.Anchored then v.Anchored = false end
            end
        end
        if Humanoid and Humanoid.Sit then
            pcall(function() Humanoid.Sit = false end)
        end
    end
    applyPhaseNoclip()

    local Conn = nil
    local StepConn = nil
    local RenderConn = nil
    local clock = 0
    local missingFrames = 0

    -- Static height calibration for Wall Rizz (computed once per target character so it never bobs per frame!)
    local cachedRizzChar = nil
    local cachedRizzY, cachedRizzZ = 0, 0
    local function getStaticPresetAdjust()
        local adjY, adjZ = 0, 0
        if PresetKey == "rizz" and TargetChar and TargetPart then
            if cachedRizzChar ~= TargetChar then
                cachedRizzChar = TargetChar
                local yVal, _, _, zVal = computeDynamicHeightWeld(Character, Humanoid, Root, TargetChar, TargetHum, TargetPart, RefMode, "rizz")
                cachedRizzY = yVal or 0
                cachedRizzZ = zVal or 0
            end
            adjY, adjZ = cachedRizzY, cachedRizzZ
        end
        local spinYaw = (V.Spin and ((clock * 180) % 360) or 0)
        return CFrame.new(V.X or 0, (V.Y or 0) + adjY, ((V.Z or 1.3) - 1.3) + adjZ)
            * CFrame.Angles(math.rad(V.RX or 0), math.rad((V.RY or 0) + spinYaw), math.rad(V.RZ or 0))
    end

    local function checkAndHotSwapReanimCharacter()
        local curLPChar = LP and LP.Character
        if curLPChar and curLPChar.Parent and curLPChar ~= Character then
            local newRoot = curLPChar:FindFirstChild("HumanoidRootPart") or curLPChar:FindFirstChildWhichIsA("BasePart")
            local newHum  = curLPChar:FindFirstChildWhichIsA("Humanoid")
            if newRoot and newHum and isLocalCharAliveOrReanimated(curLPChar, newHum) then
                Character = curLPChar
                Root = newRoot
                Humanoid = newHum
                Root.Anchored = false
                breakAllSeatsAndExternalJoints(Character, Humanoid, Root)
                pcall(function() Humanoid.Sit = false end)
                pcall(function() Humanoid.PlatformStand = true end)
                pcall(function() Humanoid.AutoRotate = false end)
                forcePhysicsState(Humanoid)
                killAnimate(Character)
                rebuildWeldPartsCache(Character)
                applyPhaseNoclip()
                if AnimTrack then
                    pcall(function() AnimTrack:Stop(0); AnimTrack:Destroy() end)
                    AnimTrack = nil
                end
                ensureAnim(true)
                return true
            end
        end
        return false
    end

    -- Track the last verified on-map anchor CFrame of the target so if they throw their Head/body into the void,
    -- we stay connected RIGHT THERE on the map instead of ever being dragged into the void!
    local lastTargetSafeAnchorCF = (TargetPart and TargetPart.Parent and isPartInSafeWorldBounds(TargetPart) and not isPartDetachedOrThrown(TargetPart, TargetChar)) and TargetPart.CFrame or nil

    -- Zero-Delay CFrame + Anti-Head-Void-Throw + Voice-Tag Anchor + Void-Proof PhysicsRepRootPart Lock
    local function stepExactOyeeHoyeWeld()
        if Weld.destroyed then return end
        if Character ~= LP.Character then
            checkAndHotSwapReanimCharacter()
        end
        if not Root or not Root.Parent then return end
        local targetPartUnsafe = (not TargetPart or not TargetPart.Parent or not isPartInSafeWorldBounds(TargetPart) or isPartDetachedOrThrown(TargetPart, TargetChar))
        if targetPartUnsafe then
            -- Target threw their Head or limb toward the void! Immediately switch to their safe on-map body/HRP/VoiceTag!
            local rescued = nil
            if TargetChar and TargetChar.Parent then
                rescued = pickTargetRef(TargetChar, RefMode or "torso", TargetPlayer)
                if rescued and (rescued == TargetPart or isPartDetachedOrThrown(rescued, TargetChar)) then
                    rescued = nil
                end
            end
            if not rescued and TargetPlayer then
                local vPart, vModel = findPlayerVoiceTagAnchor(TargetPlayer, TargetChar)
                if vPart and vPart.Parent and isPartInSafeWorldBounds(vPart) and not isPartDetachedOrThrown(vPart, vModel or TargetChar) then
                    rescued = vPart
                    if vModel and vModel.Parent then
                        TargetChar = vModel
                        TargetHum = vModel:FindFirstChildOfClass("Humanoid")
                    end
                end
            end
            if rescued and rescued.Parent and isPartInSafeWorldBounds(rescued) then
                TargetPart = rescued
                cachedRizzChar = nil
            else
                -- All target parts are momentarily in void/thrown: STAY CONNECTED RIGHT THERE at lastTargetSafeAnchorCF!
                if sethiddenproperty then
                    pcall(function() sethiddenproperty(Root, "PhysicsRepRootPart", nil) end)
                    pcall(function() sethiddenproperty(Root, "PhysicsRepRootRef", nil) end)
                end
                local holdAnchor = (lastTargetSafeAnchorCF and isSafePlayableCF(lastTargetSafeAnchorCF)) and lastTargetSafeAnchorCF
                    or (lastSafeCF and isSafePlayableCF(lastSafeCF) and lastSafeCF)
                if holdAnchor then
                    local holdCF = getFlatYawCFrame(holdAnchor, holdAnchor.Position) * Offset * getStaticPresetAdjust()
                    if not isLethalVoidCF(holdCF) then
                        Root.Anchored = false
                        Root.CFrame = holdCF
                        Root.AssemblyLinearVelocity = Vector3.zero
                        Root.AssemblyAngularVelocity = Vector3.zero
                        syncAllActiveReanimRoots(holdCF, Root)
                        markIntentionalTeleport(holdCF)
                    end
                end
                return
            end
        end
        local tVel = TargetPart.AssemblyLinearVelocity
        if isLethalVoidCF(TargetPart.CFrame, tVel) or isPartDetachedOrThrown(TargetPart, TargetChar) then
            if sethiddenproperty then
                pcall(function() sethiddenproperty(Root, "PhysicsRepRootPart", nil) end)
                pcall(function() sethiddenproperty(Root, "PhysicsRepRootRef", nil) end)
            end
            return
        end
        -- Record last verified safe on-map anchor CFrame (only when stable & non-falling)
        if isSafePlayableCF(TargetPart.CFrame) and math.abs(tVel.Y) < 45 and tVel.Magnitude < 160 then
            lastTargetSafeAnchorCF = TargetPart.CFrame
        end

        local customAdjust = getStaticPresetAdjust()
        local voiceDropY = getVoiceTagHeightDropY(TargetPart, TargetChar, RefMode, PresetKey)
        local sideMode = V.SideMode or "auto"
        local distAdd  = V.DistAdd or 0
        local effOffset = Offset
        if sideMode == "front" then
            local ox, oy, oz = Offset.Position.X, Offset.Position.Y, Offset.Position.Z
            local d = math.max(0.4, math.abs(oz) + distAdd)
            effOffset = CFrame.new(ox, oy, -d) * CFrame.Angles(0, math.rad(180), 0)
        elseif sideMode == "back" then
            local ox, oy, oz = Offset.Position.X, Offset.Position.Y, Offset.Position.Z
            local d = math.max(0.4, math.abs(oz) + distAdd)
            effOffset = CFrame.new(ox, oy, d)
        elseif distAdd ~= 0 then
            local oz = Offset.Position.Z
            local signZ = (oz < 0) and -1 or 1
            effOffset = CFrame.new(0, 0, signZ * distAdd) * Offset
        end
        local localOffset = (voiceDropY ~= 0 and (CFrame.new(0, voiceDropY, 0) * effOffset) or effOffset) * customAdjust
        if Osc and Osc.period and Osc.period > 0 then
            local phase = (math.sin(clock * (2 * math.pi) / Osc.period) + 1) * 0.5
            localOffset = localOffset * CFrame.new(0, 0, -Osc.distance * phase)
        end
        local attachCF
        if PresetKey == "goon" and sideMode == "auto" then
            -- Exact Face-to-Face Lock: uses safe Head if attached, or virtual Head above safe body if Head was thrown into void!
            local rawHead = TargetChar and TargetChar:FindFirstChild("Head")
            local safeHead = (rawHead and isPartInSafeWorldBounds(rawHead) and not isPartDetachedOrThrown(rawHead, TargetChar)) and rawHead or nil
            local tHead = safeHead or TargetPart
            local headPos = safeHead and safeHead.Position or (TargetPart.Position + Vector3.new(0, 1.5, 0))
            local flatHeadCF = getFlatYawCFrame(tHead.CFrame, headPos)
            local myHead = Character and Character:FindFirstChild("Head")
            local myHeadToRootY = 1.45
            if myHead and Root then
                local dy = myHead.Position.Y - Root.Position.Y
                if dy > 0.3 and dy < 4.5 then myHeadToRootY = dy end
            end
            local exactPos = (flatHeadCF * CFrame.new(0, -myHeadToRootY, -math.max(0.4, 1.65 + distAdd)) * customAdjust).Position
            local faceTargetPt = Vector3.new(tHead.Position.X, exactPos.Y, tHead.Position.Z)
            local extraYaw = math.rad((V.RY or 0) + (V.Spin and ((clock * 180) % 360) or 0))
            if (faceTargetPt - exactPos).Magnitude > 0.05 then
                attachCF = CFrame.lookAt(exactPos, faceTargetPt, Vector3.yAxis) * CFrame.Angles(0, extraYaw, 0)
            else
                attachCF = flatHeadCF * CFrame.new(0, -myHeadToRootY, -1.65) * CFrame.Angles(0, math.rad(180) + extraYaw, 0) * customAdjust
            end
        elseif PresetKey == "poop" and sideMode == "auto" then
            -- Directly Above & In Front of Target's Head, facing BACKWARDS (uses virtual Head if real Head was thrown into void!)
            local rawHead = TargetChar and TargetChar:FindFirstChild("Head")
            local safeHead = (rawHead and isPartInSafeWorldBounds(rawHead) and not isPartDetachedOrThrown(rawHead, TargetChar)) and rawHead or nil
            local tHead = safeHead or TargetPart
            local headPos = safeHead and safeHead.Position or (TargetPart.Position + Vector3.new(0, 1.5, 0))
            local flatHeadCF = getFlatYawCFrame(tHead.CFrame, headPos)
            local poopPos = (flatHeadCF * CFrame.new(0, 2.35, -math.max(0.2, 0.85 + distAdd)) * customAdjust).Position
            local lookPt = Vector3.new(tHead.Position.X, poopPos.Y, tHead.Position.Z)
            local extraYaw = math.rad((V.RY or 0) + (V.Spin and ((clock * 180) % 360) or 0))
            if (lookPt - poopPos).Magnitude > 0.05 then
                attachCF = CFrame.lookAt(poopPos, lookPt, Vector3.yAxis) * CFrame.Angles(0, math.rad(180) + extraYaw, 0)
            else
                attachCF = flatHeadCF * CFrame.new(0, 2.35, -0.85) * CFrame.Angles(0, extraYaw, 0) * customAdjust
            end
        elseif sideMode ~= "auto" or PresetKey == "selfanim" or PresetKey == "finger" or TargetPart.Name ~= "HumanoidRootPart" then
            attachCF = getFlatYawCFrame(TargetPart.CFrame, TargetPart.Position) * localOffset
        else
            attachCF = TargetPart.CFrame * localOffset
        end
        -- Final hard void gate: NEVER write a void/NaN/sky-dump CFrame to our own Root!
        if isLethalVoidCF(attachCF, tVel) then
            if sethiddenproperty then
                pcall(function() sethiddenproperty(Root, "PhysicsRepRootPart", nil) end)
                pcall(function() sethiddenproperty(Root, "PhysicsRepRootRef", nil) end)
            end
            return
        end
        Root.Anchored = false
        Root.CFrame = attachCF
        local microWake = Vector3.new(0, math.sin(clock * 24) * 0.03, 0)
        Root.AssemblyLinearVelocity = (tVel.Magnitude < 250 and (tVel * 0.85) or Vector3.zero) + microWake
        Root.AssemblyAngularVelocity = Vector3.zero
        syncAllActiveReanimRoots(attachCF, Root)
        markIntentionalTeleport(attachCF)
        pcall(function() LP.ReplicationFocus = TargetPart end)
        if sethiddenproperty then
            pcall(function()
                -- Only bind PhysicsRepRootPart when TargetPart is stable & well above void floor (prevents reanim/limb-remover rubberbanding into void!)
                if tVel.Magnitude < 200 and TargetPart.Position.Y > (OriginalFPDH + 35) then
                    sethiddenproperty(Root, "PhysicsRepRootPart", TargetPart)
                    if InstanceHandleNew then
                        sethiddenproperty(Root, "PhysicsRepRootRef", InstanceHandleNew(TargetPart))
                    end
                else
                    sethiddenproperty(Root, "PhysicsRepRootPart", nil)
                    sethiddenproperty(Root, "PhysicsRepRootRef", nil)
                end
                sethiddenproperty(Root, "NetworkIsSleeping", false)
            end)
        end
    end

    -- 0.00ms Zero-Delay Target Hot-Swap (used by ALL Players Cycle so switching players never restarts animations or unbinds RenderStep!)
    function Weld:SwitchTargetZeroDelay(newTargetPart, newTargetChar, newTargetHum, newTargetPlayer)
        if self.destroyed then return false end
        if not newTargetPart or not newTargetPart.Parent or not newTargetPlayer or newTargetPlayer.Parent ~= Players then
            return false
        end
        TargetPart   = newTargetPart
        TargetChar   = newTargetChar or newTargetPart.Parent
        TargetHum    = newTargetHum or (TargetChar and TargetChar:FindFirstChildOfClass("Humanoid"))
        TargetPlayer = newTargetPlayer
        targetUid    = newTargetPlayer.UserId
        targetName   = newTargetPlayer.Name or "Target"
        targetDisp   = newTargetPlayer.DisplayName or targetName
        targetAge    = tostring(newTargetPlayer.AccountAge or "—") .. "d"
        missingFrames = 0
        cachedRizzChar = nil
        stepExactOyeeHoyeWeld()
        return true
    end

    function Weld:Destroy(skipReturn)
        if self.destroyed then return end
        self.destroyed = true
        pcall(function() RunService:UnbindFromRenderStep("CocoWeldZeroDelayPreCam") end)
        pcall(function() RunService:UnbindFromRenderStep("CocoWeldZeroDelayLock") end)
        if WeldDescConn then WeldDescConn:Disconnect(); WeldDescConn = nil end
        if Conn then Conn:Disconnect(); Conn = nil end
        if RenderConn then RenderConn:Disconnect(); RenderConn = nil end
        if StepConn then StepConn:Disconnect(); StepConn = nil end
        pcall(function() LP.ReplicationFocus = nil end)
        if Root and sethiddenproperty then
            pcall(function() sethiddenproperty(Root, "PhysicsRepRootPart", nil) end)
            pcall(function() sethiddenproperty(Root, "PhysicsRepRootRef", nil) end)
        end
        if AnimTrack then
            pcall(function() AnimTrack:Stop(0) end)
            pcall(function() AnimTrack:Destroy() end)
            AnimTrack = nil
        end
        if AnimInstance then
            pcall(function() AnimInstance:Destroy() end)
            AnimInstance = nil
        end
        if CurrentWeld == self then
            CurrentWeld = nil
        end
        -- Restore Animate & Humanoid state so stopping Bang / Weld NEVER leaves our character animation dead!
        pcall(function() restoreAnimate(Character) end)
        if LP.Character and LP.Character ~= Character then
            pcall(function() restoreAnimate(LP.Character) end)
        end
        pcall(function()
            if Humanoid and Humanoid.Parent then
                Humanoid.PlatformStand = false
                Humanoid.AutoRotate = true
                Humanoid.Sit = false
                if Humanoid.Health > 0 then
                    Humanoid:ChangeState(Enum.HumanoidStateType.Running)
                end
            end
        end)
        if EmoteHub and (savedPackNameForRestore or savedPackObjForRestore) then
            task.defer(function()
                task.wait(0.08)
                if CurrentWeld ~= nil then return end
                pcall(function()
                    if type(EmoteHub.ApplyPack) == "function" then
                        if savedPackNameForRestore then
                            EmoteHub:ApplyPack(savedPackNameForRestore)
                        elseif savedPackObjForRestore then
                            EmoteHub:ApplyPack(savedPackObjForRestore)
                        end
                    elseif type(EmoteHub.ReapplyCurrentPack) == "function" then
                        EmoteHub:ReapplyCurrentPack()
                    end
                end)
            end)
        end
        if not skipReturn then
            LastVoidActionEnd = tick()
            local returnCF = (PreSeekSafeCF and typeof(PreSeekSafeCF) == "CFrame" and isSafePlayableCF(PreSeekSafeCF)) and PreSeekSafeCF or lastSafeCF
            safeReturnFromVoid(Character, returnCF)
            if LP.Character and LP.Character ~= Character then
                safeReturnFromVoid(LP.Character, returnCF)
            end
        end
    end

    -- Frame-0 Immediate Zero-Delay Lock (0.00ms!)
    stepExactOyeeHoyeWeld()

    pcall(function() RunService:UnbindFromRenderStep("CocoWeldZeroDelayPreCam") end)
    pcall(function() RunService:UnbindFromRenderStep("CocoWeldZeroDelayLock") end)
    pcall(function()
        RunService:BindToRenderStep("CocoWeldZeroDelayPreCam", Enum.RenderPriority.Camera.Value - 1, stepExactOyeeHoyeWeld)
    end)
    pcall(function()
        RunService:BindToRenderStep("CocoWeldZeroDelayLock", Enum.RenderPriority.Character.Value + 1, stepExactOyeeHoyeWeld)
    end)

    -- Stepped pass ensures we phase through walls, doors, roofs, and seats inside any hiding spot (exact oyee hoye.lua + zero-delay lock)
    StepConn = RunService.Stepped:Connect(function()
        if Weld.destroyed then return end
        applyPhaseNoclip()
        stepExactOyeeHoyeWeld()
    end)

    -- RenderStepped pass guarantees zero-jitter visual lock on every rendered frame
    RenderConn = RunService.RenderStepped:Connect(function()
        if Weld.destroyed then return end
        stepExactOyeeHoyeWeld()
    end)

    -- Heartbeat pass: exact oyee hoye.lua L682–792 logic!
    Conn = RunService.Heartbeat:Connect(function(dt)
        if Character ~= LP.Character then
            checkAndHotSwapReanimCharacter()
        end
        -- 1. Check if our own character died or respawned
        if not Character.Parent or Character ~= LP.Character or not Root.Parent or not Humanoid.Parent or not isLocalCharAliveOrReanimated(Character, Humanoid) then
            Weld:Destroy(false)
            return
        end

        -- 2. Check if target player left the server completely
        if TargetPlayer and TargetPlayer.Parent ~= Players then
            local savedKey = PresetKey or WeldIntent.presetKey or LastPresetKey or "facebang"
            WeldIntent.leftInfo = {
                userId = targetUid,
                name = targetName,
                displayName = targetDisp,
                accountAge = targetAge or "—",
                friendsText = "LEFT GAME",
                leftAt = tick(),
                wasWelded = true,
                presetKey = savedKey,
            }
            if WeldIntent.allMode and type(_G.CocoAdvanceAllPlayersCycle) == "function" then
                local switched = _G.CocoAdvanceAllPlayersCycle(true, targetName)
                if switched then
                    return
                end
            end
            WeldIntent.typedUsername = targetName
            if WeldIntent.setUsernameBoxText then pcall(WeldIntent.setUsernameBoxText, targetName) end
            WeldIntent.active = false
            WeldIntent.target = nil
            WeldIntent.waitingForSpawn = true
            WeldIntent.topStatusText = "target left · @" .. targetName .. " has left"
            WeldIntent.topStatusColor = T.Danger
            WeldIntent.midStatusText = "🚨 " .. targetDisp .. " (@" .. targetName .. ") has left"
            WeldIntent.midStatusColor = T.Danger
            WeldIntent.bottomStatusText = "name kept in panel until changed · auto-attaches if they rejoin"
            WeldIntent.bottomStatusColor = T.Warning
            Weld:Destroy(false)
            if syncAllActiveIndicators then pcall(syncAllActiveIndicators) end
            if WeldIntent.refreshUI then pcall(WeldIntent.refreshUI) end
            showOwnerScreenBanner(
                "🚨 TARGET HAS LEFT THE GAME",
                "@" .. targetName .. " (" .. targetDisp .. ") left — name kept in panel until changed",
                T.Danger,
                4.5,
                "TargetLeftBanner"
            )
            notify("COCO POWDER", "Target @" .. targetName .. " has left — kept in panel until changed!")
            return
        end

        -- 3. Check if target died (keep connected if target's Voice Tag anchor or reanim rig is still alive & safe!)
        if TargetHum and TargetHum.Parent and TargetHum.Health <= 0 then
            local vAnchor, vModel = TargetPlayer and findPlayerVoiceTagAnchor(TargetPlayer, TargetChar)
            local reanimChar = (vModel and vModel.Parent and vModel) or (TargetPlayer and findTargetReanimModel(TargetPlayer))
            if vAnchor and vAnchor.Parent and isPartInSafeWorldBounds(vAnchor) then
                TargetPart = vAnchor
                if reanimChar and reanimChar.Parent then
                    TargetChar = reanimChar
                    TargetHum  = reanimChar:FindFirstChildOfClass("Humanoid")
                end
                missingFrames = 0
            elseif reanimChar and reanimChar ~= TargetChar then
                local rPart = pickTargetRef(reanimChar, RefMode or "torso", TargetPlayer)
                if rPart and rPart.Parent then
                    TargetChar = reanimChar
                    TargetHum  = reanimChar:FindFirstChildOfClass("Humanoid")
                    TargetPart = rPart
                    missingFrames = 0
                else
                    WeldIntent.waitingForSpawn = true
                    Weld:Destroy(false)
                    return
                end
            elseif isCharacterNetlessReanimated and isCharacterNetlessReanimated(TargetChar) then
                local liveRef = pickTargetRef(TargetChar, RefMode or "torso", TargetPlayer)
                if liveRef and liveRef.Parent then
                    TargetPart = liveRef
                    missingFrames = 0
                else
                    WeldIntent.waitingForSpawn = true
                    Weld:Destroy(false)
                    return
                end
            else
                WeldIntent.waitingForSpawn = true
                WeldIntent.topStatusText = "target respawning · waiting"
                WeldIntent.topStatusColor = T.Warning
                WeldIntent.midStatusText = "respawning · " .. targetName
                WeldIntent.midStatusColor = T.Warning
                WeldIntent.bottomStatusText = "target respawning · will attach on spawn"
                WeldIntent.bottomStatusColor = T.Warning
                if WeldIntent.refreshUI then pcall(WeldIntent.refreshUI) end
                Weld:Destroy(false)
                return
            end
        end

        -- 3b. CONNECT MODE LOCK (Voice Tag Connect vs Normal Safe Body/Head):
        --     • In Voice Tag mode (V.ConnectMode == "voicetag" or RefMode == "voicetag"): strictly lock to Voice Tag anchor!
        --     • In Normal Body mode (default): keep exact Head for head presets (e.g. facebang) & exact safe Body for torso presets,
        --       while still instantly switching to Voice Tag / Head if TargetPart ever drops into void or desyncs!
        if TargetPlayer then
            local wantVoiceTag = (RefMode == "voicetag") or (V and V.ConnectMode == "voicetag")
            if wantVoiceTag then
                local liveVoicePart, liveVoiceModel = findPlayerVoiceTagAnchor(TargetPlayer, TargetChar)
                if liveVoicePart and liveVoicePart.Parent and liveVoicePart ~= TargetPart and isPartInSafeWorldBounds(liveVoicePart) then
                    TargetPart = liveVoicePart
                    if liveVoiceModel and liveVoiceModel.Parent then
                        TargetChar = liveVoiceModel
                        TargetHum  = liveVoiceModel:FindFirstChildOfClass("Humanoid")
                    end
                    cachedRizzChar = nil
                end
            elseif RefMode == "head" and TargetPart and TargetPart.Name ~= "Head" and TargetChar then
                local exactHead = TargetChar:FindFirstChild("Head") or TargetChar:FindFirstChild("head", true)
                if exactHead and exactHead:IsA("BasePart") and isPartInSafeWorldBounds(exactHead) and not isPartDetachedOrThrown(exactHead, TargetChar) then
                    TargetPart = exactHead
                    cachedRizzChar = nil
                end
            end
        end

        -- 4. OMNIPRESENT RE-LOCK (Voice-Tag, Reanim, Limb-Remover, FE Invisibility & Streaming-Aware):
        --    Dynamically re-acquires if TargetPart streamed out, became desynced/voided (FE Invis/Reanim/Limb Remover),
        --    or if the target switched to a reanimation clone rig or new character model!
        if not TargetPart or not TargetPart.Parent or (isRefPartValid and not isRefPartValid(TargetPart, TargetChar, TargetPlayer)) or (TargetPlayer and findPlayerCharacterAnywhere(TargetPlayer) ~= TargetChar and not (findPlayerVoiceTagAnchor(TargetPlayer, TargetChar) == TargetPart)) then
            if TargetPlayer then
                local vPart, vModel = findPlayerVoiceTagAnchor(TargetPlayer, TargetChar)
                if vPart and vPart.Parent and isPartInSafeWorldBounds(vPart) then
                    TargetPart = vPart
                    if vModel and vModel.Parent then
                        TargetChar = vModel
                        TargetHum  = vModel:FindFirstChildOfClass("Humanoid")
                    end
                    missingFrames = 0
                else
                    local newChar = findPlayerCharacterAnywhere(TargetPlayer)
                    local newHum  = newChar and newChar:FindFirstChildOfClass("Humanoid")
                    if newHum and newHum.Health <= 0 and not (isCharacterNetlessReanimated and isCharacterNetlessReanimated(newChar)) then
                        local altReanim = findTargetReanimModel and findTargetReanimModel(TargetPlayer)
                        if altReanim and altReanim.Parent then
                            newChar = altReanim
                            newHum = altReanim:FindFirstChildOfClass("Humanoid")
                        else
                            WeldIntent.waitingForSpawn = true
                            Weld:Destroy(false)
                            return
                        end
                    end
                    local newPart = newChar and pickTargetRef(newChar, RefMode or "torso", TargetPlayer)
                    if newPart and newPart.Parent and isPartInSafeWorldBounds(newPart) then
                        TargetChar = newChar
                        TargetHum  = newHum
                        TargetPart = newPart
                        missingFrames = 0
                    else
                        -- Target is unstreamed or all real body parts are in the void! Hold safe CFrame and stream without entering void!
                        missingFrames = missingFrames + 1
                        local hiddenCF = getBestTargetCFrame(TargetPlayer)
                        if hiddenCF and isSafePlayableCF(hiddenCF) and not isLethalVoidCF(hiddenCF) then
                            pcall(function() LP:RequestStreamAroundAsync(hiddenCF.Position, 1) end)
                            local destCF = hiddenCF * Offset
                            if not isLethalVoidCF(destCF) then
                                Root.CFrame = destCF
                                Root.AssemblyLinearVelocity = Vector3.zero
                                Root.AssemblyAngularVelocity = Vector3.zero
                                syncAllActiveReanimRoots(destCF, Root)
                                markIntentionalTeleport(Root.CFrame)
                            end
                        elseif lastSafeCF and isSafePlayableCF(lastSafeCF) then
                            Root.CFrame = lastSafeCF
                            Root.AssemblyLinearVelocity = Vector3.zero
                            Root.AssemblyAngularVelocity = Vector3.zero
                            syncAllActiveReanimRoots(lastSafeCF, Root)
                        end
                        if missingFrames > 180 then
                            WeldIntent.waitingForSpawn = true
                            Weld:Destroy(false)
                        end
                        return
                    end
                end
            else
                Weld:Destroy(false)
                return
            end
        else
            missingFrames = 0
        end

        -- 5. ANTI-HEAD-VOID-THROW & STAY-CONNECTED PROTECTION:
        --    If TargetPart (e.g. Head thrown into void by Limb Remover / Reanim) detaches or enters void,
        --    immediately switch to the player's safe on-map body/HRP/Voice Tag and KEEP WELD CONNECTED RIGHT THERE!
        local tVel = TargetPart.AssemblyLinearVelocity
        if not isPartInSafeWorldBounds(TargetPart) or isLethalVoidCF(TargetPart.CFrame, tVel) or isPartDetachedOrThrown(TargetPart, TargetChar) then
            local rescuePart = TargetChar and pickTargetRef(TargetChar, RefMode or "torso", TargetPlayer)
            if rescuePart and (rescuePart == TargetPart or isPartDetachedOrThrown(rescuePart, TargetChar)) then
                rescuePart = nil
            end
            if not rescuePart and TargetPlayer then
                local vP = select(1, findPlayerVoiceTagAnchor(TargetPlayer, TargetChar))
                if vP and vP ~= TargetPart and isPartInSafeWorldBounds(vP) and not isPartDetachedOrThrown(vP, TargetChar) then
                    rescuePart = vP
                end
            end
            if not rescuePart and TargetPlayer then
                local altChar = findTargetReanimModel and findTargetReanimModel(TargetPlayer)
                if altChar and altChar.Parent then
                    TargetChar = altChar
                    TargetHum = altChar:FindFirstChildOfClass("Humanoid")
                    rescuePart = pickTargetRef(altChar, RefMode or "torso", TargetPlayer)
                end
            end
            if rescuePart and rescuePart.Parent and isPartInSafeWorldBounds(rescuePart) and not isPartDetachedOrThrown(rescuePart, TargetChar) then
                TargetPart = rescuePart
                tVel = TargetPart.AssemblyLinearVelocity
                cachedRizzChar = nil
            elseif lastTargetSafeAnchorCF and isSafePlayableCF(lastTargetSafeAnchorCF) then
                -- Stay connected right there at their safe map position instead of following their Head into the void!
                if sethiddenproperty then
                    pcall(function() sethiddenproperty(Root, "PhysicsRepRootPart", nil) end)
                    pcall(function() sethiddenproperty(Root, "PhysicsRepRootRef", nil) end)
                end
                local speedMult = math.clamp(V.Speed or 1.0, 0.2, 6.0)
                clock = clock + (dt * speedMult)
                stepExactOyeeHoyeWeld()
                pcall(function() ensureAnim(false) end)
                return
            else
                Weld:Destroy(false)
                notify("COCO POWDER", "Target dropped into Void — stayed safe & detached!")
                return
            end
        end

        -- Keep server streaming focused on the target so they can never outrun our client stream
        pcall(function() LP.ReplicationFocus = TargetPart end)
        ensureTargetVisibleOnClient(TargetPlayer, TargetChar)

        -- Cache target location & update safe standing CFrame ONLY when strictly safe & non-flinging!
        if TargetPlayer then
            PlayerLocationCache[TargetPlayer.UserId] = { cf = TargetPart.CFrame, time = tick(), verified = true }
            WeldIntent.waitingForSpawn = false
        end
        if isSafePlayableCF(TargetPart.CFrame) and not isLethalVoidCF(TargetPart.CFrame, tVel) and math.abs(tVel.Y) < 35 and tVel.Magnitude < 120 and TargetPart.Position.Y > (OriginalFPDH + 35) then
            local _, yYaw, _ = TargetPart.CFrame:ToEulerAnglesYXZ()
            lastSafeCF = CFrame.new(TargetPart.Position + Vector3.new(0, 2.5, 0)) * CFrame.Angles(0, yYaw, 0)
            LastKnownSafeCF = lastSafeCF
        end

        local animate = Character:FindFirstChild("Animate")
        if animate and not animate.Disabled then
            animate.Disabled = true
            AnimateWasDisabled = true
        end

        local speedMult = math.clamp(V.Speed or 1.0, 0.2, 6.0)
        clock = clock + (dt * speedMult)
        stepExactOyeeHoyeWeld()
        pcall(function() ensureAnim(false) end)
        pcall(function() if not Humanoid.PlatformStand then Humanoid.PlatformStand = true end end)
    end)

    return Weld
end

local function unweld(skipReturn)
    if CurrentWeld then
        pcall(function() CurrentWeld:Destroy(skipReturn) end)
        CurrentWeld = nil
    end
    if not skipReturn and LP.Character then
        pcall(function() safeReturnFromVoid(LP.Character, LastKnownSafeCF) end)
    end
    local reanimActiveNow = (_G.CocaSkyDestroyer and (_G.CocaSkyDestroyer.isAnyActive() or _G.CocaSkyDestroyer.is_reanimated()))
        or (_G._AngoorZenApi and type(_G._AngoorZenApi.is_reanimated) == "function" and _G._AngoorZenApi.is_reanimated())
    if not reanimActiveNow and not (Anti and Anti.Void and Anti.Void.enabled) and not (Anti and Anti.Kill and Anti.Kill.enabled) then
        pcall(function() workspace.FallenPartsDestroyHeight = OriginalFPDH end)
    end
end

