    local ResolvedPackAnimCache = {}
    local function resolveCatalogAnimUri(idStr)
        local digits = tostring(idStr or ""):gsub("%D", "")
        if digits == "" then return nil end
        if ResolvedPackAnimCache[digits] then
            return ResolvedPackAnimCache[digits]
        end
        local uri = "rbxassetid://" .. digits
        -- Unwrap Catalog Animation Asset IDs that wrap an Animation instance (common in 2024-2026 UGC packs)
        if #digits >= 12 and typeof(game.GetObjects) == "function" then
            pcall(function()
                local objs = game:GetObjects(uri)
                if objs and #objs > 0 then
                    local first = objs[1]
                    if first:IsA("Animation") and first.AnimationId ~= "" then
                        uri = first.AnimationId
                    else
                        local inner = first:FindFirstChildWhichIsA("Animation", true)
                        if inner and inner.AnimationId ~= "" then
                            uri = inner.AnimationId
                        end
                    end
                    pcall(function() first:Destroy() end)
                end
            end)
        end
        ResolvedPackAnimCache[digits] = uri
        return uri
    end

    local function setAnimChildId(animateScript, folderName, childName, idStr)
        if not animateScript or not idStr then return end
        local folder = animateScript:FindFirstChild(folderName)
        if not folder then return end
        local uri = resolveCatalogAnimUri(idStr)
        if not uri then return end
        local animObj = (childName and folder:FindFirstChild(childName)) or folder:FindFirstChildOfClass("Animation")
        if animObj and animObj:IsA("Animation") then
            animObj.AnimationId = uri
        else
            for _, child in ipairs(folder:GetChildren()) do
                if child:IsA("Animation") then
                    child.AnimationId = uri
                end
            end
        end
    end

    function EmoteHub:SaveDefaultPack(char)
        char = char or LP.Character
        local animate = char and char:FindFirstChild("Animate")
        if not animate or self.savedDefaultPack then return end
        local snap = {}
        for _, folder in ipairs(animate:GetChildren()) do
            snap[folder.Name] = {}
            for _, a in ipairs(folder:GetChildren()) do
                if a:IsA("Animation") then
                    snap[folder.Name][a.Name] = a.AnimationId
                end
            end
        end
        self.savedDefaultPack = snap
    end

    function EmoteHub:StopProceduralPack()
        if self.procPackConn then
            self.procPackConn:Disconnect()
            self.procPackConn = nil
        end
        self.procPackMode = nil
        if self.procSavedMotors then
            for m, origC0 in pairs(self.procSavedMotors) do
                if m and m.Parent then
                    pcall(function() m.C0 = origC0 end)
                end
            end
            table.clear(self.procSavedMotors)
        end
    end

    function EmoteHub:StartProceduralPack(mode)
        self:StopProceduralPack()
        if not mode or mode == "" then return end
        self.procPackMode = mode
        self.procSavedMotors = self.procSavedMotors or {}
        local clock = 0
        self.procPackConn = RunService.RenderStepped:Connect(function(dt)
            -- Pause procedural Motor6D C0 overrides while welded, copying animations, or in Coca Bang lock so animations NEVER flicker or twist!
            if CurrentWeld ~= nil or WeldSeekingTarget or (WeldIntent and WeldIntent.active) or _G.CocaBangActive or _G.CocaCopierActive or (AnimCopySys and AnimCopySys.active) then
                if self.procSavedMotors and next(self.procSavedMotors) ~= nil then
                    for m, origC0 in pairs(self.procSavedMotors) do
                        if m and m.Parent then
                            pcall(function() m.C0 = origC0 end)
                        end
                    end
                    table.clear(self.procSavedMotors)
                end
                return
            end
            local ch = LP.Character
            local hum = ch and ch:FindFirstChildOfClass("Humanoid")
            if not ch or not hum or hum.Health <= 0 then return end
            local moveMag = hum.MoveDirection.Magnitude
            local inAir = (hum.FloorMaterial == Enum.Material.Air)
            local r15 = (hum.RigType == Enum.HumanoidRigType.R15)
            local rate = (moveMag > 0.05) and math.clamp(hum.WalkSpeed / 16, 0.75, 2.8) or 1.0
            clock = clock + dt * rate

            local function poseMotor(parentPart, motorName, offsetCF)
                if not parentPart then return end
                local m = parentPart:FindFirstChild(motorName)
                if m and m:IsA("Motor6D") then
                    if not self.procSavedMotors[m] then
                        self.procSavedMotors[m] = m.C0
                    end
                    m.C0 = self.procSavedMotors[m] * offsetCF
                end
            end

            if mode == "dog" or mode == "wolf" or mode == "cat" then
                local freq = (moveMag > 0.05) and 11.0 or 2.6
                local s = math.sin(clock * freq)
                local c = math.cos(clock * freq)
                local stride = (moveMag > 0.05) and (s * 48) or (s * 4)
                local wag = (mode == "cat") and (math.sin(clock * 3.2) * 14) or (math.sin(clock * 8.5) * 18)
                local bob = (moveMag > 0.05) and (math.abs(c) * 0.22) or (math.sin(clock * 2.5) * 0.06)
                local leapPitch = inAir and 22 or 0
                if r15 then
                    poseMotor(ch:FindFirstChild("LowerTorso"), "Root", CFrame.new(0, -1.22 + bob, 0) * CFrame.Angles(math.rad(-78 + leapPitch), 0, math.rad(wag * 0.35)))
                    poseMotor(ch:FindFirstChild("UpperTorso"), "Waist", CFrame.Angles(math.rad(-8), math.rad(-wag * 0.4), 0))
                    poseMotor(ch:FindFirstChild("Head"), "Neck", CFrame.Angles(math.rad(68 + math.sin(clock * 3) * 5), math.rad(wag * 0.3), 0))
                    poseMotor(ch:FindFirstChild("LeftUpperArm"), "LeftShoulder", CFrame.Angles(math.rad(78 + stride), 0, math.rad(-8)))
                    poseMotor(ch:FindFirstChild("RightUpperArm"), "RightShoulder", CFrame.Angles(math.rad(78 - stride), 0, math.rad(8)))
                    poseMotor(ch:FindFirstChild("LeftLowerArm"), "LeftElbow", CFrame.Angles(math.rad(22 + math.max(0, -s) * 28), 0, 0))
                    poseMotor(ch:FindFirstChild("RightLowerArm"), "RightElbow", CFrame.Angles(math.rad(22 + math.max(0, s) * 28), 0, 0))
                    poseMotor(ch:FindFirstChild("LeftUpperLeg"), "LeftHip", CFrame.Angles(math.rad(72 - stride), 0, math.rad(-8)))
                    poseMotor(ch:FindFirstChild("RightUpperLeg"), "RightHip", CFrame.Angles(math.rad(72 + stride), 0, math.rad(8)))
                    poseMotor(ch:FindFirstChild("LeftLowerLeg"), "LeftKnee", CFrame.Angles(math.rad(-35 - math.max(0, s) * 30), 0, 0))
                    poseMotor(ch:FindFirstChild("RightLowerLeg"), "RightKnee", CFrame.Angles(math.rad(-35 - math.max(0, -s) * 30), 0, 0))
                else
                    local torso = ch:FindFirstChild("Torso")
                    poseMotor(ch:FindFirstChild("HumanoidRootPart"), "RootJoint", CFrame.new(0, 0, -1.22 + bob) * CFrame.Angles(math.rad(78 - leapPitch), math.rad(wag * 0.35), 0))
                    poseMotor(torso, "Neck", CFrame.Angles(math.rad(-68 - math.sin(clock * 3) * 5), 0, 0))
                    poseMotor(torso, "Left Shoulder", CFrame.Angles(0, 0, math.rad(-82 - stride)))
                    poseMotor(torso, "Right Shoulder", CFrame.Angles(0, 0, math.rad(82 - stride)))
                    poseMotor(torso, "Left Hip", CFrame.Angles(0, 0, math.rad(-74 + stride)))
                    poseMotor(torso, "Right Hip", CFrame.Angles(0, 0, math.rad(74 + stride)))
                end
            elseif mode == "moonwalk" or mode == "moonwalk_reverse" then
                local s = math.sin(clock * 7.5)
                local revYaw = (mode == "moonwalk_reverse" and moveMag > 0.05) and math.pi or 0
                local legSwing = (moveMag > 0.05) and (s * 42) or 0
                if r15 then
                    poseMotor(ch:FindFirstChild("LowerTorso"), "Root", CFrame.new(0, 0, 0) * CFrame.Angles(math.rad((moveMag > 0.05) and -6 or 0), revYaw, 0))
                    poseMotor(ch:FindFirstChild("UpperTorso"), "Waist", CFrame.Angles(math.rad(-6), math.rad(s * 8), 0))
                    poseMotor(ch:FindFirstChild("Head"), "Neck", CFrame.Angles(math.rad(-18), 0, 0))
                    poseMotor(ch:FindFirstChild("RightUpperArm"), "RightShoulder", CFrame.Angles(math.rad(68), math.rad(-25), math.rad(12)))
                    poseMotor(ch:FindFirstChild("RightLowerArm"), "RightElbow", CFrame.Angles(math.rad(82), 0, 0))
                    poseMotor(ch:FindFirstChild("LeftUpperArm"), "LeftShoulder", CFrame.Angles(math.rad(-legSwing * 0.55), 0, math.rad(-12)))
                    poseMotor(ch:FindFirstChild("LeftUpperLeg"), "LeftHip", CFrame.Angles(math.rad(legSwing), 0, 0))
                    poseMotor(ch:FindFirstChild("LeftLowerLeg"), "LeftKnee", CFrame.Angles(math.rad((moveMag > 0.05) and (-math.max(0, -s) * 58) or 0), 0, 0))
                    poseMotor(ch:FindFirstChild("RightUpperLeg"), "RightHip", CFrame.Angles(math.rad(-legSwing), 0, 0))
                    poseMotor(ch:FindFirstChild("RightLowerLeg"), "RightKnee", CFrame.Angles(math.rad((moveMag > 0.05) and (-math.max(0, s) * 58) or 0), 0, 0))
                else
                    local torso = ch:FindFirstChild("Torso")
                    poseMotor(ch:FindFirstChild("HumanoidRootPart"), "RootJoint", CFrame.Angles(math.rad((moveMag > 0.05) and 6 or 0), 0, revYaw))
                    poseMotor(torso, "Neck", CFrame.Angles(math.rad(18), 0, 0))
                    poseMotor(torso, "Right Shoulder", CFrame.Angles(math.rad(25), 0, math.rad(72)))
                    poseMotor(torso, "Left Shoulder", CFrame.Angles(0, 0, math.rad(-legSwing * 0.55)))
                    poseMotor(torso, "Left Hip", CFrame.Angles(0, 0, math.rad(-legSwing)))
                    poseMotor(torso, "Right Hip", CFrame.Angles(0, 0, math.rad(-legSwing)))
                end
            elseif mode == "spider" then
                local s = math.sin(clock * ((moveMag > 0.05) and 12.0 or 3.0))
                local stride = (moveMag > 0.05) and (s * 45) or (s * 6)
                if r15 then
                    poseMotor(ch:FindFirstChild("LowerTorso"), "Root", CFrame.new(0, -1.12 + math.abs(s) * 0.16, 0) * CFrame.Angles(math.rad(88), 0, math.rad(s * 10)))
                    poseMotor(ch:FindFirstChild("Head"), "Neck", CFrame.Angles(math.rad(65), math.rad(s * 35), 0))
                    poseMotor(ch:FindFirstChild("LeftUpperArm"), "LeftShoulder", CFrame.Angles(math.rad(165 + stride), 0, math.rad(-25)))
                    poseMotor(ch:FindFirstChild("RightUpperArm"), "RightShoulder", CFrame.Angles(math.rad(165 - stride), 0, math.rad(25)))
                    poseMotor(ch:FindFirstChild("LeftUpperLeg"), "LeftHip", CFrame.Angles(math.rad(-65 - stride), 0, math.rad(-22)))
                    poseMotor(ch:FindFirstChild("RightUpperLeg"), "RightHip", CFrame.Angles(math.rad(-65 + stride), 0, math.rad(22)))
                else
                    local torso = ch:FindFirstChild("Torso")
                    poseMotor(ch:FindFirstChild("HumanoidRootPart"), "RootJoint", CFrame.new(0, 0, -1.12 + math.abs(s) * 0.16) * CFrame.Angles(math.rad(-88), math.rad(s * 10), 0))
                    poseMotor(torso, "Neck", CFrame.Angles(math.rad(-65), 0, math.rad(s * 35)))
                    poseMotor(torso, "Left Shoulder", CFrame.Angles(0, 0, math.rad(-165 - stride)))
                    poseMotor(torso, "Right Shoulder", CFrame.Angles(0, 0, math.rad(165 - stride)))
                    poseMotor(torso, "Left Hip", CFrame.Angles(0, 0, math.rad(65 + stride)))
                    poseMotor(torso, "Right Hip", CFrame.Angles(0, 0, math.rad(-65 + stride)))
                end
            elseif mode == "sonic" then
                local s = math.sin(clock * ((moveMag > 0.05) and 16.0 or 2.8))
                local lean = (moveMag > 0.05) and -48 or -6
                local armBack = (moveMag > 0.05) and -78 or (-12 + s * 8)
                if r15 then
                    poseMotor(ch:FindFirstChild("LowerTorso"), "Root", CFrame.new(0, (moveMag > 0.05) and (math.abs(s) * 0.22) or 0, 0) * CFrame.Angles(math.rad(lean), 0, 0))
                    poseMotor(ch:FindFirstChild("Head"), "Neck", CFrame.Angles(math.rad(-lean * 0.75), 0, 0))
                    poseMotor(ch:FindFirstChild("LeftUpperArm"), "LeftShoulder", CFrame.Angles(math.rad(armBack), 0, math.rad(-18)))
                    poseMotor(ch:FindFirstChild("RightUpperArm"), "RightShoulder", CFrame.Angles(math.rad(armBack), 0, math.rad(18)))
                else
                    local torso = ch:FindFirstChild("Torso")
                    poseMotor(ch:FindFirstChild("HumanoidRootPart"), "RootJoint", CFrame.Angles(math.rad(-lean), 0, 0))
                    poseMotor(torso, "Neck", CFrame.Angles(math.rad(lean * 0.75), 0, 0))
                    poseMotor(torso, "Left Shoulder", CFrame.Angles(0, 0, math.rad(-armBack)))
                    poseMotor(torso, "Right Shoulder", CFrame.Angles(0, 0, math.rad(armBack)))
                end
            elseif mode == "airwalk" then
                local bob = math.sin(clock * 2.2) * 0.28
                if r15 then
                    poseMotor(ch:FindFirstChild("LowerTorso"), "Root", CFrame.new(0, 2.85 + bob, 0))
                else
                    poseMotor(ch:FindFirstChild("HumanoidRootPart"), "RootJoint", CFrame.new(0, 0, 2.85 + bob))
                end
            end
        end)
    end

    function EmoteHub:StopPackFallback()
        if self.packFallbackConn then
            pcall(function() self.packFallbackConn:Disconnect() end)
            self.packFallbackConn = nil
        end
        if self.packFallbackTracks then
            for _, tr in pairs(self.packFallbackTracks) do
                pcall(function() tr:Stop(0.1); tr:Destroy() end)
            end
            table.clear(self.packFallbackTracks)
        end
        self.packFallbackActiveState = nil
    end

    local function countActiveNonBeaconTracks(ch)
        local hum = ch and ch:FindFirstChildOfClass("Humanoid")
        local anim = hum and hum:FindFirstChildOfClass("Animator")
        if not anim then return 0 end
        local ok, tracks = pcall(function() return anim:GetPlayingAnimationTracks() end)
        if not ok or not tracks then return 0 end
        local n = 0
        for _, t in ipairs(tracks) do
            if t.IsPlaying and not IsCocoBeaconTrack[t] then
                n = n + 1
            end
        end
        return n
    end

    function EmoteHub:StartPackHealthWatchdog(packEntry, resolvedMap)
        self:StopPackFallback()
        if not packEntry then return end
        self.packFallbackTracks = self.packFallbackTracks or {}
        local silentSince = nil
        local fallbackMode = false
        local lastState = nil
        local lastChar = nil
        local lastReviveAttempt = 0

        local function stopFallbackTracksOnly()
            if self.packFallbackTracks then
                for _, tr in pairs(self.packFallbackTracks) do
                    pcall(function() if tr.IsPlaying then tr:Stop(0.12) end end)
                end
            end
            lastState = nil
        end

        self.packFallbackConn = RunService.Heartbeat:Connect(function()
            if not self.activePackName or self.activePackName == "Default" or self.activePackEntry ~= packEntry then
                self:StopPackFallback()
                return
            end
            local ch = LP.Character
            local hum = ch and ch:FindFirstChildOfClass("Humanoid")
            if not ch or not hum or hum.Health <= 0 then
                silentSince = nil
                fallbackMode = false
                return
            end
            -- Pause while a weld, emote, jerk, fly, animcopy, or reanim owns the character
            local busy = (CurrentWeld ~= nil) or WeldSeekingTarget or (WeldIntent and WeldIntent.active)
                or _G.CocaBangActive or _G.CocaCopierActive or (AnimCopySys and AnimCopySys.active)
                or self.jerkActive or (self.currentEmoteTrack and self.currentEmoteTrack.IsPlaying)
                or (moveState and (moveState.fly or moveState.flyLanding))
                or (_G.CocaSkyDestroyer and (_G.CocaSkyDestroyer.isAnyActive() or _G.CocaSkyDestroyer.is_reanimated()))
                or (_G._AngoorZenApi and type(_G._AngoorZenApi.is_reanimated) == "function" and _G._AngoorZenApi.is_reanimated())
            if busy then
                if fallbackMode then
                    stopFallbackTracksOnly()
                    fallbackMode = false
                end
                silentSince = nil
                return
            end

            if lastChar ~= ch then
                lastChar = ch
                if self.packFallbackTracks then
                    for _, tr in pairs(self.packFallbackTracks) do pcall(function() tr:Stop(0); tr:Destroy() end) end
                    table.clear(self.packFallbackTracks)
                end
                fallbackMode = false
                silentSince = nil
                lastState = nil
            end

            -- Make sure Animate isn't left stuck Disabled when nothing is using the character
            local animate = ch:FindFirstChild("Animate")
            if animate and animate.Disabled and not AnimateWasDisabled then
                pcall(function() animate.Disabled = false; animate.Enabled = true end)
            end

            local playingCount = countActiveNonBeaconTracks(ch)
            if playingCount == 0 then
                if not silentSince then
                    silentSince = os.clock()
                elseif (os.clock() - silentSince) >= 0.45 then
                    -- First try nudging Animate once every 2.5s; if Animate is truly dead, drive the pack tracks seamlessly!
                    if not fallbackMode and animate and (os.clock() - lastReviveAttempt) > 2.5 then
                        lastReviveAttempt = os.clock()
                        pcall(function()
                            animate.Disabled = false
                            animate.Enabled = true
                            if hum:GetState() == Enum.HumanoidStateType.Running or hum:GetState() == Enum.HumanoidStateType.RunningNoPhysics then
                                hum:ChangeState(Enum.HumanoidStateType.Landed)
                            end
                        end)
                    end
                    if (os.clock() - silentSince) >= 0.85 then
                        fallbackMode = true
                    end
                end
            else
                if not fallbackMode then
                    silentSince = nil
                end
            end

            if fallbackMode then
                local animator = hum:FindFirstChildOfClass("Animator")
                if not animator then
                    pcall(function() animator = Instance.new("Animator", hum) end)
                end
                if not animator then return end

                local st = hum:GetState()
                local desiredKey = "idle"
                if st == Enum.HumanoidStateType.Jumping then
                    desiredKey = "jump"
                elseif st == Enum.HumanoidStateType.Freefall then
                    desiredKey = "fall"
                elseif st == Enum.HumanoidStateType.Climbing then
                    desiredKey = "climb"
                elseif st == Enum.HumanoidStateType.Swimming then
                    desiredKey = (hum.MoveDirection.Magnitude > 0.05) and "swim" or "swimidle"
                elseif hum.MoveDirection.Magnitude > 0.05 then
                    desiredKey = (hum.WalkSpeed > 13) and "run" or "walk"
                end

                local uri = resolvedMap[desiredKey] or resolvedMap.run or resolvedMap.walk or resolvedMap.idle
                if uri and desiredKey ~= lastState then
                    local tr = self.packFallbackTracks[desiredKey]
                    if not tr then
                        local aObj = Instance.new("Animation")
                        aObj.AnimationId = uri
                        local okL, loaded = pcall(function() return animator:LoadAnimation(aObj) end)
                        pcall(function() aObj:Destroy() end)
                        if okL and loaded then
                            loaded.Priority = Enum.AnimationPriority.Core
                            loaded.Looped = (desiredKey ~= "jump")
                            self.packFallbackTracks[desiredKey] = loaded
                            tr = loaded
                        end
                    end
                    if tr then
                        for k, other in pairs(self.packFallbackTracks) do
                            if k ~= desiredKey and other.IsPlaying then
                                pcall(function() other:Stop(0.15) end)
                            end
                        end
                        if not tr.IsPlaying then
                            pcall(function() tr:Play(0.15) end)
                        end
                        lastState = desiredKey
                    end
                elseif lastState and self.packFallbackTracks[lastState] and not self.packFallbackTracks[lastState].IsPlaying and lastState ~= "jump" then
                    pcall(function() self.packFallbackTracks[lastState]:Play(0.1) end)
                end
            end
        end)
    end

    function EmoteHub:EnsureActivePackAlive(ch)
        if not self.activePackEntry or not self.activePackName or self.activePackName == "Default" then return end
        ch = ch or LP.Character
        if not ch or not ch.Parent then return end
        local animate = ch:FindFirstChild("Animate")
        if animate and animate.Disabled then
            pcall(function() animate.Disabled = false; animate.Enabled = true end)
        end
        if not self.packFallbackConn and self.activePackResolvedMap then
            self:StartPackHealthWatchdog(self.activePackEntry, self.activePackResolvedMap)
        end
    end

    function EmoteHub:ApplyCatalogPack(packEntry, silentNotify)
        local ch = LP.Character
        local hum = ch and ch:FindFirstChildOfClass("Humanoid")
        local animate = ch and ch:FindFirstChild("Animate")
        if not ch or not hum then
            if not silentNotify then
                notify("📦 ANIM PACK", "Character not ready!")
                sError()
            end
            return false
        end
        self._packApplyGen = (self._packApplyGen or 0) + 1
        local myGen = self._packApplyGen
        self:StopProceduralPack()
        self:StopPackFallback()

        -- Pre-resolve all catalog URIs BEFORE disabling Animate so Animate is never stuck disabled during network fetches!
        local resolvedMap = {
            idle     = resolveCatalogAnimUri(packEntry.idle1),
            idle2    = resolveCatalogAnimUri(packEntry.idle2 or packEntry.idle1),
            walk     = resolveCatalogAnimUri(packEntry.walk or packEntry.run),
            run      = resolveCatalogAnimUri(packEntry.run or packEntry.walk),
            jump     = resolveCatalogAnimUri(packEntry.jump),
            fall     = resolveCatalogAnimUri(packEntry.fall),
            climb    = resolveCatalogAnimUri(packEntry.climb),
            swim     = resolveCatalogAnimUri(packEntry.swim),
            swimidle = resolveCatalogAnimUri(packEntry.swimidle),
        }
        if self._packApplyGen ~= myGen then return false end

        -- Refresh character references in case of respawn during URI resolution
        ch = LP.Character
        hum = ch and ch:FindFirstChildOfClass("Humanoid")
        animate = ch and ch:FindFirstChild("Animate")
        if not ch or not hum then return false end

        if animate then
            self:SaveDefaultPack(ch)
            pcall(function() animate.Disabled = true; animate.Enabled = false end)
            stopDefaultTracks(ch)
            -- Reset to clean defaults first so partial UGC packs never inherit leftover tracks from a previous pack
            if self.savedDefaultPack then
                for folderName, animMap in pairs(self.savedDefaultPack) do
                    local folder = animate:FindFirstChild(folderName)
                    if folder then
                        for animName, animId in pairs(animMap) do
                            local a = folder:FindFirstChild(animName)
                            if a and a:IsA("Animation") then
                                a.AnimationId = animId
                            end
                        end
                    end
                end
            end

            setAnimChildId(animate, "idle",     "Animation1", packEntry.idle1)
            setAnimChildId(animate, "idle",     "Animation2", packEntry.idle2 or packEntry.idle1)
            setAnimChildId(animate, "pose",     nil,          packEntry.idle1)
            setAnimChildId(animate, "walk",     "WalkAnim",   packEntry.walk or packEntry.run)
            setAnimChildId(animate, "run",      "RunAnim",    packEntry.run or packEntry.walk)
            setAnimChildId(animate, "jump",     "JumpAnim",   packEntry.jump)
            setAnimChildId(animate, "fall",     "FallAnim",   packEntry.fall)
            setAnimChildId(animate, "climb",    "ClimbAnim",  packEntry.climb)
            setAnimChildId(animate, "swim",     "Swim",       packEntry.swim)
            setAnimChildId(animate, "swim",     "SwimAnim",   packEntry.swim)
            setAnimChildId(animate, "swimidle", "SwimIdle",   packEntry.swimidle)

            -- Re-enable Animate cleanly after 1 frame (NEVER call stopDefaultTracks AFTER re-enabling, or it kills the new idle track!)
            task.spawn(function()
                task.wait(0.05)
                if self._packApplyGen ~= myGen then return end
                if ch and ch.Parent then
                    stopDefaultTracks(ch)
                end
                if animate and animate.Parent then
                    pcall(function() animate.Disabled = false; animate.Enabled = true end)
                end
                if hum and hum.Parent and hum.Health > 0 then
                    pcall(function() hum:ChangeState(Enum.HumanoidStateType.Landed) end)
                    task.wait(0.03)
                    if self._packApplyGen ~= myGen then return end
                    if hum and hum.Parent and hum.Health > 0 then
                        pcall(function() hum:ChangeState(Enum.HumanoidStateType.Running) end)
                    end
                end
            end)
        end

        local autoProc = packEntry.procMode
        if not autoProc and hum.RigType == Enum.HumanoidRigType.R6 then
            local ln = (packEntry.name or ""):lower()
            if ln:find("dog") or ln:find("quadruped") then autoProc = "dog"
            elseif ln:find("wolf") then autoProc = "wolf"
            elseif ln:find("cat") and not ln:find("catwalk") then autoProc = "cat"
            elseif ln:find("moonwalk") then autoProc = "moonwalk"
            elseif ln:find("spider") or ln:find("crawl") then autoProc = "spider"
            elseif ln:find("sonic") then autoProc = "sonic"
            elseif ln:find("air walk") then autoProc = "airwalk"
            end
        end
        if autoProc then
            self:StartProceduralPack(autoProc)
        end

        self.activePackName = packEntry.name
        self.activePackEntry = packEntry
        self.activePackResolvedMap = resolvedMap
        self:StartPackHealthWatchdog(packEntry, resolvedMap)
        if not silentNotify then
            notify("📦 CATALOG PACK", "Applied '" .. packEntry.name .. "' Animation Pack!")
            sSuccess()
        end
        return true
    end

    function EmoteHub:RestoreDefaultPack()
        self._packApplyGen = (self._packApplyGen or 0) + 1
        self:StopProceduralPack()
        self:StopPackFallback()
        self.activePackEntry = nil
        self.activePackResolvedMap = nil
        local ch = LP.Character
        local hum = ch and ch:FindFirstChildOfClass("Humanoid")
        local animate = ch and ch:FindFirstChild("Animate")
        if not ch or not animate or not self.savedDefaultPack then
            self.activePackName = "Default"
            notify("📦 ANIM PACK", "Restored Default Character Posture!")
            return
        end
        pcall(function() animate.Disabled = true; animate.Enabled = false end)
        stopDefaultTracks(ch)
        for folderName, animMap in pairs(self.savedDefaultPack) do
            local folder = animate:FindFirstChild(folderName)
            if folder then
                for animName, animId in pairs(animMap) do
                    local a = folder:FindFirstChild(animName)
                    if a and a:IsA("Animation") then
                        a.AnimationId = animId
                    end
                end
            end
        end
        pcall(function() animate.Disabled = false; animate.Enabled = true end)
        if hum then pcall(function() hum:ChangeState(Enum.HumanoidStateType.Landed); hum:ChangeState(Enum.HumanoidStateType.Running) end) end
        self.activePackName = "Default"
        notify("📦 CATALOG PACK", "Restored Default Animation Pack!")
        sSuccess()
    end

    -- ═══════════════════════════════════════════════════════════════════════════
    -- Re-apply selected Catalog Animation Pack & restore CameraSubject automatically on respawn (Zero-Delay)
    LP.CharacterAdded:Connect(function(newChar)
        task.defer(function()
            local newHum = newChar:WaitForChild("Humanoid", 5.0)
            local cam = workspace.CurrentCamera
            if newHum and cam and not SpectatingTarget and not (moveState and moveState.Vanish and moveState.Vanish.selfActive) then
                pcall(function()
                    cam.CameraType = Enum.CameraType.Custom
                    cam.CameraSubject = newHum
                end)
            end
        end)
        task.spawn(function()
            newChar:WaitForChild("Humanoid", 5.0)
            newChar:WaitForChild("Animate", 5.0)
            task.wait(0.25)
            if LP.Character ~= newChar then return end
            if EmoteHub.activePackName and EmoteHub.activePackName ~= "Default" then
                for _, p in ipairs(EmoteHub.CatalogPacks) do
                    if p.name == EmoteHub.activePackName then
                        pcall(function() EmoteHub:ApplyCatalogPack(p, true) end)
                        break
                    end
                end
            end
        end)
    end)

