    spiderWalk = false,
    airWalk = false,
    airWalkY = nil,
    airWalkPart = nil,
    fpsBoost = false,
    fullbright = false,
    dashDistance = 32,
    flyConn = nil,
    jumpConn = nil,
    noclipConn = nil,
    speedLoopConn = nil,
    spiderConn = nil,
    airWalkConn = nil,
    fullbrightConn = nil,
    savedLighting = nil,
    savedFpsParts = setmetatable({}, {__mode = "k"}),
    savedFpsEffects = setmetatable({}, {__mode = "k"}),
    lastTeleportTick = 0,
    restoreFlyJoints = nil,
    stopFlyImmediate = nil,
    Vanish = {
        selfActive = false,
        hideMode = "Skybox", -- "Skybox", "Underground", or "BlinkDesync"
        unvanishAtGhost = true,
        ghostModel = nil,
        originCF = nil,
        ghostCF = nil,
        stepConn = nil,
        hbConn = nil,
        vanishedTargets = {}, -- [userId] = Player
        savedTargetParts = setmetatable({}, { __mode = "k" }),
        targetLoopConn = nil,
        uiSwitchSetters = {},
    },
}

local syncAllAntiButtons = nil

