        muteBtn.TextColor3 = Color3.fromRGB(245, 240, 255)
        muteBtn.Font = Enum.Font.GothamBold
        muteBtn.TextSize = 11
        muteBtn.Parent = mainFrame
        Instance.new("UICorner", muteBtn).CornerRadius = UDim.new(0, 8)
