        muteStroke.Color = Color3.fromRGB(135, 115, 175)
        muteStroke.Thickness = 1
        muteStroke.Transparency = 0.45
        muteStroke.Parent = muteBtn

        nvActivePanelStatusUpdater = function(txt, col)
            if statusLbl and statusLbl.Parent then
                statusLbl.Text = tostring(txt or "")
                if col then statusLbl.TextColor3 = col end
            end
        end

        local function selectModeVisual(m)
            selectedMode = m
            if m == "V1" then
                TweenService:Create(v1Btn, TweenInfo.new(0.2), { BackgroundColor3 = Color3.fromRGB(168, 85, 247), BackgroundTransparency = 0.2, TextColor3 = Color3.fromRGB(245, 240, 255) }):Play()
                TweenService:Create(v2Btn, TweenInfo.new(0.2), { BackgroundColor3 = Color3.fromRGB(36, 28, 50), BackgroundTransparency = 0.4, TextColor3 = Color3.fromRGB(165, 155, 185) }):Play()
                statusLbl.Text = Anti.VCV1.enabled and "Status: V1 Bypassed! Use Floating UI" or "Status: Ready (Bypass V1 Selected)"
            else
                TweenService:Create(v2Btn, TweenInfo.new(0.2), { BackgroundColor3 = Color3.fromRGB(168, 85, 247), BackgroundTransparency = 0.2, TextColor3 = Color3.fromRGB(245, 240, 255) }):Play()
                TweenService:Create(v1Btn, TweenInfo.new(0.2), { BackgroundColor3 = Color3.fromRGB(36, 28, 50), BackgroundTransparency = 0.4, TextColor3 = Color3.fromRGB(165, 155, 185) }):Play()
                statusLbl.Text = Anti.VCV2.enabled and "Status: V2 Bypassed! Topbar Ready" or "Status: Ready (Bypass V2 Selected)"
            end
        end
        selectModeVisual(selectedMode)

        v1Btn.MouseButton1Click:Connect(function()
            if not Anti.VCV1.running and not Anti.VCV2.running then
                selectModeVisual("V1")
            end
        end)
        v2Btn.MouseButton1Click:Connect(function()
            if not Anti.VCV1.running and not Anti.VCV2.running then
                selectModeVisual("V2")
            end
        end)

        execBtn.MouseButton1Click:Connect(function()
            if selectedMode == "V1" then
                nvStartV1()
            else
                nvStartV2()
            end
        end)

        muteBtn.MouseButton1Click:Connect(function()
            local mNow = nvToggleMuteAny()
            if mNow ~= nil then
                muteBtn.Text = mNow and "🔇 Muted" or "🎙️ Live"
            end
        end)

        closeBtn.MouseButton1Click:Connect(function()
            nvActivePanelStatusUpdater = nil
            sg:Destroy()
        end)
    end

    Anti.VCV1.startFn = nvStartV1
    Anti.VCV1.stopFn = nvCleanupV1
    Anti.VCV1.toggleMuteFn = nvToggleMuteAny
    Anti.VCV2.startFn = nvStartV2
    Anti.VCV2.stopFn = nvCleanupV2
    Anti.VCV2.toggleMuteFn = nvToggleMuteAny
    Anti.VC.openNovolinePanelFn = function() launchNovolineVCBypasser("V1") end
    Anti.VC.openVCB2Fn = function() launchNovolineVCBypasser("V2") end

    _G.launchCocoAntiVCBypassSuite = function() launchNovolineVCBypasser("V1") end
    _G.launchCocoAntiVCB2 = function() launchNovolineVCBypasser("V2") end
    _G.NovolineVCBypasser = {
        LaunchUI = launchNovolineVCBypasser,
        LaunchV1 = function() launchNovolineVCBypasser("V1") end,
        LaunchV2 = function() launchNovolineVCBypasser("V2") end,
        RunV1Direct = nvStartV1,
        RunV2Direct = nvStartV2,
        StopV1 = nvCleanupV1,
        StopV2 = nvCleanupV2,
        ToggleMute = nvToggleMuteAny,
    }
end
end)()
;(function() -- Sub-scope 2 for Anti (Ragdoll, Anchor, Attach, Blind, Bring, FlingShield, DefenceTroll)
local contactTimers = {}
local deflectCooldowns = {}
local attackerLastPos = {}

-- ═══════════════════════════════════════════════════════════════════════════════
-- 6. ADVANCED ANTI-RAGDOLL / ANTI-SIT / ANTI-STUN / ANTI-TRIP V2
--    • Disables Ragdoll, FallingDown, Seated, PlatformStand states
--    • Destroys SeatWelds and Ragdoll BallSocketConstraints / NoCollisionConstraints
--    • Automatically re-enables disabled Motor6D joints
--    • Cures stun/freeze walkspeed locks (when WalkSpeed is forced to 0)
-- ═══════════════════════════════════════════════════════════════════════════════
local function ragdollCleanseCharacter(c)
    if not c then return end
    if (_G.CocaSkyDestroyer and (_G.CocaSkyDestroyer.isAnyActive() or _G.CocaSkyDestroyer.is_reanimated()))
        or (_G._AngoorZenApi and type(_G._AngoorZenApi.is_reanimated) == "function" and _G._AngoorZenApi.is_reanimated()) then
        return
    end
    local hum = c:FindFirstChildOfClass("Humanoid")
    if hum then
        pcall(function()
            if hum:GetStateEnabled(Enum.HumanoidStateType.Ragdoll) then hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, false) end
            if hum:GetStateEnabled(Enum.HumanoidStateType.FallingDown) then hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false) end
            if hum:GetStateEnabled(Enum.HumanoidStateType.Seated) then hum:SetStateEnabled(Enum.HumanoidStateType.Seated, false) end
            if not hum:GetStateEnabled(Enum.HumanoidStateType.GettingUp) then hum:SetStateEnabled(Enum.HumanoidStateType.GettingUp, true) end
            if CurrentWeld == nil and not WeldSeekingTarget and not (WeldIntent and WeldIntent.active) and not _G.CocaBangActive and not _G.CocaCopierActive and not (AnimCopySys and AnimCopySys.active) and not FlingActive and not (moveState and (moveState.fly or moveState.flyLanding)) then
                if hum:GetStateEnabled(Enum.HumanoidStateType.Physics) then hum:SetStateEnabled(Enum.HumanoidStateType.Physics, false) end
                if hum.PlatformStand then hum.PlatformStand = false end
                if hum.Sit then hum.Sit = false end
                if not hum.AutoRotate then hum.AutoRotate = true end
                local st = hum:GetState()
                if st == Enum.HumanoidStateType.Ragdoll
                    or st == Enum.HumanoidStateType.FallingDown
                    or st == Enum.HumanoidStateType.PlatformStanding
                    or st == Enum.HumanoidStateType.Seated
                    or st == Enum.HumanoidStateType.Physics then
                    hum:ChangeState(Enum.HumanoidStateType.GettingUp)
                    hum:ChangeState(Enum.HumanoidStateType.Running)
                    Anti.Ragdoll.recoveries = Anti.Ragdoll.recoveries + 1
                end
                -- Only cure hard stun-locks that freeze WalkSpeed at 0
                if hum.WalkSpeed <= 0.1 and not (moveState and moveState.speed) then
                    hum.WalkSpeed = 16
                end
            end
        end)
    end
    for _, obj in ipairs(c:GetDescendants()) do
        if obj:IsA("Motor6D") and not obj.Enabled then
            pcall(function() obj.Enabled = true end)
        elseif obj:IsA("SeatWeld") or obj.Name == "SeatWeld" or obj.Name:lower():find("ragdoll") then
            if not obj:IsA("BasePart") and not obj:IsA("Humanoid") then
                pcall(function() obj:Destroy() end)
            end
        elseif obj:IsA("BallSocketConstraint") or obj:IsA("HingeConstraint") then
            pcall(function() obj:Destroy() end)
        end
    end
end

ragdollStart = function()
    if Anti.Ragdoll.enabled then return end
    Anti.Ragdoll.enabled = true
    local function hookRagdollCharacter(char)
        if Anti.Ragdoll.descConn then Anti.Ragdoll.descConn:Disconnect(); Anti.Ragdoll.descConn = nil end
        if Anti.Ragdoll.stateConn then Anti.Ragdoll.stateConn:Disconnect(); Anti.Ragdoll.stateConn = nil end
        if not char then return end
        local readyHumanoid = char:FindFirstChildOfClass("Humanoid") or char:WaitForChild("Humanoid", 3)
        if not readyHumanoid then return end
        ragdollCleanseCharacter(char)
        Anti.Ragdoll.descConn = char.DescendantAdded:Connect(function(obj)
            if not Anti.Ragdoll.enabled then return end
            if (_G.CocaSkyDestroyer and (_G.CocaSkyDestroyer.isAnyActive() or _G.CocaSkyDestroyer.is_reanimated()))
                or (_G._AngoorZenApi and type(_G._AngoorZenApi.is_reanimated) == "function" and _G._AngoorZenApi.is_reanimated()) then
                return
            end
            if obj:IsA("Motor6D") and not obj.Enabled then
                pcall(function() obj.Enabled = true end)
            elseif obj:IsA("SeatWeld") or obj.Name == "SeatWeld" or obj.Name:lower():find("ragdoll")
                or obj:IsA("BallSocketConstraint") or obj:IsA("HingeConstraint") then
                pcall(function() obj:Destroy() end)
            end
        end)
        local hum = char:FindFirstChildOfClass("Humanoid")
        if hum then
            Anti.Ragdoll.stateConn = hum.StateChanged:Connect(function(_, state)
                if Anti.Ragdoll.enabled and (state == Enum.HumanoidStateType.Ragdoll
                    or state == Enum.HumanoidStateType.FallingDown or state == Enum.HumanoidStateType.Physics) then
                    task.defer(function() if Anti.Ragdoll.enabled and char.Parent then ragdollCleanseCharacter(char) end end)
                end
            end)
        end
    end
    hookRagdollCharacter(LP.Character)
    if Anti.Ragdoll.charAdded then Anti.Ragdoll.charAdded:Disconnect() end
    Anti.Ragdoll.charAdded = LP.CharacterAdded:Connect(function(char)
        task.defer(function() if Anti.Ragdoll.enabled then hookRagdollCharacter(char) end end)
    end)
    if syncAllAntiButtons then pcall(syncAllAntiButtons) end
    notify("COCO POWDER", "Anti-Ragdoll / Anti-Stun / Anti-Sit v2 ON")
    sToggleOn()
end

ragdollStop = function()
    if not Anti.Ragdoll.enabled then return end
    Anti.Ragdoll.enabled = false
    if Anti.Ragdoll.steppedConn then Anti.Ragdoll.steppedConn:Disconnect(); Anti.Ragdoll.steppedConn = nil end
    if Anti.Ragdoll.descConn then Anti.Ragdoll.descConn:Disconnect(); Anti.Ragdoll.descConn = nil end
    if Anti.Ragdoll.stateConn then Anti.Ragdoll.stateConn:Disconnect(); Anti.Ragdoll.stateConn = nil end
    if Anti.Ragdoll.charAdded then Anti.Ragdoll.charAdded:Disconnect(); Anti.Ragdoll.charAdded = nil end
    local c = LP.Character
    local hum = c and c:FindFirstChildOfClass("Humanoid")
    if hum and not (Anti.SeatTrap and Anti.SeatTrap.enabled) then
        pcall(function()
            hum:SetStateEnabled(Enum.HumanoidStateType.Seated, true)
        end)
    end
    if syncAllAntiButtons then pcall(syncAllAntiButtons) end
    notify("COCO POWDER", "Anti-Ragdoll disabled")
    sToggleOff()
end

-- ═══════════════════════════════════════════════════════════════════════════════
-- 7. ADVANCED ANTI-ANCHOR / ANTI-FREEZE / ANTI-MOVER V2
--    • Initial scan plus DescendantAdded hook; no per-frame full-character scan
--    • Purges hostile BodyPosition, BodyVelocity, BodyGyro, AlignPosition,
--      AlignOrientation, LinearVelocity, AngularVelocity, VectorForce injected by enemies
-- ═══════════════════════════════════════════════════════════════════════════════
local HOSTILE_MOVER_CLASSES = {
    BodyVelocity = true,
    BodyPosition = true,
    BodyGyro = true,
    BodyAngularVelocity = true,
    BodyForce = true,
    BodyThrust = true,
    RocketPropulsion = true,
    LinearVelocity = true,
    AngularVelocity = true,
    VectorForce = true,
    LineForce = true,
    AlignPosition = true,
    AlignOrientation = true,
}

local function anchorCleanse(c)
    if not c or OwnerAdminState.isFrozenByOwner then return end
    for _, obj in ipairs(c:GetDescendants()) do
        if obj:IsA("BasePart") then
            if obj.Anchored and not deflectBusy then
                obj.Anchored = false
                Anti.Anchor.purgedMovers = Anti.Anchor.purgedMovers + 1
            end
        elseif HOSTILE_MOVER_CLASSES[obj.ClassName] and not obj.Name:match("^Coco") then
            pcall(function()
                obj:Destroy()
                Anti.Anchor.purgedMovers = Anti.Anchor.purgedMovers + 1
            end)
        end
    end
end

local function anchorWatchPart(part)
    if not (part and part:IsA("BasePart")) or Anti.Anchor.partConns[part] then return end
    Anti.Anchor.partConns[part] = part:GetPropertyChangedSignal("Anchored"):Connect(function()
        if Anti.Anchor.enabled and not OwnerAdminState.isFrozenByOwner and part.Parent and part.Anchored and not deflectBusy then
            pcall(function() part.Anchored = false end)
            Anti.Anchor.purgedMovers = Anti.Anchor.purgedMovers + 1
        end
    end)
end

local function anchorCleanseObject(obj)
    if not obj or OwnerAdminState.isFrozenByOwner then return end
    if obj:IsA("BasePart") then
        anchorWatchPart(obj)
        if obj.Anchored and not deflectBusy then
            pcall(function() obj.Anchored = false end)
            Anti.Anchor.purgedMovers = Anti.Anchor.purgedMovers + 1
        end
    elseif HOSTILE_MOVER_CLASSES[obj.ClassName] and not obj.Name:match("^Coco") then
        pcall(function() obj:Destroy(); Anti.Anchor.purgedMovers = Anti.Anchor.purgedMovers + 1 end)
    end
end

local function anchorHookCharacter(char)
    if Anti.Anchor.descConn then Anti.Anchor.descConn:Disconnect(); Anti.Anchor.descConn = nil end
    for part, conn in pairs(Anti.Anchor.partConns) do
        if conn then pcall(function() conn:Disconnect() end) end
        Anti.Anchor.partConns[part] = nil
    end
    if not char then return end
    anchorCleanse(char)
    for _, obj in ipairs(char:GetDescendants()) do
        if obj:IsA("BasePart") then anchorWatchPart(obj) end
    end
    Anti.Anchor.descConn = char.DescendantAdded:Connect(function(obj)
        if Anti.Anchor.enabled then anchorCleanseObject(obj) end
    end)
end

anchorStart = function()
    if Anti.Anchor.enabled then return end
    Anti.Anchor.enabled = true
    anchorHookCharacter(LP.Character)
    if Anti.Anchor.charAdded then Anti.Anchor.charAdded:Disconnect() end
    Anti.Anchor.charAdded = LP.CharacterAdded:Connect(function(char)
        task.defer(function() if Anti.Anchor.enabled then anchorHookCharacter(char) end end)
    end)
    if syncAllAntiButtons then pcall(syncAllAntiButtons) end
    notify("COCO POWDER", "Event-driven Anti-Anchor / Anti-Mover ON")
    sToggleOn()
end

anchorStop = function()
    if not Anti.Anchor.enabled then return end
    Anti.Anchor.enabled = false
    if Anti.Anchor.steppedConn then Anti.Anchor.steppedConn:Disconnect(); Anti.Anchor.steppedConn = nil end
    if Anti.Anchor.descConn then Anti.Anchor.descConn:Disconnect(); Anti.Anchor.descConn = nil end
    if Anti.Anchor.charAdded then Anti.Anchor.charAdded:Disconnect(); Anti.Anchor.charAdded = nil end
    for part, conn in pairs(Anti.Anchor.partConns) do
        if conn then pcall(function() conn:Disconnect() end) end
        Anti.Anchor.partConns[part] = nil
    end
    if syncAllAntiButtons then pcall(syncAllAntiButtons) end
    notify("COCO POWDER", "Anti-Anchor disabled")
    sToggleOff()
end

-- ═══════════════════════════════════════════════════════════════════════════════
-- 8. ADVANCED ANTI-ATTACH / HOSTILE WELD & GRAB SEVER V2
--    • Scans BOTH LP.Character AND external characters/workspace for any Joint/Constraint
--      (Weld, WeldConstraint, RigidConstraint, Motor6D, AlignPosition, Rope, etc.)
--      that links any part of our character to an external object or player!
-- ═══════════════════════════════════════════════════════════════════════════════
local function isJointHostileToCharacter(obj, myChar)
    if not obj or not myChar then return false end
    if isCarriedPlayerJoint(obj, myChar) then return false end
    if obj:IsA("JointInstance") or obj:IsA("WeldConstraint") then
        local p0, p1 = obj.Part0, obj.Part1
        local p0Mine = p0 and p0:IsDescendantOf(myChar)
        local p1Mine = p1 and p1:IsDescendantOf(myChar)
        if (p0Mine and p1 and not p1Mine) or (p1Mine and p0 and not p0Mine) then
            return true
        end
    elseif obj:IsA("Constraint") then
        local a0, a1 = obj.Attachment0, obj.Attachment1
        local a0Mine = a0 and a0:IsDescendantOf(myChar)
        local a1Mine = a1 and a1:IsDescendantOf(myChar)
        if (a0Mine and a1 and not a1Mine) or (a1Mine and a0 and not a0Mine) then
            return true
        end
    end
    return false
end

local function severAllHostileAttachments()
    local myChar = LP.Character
    if not myChar then return 0 end
    local severed = 0
    -- 1. Check joints/constraints inside our own character
    for _, obj in ipairs(myChar:GetDescendants()) do
        if isJointHostileToCharacter(obj, myChar) then
            pcall(function() obj:Destroy() end)
            severed = severed + 1
        elseif obj:IsA("BasePart") then
            local okJ, joints = pcall(function() return obj:GetJoints() end)
            if okJ and joints then
                for _, j in ipairs(joints) do
                    if isJointHostileToCharacter(j, myChar) then
                        pcall(function() j:Destroy() end)
                        severed = severed + 1
                    end
                end
            end
        end
    end
    -- 2. Check joints/constraints inside other players' characters & tools (catches external grab welds!)
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= LP and p.Character then
            for _, obj in ipairs(p.Character:GetDescendants()) do
                if isJointHostileToCharacter(obj, myChar) then
                    pcall(function() obj:Destroy() end)
                    severed = severed + 1
                end
            end
        end
    end
    Anti.Attach.severedCount = Anti.Attach.severedCount + severed
    return severed
end

attachStart = function()
    if Anti.Attach.enabled then return end
    Anti.Attach.enabled = true
    severAllHostileAttachments()
    if Anti.Attach.descConn then Anti.Attach.descConn:Disconnect() end
    Anti.Attach.descConn = workspace.DescendantAdded:Connect(function(obj)
        if not Anti.Attach.enabled then return end
        local char = LP.Character
        if char and isJointHostileToCharacter(obj, char) then
            pcall(function() obj:Destroy() end)
            Anti.Attach.severedCount = Anti.Attach.severedCount + 1
        end
    end)
    if syncAllAntiButtons then pcall(syncAllAntiButtons) end
    notify("COCO POWDER", "Event-driven Anti-Attach / Grab Monitor ON")
    sToggleOn()
end

attachStop = function()
    if not Anti.Attach.enabled then return end
    Anti.Attach.enabled = false
    if Anti.Attach.steppedConn then Anti.Attach.steppedConn:Disconnect(); Anti.Attach.steppedConn = nil end
    if Anti.Attach.descConn then Anti.Attach.descConn:Disconnect(); Anti.Attach.descConn = nil end
    if syncAllAntiButtons then pcall(syncAllAntiButtons) end
    notify("COCO POWDER", "Anti-Attach disabled")
    sToggleOff()
end

-- ═══════════════════════════════════════════════════════════════════════════════
-- 9. ADVANCED ANTI-BLIND / ANTI-FLASH & VISION CLEAR V2
--    • Cleanses Lighting & Camera post-effects (Blur, ColorCorrection, Bloom, DepthOfField, Fog)
--    • Neutralizes full-screen blinding flashbang overlays in PlayerGui
-- ═══════════════════════════════════════════════════════════════════════════════
local function blindCleanse()
    local Lighting = game:GetService("Lighting")
    pcall(function()
        if Lighting.FogEnd < 250 then Lighting.FogEnd = 100000 end
        for _, eff in ipairs(Lighting:GetChildren()) do
            if eff.Name:match("^CocoAdmin") then
                -- Preserve verified Owner/Admin Blind & Glitch overlays
            elseif eff:IsA("BlurEffect") and eff.Size > 4 then
                eff.Enabled = false; eff.Size = 0
            elseif eff:IsA("ColorCorrectionEffect") and (eff.Brightness < -0.25 or eff.Brightness > 0.6 or eff.Contrast > 1.5 or eff.TintColor ~= Color3.new(1, 1, 1)) then
                eff.Enabled = false
            elseif eff:IsA("DepthOfFieldEffect") and eff.FarIntensity > 0.5 then
                eff.Enabled = false
            elseif eff:IsA("BloomEffect") and eff.Intensity > 2.5 then
                eff.Enabled = false
            elseif eff:IsA("Atmosphere") and eff.Density > 0.65 then
                eff.Density = 0.25
            end
        end
        local currentCam = workspace.CurrentCamera
        if currentCam then
            if currentCam.FieldOfView < 40 or currentCam.FieldOfView > 115 then
                currentCam.FieldOfView = 70
            end
            for _, eff in ipairs(currentCam:GetChildren()) do
                if eff:IsA("PostEffect") and not eff.Name:match("^Coco") then
                    eff.Enabled = false
                end
            end
        end
        -- Check PlayerGui for hostile full-screen blind/flashbang ScreenGuis
        local pgui = LP:FindFirstChildOfClass("PlayerGui")
        if pgui then
            for _, sg in ipairs(pgui:GetChildren()) do
                local lowerName = sg.Name:lower()
                local isBlindOverlay = lowerName:find("blind", 1, true)
                    or lowerName:find("flash", 1, true)
                    or lowerName:find("blackout", 1, true)
                    or lowerName:find("jumpscare", 1, true)
                    or lowerName:find("fade", 1, true)
                if sg:IsA("ScreenGui") and not sg.Name:match("^Coco") and isBlindOverlay then
                    sg.Enabled = false
                end
            end
        end
    end)
end

blindStart = function()
    if Anti.Blind.enabled then return end
    Anti.Blind.enabled = true
    blindCleanse()
    if Anti.Blind.loopConn then Anti.Blind.loopConn:Disconnect() end
    local lastBlindCleanse = 0
    Anti.Blind.loopConn = RunService.Heartbeat:Connect(function()
        if not Anti.Blind.enabled then return end
        local now = tick()
        if now - lastBlindCleanse >= 0.65 then
            lastBlindCleanse = now
            blindCleanse()
        end
    end)
    if syncAllAntiButtons then pcall(syncAllAntiButtons) end
    notify("COCO POWDER", "Anti-Blind / Anti-Flashbang & Fog Clear v2 ON")
    sToggleOn()
end

blindStop = function()
    if not Anti.Blind.enabled then return end
    Anti.Blind.enabled = false
    if Anti.Blind.loopConn then Anti.Blind.loopConn:Disconnect(); Anti.Blind.loopConn = nil end
    if syncAllAntiButtons then pcall(syncAllAntiButtons) end
    notify("COCO POWDER", "Anti-Blind disabled")
    sToggleOff()
end

-- ═══════════════════════════════════════════════════════════════════════════════
-- 10. ADVANCED ANTI-BRING / ANTI-TELEPORT / ANTI-TOOL-GRAB GUARD V4
--     • Uses horizontal (XZ) snap detection + foreign joint check so jumping,
--       falling under gravity, or high JumpPower NEVER freezes/levitates you in mid-air!
-- ═══════════════════════════════════════════════════════════════════════════════
bringStart = function()
    if Anti.Bring.enabled then return end
    Anti.Bring.enabled = true
    local c = LP.Character
    local root = c and c:FindFirstChild("HumanoidRootPart")
    if root and isSafePlayableCF(root.CFrame) then
        Anti.Bring.lastCF = root.CFrame
        Anti.Bring.lastSafeTime = tick()
    end
    if Anti.Bring.steppedConn then Anti.Bring.steppedConn:Disconnect() end
    Anti.Bring.steppedConn = RunService.Stepped:Connect(function(_, dt)
        if not Anti.Bring.enabled then return end
        local ch = LP.Character
        local r = ch and ch:FindFirstChild("HumanoidRootPart")
        if WeldIntent.active or CurrentWeld ~= nil or WeldSeekingTarget or (AnimCopySys and AnimCopySys.active) or (moveState and moveState.Vanish and moveState.Vanish.selfActive) or _G.CocaBangActive or _G.CocaCopierActive or (OwnerAdminState and OwnerAdminState.formationMode) or (_G.CocaSkyDestroyer and (_G.CocaSkyDestroyer.isAnyActive() or _G.CocaSkyDestroyer.is_reanimated())) or (_G._AngoorZenApi and type(_G._AngoorZenApi.is_reanimated) == "function" and _G._AngoorZenApi.is_reanimated()) or FlingActive or deflectBusy or (moveState and (moveState.fly or moveState.flyLanding or moveState.spiderWalk or moveState.airWalk)) or (RewindSys and RewindSys.rewinding) then
            if r and isSafePlayableCF(r.CFrame) then Anti.Bring.lastCF = r.CFrame end
            return
        end
        if tick() - (moveState.lastTeleportTick or 0) < 0.85 then
            if r and isSafePlayableCF(r.CFrame) then Anti.Bring.lastCF = r.CFrame end
            return
        end

        local hum = ch and ch:FindFirstChildOfClass("Humanoid")
        if not r or not hum or hum.Health <= 0 then return end

        -- Reset cached position on character respawn so Anti-Bring NEVER snaps you back to where you died!
        if Anti.Bring.lastChar ~= ch then
            Anti.Bring.lastChar = ch
            Anti.Bring.lastCF = isSafePlayableCF(r.CFrame) and r.CFrame or nil
            return
        end

        if Anti.Bring.lastCF then
            local lastPos = Anti.Bring.lastCF.Position
            local curPos = r.Position
            local horizDist = Vector2.new(curPos.X - lastPos.X, curPos.Z - lastPos.Z).Magnitude
            local totalDist = (curPos - lastPos).Magnitude
            local maxAllowedHoriz = math.max(75, (hum.WalkSpeed or 16) * math.max(dt or 0.016, 0.016) * 7.5 + 52)
            local severed = (totalDist > 14) and severAllHostileAttachments() or 0
            if (severed > 0 and totalDist > 14) or horizDist > maxAllowedHoriz or not isSafePlayableCF(r.CFrame) then
                if severed == 0 then severAllHostileAttachments() end
                -- Preserve gentle downward gravity instead of freezing at Y=0 in mid-air
                local preserveGravY = math.min(0, math.max(r.AssemblyLinearVelocity.Y, -35))
                r.AssemblyLinearVelocity = Vector3.new(0, preserveGravY, 0)
                r.AssemblyAngularVelocity = Vector3.zero
                r.CFrame = Anti.Bring.lastCF
                Anti.Bring.blockedBrings = Anti.Bring.blockedBrings + 1
                notify("COCO POWDER", "Anti-Bring v4: Blocked hostile teleport/grab!")
            elseif isSafePlayableCF(r.CFrame) then
                Anti.Bring.lastCF = r.CFrame
            end
        elseif isSafePlayableCF(r.CFrame) then
            Anti.Bring.lastCF = r.CFrame
        end
    end)
    if syncAllAntiButtons then pcall(syncAllAntiButtons) end
    notify("COCO POWDER", "Anti-Bring / Tool-Grab & Snap Guard v4 ON")
    sToggleOn()
end

bringStop = function()
    if not Anti.Bring.enabled then return end
    Anti.Bring.enabled = false
    if Anti.Bring.steppedConn then Anti.Bring.steppedConn:Disconnect(); Anti.Bring.steppedConn = nil end
    if syncAllAntiButtons then pcall(syncAllAntiButtons) end
    notify("COCO POWDER", "Anti-Bring disabled")
    sToggleOff()
end

-- ═══════════════════════════════════════════════════════════════════════════════
-- 11. ADVANCED ANTI-FLING & NO-CONTACT SHIELD V4 (ZERO-LEVITATION & NATURAL GRAVITY)
--     • Strips CanCollide/CanTouch on all other players' characters so spinners
--       pass harmlessly through you without ever touching your physics assembly.
--     • Distinguishes natural jumping/falling & Y-axis camera turning from 3-axis
--       fling impulses so your character NEVER levitates or stutters in mid-air!
-- ═══════════════════════════════════════════════════════════════════════════════
local function dampHostileFlingImpulse(myChar, myRoot)
    local myHum = myChar and myChar:FindFirstChildOfClass("Humanoid")
    local isIntentionalFast = (moveState and (moveState.fly or moveState.flyLanding or moveState.speed or moveState.spiderWalk or moveState.airWalk))
    local walkSpd = (myHum and myHum.WalkSpeed) or 16
    local jumpPwr = (myHum and myHum.JumpPower) or 50

    local vel = myRoot.AssemblyLinearVelocity
    local angVel = myRoot.AssemblyAngularVelocity
    local horizSpeed = Vector2.new(vel.X, vel.Z).Magnitude
    local tiltSpin = Vector2.new(angVel.X, angVel.Z).Magnitude

    local maxHorizAllowed = isIntentionalFast and math.max(580, walkSpd * 2.5) or math.max(175, walkSpd * 3.0)
    local maxUpAllowed    = isIntentionalFast and 580 or math.max(380, jumpPwr * 1.6)
    local maxDownAllowed  = -255
    local maxTiltSpin     = isIntentionalFast and 68 or 44
    local maxTotalSpin    = isIntentionalFast and 130 or 105

    local isFlingSpike = (horizSpeed > maxHorizAllowed)
        or (vel.Y > maxUpAllowed)
        or (vel.Y < maxDownAllowed)
        or (tiltSpin > maxTiltSpin)
        or (angVel.Magnitude > maxTotalSpin)

    if not isFlingSpike then
        if isSafePlayableCF(myRoot.CFrame) then
            Anti.FlingShield.preStepCF = myRoot.CFrame
        end
        return false
    end

    -- Clamp only the hostile impulse while preserving natural downward gravity so you never hover in mid-air!
    local clampedY = math.clamp(vel.Y, -65, math.min(jumpPwr, 55))
    if vel.Y > maxUpAllowed then clampedY = 0 end
    myRoot.AssemblyLinearVelocity = Vector3.new(0, clampedY, 0)
    myRoot.AssemblyAngularVelocity = Vector3.zero

    if Anti.FlingShield.preStepCF and isSafePlayableCF(Anti.FlingShield.preStepCF) then
        local prePos = Anti.FlingShield.preStepCF.Position
        local curPos = myRoot.Position
        local horizJump = Vector2.new(curPos.X - prePos.X, curPos.Z - prePos.Z).Magnitude
        if horizJump > 18 or not isSafePlayableCF(myRoot.CFrame) then
            local _, yYaw, _ = myRoot.CFrame:ToEulerAnglesYXZ()
            myRoot.CFrame = CFrame.new(prePos.X, math.min(curPos.Y, prePos.Y + 0.5), prePos.Z) * CFrame.Angles(0, yYaw, 0)
        end
    end
    if isSafePlayableCF(myRoot.CFrame) then
        Anti.FlingShield.preStepCF = myRoot.CFrame
    end
    Anti.FlingShield.blockedFlings = Anti.FlingShield.blockedFlings + 1
    if updateDefenceStatsUI then pcall(updateDefenceStatsUI) end
    return true
end

flingShieldStart = function()
    if Anti.FlingShield.enabled then return end
    Anti.FlingShield.enabled = true
    if Anti.FlingShield.steppedConn then Anti.FlingShield.steppedConn:Disconnect() end
    Anti.FlingShield.steppedConn = RunService.Stepped:Connect(function()
        if not Anti.FlingShield.enabled and not DefenceTroll.enabled then return end
        local myChar = LP.Character
        local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
        if not myRoot then return end
        if Anti.FlingShield.lastChar ~= myChar then
            Anti.FlingShield.lastChar = myChar
            Anti.FlingShield.preStepCF = isSafePlayableCF(myRoot.CFrame) and myRoot.CFrame or nil
            return
        end
        if WeldIntent.active or CurrentWeld ~= nil or WeldSeekingTarget or (AnimCopySys and AnimCopySys.active) or (moveState and moveState.Vanish and moveState.Vanish.selfActive) or _G.CocaBangActive or _G.CocaCopierActive or (OwnerAdminState and OwnerAdminState.formationMode) or (_G.CocaSkyDestroyer and (_G.CocaSkyDestroyer.isAnyActive() or _G.CocaSkyDestroyer.is_reanimated())) or (_G._AngoorZenApi and type(_G._AngoorZenApi.is_reanimated) == "function" and _G._AngoorZenApi.is_reanimated()) or FlingActive or deflectBusy or (RewindSys and RewindSys.rewinding) then
            if isSafePlayableCF(myRoot.CFrame) then
                Anti.FlingShield.preStepCF = myRoot.CFrame
            end
            return
        end

        dampHostileFlingImpulse(myChar, myRoot)

        -- Proactive Fling & Bang Collision Nullifier: strips CanCollide + CanTouch on hostile spinners/flingers/bangers
        -- (catches WalkFling, TouchFling, Reanim-Fling & CFrame-snap spinners) without affecting normal/target players!
        local nowTick = os.clock()
        if nowTick - (Anti.FlingShield.lastNullifyScan or 0) > 0.08 then
            Anti.FlingShield.lastNullifyScan = nowTick
            for _, otherPlr in ipairs(Players:GetPlayers()) do
                if otherPlr ~= LP and otherPlr ~= selectedPlayer and otherPlr ~= CurrentTarget and otherPlr ~= (WeldIntent and WeldIntent.target) and otherPlr.Character then
                    local otherRoot = otherPlr.Character:FindFirstChild("HumanoidRootPart") or otherPlr.Character:FindFirstChild("UpperTorso") or otherPlr.Character:FindFirstChild("Torso")
                    if otherRoot then
                        local d = (otherRoot.Position - myRoot.Position).Magnitude
                        if d < 28 then
                            local vMag = otherRoot.AssemblyLinearVelocity.Magnitude
                            local aMag = otherRoot.AssemblyAngularVelocity.Magnitude
                            local isHostileSpinner = (vMag > 75 or aMag > 32) or (d < 9 and (vMag > 52 or aMag > 22))
                            local isCloseBanger = Anti.Bang.enabled and (d < 5.0)
                            if isHostileSpinner or isCloseBanger then
                                for _, p in ipairs(otherPlr.Character:GetChildren()) do
                                    if p:IsA("BasePart") then
                                        if p.CanCollide then p.CanCollide = false end
                                        if isHostileSpinner and p.CanTouch then p.CanTouch = false end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end)
    if Anti.FlingShield.heartbeatConn then Anti.FlingShield.heartbeatConn:Disconnect() end
    Anti.FlingShield.heartbeatConn = RunService.Heartbeat:Connect(function()
        if not Anti.FlingShield.enabled and not DefenceTroll.enabled then return end
        local myChar = LP.Character
        local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
        if not myRoot then return end
        if WeldIntent.active or CurrentWeld ~= nil or WeldSeekingTarget or (AnimCopySys and AnimCopySys.active) or (moveState and moveState.Vanish and moveState.Vanish.selfActive) or _G.CocaBangActive or _G.CocaCopierActive or (OwnerAdminState and OwnerAdminState.formationMode) or (_G.CocaSkyDestroyer and (_G.CocaSkyDestroyer.isAnyActive() or _G.CocaSkyDestroyer.is_reanimated())) or (_G._AngoorZenApi and type(_G._AngoorZenApi.is_reanimated) == "function" and _G._AngoorZenApi.is_reanimated()) or FlingActive or deflectBusy or (RewindSys and RewindSys.rewinding) then
            if isSafePlayableCF(myRoot.CFrame) then
                Anti.FlingShield.preStepCF = myRoot.CFrame
            end
            return
        end
        dampHostileFlingImpulse(myChar, myRoot)
    end)
    if syncAllAntiButtons then pcall(syncAllAntiButtons) end
    notify("COCO POWDER", "Anti-Fling Shield v4 (Zero-Impulse + Natural Gravity) ON")
    sToggleOn()
end

flingShieldStop = function()
    if not Anti.FlingShield.enabled then return end
    Anti.FlingShield.enabled = false
    if not DefenceTroll.enabled then
        if Anti.FlingShield.steppedConn then
            Anti.FlingShield.steppedConn:Disconnect()
            Anti.FlingShield.steppedConn = nil
        end
        if Anti.FlingShield.heartbeatConn then
            Anti.FlingShield.heartbeatConn:Disconnect()
            Anti.FlingShield.heartbeatConn = nil
        end
    end
    if syncAllAntiButtons then pcall(syncAllAntiButtons) end
    notify("COCO POWDER", "Anti-Fling Shield disabled")
    sToggleOff()
end

-- ═══════════════════════════════════════════════════════════════════════════════
-- 12. ADVANCED DEFENCE TROLL MATRIX V2 (6 COUNTER-MODES + OMNI-THREAT RADAR)
-- ═══════════════════════════════════════════════════════════════════════════════
local function findBestRedirectVictim(attacker)
    local myChar = LP.Character
    local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
    if not myRoot then return nil end
    local bestPlr, bestDist = nil, math.huge
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= LP and p ~= attacker and not (OwnerAdminState.isPlayerCarriedOrInteracting and OwnerAdminState.isPlayerCarriedOrInteracting(p, LP)) and p.Character then
            local r = p.Character:FindFirstChild("HumanoidRootPart")
            local h = p.Character:FindFirstChildOfClass("Humanoid")
            if r and (not h or h.Health > 0) and r.Position.Y > (OriginalFPDH + 25) then
                local d = (r.Position - myRoot.Position).Magnitude
                if d < bestDist then
                    bestDist = d
                    bestPlr = p
                end
            end
        end
    end
    return bestPlr
end

local function executeDeflectAction(attacker, threatReason)
    if deflectBusy then return end
    local myChar = LP.Character
    local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
    local myHum  = myChar and myChar:FindFirstChildOfClass("Humanoid")
    if not myRoot or not myHum or myHum.Health <= 0 then return end
    if not attacker or not attacker.Character then return end
    local attRoot = pickTargetRef(attacker.Character, "torso")
    if not attRoot then return end

    deflectBusy = true
    DefenceTroll.deflectCount = DefenceTroll.deflectCount + 1
    DefenceTroll.lastAttackerName = attacker.Name
    DefenceTroll.lastThreatReason = threatReason or "Proximity/Troll"

    -- Determine active counter mode (respects dedicated PauseTrap / Redirect toggles too)
    local mode = DefenceTroll.mode or "GodMatrix"
    if not DefenceTroll.enabled then
        if Anti.Redirect.enabled then mode = "Redirect"
        elseif Anti.PauseTrap.enabled then mode = "VoidPause" end
    end

    local savedCF = isSafePlayableCF(myRoot.CFrame) and myRoot.CFrame or findFallbackSafeCF()
    markIntentionalTeleport(savedCF)
    local currentCam = workspace.CurrentCamera
    local savedCamCF = currentCam and currentCam.CFrame
    local savedCamType = currentCam and currentCam.CameraType

    pcall(function() workspace.FallenPartsDestroyHeight = -50000 end)
    if currentCam and savedCamCF then
        pcall(function()
            currentCam.CameraType = Enum.CameraType.Scriptable
            currentCam.CFrame = savedCamCF
        end)
    end

    -- 1. Instant Disarm: Sever any hostile welds/constraints & make local parts non-colliding with world walls
    severAllHostileAttachments()
    for _, part in ipairs(myChar:GetDescendants()) do
        if part:IsA("BasePart") then
            part.CanCollide = false
            part.CanTouch = false
            part.Massless = true
        end
    end

    local alertMsg = "🛡️ " .. (DefenceTroll.modeLabels[mode] or mode) .. " -> " .. attacker.Name .. " (" .. tostring(DefenceTroll.lastThreatReason) .. ")"
    notify("COCO POWDER", alertMsg)
    if showDefenceToast then showDefenceToast(alertMsg) end
    sFling()

    local voidDropY = math.clamp(OriginalFPDH - 155, -780, -340)
    local voidDropCF = CFrame.new(savedCF.Position.X, voidDropY, savedCF.Position.Z)

    if mode == "GodMatrix" then
        -- Phase 1: High-RPM Kinetic Vortex Intersection through Attacker Center of Mass
        for i = 1, 6 do
            if not myRoot.Parent or not attRoot.Parent then break end
            local angle = i * 1.15
            myRoot.CFrame = attRoot.CFrame * CFrame.new(math.cos(angle) * 0.65, 0, math.sin(angle) * 0.65)
                * CFrame.Angles(math.rad(math.random(-180, 180)), angle, math.rad(math.random(-180, 180)))
            myRoot.AssemblyAngularVelocity = Vector3.new(95000, 95000, 95000)
            myRoot.AssemblyLinearVelocity = Vector3.new(math.random(-28000, 28000), -60000, math.random(-28000, 28000))
            RunService.Heartbeat:Wait()
        end
        -- Phase 2: Streamed-Chunk Void Drop (kills welded attackers instantly)
        for _ = 1, 5 do
            if not myRoot.Parent then break end
            myRoot.CFrame = voidDropCF
            myRoot.AssemblyLinearVelocity = Vector3.new(0, -75000, 0)
            myRoot.AssemblyAngularVelocity = Vector3.zero
            RunService.Heartbeat:Wait()
        end
        -- Phase 3: Bystander Slingshot Redirect
        local victim = findBestRedirectVictim(attacker)
        if victim and victim.Character then
            local vRoot = pickTargetRef(victim.Character, "torso")
            if vRoot and isSafePlayableCF(vRoot.CFrame) then
                for _ = 1, 4 do
                    if not myRoot.Parent or not vRoot.Parent then break end
                    myRoot.CFrame = vRoot.CFrame * CFrame.new(0, 0, 0.35)
                    myRoot.AssemblyLinearVelocity = Vector3.zero
                    RunService.Heartbeat:Wait()
                end
            end
        end
    elseif mode == "ReverseFling" then
        local startT = tick()
        while tick() - startT < 0.26 do
            if not myRoot.Parent or not attRoot.Parent then break end
            local t = (tick() - startT) * 48
            local vel = attRoot.AssemblyLinearVelocity
            local lead = Vector3.new(vel.X, 0, vel.Z) * 0.06
            myRoot.CFrame = CFrame.new(attRoot.Position + lead + Vector3.new(math.cos(t) * 1.1, 0.3, math.sin(t) * 1.1))
                * CFrame.Angles(t, t * 1.5, 0)
            myRoot.AssemblyAngularVelocity = Vector3.new(95000, 95000, 95000)
            myRoot.AssemblyLinearVelocity = Vector3.new(math.random(-22000, 22000), 48000, math.random(-22000, 22000))
            RunService.Heartbeat:Wait()
        end
    elseif mode == "VoidPause" then
        for _ = 1, 7 do
            if not myRoot.Parent then break end
            myRoot.CFrame = voidDropCF
            myRoot.AssemblyLinearVelocity = Vector3.new(0, -78000, 0)
            myRoot.AssemblyAngularVelocity = Vector3.new(45000, 0, 45000)
            RunService.Heartbeat:Wait()
        end
    elseif mode == "Redirect" then
        local victim = findBestRedirectVictim(attacker)
        local vRoot = victim and victim.Character and pickTargetRef(victim.Character, "torso")
        if vRoot and isSafePlayableCF(vRoot.CFrame) then
            local startT = tick()
            while tick() - startT < 0.30 do
                if not myRoot.Parent or not vRoot.Parent then break end
                myRoot.AssemblyLinearVelocity = Vector3.zero
                myRoot.AssemblyAngularVelocity = Vector3.zero
                myRoot.CFrame = vRoot.CFrame * CFrame.new(0, 0, 0.32)
                RunService.Heartbeat:Wait()
            end
        else
            for _ = 1, 6 do
                if not myRoot.Parent then break end
                myRoot.CFrame = voidDropCF
                myRoot.AssemblyLinearVelocity = Vector3.new(0, -70000, 0)
                RunService.Heartbeat:Wait()
            end
        end
    elseif mode == "Blackhole" then
        local startT = tick()
        while tick() - startT < 0.26 do
            if not myRoot.Parent or not attRoot.Parent then break end
            local elapsed = tick() - startT
            local radius = 0.8 + (elapsed * 18)
            local angle = elapsed * 58
            local offset = Vector3.new(math.cos(angle) * radius, 0.6, math.sin(angle) * radius)
            myRoot.CFrame = CFrame.lookAt(attRoot.Position + offset, attRoot.Position)
            myRoot.AssemblyLinearVelocity = offset.Unit * 58000
            myRoot.AssemblyAngularVelocity = Vector3.new(0, 95000, 0)
            RunService.Heartbeat:Wait()
        end
    elseif mode == "SkyOrbit" then
        -- SKY ORBIT: Launches welded/attacking troll vertically into upper-atmosphere orbit (+18,000 Y)
        local skyCF = CFrame.new(savedCF.Position.X, math.min(savedCF.Position.Y + 18000, 45000), savedCF.Position.Z)
        for _ = 1, 5 do
            if not myRoot.Parent or not attRoot.Parent then break end
            myRoot.CFrame = attRoot.CFrame
            myRoot.AssemblyLinearVelocity = Vector3.new(0, 85000, 0)
            myRoot.AssemblyAngularVelocity = Vector3.new(85000, 85000, 85000)
            RunService.Heartbeat:Wait()
        end
        for _ = 1, 4 do
            if not myRoot.Parent then break end
            myRoot.CFrame = skyCF
            myRoot.AssemblyLinearVelocity = Vector3.new(0, 90000, 0)
            RunService.Heartbeat:Wait()
        end
    end

    -- Multi-frame anchored snapback to exact savedCF so local player NEVER stays stuck in the void
    LastVoidActionEnd = tick()
    markIntentionalTeleport(savedCF)
    safeReturnFromVoid(myChar, savedCF)
    task.wait(0.06)
    if currentCam then
        pcall(function()
            currentCam.CameraType = savedCamType or Enum.CameraType.Custom
            if myHum then currentCam.CameraSubject = myHum end
        end)
    end
    deflectBusy = false
    if updateDefenceStatsUI then pcall(updateDefenceStatsUI) end
end

-- Known Bang / Facebang / Backshots / Jerk / Poop Troll Animation IDs for Anti-Bang detection
local KNOWN_BANG_ANIM_IDS = {
    ["148840371"] = true, ["5918726674"] = true, ["116235062592344"] = true,
    ["128342454196913"] = true, ["4555808220"] = true, ["109168916859109"] = true,
    ["85194549268064"] = true, ["72042024"] = true, ["136828069054505"] = true,
    ["110110691026962"] = true, ["124127012123232"] = true, ["178130996"] = true,
}
local bangTrackState = {} -- [userId] = { lastDist, lastDir, flips, flipResetAt, glueTime, lastRelVec }

local function isPlayingBangAnim(hum)
    if not hum then return false end
    local animator = hum:FindFirstChildOfClass("Animator")
    if not animator then return false end
    local ok, tracks = pcall(function() return animator:GetPlayingAnimationTracks() end)
    if not ok or not tracks then return false end
    for i = 1, #tracks do
        local tr = tracks[i]
        local aObj = tr and tr.Animation
        local aId = aObj and tostring(aObj.AnimationId or "")
        if aId and aId ~= "" then
            local numId = aId:match("(%d+)")
            if numId and KNOWN_BANG_ANIM_IDS[numId] then
                return true
            end
        end
    end
    return false
end

-- Omni-Threat Radar V3: Detects Flingers (Spinners/WalkFling/TouchFling) AND Bang/Facebang/Backshots/Headsit/CFrame-Weld Trolls -> Instant Deflect!
local lastRadarTick = 0
RunService.Heartbeat:Connect(function(dt)
    local antiFlingDeflectOn = Anti.FlingShield.enabled and (Anti.FlingShield.autoDeflect ~= false)
    local antiBangOn = Anti.Bang.enabled
    if not DefenceTroll.enabled and not Anti.Redirect.enabled and not Anti.PauseTrap.enabled and not antiFlingDeflectOn and not antiBangOn then
        return
    end
    local nowClock = os.clock()
    if nowClock - lastRadarTick < 0.05 then return end
    dt = nowClock - lastRadarTick
    lastRadarTick = nowClock

    if WeldIntent.active or CurrentWeld ~= nil or (AnimCopySys and AnimCopySys.active) or _G.CocaBangActive or (EmoteHub and EmoteHub.jerkActive) or (_G.CocaSkyDestroyer and _G.CocaSkyDestroyer.isAnyActive()) or FlingActive or deflectBusy or (tick() - (moveState.lastTeleportTick or 0) < 1.2) then
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LP and p.Character then
                local tr = pickTargetRef(p.Character, "torso", p)
                if tr then attackerLastPos[p.UserId] = tr.Position end
            end
        end
        return
    end

    local myChar = LP.Character
    local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
    local myHead = myChar and myChar:FindFirstChild("Head")
    local myHum  = myChar and myChar:FindFirstChildOfClass("Humanoid")
    if not myRoot or not myHum or myHum.Health <= 0 then return end

    local baseRange = DefenceTroll.enabled and (DefenceTroll.range or 7.5) or 7.0
    local mySpeed = myRoot.AssemblyLinearVelocity.Magnitude
    local now = tick()

    for _, p in ipairs(Players:GetPlayers()) do
        local isFriendlyTarget = (p == selectedPlayer) or (p == CurrentTarget) or (p == WeldIntent.target) or (AnimCopySys and p == AnimCopySys.target) or (OwnerAdminState.isPlayerCarriedOrInteracting and OwnerAdminState.isPlayerCarriedOrInteracting(p, LP))
        if p ~= LP and not isFriendlyTarget and p.Character and not isProtectedFromLocalPlayer(p) then
            local tRoot = pickTargetRef(p.Character, "torso", p)
            local tHum  = p.Character:FindFirstChildOfClass("Humanoid")
            if tRoot and (not tHum or tHum.Health > 0) then
                local distRoot = (tRoot.Position - myRoot.Position).Magnitude
                local distHead = myHead and (tRoot.Position - myHead.Position).Magnitude or distRoot
                local dist = math.min(distRoot, distHead)
                local vel = tRoot.AssemblyLinearVelocity
                local velMag = vel.Magnitude
                local angMag = tRoot.AssemblyAngularVelocity.Magnitude

                local toMe = (myRoot.Position - tRoot.Position)
                local closingSpeed = (toMe.Magnitude > 0.01) and vel:Dot(toMe.Unit) or 0

                local prevPos = attackerLastPos[p.UserId]
                attackerLastPos[p.UserId] = tRoot.Position
                local stepDelta = prevPos and (tRoot.Position - prevPos).Magnitude or 0

                -- 1. Anti-Fling Threat Detection (Spinners, WalkFling, TouchFling, Reanim-Fling — even if spinning in place on top of you!)
                local isSpinnerThreat = (
                    ((velMag > 110 or angMag > 42) and dist <= (baseRange * 1.8) and (closingSpeed > 15 or dist <= 9.5))
                    or ((velMag > 72 or angMag > 28) and dist <= 6.0)
                )

                -- 2. Anti-Bang / Facebang / Backshots / Headsit / CFrame-Weld Detection
                local isBangThreat = false
                local bangReason = "Anti-Bang Deflect"
                if dist <= 4.8 and (antiBangOn or DefenceTroll.enabled or Anti.Redirect.enabled or Anti.PauseTrap.enabled) then
                    local st = bangTrackState[p.UserId]
                    if not st then
                        st = { lastDist = dist, lastDir = 0, flips = 0, flipResetAt = now, glueTime = 0, lastRelVec = tRoot.Position - myRoot.Position }
                        bangTrackState[p.UserId] = st
                    end
                    -- Signal A: Playing known Bang / Facebang / Jerk / Poop animation right on top of us
                    if dist <= 4.4 and isPlayingBangAnim(tHum) then
                        isBangThreat = true
                        bangReason = "Bang/Troll Anim"
                    end
                    -- Signal B: Rapid inward/outward oscillation (classic bang/facebang/backshots CFrame thrust!)
                    local dDelta = dist - (st.lastDist or dist)
                    if math.abs(dDelta) >= 0.14 then
                        local dir = (dDelta > 0) and 1 or -1
                        if st.lastDir ~= 0 and dir ~= st.lastDir then
                            if (now - st.flipResetAt) > 1.1 then
                                st.flips = 1
                                st.flipResetAt = now
                            else
                                st.flips = st.flips + 1
                            end
                        end
                        st.lastDir = dir
                    end
                    st.lastDist = dist
                    if st.flips >= 3 and (now - st.flipResetAt) <= 1.1 then
                        isBangThreat = true
                        bangReason = "Bang Oscillation"
                    end
                    -- Signal C: Glued / CFrame-welded to our Head or Back (PlatformStand/Physics or matching our movement 1:1)
                    local relVec = tRoot.Position - myRoot.Position
                    local relDrift = st.lastRelVec and (relVec - st.lastRelVec).Magnitude or 99
                    st.lastRelVec = relVec
                    local okSt, humSt = pcall(function() return tHum and tHum:GetState() end)
                    local isPhysLock = tHum and (tHum.PlatformStand or (okSt and humSt == Enum.HumanoidStateType.Physics))
                    if dist <= 3.8 and (isPhysLock or (mySpeed > 4.5 and relDrift < 0.85)) then
                        st.glueTime = st.glueTime + dt
                        if st.glueTime >= 0.22 then
                            isBangThreat = true
                            bangReason = isPhysLock and "Weld/Bang Lock" or "CFrame Weld Lock"
                        end
                    else
                        st.glueTime = math.max(0, st.glueTime - dt * 2)
                    end
                elseif bangTrackState[p.UserId] then
                    bangTrackState[p.UserId].flips = 0
                    bangTrackState[p.UserId].glueTime = 0
                end

                local isWeldTrollState = dist <= 3.6 and (
                    (tHum and (tHum.PlatformStand or tHum:GetState() == Enum.HumanoidStateType.Physics))
                    and (closingSpeed > 18 or stepDelta > 2.2)
                )

                local shouldDeflectFling = isSpinnerThreat and (antiFlingDeflectOn or DefenceTroll.enabled or Anti.Redirect.enabled or Anti.PauseTrap.enabled)
                local shouldDeflectBang  = (isBangThreat or isWeldTrollState) and (antiBangOn or DefenceTroll.enabled or Anti.Redirect.enabled or Anti.PauseTrap.enabled)

                if shouldDeflectFling or shouldDeflectBang then
                    local weight = shouldDeflectFling and 6.0 or 5.0
                    local reason = shouldDeflectFling and "Anti-Fling Deflect" or (isBangThreat and bangReason or "Weld/Troll Lock")
                    contactTimers[p.UserId] = (contactTimers[p.UserId] or 0) + dt * weight
                    local lastCd = deflectCooldowns[p.UserId] or 0
                    if (contactTimers[p.UserId] >= 0.08 or shouldDeflectFling or isBangThreat) and (now - lastCd) > 0.70 then
                        deflectCooldowns[p.UserId] = now
                        contactTimers[p.UserId] = 0
                        if bangTrackState[p.UserId] then
                            bangTrackState[p.UserId].flips = 0
                            bangTrackState[p.UserId].glueTime = 0
                        end
                        if shouldDeflectBang then
                            Anti.Bang.blockedBangs = (Anti.Bang.blockedBangs or 0) + 1
                            Anti.Bang.deflectedBangs = (Anti.Bang.deflectedBangs or 0) + 1
                        else
                            Anti.FlingShield.deflectedFlings = (Anti.FlingShield.deflectedFlings or 0) + 1
                        end
                        task.spawn(function() executeDeflectAction(p, reason) end)
                        break
                    end
                else
                    contactTimers[p.UserId] = math.max(0, (contactTimers[p.UserId] or 0) - dt * 3)
                end
            end
        end
    end
end)

