-- 👑 OWNER FREEZE, SCRIPT BAN, OVERHEAD NAME TAGS & BEACON SYNC IMPLEMENTATION
local broadcastOwnerAdminCommand, notifyOwnerJoinedServer
;(function()
-- ═══════════════════════════════════════════════════════════════════════════════
local function applyOwnerFreezeState(freezeOn, ownerName)
    if freezeOn and isConfiguredScriptOwner(LP) and (OwnerAdminState.ownerImmunityEnabled ~= false) then return end -- Respect Manual Owner Immunity
    ownerName = ownerName or "Script Owner"
    OwnerAdminState.isFrozenByOwner = freezeOn and true or false
    OwnerAdminState.frozenByOwnerName = ownerName
    if DetectedScriptUsers[LP.UserId] then
        DetectedScriptUsers[LP.UserId].isFrozen = OwnerAdminState.isFrozenByOwner
    end

    if freezeOn then
        if stopWeld then pcall(stopWeld) end
        if StateManager and StateManager.Cleanup then pcall(function() StateManager:Cleanup(false) end) end
        if moveState and moveState.stopFlyImmediate then pcall(moveState.stopFlyImmediate) end
        if _G.stopSkyDestroyer then pcall(_G.stopSkyDestroyer) end
        if _G._AngoorZenApi and type(_G._AngoorZenApi.reanimate) == "function" then
            pcall(function() if _G._AngoorZenApi.is_reanimated() then _G._AngoorZenApi.reanimate(false) end end)
        end

        local frozenLockChar = LP.Character
        local initRt = frozenLockChar and (frozenLockChar:FindFirstChild("HumanoidRootPart") or frozenLockChar:FindFirstChildWhichIsA("BasePart"))
        local frozenLockCF = initRt and initRt.CFrame or nil

        if OwnerAdminState.freezeLoopConn then OwnerAdminState.freezeLoopConn:Disconnect() end
        OwnerAdminState.freezeLoopConn = RunService.Stepped:Connect(function()
            if not OwnerAdminState.isFrozenByOwner then return end
            if stopWeld and (WeldIntent.active or CurrentWeld) then pcall(stopWeld) end
            if AnimCopySys and AnimCopySys.active then pcall(function() AnimCopySys:Stop(true) end) end
            if moveState and moveState.fly and moveState.stopFlyImmediate then pcall(moveState.stopFlyImmediate) end
            local ch = LP.Character
            if not ch then return end
            local rt = ch:FindFirstChild("HumanoidRootPart") or ch:FindFirstChildWhichIsA("BasePart")
            local hm = ch:FindFirstChildOfClass("Humanoid")
            if ch ~= frozenLockChar and rt then
                frozenLockChar = ch
                frozenLockCF = rt.CFrame
            end
            for _, p in ipairs(ch:GetDescendants()) do
                if p:IsA("BasePart") then
                    p.Anchored = true
                    p.AssemblyLinearVelocity = Vector3.zero
                    p.AssemblyAngularVelocity = Vector3.zero
                end
            end
            if rt and frozenLockCF then
                rt.CFrame = frozenLockCF
            end
            if hm then
                hm.WalkSpeed = 0
                hm.UseJumpPower = true
                hm.JumpPower = 0
                pcall(function() hm.JumpHeight = 0 end)
                hm.PlatformStand = true
                hm.AutoRotate = false
                hm.Sit = false
            end
        end)

        showOwnerScreenBanner(
            "❄️ FROZEN BY SCRIPT OWNER",
            "@" .. tostring(ownerName) .. " froze your character. Waiting for Owner to unfreeze you.",
            Color3.fromRGB(86, 204, 255),
            0,
            "FreezeLockBanner"
        )
        notify("❄️ FROZEN BY OWNER", "Script Owner @" .. tostring(ownerName) .. " has frozen you!")
        sError()
    else
        if OwnerAdminState.freezeLoopConn then
            OwnerAdminState.freezeLoopConn:Disconnect()
            OwnerAdminState.freezeLoopConn = nil
        end
        local ch = LP.Character
        if ch then
            for _, part in ipairs(ch:GetDescendants()) do
                if part:IsA("BasePart") then
                    part.Anchored = false
                end
            end
            local hm = ch:FindFirstChildOfClass("Humanoid")
            if hm then
                hm.WalkSpeed = 16
                hm.UseJumpPower = true
                hm.JumpPower = 50
                pcall(function() hm.JumpHeight = 7.2 end)
                hm.PlatformStand = false
                hm.AutoRotate = true
            end
        end
        clearPersistentBanner("FreezeLockBanner")
        showOwnerScreenBanner(
            "✅ UNFROZEN BY SCRIPT OWNER",
            "@" .. tostring(ownerName) .. " unfroze your character!",
            Color3.fromRGB(52, 211, 153),
            4.0,
            nil
        )
        notify("👑 OWNER ADMIN", "You have been unfrozen by @" .. tostring(ownerName) .. "!")
        sSuccess()
    end
end

local function applyOwnerScriptBan(ownerName, blockerRole)
    if isConfiguredScriptOwner(LP) then return end -- Script Owners can NEVER be script-blocked
    ownerName = ownerName or "Script Owner"
    blockerRole = blockerRole or "Admin"
    OwnerAdminState.isBannedByOwner = true
    OwnerAdminState.bannedByOwnerName = ownerName
    saveBanStateToDisk(true, ownerName)

    if OwnerAdminState.isFrozenByOwner then
        applyOwnerFreezeState(false, ownerName)
    end
    if stopWeld then pcall(stopWeld) end
    if StateManager and StateManager.Cleanup then pcall(function() StateManager:Cleanup(false) end) end
    if moveState and moveState.stopFlyImmediate then pcall(moveState.stopFlyImmediate) end
    if _G._AngoorZenStretch and _G._AngoorZenStretch.stopAll then pcall(_G._AngoorZenStretch.stopAll) end
    if _G._AngoorZenUltra and _G._AngoorZenUltra.stopAll then pcall(_G._AngoorZenUltra.stopAll) end
    if _G._AngoorZenTwist and _G._AngoorZenTwist.stopAll then pcall(_G._AngoorZenTwist.stopAll) end
    if _G._AngoorZenApi and type(_G._AngoorZenApi.reanimate) == "function" then
        pcall(function() if _G._AngoorZenApi.is_reanimated() then _G._AngoorZenApi.reanimate(false) end end)
    end

    -- Destroy all overhead tags
    for uid, entry in pairs(OverheadTagGuis) do
        if entry and entry.gui then pcall(function() entry.gui:Destroy() end) end
        OverheadTagGuis[uid] = nil
    end

    -- Destroy main CocoPowder GUI so blocked user cannot use any script features
    if gui and gui.Parent then
        pcall(function() gui:Destroy() end)
    end
    cleanupOldGuis(GuiParent)
    cleanupOldGuis(LP:FindFirstChildOfClass("PlayerGui"))

    showOwnerScreenBanner(
        "🚫 BLOCKED FROM COCO POWDER",
        tostring(blockerRole) .. " @" .. tostring(ownerName) .. " blocked you from using this script.",
        Color3.fromRGB(244, 63, 94),
        12.0,
        "BanLockBanner"
    )
    notify("🚫 SCRIPT BLOCKED", "You were blocked from using Coco Powder by " .. tostring(blockerRole) .. " @" .. tostring(ownerName))
    sError()
end

local function clearOwnerScriptBan(ownerName, blockerRole)
    ownerName = ownerName or "Script Owner"
    blockerRole = blockerRole or "Admin"
    OwnerAdminState.isBannedByOwner = false
    saveBanStateToDisk(false, ownerName)
    clearPersistentBanner("BanLockBanner")
    showOwnerScreenBanner(
        "✅ UNBLOCKED FROM COCO POWDER",
        tostring(blockerRole) .. " @" .. tostring(ownerName) .. " restored your Coco Powder access! Re-execute to open UI.",
        Color3.fromRGB(52, 211, 153),
        6.0,
        nil
    )
    notify("✅ ACCESS RESTORED", "You were unblocked by " .. tostring(blockerRole) .. " @" .. tostring(ownerName) .. "! Re-execute script to open UI.")
    sSuccess()
end

local function bringLocalPlayerToOwner(ownerPlr)
    if isConfiguredScriptOwner(LP) and (OwnerAdminState.ownerImmunityEnabled ~= false) then return end -- Respect Manual Owner Immunity
    if not ownerPlr then return end
    if stopWeld and (WeldIntent.active or CurrentWeld) then pcall(stopWeld, true) end
    if AnimCopySys and AnimCopySys.active then pcall(function() AnimCopySys:Stop(true) end) end
    if moveState and moveState.fly and moveState.stopFlyImmediate then pcall(moveState.stopFlyImmediate) end
    local oChar = findPlayerCharacterAnywhere and findPlayerCharacterAnywhere(ownerPlr) or ownerPlr.Character
    local oRoot = (findPlayerVoiceTagAnchor and select(1, findPlayerVoiceTagAnchor(ownerPlr, oChar)))
        or (oChar and pickTargetRef and pickTargetRef(oChar, "torso", ownerPlr))
        or (oChar and (oChar:FindFirstChild("HumanoidRootPart") or oChar:FindFirstChild("Head") or oChar:FindFirstChildWhichIsA("BasePart")))
    local myChar = LP.Character
    if not oRoot or not myChar or not isPartInSafeWorldBounds(oRoot) then return end
    local myHum = myChar:FindFirstChildOfClass("Humanoid")
    local myRoot = myChar:FindFirstChild("HumanoidRootPart") or myChar:FindFirstChildWhichIsA("BasePart")
    if breakAllSeatsAndExternalJoints then pcall(breakAllSeatsAndExternalJoints, myChar, myHum, myRoot) end
    local baseCF = getFlatYawCFrame and getFlatYawCFrame(oRoot.CFrame, oRoot.Position) or oRoot.CFrame
    local dropY = (oRoot.Name == "Head") and -1.4 or 0.5
    local destCF = baseCF * CFrame.new(0, dropY, -3.5)
    if isLethalVoidCF and isLethalVoidCF(destCF) then return end
    markIntentionalTeleport(destCF)
    safeReturnFromVoid(myChar, destCF)
    notify("👑 OWNER SUMMON", "Teleported to Admin @" .. ownerPlr.Name)
    sWhoosh()
end

