maintainLocalScriptBeacon = function()
    if OwnerAdminState.isBannedByOwner then
        if OwnerAdminState.beaconTrack then
            pcall(function() OwnerAdminState.beaconTrack:Stop(0); OwnerAdminState.beaconTrack:Destroy() end)
            OwnerAdminState.beaconTrack = nil
        end
        return
    end

    local ch = LP.Character
    local hum = ch and ch:FindFirstChildOfClass("Humanoid")
    if not ch or not hum or hum.Health <= 0 then return end
    local animator = hum:FindFirstChildOfClass("Animator")
    if not animator then
        pcall(function() animator = Instance.new("Animator", hum) end)
    end
    if not animator then return end

    local desiredSpeed = BEACON_SPEED_REGULAR
    if OwnerAdminState.activeCommandCode and tick() < OwnerAdminState.activeCommandUntil then
        desiredSpeed = OwnerAdminState.activeCommandCode
    else
        OwnerAdminState.activeCommandCode = nil
        if isScriptOwner(LP) then
            desiredSpeed = (OwnerAdminState.ownerImmunityEnabled ~= false) and BEACON_SPEED_OWNER or BEACON_SPEED_OWNER_NO_IMMUNE
        elseif isEliteUser(LP) then
            desiredSpeed = BEACON_SPEED_PREMIUM -- Elite User Beacon
        elseif isCocoStaff(LP) then
            desiredSpeed = BEACON_SPEED_STAFF   -- Coco Staff Beacon
        elseif OwnerAdminState.isFrozenByOwner then
            desiredSpeed = BEACON_SPEED_FROZEN  -- Frozen User Beacon
        else
            desiredSpeed = BEACON_SPEED_REGULAR -- Regular Script User Beacon
        end
    end

    local tr = OwnerAdminState.beaconTrack
    if not tr or not tr.IsPlaying or OwnerAdminState.beaconChar ~= ch then
        pcall(function()
            if tr then tr:Stop(0); tr:Destroy() end
            if OwnerAdminState.beaconAnim then OwnerAdminState.beaconAnim:Destroy() end
        end)
        local anim = Instance.new("Animation")
        anim.Name = "CocoPowderSyncBeacon"
        anim.AnimationId = (hum.RigType == Enum.HumanoidRigType.R15) and BEACON_ANIM_R15 or BEACON_ANIM_R6
        local ok, loaded = pcall(function() return animator:LoadAnimation(anim) end)
        if ok and loaded then
            IsCocoBeaconTrack[loaded] = true
            loaded.Priority = Enum.AnimationPriority.Core
            loaded.Looped = true
            pcall(function() loaded:Play(0, 0.005, desiredSpeed) end)
            pcall(function() loaded:AdjustWeight(0.005, 0) end)
            pcall(function() loaded:AdjustSpeed(desiredSpeed) end)
            OwnerAdminState.beaconTrack = loaded
            OwnerAdminState.beaconAnim = anim
            OwnerAdminState.beaconChar = ch
        else
            pcall(function() anim:Destroy() end)
        end
    else
        IsCocoBeaconTrack[tr] = true
        pcall(function() tr:AdjustWeight(0.005, 0) end)
        if math.abs(tr.Speed - desiredSpeed) > 0.0001 then
            pcall(function() tr:AdjustSpeed(desiredSpeed) end)
        end
    end

    DetectedScriptUsers[LP.UserId] = {
        player = LP,
        isOwner = isScriptOwner(LP),
        isPremium = isEliteUser(LP),
        isElite = isEliteUser(LP),
        isStaff = isCocoStaff(LP),
        isScriptUser = true,
        isFrozen = OwnerAdminState.isFrozenByOwner,
        lastSeen = tick(),
    }
end

-- Inspect a player's Animator tracks with strict zero-false-positive multi-signature checks
inspectPlayerBeaconTracks = function(plr)
    if not plr or plr == LP or typeof(plr) ~= "Instance" or not plr:IsA("Player") or plr.Parent ~= Players then return nil end
    local ch = plr.Character
    local hum = ch and ch:FindFirstChildOfClass("Humanoid")
    local animator = hum and hum:FindFirstChildOfClass("Animator")
    if not animator then return nil end

    local ok, tracks = pcall(function() return animator:GetPlayingAnimationTracks() end)
    if not ok or not tracks then return nil end

    local cfgOwner = isConfiguredScriptOwner(plr)
    local cfgPrem  = isConfiguredEliteUser(plr)
    local cfgStaff = isConfiguredCocoStaff(plr)

    for i = 1, #tracks do
        local t = tracks[i]
        local spd = t.Speed
        local animObj = t.Animation
        local animId = animObj and animObj.AnimationId or ""
        local isBeaconAnim = (animId:find("10714389396", 1, true) ~= nil) or (animId:find("33796059", 1, true) ~= nil)
        local wCur = tonumber(t.WeightCurrent) or 1
        local wTgt = tonumber(t.WeightTarget) or wCur
        local beaconWeight = math.min(wCur, wTgt)

        -- Zero-False-Positive Replication-Safe Signature Verification:
        -- Roblox Animator does not reliably replicate Lua-set Priority/Looped to remote clients,
        -- so we verify the obscure beacon asset ID + IsPlaying + near-zero weight (<= 0.05; normal emotes are 1.0)
        -- combined with our exact 6-digit cryptographic speed handshake.
        isBeaconAnim = isBeaconAnim and (t.IsPlaying == true) and (beaconWeight <= 0.1)

        if isBeaconAnim then
            -- Replication-safe speed handshake check (widened separation + backwards compatibility with legacy speeds)
            if math.abs(spd - BEACON_SPEED_FROZEN_LEGACY) < 0.0012 or math.abs(spd - BEACON_SPEED_FROZEN) < 0.012 then
                return { isUser = true, isOwner = cfgOwner, isPremium = cfgPrem, isFrozen = true, cmdType = nil, targetCode = nil }
            elseif math.abs(spd - BEACON_SPEED_REGULAR) < 0.012 then
                return { isUser = true, isOwner = cfgOwner, isPremium = cfgPrem, isFrozen = false, cmdType = nil, targetCode = nil }
            elseif math.abs(spd - BEACON_SPEED_STAFF) < 0.012 then
                return { isUser = true, isOwner = cfgOwner, isPremium = cfgPrem, isStaff = cfgStaff, isFrozen = false, cmdType = nil, targetCode = nil }
            elseif math.abs(spd - BEACON_SPEED_PREMIUM) < 0.012 then
                return { isUser = true, isOwner = cfgOwner, isPremium = cfgPrem, isStaff = cfgStaff, isFrozen = false, cmdType = nil, targetCode = nil }
            elseif math.abs(spd - BEACON_SPEED_OWNER_NOIMM_LEG) < 0.0012 or math.abs(spd - BEACON_SPEED_OWNER_NO_IMMUNE) < 0.012 then
                if cfgOwner then OwnerAdminState.ownerImmunityByUserId[plr.UserId] = false end
                return { isUser = true, isOwner = cfgOwner, isPremium = cfgPrem, isFrozen = false, cmdType = nil, targetCode = nil }
            elseif math.abs(spd - BEACON_SPEED_OWNER) < 0.012 then
                if cfgOwner then OwnerAdminState.ownerImmunityByUserId[plr.UserId] = true end
                return { isUser = true, isOwner = cfgOwner, isPremium = cfgPrem, isFrozen = false, cmdType = nil, targetCode = nil }
            end

            -- Encoded Admin commands on verified beacon track:
            --   • Owners & Elite Users: full command set
            --   • Coco Staff: strictly ONLY 32 (block/ban) & 42 (unblock/unban) targeting a single player (rem 100..998)
            local canSendAdmin = cfgOwner or cfgPrem
            local canSendStaffBlock = cfgStaff
            if canSendAdmin or canSendStaffBlock then
                local baseCmd = math.floor(spd + 0.0005)
                if canSendStaffBlock and not canSendAdmin then
                    if baseCmd == 32 or baseCmd == 42 then
                        local rem = math.floor(((spd - baseCmd) * 1000) + 0.5)
                        if rem >= 100 and rem <= 998 then
                            return { isUser = true, isOwner = false, isPremium = false, isStaff = true, isFrozen = false, cmdType = baseCmd, targetCode = rem }
                        end
                    end
                elseif baseCmd == 12 or baseCmd == 22 or baseCmd == 32 or baseCmd == 42 or baseCmd == 52 or baseCmd == 62 or baseCmd == 72 or baseCmd == 82
                    or (baseCmd >= 92 and baseCmd <= 96)
                    or baseCmd == 102 or baseCmd == 112 or baseCmd == 122 or baseCmd == 132 or baseCmd == 133
                    or baseCmd == 142 or baseCmd == 143
                    or (baseCmd >= 152 and baseCmd <= 156)
                    or (baseCmd >= 162 and baseCmd <= 166)
                    or (baseCmd >= 172 and baseCmd <= 174)
                    or (baseCmd >= 182 and baseCmd <= 186)
                    or (baseCmd >= 192 and baseCmd <= 194)
                    or (baseCmd >= 202 and baseCmd <= 204)
                    or (baseCmd >= 212 and baseCmd <= 216)
                    or (baseCmd >= 222 and baseCmd <= 223)
                    or (baseCmd >= 232 and baseCmd <= 249) then
                    local rem = math.floor(((spd - baseCmd) * 1000) + 0.5)
                    -- Commands 72/82 (runtime session elite) are disabled: roles are strictly hardcoded allowlists only!
                    if baseCmd == 72 or baseCmd == 82 then
                        -- Ignored intentionally
                    elseif baseCmd == 202 or baseCmd == 204 or baseCmd == 222 or baseCmd == 223 then
                        if cfgOwner and rem >= 0 and rem <= 999 then
                            return { isUser = true, isOwner = cfgOwner, isPremium = cfgPrem, isStaff = cfgStaff, isFrozen = false, cmdType = baseCmd, targetCode = rem }
                        end
                    elseif rem >= 0 and rem <= 999 then
                        return { isUser = true, isOwner = cfgOwner, isPremium = cfgPrem, isStaff = cfgStaff, isFrozen = false, cmdType = baseCmd, targetCode = rem }
                    end
                end
            end
        end
    end
    return nil
end

OwnerAdminState.maintainLocalScriptBeacon = maintainLocalScriptBeacon
OwnerAdminState.inspectPlayerBeaconTracks = inspectPlayerBeaconTracks

