-- Process incoming Owner / Elite User / Coco Staff Command (from either Beacon or Chat)
local function handleIncomingOwnerCommand(senderPlr, cmdType, targetCode, rawTargetName, customMsg)
    if not senderPlr or senderPlr == LP or typeof(senderPlr) ~= "Instance" or not senderPlr:IsA("Player") or senderPlr.Parent ~= Players then return end
    local senderIsOwner = isConfiguredScriptOwner(senderPlr)
    local senderIsElite = not senderIsOwner and isConfiguredEliteUser(senderPlr)
    local senderIsStaff = not senderIsOwner and not senderIsElite and isConfiguredCocoStaff(senderPlr)
    if not senderIsOwner and not senderIsElite and not senderIsStaff then return end

    local isBlockOrUnblockCmd = (cmdType == 32 or cmdType == "ban" or cmdType == "block" or cmdType == 42 or cmdType == "unban" or cmdType == "unblock")
    -- Strict Script-User Enforcement: remote sender MUST be an active verified Coco Powder script user!
    if not isVerifiedActiveCocoSender(senderPlr) then
        return
    end

    local isOwnerOnlyCmd = (cmdType == 202 or cmdType == "syncvip" or cmdType == 204 or cmdType == "clearvip" or cmdType == 222 or cmdType == "immuneon" or cmdType == 223 or cmdType == "immuneoff" or cmdType == "ownercustom")

    -- Coco Staff can ONLY execute block/unblock commands (32 / 42 / ban / unban / block / unblock)
    if senderIsStaff and not isBlockOrUnblockCmd then
        return
    end

    -- Owner-only commands strictly require a hardcoded Script Owner
    if isOwnerOnlyCmd and not senderIsOwner then
        return
    end

    -- Sync remote Owner's manual immunity state if they broadcast 222 (ON) or 223 (OFF)
    if senderIsOwner and (cmdType == 222 or cmdType == "immuneon") then
        local changedImm = (OwnerAdminState.ownerImmunityByUserId[senderPlr.UserId] ~= true)
        OwnerAdminState.ownerImmunityByUserId[senderPlr.UserId] = true
        pcall(updateOverheadNameTags)
        if changedImm and OwnerAdminState.refreshAdminUIFn then pcall(OwnerAdminState.refreshAdminUIFn) end
        return
    elseif senderIsOwner and (cmdType == 223 or cmdType == "immuneoff") then
        local changedImm = (OwnerAdminState.ownerImmunityByUserId[senderPlr.UserId] ~= false)
        OwnerAdminState.ownerImmunityByUserId[senderPlr.UserId] = false
        pcall(updateOverheadNameTags)
        if changedImm and OwnerAdminState.refreshAdminUIFn then pcall(OwnerAdminState.refreshAdminUIFn) end
        return
    end

    -- Unconditional Script-Block Hierarchy Enforcement on Receiver Side:
    --   • Elite Users & Coco Staff can NEVER block/unblock Script Owners (even if Owner Immunity is OFF!)
    --   • Coco Staff can NEVER block/unblock Elite Users or other Coco Staff!
    if isBlockOrUnblockCmd then
        local allowedBlock = canBlockTarget(senderPlr, LP)
        if not allowedBlock then return end
    end

    -- Unconditional Owner Hierarchy Protection: Elite Users & Coco Staff can NEVER execute ANY admin command on a Script Owner!
    if isConfiguredScriptOwner(LP) and not senderIsOwner then return end

    -- Script Owners (shivyy73, retreee_yawrrr, kaun_bhai, retree) are immune to Admin commands while their Manual Owner Immunity is ON (default ON)!
    if isConfiguredScriptOwner(LP) and (OwnerAdminState.ownerImmunityEnabled ~= false) then return end

    local myCode = getPlayerTargetCode(LP)
    local isTargeted = false
    local isPremGrantOrRevoke = (cmdType == 72 or cmdType == "grantprem" or cmdType == "grantelite" or cmdType == 82 or cmdType == "revokeprem" or cmdType == "revokeelite")

    -- Dynamic runtime Session Elite promotion/revocation is disabled so ONLY hardcoded Owners, Elite Users & Coco Staff hold authority.
    if isPremGrantOrRevoke then
        return
    else
        if targetCode ~= nil then
            -- Coco Staff can never broadcast to targetCode 0 ("all")
            if senderIsStaff and targetCode == 0 then
                isTargeted = false
            else
                isTargeted = (targetCode == 0 or targetCode == myCode)
            end
        elseif rawTargetName and rawTargetName ~= "" then
            local q = rawTargetName:lower():gsub("^%s*@+%s*", ""):gsub("^%s+", ""):gsub("%s+$", "")
            if q == "all" or q == "everyone" or q == "others" then
                if not senderIsStaff then
                    isTargeted = true
                end
            elseif q ~= "" and (LP.Name:lower():find(q, 1, true) == 1 or LP.DisplayName:lower():find(q, 1, true) == 1 or tonumber(q) == LP.UserId) then
                isTargeted = true
            end
        end
    end

    if not isTargeted then return end

    local canonicalCmdMap = {
        [12] = "freeze", [22] = "unfreeze", [32] = "ban", [42] = "unban",
        [52] = "bring", [62] = "notify", [72] = "grantprem", [82] = "revokeprem",
        [92] = "chat", [93] = "chat", [94] = "chat", [95] = "chat", [96] = "chat",
        [102] = "dance", [112] = "skylaunch", [122] = "reset", [132] = "blind", [133] = "unblind",
        [142] = "puppet", [143] = "unpuppet",
        [152] = "formation", [153] = "formation", [154] = "formation", [155] = "formation", [156] = "unformation",
        [162] = "skydestroy", [163] = "skydestroy", [164] = "skydestroy", [165] = "skydestroy", [166] = "skystop",
        [172] = "countdown", [173] = "wavechat", [174] = "chant",
        [182] = "invert", [183] = "drunk", [184] = "flashbang", [185] = "fakemodal", [186] = "clearfx",
        [192] = "tppos", [193] = "skylounge", [194] = "groundreturn",
        [202] = "syncvip", [203] = "bodyguard", [204] = "clearvip",
        [212] = "swarmfling", [213] = "massweld", [214] = "stopall", [215] = "gravity", [216] = "speedprank",
        [232] = "clearmsg", [233] = "jail", [234] = "unjail", [235] = "orbit", [236] = "unorbit",
        [237] = "bounce", [238] = "spin", [239] = "sit", [240] = "setws", [241] = "setjp",
        [242] = "watch", [243] = "unwatch", [244] = "quake", [245] = "glitch",
        [246] = "conga", [247] = "unconga", [248] = "fullreset",
    }
    local canonCmd = canonicalCmdMap[cmdType] or tostring(cmdType)
    -- Skip empty beacon triggers for commands that strictly require chat payload (target/coords/ids) so chat packet executes cleanly
    if (cmdType == 212 or cmdType == 213) and (not customMsg or customMsg == "") then
        return
    end
