removeOverheadTagForUser = function(uid)
    local entry = OverheadTagGuis[uid]
    if entry then
        if entry.gui then pcall(function() entry.gui:Destroy() end) end
        OverheadTagGuis[uid] = nil
    end
    stopOverheadTagAnimatorIfEmpty()
end

updateOverheadNameTags = function()
    if not OwnerAdminState.overheadTagsEnabled or OwnerAdminState.isBannedByOwner then
        if next(OverheadTagGuis) ~= nil then
            for uid, _ in pairs(OverheadTagGuis) do
                removeOverheadTagForUser(uid)
            end
        end
        stopOverheadTagAnimatorIfEmpty()
        return
    end

    local parentContainer = GuiParent or LP:FindFirstChildOfClass("PlayerGui")
    if not parentContainer then return end

    local activeUids = {}
    for _, plr in ipairs(Players:GetPlayers()) do
        local uid = plr.UserId
        local det = DetectedScriptUsers[uid]
        -- Only the exact configured account username/UserId receives a special badge.
        -- A public animation beacon or a matching DisplayName can never grant Premium.
        local plrIsOwner = isConfiguredScriptOwner(plr)
        local plrIsElite = not plrIsOwner and isConfiguredEliteUser(plr)
        local plrIsStaff = not plrIsOwner and not plrIsElite and isConfiguredCocoStaff(plr)
        -- STRICT EXECUTOR-ONLY RULE:
        -- Local player is running the script; remote players (including Owners, Premium, Elite, and Users)
        -- MUST have an active, fresh verified COCO POWDER beacon to show an overhead tag!
        -- Players who have NOT executed the script NEVER get any head tag.
        local beaconFresh = (plr == LP)
            or (det ~= nil and det.isScriptUser == true and (tick() - (tonumber(det.lastSeen) or 0)) <= 25.0)
        local plrIsScriptUser = false
        if beaconFresh then
            if plrIsOwner or plrIsElite or plrIsStaff then
                plrIsScriptUser = true
            elseif OwnerAdminState.showNormalPlayerTags == true then
                plrIsScriptUser = true
            end
        end

        if plr == LP and not OwnerAdminState.showSelfOverheadTag then
            plrIsScriptUser = false
        end

        local ch = plr.Character
        local adorneePart = ch and (ch:FindFirstChild("Head") or ch:FindFirstChild("HumanoidRootPart"))

        if plrIsScriptUser and adorneePart then
            activeUids[uid] = true
            local entry = OverheadTagGuis[uid]
            if not entry or not entry.gui or not entry.gui.Parent then
                local bbg = Instance.new("BillboardGui")
                bbg.Name = "CocoPowderTag_" .. tostring(uid)
                bbg.Size = UDim2.new(0, 228, 0, 44)
                bbg.StudsOffset = Vector3.new(0, 2.58, 0)
                bbg.AlwaysOnTop = true
                bbg.Active = (plr ~= LP)
                bbg.MaxDistance = 360
                bbg.LightInfluence = 0
                bbg.ResetOnSpawn = false
                bbg.Adornee = adorneePart
                bbg.Parent = parentContainer

                -- Soft outer ambient cyber-aura
                local glowFrame = Instance.new("Frame")
                glowFrame.Name = "AuraGlow"
                glowFrame.Size = UDim2.new(1, 0, 1, 0)
                glowFrame.Position = UDim2.new(0, 0, 0, 0)
                glowFrame.BackgroundColor3 = Color3.fromRGB(178, 108, 255)
                glowFrame.BackgroundTransparency = 0.85
                glowFrame.BorderSizePixel = 0
                glowFrame.ZIndex = 1
                glowFrame.Parent = bbg
                Instance.new("UICorner", glowFrame).CornerRadius = UDim.new(0, 14)

                -- Sleek Obsidian Cyber-Glass Card
                local bg = Instance.new("Frame")
                bg.Name = "TagCard"
                bg.Size = UDim2.new(1, -6, 1, -6)
                bg.Position = UDim2.new(0, 3, 0, 3)
                bg.BackgroundColor3 = Color3.new(1, 1, 1)
                bg.BackgroundTransparency = 0.08
                bg.BorderSizePixel = 0
                bg.ClipsDescendants = true
                bg.ZIndex = 2
                bg.Parent = bbg
                Instance.new("UICorner", bg).CornerRadius = UDim.new(0, 12)

                local bgGrad = Instance.new("UIGradient")
                bgGrad.Rotation = 16
                bgGrad.Parent = bg

                -- Razor-sharp orbiting liquid-metallic border
                local st = Instance.new("UIStroke")
                st.Thickness = 1.35
                st.Transparency = 0.14
                st.Color = Color3.new(1, 1, 1)
                st.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
                st.Parent = bg

                local strokeGrad = Instance.new("UIGradient")
                strokeGrad.Rotation = 0
                strokeGrad.Parent = st

                -- Top specular glass rim highlight
                local glassHighlight = Instance.new("Frame")
                glassHighlight.Name = "GlassHighlight"
                glassHighlight.Size = UDim2.new(0.82, 0, 0, 1)
                glassHighlight.Position = UDim2.new(0.09, 0, 0, 1)
                glassHighlight.BackgroundColor3 = Color3.new(1, 1, 1)
                glassHighlight.BackgroundTransparency = 0.72
                glassHighlight.BorderSizePixel = 0
                glassHighlight.ZIndex = 3
                glassHighlight.Parent = bg
                local hlGrad = Instance.new("UIGradient")
                hlGrad.Transparency = NumberSequence.new({
                    NumberSequenceKeypoint.new(0.0, 1.0),
                    NumberSequenceKeypoint.new(0.5, 0.0),
                    NumberSequenceKeypoint.new(1.0, 1.0),
                })
                hlGrad.Parent = glassHighlight

                -- Bottom glowing energy accent line
