                        if tRef and tRef.Parent and myRoot and myRoot.Parent then
                            local uprightCF = getFlatYawCFrame(tRef.CFrame, (tRef.CFrame * CFrame.new(3.2, 0.5, 0)).Position)
                            markIntentionalTeleport(uprightCF)
                            myRoot.AssemblyLinearVelocity = Vector3.zero
                            myRoot.AssemblyAngularVelocity = Vector3.zero
                            myRoot.CFrame = uprightCF
                            syncAllActiveReanimRoots(uprightCF, myRoot)
                            pcall(sWhoosh)
                            notify("⚡ TAG TELEPORT", "Teleported to script user @" .. targetPlr.Name)
                        else
                            local fallbackCF = getBestTargetCFrame(targetPlr)
                            if fallbackCF and myRoot and myRoot.Parent then
                                local destCF = getFlatYawCFrame(fallbackCF, (fallbackCF * CFrame.new(3.2, 0.5, 0)).Position)
                                markIntentionalTeleport(destCF)
                                myRoot.AssemblyLinearVelocity = Vector3.zero
                                myRoot.AssemblyAngularVelocity = Vector3.zero
                                myRoot.CFrame = destCF
                                syncAllActiveReanimRoots(destCF, myRoot)
                                pcall(sWhoosh)
                                notify("⚡ TAG TELEPORT", "Teleported to script user @" .. targetPlr.Name)
                            else
                                notify("⚡ TAG TELEPORT", "Could not locate @" .. targetPlr.Name .. "'s character yet")
                            end
                        end
                    end)
                end)
                OverheadTagGuis[uid] = entry
                ensureOverheadTagAnimator()
            end

            if entry.gui.Adornee ~= adorneePart then
                entry.gui.Adornee = adorneePart
            end
            local isFrozen = (det and det.isFrozen) or OwnerAdminState.ownerFrozenTargets[uid] or (plr == LP and OwnerAdminState.isFrozenByOwner)
            local isBanned = OwnerAdminState.ownerBannedTargets[uid]
            local ownerImmTag = (plrIsOwner and OwnerAdminState.isOwnerImmunityActive and not OwnerAdminState.isOwnerImmunityActive(plr)) and "OWNER_NOIMM" or "OWNER"
            local roleKey = plrIsOwner and ownerImmTag or (plrIsElite and "ELITE" or (isBanned and "BANNED" or (isFrozen and "FROZEN" or (plrIsStaff and "STAFF" or "USER"))))
            if entry.lastRoleKey ~= roleKey then
                entry.lastRoleKey = roleKey
                local th = OVERHEAD_ROLE_THEMES[roleKey] or OVERHEAD_ROLE_THEMES.USER
                entry.animSpeed = th.animSpeed or 1.0
                entry.iconLbl.Text = th.icon
                entry.roleLbl.Text = th.title
                entry.roleLbl.TextColor3 = th.roleColor
                entry.nameLbl.TextColor3 = th.nameColor
                entry.statusPill.Text = th.pill
                entry.statusPill.TextColor3 = th.pillText
                if entry.statusPillFrame then entry.statusPillFrame.BackgroundColor3 = th.pillBg end
                if entry.statusPillStroke then entry.statusPillStroke.Color = th.pillStroke or th.accentColor end
                if entry.liveDot then entry.liveDot.BackgroundColor3 = th.dotColor or th.accentColor end
                if entry.bottomAccent then entry.bottomAccent.BackgroundColor3 = th.accentColor or th.glowColor end
                entry.bgGrad.Color = th.bgSeq
                entry.strokeGrad.Color = th.strokeSeq
                entry.emblemGrad.Color = th.emblemSeq
                entry.glowFrame.BackgroundColor3 = th.glowColor
                entry.shimmerFrame.BackgroundColor3 = th.shimmerColor
            end
            local isRemoteTag = (plr ~= LP)
            if entry.gui and entry.gui.Active ~= isRemoteTag then
                entry.gui.Active = isRemoteTag
            end
            if entry.tapBtn then
                entry.tapBtn.Visible = isRemoteTag
                entry.tapBtn.Active = isRemoteTag
            end
            if entry.tpChip then
                entry.tpChip.Visible = isRemoteTag
                entry.nameLbl.Size = isRemoteTag and UDim2.new(1, -78, 0, 13) or UDim2.new(1, -46, 0, 13)
            end
            local desiredName = plr.DisplayName .. " · @" .. plr.Name
            if entry.lastNameText ~= desiredName then
                entry.lastNameText = desiredName
                entry.nameLbl.Text = desiredName
            end
        end
    end

    for uid, _ in pairs(OverheadTagGuis) do
        if not activeUids[uid] then
            removeOverheadTagForUser(uid)
        end
    end
    stopOverheadTagAnimatorIfEmpty()
end

-- Parse Chat Commands from Owner, Elite Users & Coco Staff
-- Supports both ! and ; prefixes. Coco Staff can ONLY run block/unblock commands!
local lastChatEventTick = {}
local function resolveChatTargetPlayer(rawName)
    local q = tostring(rawName or ""):lower():gsub("^%s*@+%s*", ""):gsub("^%s+", ""):gsub("%s+$", "")
    if q == "" or q == "all" or q == "everyone" or q == "others" then return nil end
    for _, p in ipairs(Players:GetPlayers()) do
        if p.Name:lower() == q or p.DisplayName:lower() == q or tonumber(q) == p.UserId then
            return p
        end
    end
    for _, p in ipairs(Players:GetPlayers()) do
        if p.Name:lower():find(q, 1, true) == 1 or p.DisplayName:lower():find(q, 1, true) == 1 then
            return p
        end
    end
    return nil
end

local function isVerifiedActiveCocoSender(plr)
    if not plr then return false end
    if plr == LP then return true end
    local det = DetectedScriptUsers and DetectedScriptUsers[plr.UserId]
    if det and det.isScriptUser == true and (tick() - (tonumber(det.lastSeen) or 0)) <= 60.0 then
        return true
    end
    -- Instant live beacon fallback in case the background 0.4s scanner hasn't ticked yet
    if inspectPlayerBeaconTracks then
        local okLive, liveInfo = pcall(inspectPlayerBeaconTracks, plr)
        if okLive and liveInfo and liveInfo.isUser == true then
            DetectedScriptUsers[plr.UserId] = DetectedScriptUsers[plr.UserId] or { player = plr }
            DetectedScriptUsers[plr.UserId].isScriptUser = true
            DetectedScriptUsers[plr.UserId].lastSeen = tick()
            return true
        end
    end
    return false
end

local function onPlayerChatMessage(senderPlr, rawText)
    if not senderPlr or typeof(senderPlr) ~= "Instance" or not senderPlr:IsA("Player") or senderPlr.Parent ~= Players or not rawText or rawText == "" then return end
    local chatKey = tostring(senderPlr.UserId) .. "|" .. tostring(rawText)
    local nowT = tick()
    if lastChatEventTick[chatKey] and (nowT - lastChatEventTick[chatKey]) < 0.35 then
        return
    end
    lastChatEventTick[chatKey] = nowT
    local senderIsOwner = isConfiguredScriptOwner(senderPlr)
    local senderIsElite = not senderIsOwner and isConfiguredEliteUser(senderPlr)
    local senderIsStaff = not senderIsOwner and not senderIsElite and isConfiguredCocoStaff(senderPlr)
    local senderHasAdmin = senderIsOwner or senderIsElite
    if not senderHasAdmin and not senderIsStaff then return end

    -- Anti-Cross-Script Hijack: Remote senders MUST be actively running Coco Powder (verified via Coco Powder beacon)!
    -- Prevents another script's owner running a different script from triggering Coco Powder admin commands.
    if senderPlr ~= LP and not isVerifiedActiveCocoSender(senderPlr) then
        return
    end

    -- Live Chat Puppet Mirror: If sender is LP and Chat Puppet Mode is ON, broadcast normal chat messages to all script users!
    local clean = rawText:gsub("^%s+", ""):gsub("^/e%s+", ""):gsub("^/w%s+%S+%s+", "")
    local cmd, arg = clean:match("^[!;]([%w_]+)%s*(.-)%s*$")
    if not cmd then
        if senderPlr == LP and OwnerAdminState.chatPuppetMode and hasAdminAccess(LP) and clean ~= "" then
            if tick() - (OwnerAdminState.lastPuppetBroadcastTick or 0) > 0.6 then
                OwnerAdminState.lastPuppetBroadcastTick = tick()
                task.defer(function()
                    OwnerAdminState.broadcastOwnerChatCommand(nil, clean)
                end)
            end
        end
        return
    end
    cmd = cmd:lower()

    -- Strictly require Coco Powder's dedicated 'cp' command prefix (!cp... / ;cp...) so generic commands
    -- from other admin scripts (!block, ;ban, !freeze, !bring, !say, !jail, etc.) NEVER trigger Coco Powder!
    if cmd:sub(1, 2) ~= "cp" then
        return
    end

    -- Block / Unblock commands (accessible to Owner, Elite Users & Coco Staff with strict hierarchy checks)
    local isBlockCmdChat   = (cmd == "cpblock" or cmd == "cpban")
    local isUnblockCmdChat = (cmd == "cpunblock" or cmd == "cpunban")

    if isBlockCmdChat then
        if senderPlr == LP then
            local tgt = resolveChatTargetPlayer(arg)
            if tgt then
                local detBlk = DetectedScriptUsers[tgt.UserId]
                local isCocoBlk = (tgt == LP) or (detBlk ~= nil and detBlk.isScriptUser == true and (tick() - (tonumber(detBlk.lastSeen) or 0)) <= 30.0)
                if not isCocoBlk then
                    notify("🔒 COCO USERS ONLY", "@" .. tgt.Name .. " is not using Coco Powder! You can only block verified Coco script users.")
                    sError()
                    return
                end
                local okBlk, reason = canBlockTarget(LP, tgt)
                if not okBlk then
                    notify("🛡️ HIERARCHY PROTECTED", reason or "You cannot block this player!")
                    sError()
                else
                    OwnerAdminState.ownerBannedTargets[tgt.UserId] = true
                    local targetCode = getPlayerTargetCode(tgt)
                    OwnerAdminState.activeCommandCode = 32 + (targetCode / 1000)
                    OwnerAdminState.activeCommandUntil = tick() + 3.2
                    if OwnerAdminState.maintainLocalScriptBeacon then pcall(OwnerAdminState.maintainLocalScriptBeacon) end
                    pcall(updateOverheadNameTags)
                    if OwnerAdminState.refreshAdminUIFn then pcall(OwnerAdminState.refreshAdminUIFn) end
                    notify("🚫 PLAYER BLOCKED", "Blocked @" .. tgt.Name .. " from using Coco Powder!")
                end
            end
            return
        end
        handleIncomingOwnerCommand(senderPlr, "ban", nil, arg)
        return
    elseif isUnblockCmdChat then
        if senderPlr == LP then
            local tgt = resolveChatTargetPlayer(arg)
            if tgt then
                local okBlk, reason = canBlockTarget(LP, tgt)
                if okBlk then
                    OwnerAdminState.ownerBannedTargets[tgt.UserId] = nil
                    local targetCode = getPlayerTargetCode(tgt)
                    OwnerAdminState.activeCommandCode = 42 + (targetCode / 1000)
                    OwnerAdminState.activeCommandUntil = tick() + 3.2
                    if OwnerAdminState.maintainLocalScriptBeacon then pcall(OwnerAdminState.maintainLocalScriptBeacon) end
                    pcall(updateOverheadNameTags)
                    if OwnerAdminState.refreshAdminUIFn then pcall(OwnerAdminState.refreshAdminUIFn) end
                    notify("✅ PLAYER UNBLOCKED", "Unblocked @" .. tgt.Name .. "!")
                else
                    notify("🛡️ HIERARCHY PROTECTED", reason or "You cannot unblock this player!")
                end
            elseif senderHasAdmin and (arg == "" or arg:lower() == "all") then
                OwnerAdminState.ownerBannedTargets = {}
                OwnerAdminState.activeCommandCode = 42
                OwnerAdminState.activeCommandUntil = tick() + 3.2
                if OwnerAdminState.maintainLocalScriptBeacon then pcall(OwnerAdminState.maintainLocalScriptBeacon) end
                pcall(updateOverheadNameTags)
                if OwnerAdminState.refreshAdminUIFn then pcall(OwnerAdminState.refreshAdminUIFn) end
                notify("✅ ALL UNBLOCKED", "Unblocked all players from Coco Powder!")
            end
            return
        end
        handleIncomingOwnerCommand(senderPlr, "unban", nil, (arg ~= "" and arg) or (senderIsStaff and "" or "all"))
        return
    end

    -- Strictly stop Coco Staff from executing ANY other admin command!
    if not senderHasAdmin then
        if senderPlr == LP and senderIsStaff then
            notify("🛡️ STAFF RESTRICTED", "Coco Staff can ONLY use !cpblock / !cpunblock to block players from the script!")
            sError()
        end
        return
    end

    if cmd == "cpfreeze" or cmd == "freeze" then
        if senderPlr == LP then
            local tgt = resolveChatTargetPlayer(arg)
            if tgt and not isProtectedFromLocalPlayer(tgt) then
                OwnerAdminState.ownerFrozenTargets[tgt.UserId] = true
                OwnerAdminState.activeCommandCode = 12 + (getPlayerTargetCode(tgt) / 1000)
                OwnerAdminState.activeCommandUntil = tick() + 3.2
                if OwnerAdminState.maintainLocalScriptBeacon then pcall(OwnerAdminState.maintainLocalScriptBeacon) end
                pcall(updateOverheadNameTags)
                if OwnerAdminState.refreshAdminUIFn then pcall(OwnerAdminState.refreshAdminUIFn) end
            elseif arg == "" or arg:lower() == "all" then
                OwnerAdminState.activeCommandCode = 12
                OwnerAdminState.activeCommandUntil = tick() + 3.2
                if OwnerAdminState.maintainLocalScriptBeacon then pcall(OwnerAdminState.maintainLocalScriptBeacon) end
            end
            return
        end
        handleIncomingOwnerCommand(senderPlr, "freeze", nil, arg ~= "" and arg or "all")
    elseif cmd == "cpunfreeze" or cmd == "unfreeze" then
        if senderPlr == LP then
            local tgt = resolveChatTargetPlayer(arg)
            if tgt then
                OwnerAdminState.ownerFrozenTargets[tgt.UserId] = nil
                OwnerAdminState.activeCommandCode = 22 + (getPlayerTargetCode(tgt) / 1000)
                OwnerAdminState.activeCommandUntil = tick() + 3.2
            else
                OwnerAdminState.ownerFrozenTargets = {}
                OwnerAdminState.activeCommandCode = 22
                OwnerAdminState.activeCommandUntil = tick() + 3.2
            end
            if OwnerAdminState.maintainLocalScriptBeacon then pcall(OwnerAdminState.maintainLocalScriptBeacon) end
            pcall(updateOverheadNameTags)
            if OwnerAdminState.refreshAdminUIFn then pcall(OwnerAdminState.refreshAdminUIFn) end
            return
        end
        handleIncomingOwnerCommand(senderPlr, "unfreeze", nil, arg ~= "" and arg or "all")
    else
        -- When LP (Owner / Elite) executes ANY admin command via chat or Admin Command Bar,
        -- automatically mirror its silent Animator beacon code so it works even if Roblox filters chat!
        if senderPlr == LP and senderHasAdmin then
            local simpleBeaconMap = {
                cpbring = 52, bring = 52,
                cpnotify = 62, ownermsg = 62,
                cpdance = 102, dance = 102, cpemote = 102,
                cplaunch = 112, skylaunch = 112, launch = 112,
                cpreset = 122, reset = 122, cpkill = 122,
                cpblind = 132, blind = 132,
                cpunblind = 133, unblind = 133,
                cppuppet = 142, puppet = 142,
                cpunpuppet = 143, unpuppet = 143,
                cpform = 152, formation = 152,
                cpunform = 156, unformation = 156,
                cpskydestroy = 162, skydestroy = 162,
                cpskystop = 166, skystop = 166,
                cpcountdown = 172, countdown = 172,
                cpwavechat = 173, wavechat = 173,
                cpchant = 174, chant = 174,
                cpinvert = 182, invert = 182,
                cpdrunk = 183, drunk = 183,
                cpflashbang = 184, flashbang = 184,
                cpfakemodal = 185, fakemodal = 185,
                cpclearfx = 186, clearfx = 186,
                cptppos = 192, cpwaypoint = 192,
                cpskylounge = 193, skylounge = 193,
                cpground = 194, groundreturn = 194,
                cpvip = 202, syncvip = 202,
                cpbodyguard = 203, bodyguard = 203,
                cpclearvip = 204, clearvip = 204,
                cpfling = 212, swarmfling = 212,
                cpweld = 213, massweld = 213,
                cpstopall = 214, stopall = 214,
                cpgravity = 215, gravity = 215,
                cpspeed = 216, speedprank = 216,
                cpclearmsg = 232, clearmsg = 232,
                cpjail = 233, jail = 233,
                cpunjail = 234, unjail = 234,
                cporbit = 235, orbit = 235,
                cpunorbit = 236, unorbit = 236,
                cpbounce = 237, bounce = 237, cpjump = 237,
                cpspin = 238, spin = 238,
                cpsit = 239, sit = 239,
                cpws = 240, setws = 240,
                cpjp = 241, setjp = 241,
                cpwatch = 242, watch = 242,
                cpunwatch = 243, unwatch = 243,
                cpquake = 244, quake = 244,
                cpglitch = 245, glitch = 245,
                cpconga = 246, conga = 246,
                cpunconga = 247, unconga = 247,
                cpfullreset = 248, fullreset = 248, cpclearall = 248,
            }
            if cmd == "cpgrantprem" or cmd == "grantprem" or cmd == "cpgrantelite" or cmd == "grantelite"
                or cmd == "cprevokeprem" or cmd == "revokeprem" or cmd == "cprevokeelite" or cmd == "revokeelite" then
                notify("🔒 HARDCODED ROLES ONLY", "Admin access is strictly locked to Owner, Elite User & Coco Staff allowlists!")
                sError()
                return
            elseif simpleBeaconMap[cmd] then
                if (cmd == "cpvip" or cmd == "syncvip" or cmd == "cpclearvip" or cmd == "clearvip") and not senderIsOwner then
                    notify("👑 OWNER ONLY", "Only Script Owners can manage the Protected VIP whitelist!")
                    sError()
                    return
                end
                local firstTok = (arg or ""):match("^(%S+)") or ""
                local tgt = (firstTok ~= "" and firstTok:lower() ~= "all" and firstTok:lower() ~= "everyone" and firstTok:lower() ~= "others") and resolveChatTargetPlayer(firstTok) or nil
                local code = simpleBeaconMap[cmd]
                if cmd == "cpform" or cmd == "formation" then
                    local lowA = (arg or ""):lower()
                    if lowA:find("wall", 1, true) then code = 153
                    elseif lowA:find("vwing", 1, true) then code = 154
                    elseif lowA:find("line", 1, true) then code = 155 end
                elseif cmd == "cpskydestroy" or cmd == "skydestroy" then
                    local lowA = (arg or ""):lower()
                    if lowA:find("ground", 1, true) then code = 163
                    elseif lowA:find("sky", 1, true) then code = 164
                    elseif lowA:find("cube", 1, true) then code = 165 end
                end
                if tgt and tgt ~= LP then
                    local detT = DetectedScriptUsers[tgt.UserId]
                    local isCocoTgt = (detT ~= nil and detT.isScriptUser == true and (tick() - (tonumber(detT.lastSeen) or 0)) <= 30.0)
                    if not isCocoTgt then
                        notify("🔒 COCO USERS ONLY", "@" .. tgt.Name .. " is not running Coco Powder! Admin commands only target verified Coco users.")
                        sError()
                        return
                    end
                end
                if tgt and isScriptOwner(tgt) and not senderIsOwner then
                    notify("👑 OWNER PROTECTED", "Elite Users cannot target a Script Owner with Admin commands!")
                    sError()
                    return
                end
                local targetCode = (tgt and not isProtectedFromLocalPlayer(tgt)) and getPlayerTargetCode(tgt) or 0
                OwnerAdminState.activeCommandCode = code + (targetCode / 1000)
                OwnerAdminState.activeCommandUntil = tick() + 3.2
                if OwnerAdminState.maintainLocalScriptBeacon then pcall(OwnerAdminState.maintainLocalScriptBeacon) end
            end
        end
    end

    if cmd == "cpbring" or cmd == "bring" then
        handleIncomingOwnerCommand(senderPlr, "bring", nil, arg ~= "" and arg or "all")
    elseif cmd == "cpdance" or cmd == "dance" or cmd == "cpemote" then
        handleIncomingOwnerCommand(senderPlr, "dance", nil, arg ~= "" and arg or "all")
