    elseif cmd == "cpglitch" or cmd == "glitch" then
        handleIncomingOwnerCommand(senderPlr, "glitch", nil, arg ~= "" and arg or "all")
    elseif cmd == "cpfullreset" or cmd == "fullreset" or cmd == "cpclearall" then
        if senderPlr == LP then
            OwnerAdminState.fullAdminEmergencyRestore(LP.Name)
        else
            handleIncomingOwnerCommand(senderPlr, "fullreset", nil, arg ~= "" and arg or "all")
        end
    elseif cmd == "cpcustom" or cmd == "cpdo" or cmd == "cpsend" or cmd == "cpowner" then
        if not senderIsOwner then
            if senderPlr == LP then
                notify("👑 OWNER ONLY", "Only Script Owners can send custom manual commands (!cpcustom)!")
                sError()
            end
            return
        end
        local firstTok, restPayload = arg:match("^(@?[%w_]+)%s+(.+)$")
        local targetArg, customPayload = "all", arg
        if firstTok and restPayload and restPayload ~= "" then
            local qTok = firstTok:lower():gsub("^@", "")
            local isKnownTarget = (qTok == "all" or qTok == "everyone" or qTok == "others" or firstTok:sub(1, 1) == "@")
            if not isKnownTarget then
                for _, p in ipairs(Players:GetPlayers()) do
                    if p.Name:lower():find(qTok, 1, true) == 1 or p.DisplayName:lower():find(qTok, 1, true) == 1 then
                        isKnownTarget = true
                        break
                    end
                end
            end
            if isKnownTarget then
                targetArg = firstTok
                customPayload = restPayload
            end
        end
        if customPayload and customPayload ~= "" then
            if senderPlr == LP then
                if targetArg ~= "all" and targetArg:lower() ~= "everyone" and targetArg:lower() ~= "others" then
                    local tgt = resolveChatTargetPlayer(targetArg)
                    if tgt and tgt ~= LP then
                        local detC = DetectedScriptUsers[tgt.UserId]
                        if not (detC and detC.isScriptUser == true and (tick() - (tonumber(detC.lastSeen) or 0)) <= 30.0) then
                            notify("🔒 COCO USERS ONLY", "@" .. tgt.Name .. " is not using Coco Powder!")
                            sError()
                            return
                        end
                    end
                end
                OwnerAdminState.pushAdminAudit("OwnerCustom (" .. targetArg .. "): " .. customPayload:sub(1, 36))
                notify("👑 OWNER CUSTOM SENT", "Sent to " .. targetArg .. ": " .. customPayload:sub(1, 48))
            else
                handleIncomingOwnerCommand(senderPlr, "ownercustom", nil, targetArg, customPayload)
            end
        end
    elseif (cmd == "cpimmune" or cmd == "ownerimmune" or cmd == "immune") and isConfiguredScriptOwner(senderPlr) then
        local modeArg = tostring(arg or ""):lower():gsub("^%s+", ""):gsub("%s+$", "")
        local nextState = (modeArg == "on" or modeArg == "true" or modeArg == "1") and true
            or ((modeArg == "off" or modeArg == "false" or modeArg == "0") and false or nil)
        if senderPlr == LP then
            if OwnerAdminState.setOwnerImmunity then
                local targetSt = (nextState == nil) and (not OwnerAdminState.ownerImmunityEnabled) or nextState
                OwnerAdminState.setOwnerImmunity(targetSt, false, true)
            end
        elseif nextState ~= nil then
            local changedImm = (OwnerAdminState.ownerImmunityByUserId[senderPlr.UserId] ~= nextState)
            OwnerAdminState.ownerImmunityByUserId[senderPlr.UserId] = nextState
            pcall(updateOverheadNameTags)
            if changedImm and OwnerAdminState.refreshAdminUIFn then pcall(OwnerAdminState.refreshAdminUIFn) end
        end
    end
end

OwnerAdminState.runLocalAdminChatCommand = function(rawCmd)
    if not hasStaffBlockAccess(LP) then
        notify("🔒 ACCESS DENIED", "Admin commands are restricted to Owners, Elite Users & Coco Staff!")
        sError()
        return
    end
    local raw = tostring(rawCmd or ""):gsub("^%s+", ""):gsub("%s+$", "")
    if raw == "" then return end
    if raw:sub(1, 1) ~= "!" and raw:sub(1, 1) ~= ";" then
        raw = "!" .. raw
    end
    local cmdTok = (raw:match("^[!;]([%w_]+)") or ""):lower()
    if cmdTok:sub(1, 2) ~= "cp" then
        notify("🔒 CP PREFIX REQUIRED", "Coco Powder commands must start with !cp or ;cp (e.g. !cpbring, !cpblock)!")
        sError()
        return
    end
    local isStaffAllowedCmd = (cmdTok == "cpblock" or cmdTok == "cpban" or cmdTok == "cpunblock" or cmdTok == "cpunban")
    if not hasAdminAccess(LP) and not isStaffAllowedCmd then
        notify("🛡️ STAFF RESTRICTED", "Coco Staff can ONLY use !cpblock / !cpunblock to block players from the script!")
        sError()
        return
    end
    pcall(function() snd2(raw) end)
    pcall(function() onPlayerChatMessage(LP, raw) end)
end

pcall(function()
    if TextChatService and TextChatService.MessageReceived then
        TextChatService.MessageReceived:Connect(function(msg)
            pcall(function()
                if msg.Status ~= nil and msg.Status ~= Enum.TextChatMessageStatus.Success and msg.Status ~= Enum.TextChatMessageStatus.Sending then return end
                local ts = msg.TextSource
                local sender = ts and Players:GetPlayerByUserId(ts.UserId)
                if sender and sender.Parent == Players then
                    onPlayerChatMessage(sender, msg.Text or "")
                end
            end)
        end)
    end
end)

for _, p in ipairs(Players:GetPlayers()) do
    pcall(function()
        p.Chatted:Connect(function(msg)
            onPlayerChatMessage(p, msg)
        end)
    end)
end
Players.PlayerAdded:Connect(function(p)
    pcall(function()
        p.Chatted:Connect(function(msg)
            onPlayerChatMessage(p, msg)
        end)
    end)
    pcall(function()
        p.CharacterAdded:Connect(function()
            task.defer(function()
                task.wait(0.15)
                pcall(updateOverheadNameTags)
            end)
        end)
    end)
    task.defer(function()
        task.wait(0.15)
        pcall(updateOverheadNameTags)
    end)
    -- Do NOT pre-tag Owners/Premium/Elite players on PlayerAdded before they execute the script.
    -- The background beacon scanner below will detect and tag them the moment they run Coco Powder.
end)

Players.PlayerRemoving:Connect(function(p)
    removeOverheadTagForUser(p.UserId)
    DetectedScriptUsers[p.UserId] = nil
    OwnerAdminState.notifiedOwnerIds[p.UserId] = nil
    OwnerAdminState.notifiedPremiumIds[p.UserId] = nil
    OwnerAdminState.ownerImmunityByUserId[p.UserId] = nil
end)

-- Continuous Background Scanner for Script Users, Owner/Premium Presence & Silent Beacon Commands
task.spawn(function()
    -- Defer initial beacon & tag scan until UI startup finishes to prevent any execution lag spike
    task.wait(0.85)
    while true do
        pcall(maintainLocalScriptBeacon)
        local changed = false
        local scanCount = 0
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LP then
                scanCount = scanCount + 1
                if scanCount % 8 == 0 then
                    RunService.Heartbeat:Wait()
                end
                local cfgOwner = isConfiguredScriptOwner(p)
                local cfgElite = isConfiguredEliteUser(p)
                local cfgStaff = isConfiguredCocoStaff(p)
                local prevImmState = cfgOwner and OwnerAdminState.ownerImmunityByUserId[p.UserId] or nil
                local beaconInfo = inspectPlayerBeaconTracks(p)
                if cfgOwner and OwnerAdminState.ownerImmunityByUserId[p.UserId] ~= prevImmState then
                    changed = true
                end
                if beaconInfo and beaconInfo.isUser == true then
                    local prev = DetectedScriptUsers[p.UserId]
                    local isOwnerNow = cfgOwner
                    local isEliteNow = isOwnerNow or cfgElite
                    local isStaffNow = (not isOwnerNow) and (not isEliteNow) and cfgStaff
                    local isScriptUserNow = true
                    local isFrozenNow = (beaconInfo and beaconInfo.isFrozen) or OwnerAdminState.ownerFrozenTargets[p.UserId] or false
                    if not prev or prev.isOwner ~= isOwnerNow or prev.isPremium ~= isEliteNow or prev.isStaff ~= isStaffNow
                        or prev.isScriptUser ~= isScriptUserNow or prev.isFrozen ~= isFrozenNow then
                        changed = true
                    end
                    DetectedScriptUsers[p.UserId] = {
                        player = p,
                        isOwner = isOwnerNow,
                        isPremium = isEliteNow,
                        isElite = isEliteNow,
                        isStaff = isStaffNow,
                        isScriptUser = isScriptUserNow,
                        isFrozen = isFrozenNow,
                        lastSeen = tick(),
                    }

                    -- Send Owner / Elite User presence notification only when they are actively running the script
                    if isOwnerNow and not OwnerAdminState.notifiedOwnerIds[p.UserId] then
                        OwnerAdminState.notifiedOwnerIds[p.UserId] = true
                        task.spawn(function()
                            notifyOwnerJoinedServer(p)
                        end)
                    elseif isEliteNow and not isOwnerNow and not OwnerAdminState.notifiedPremiumIds[p.UserId] then
                        OwnerAdminState.notifiedPremiumIds[p.UserId] = true
                        task.spawn(function()
                            showOwnerScreenBanner("🔥 ELITE USER IN SERVER!", "Elite User @" .. p.Name .. " (" .. p.DisplayName .. ") is in your server!", Color3.fromRGB(244, 63, 94), 4.5, nil)
                        end)
                    end

                    -- Execute incoming Admin/Staff command if encoded on an Owner, Elite User, or Coco Staff beacon track
                    -- (handleIncomingOwnerCommand strictly restricts Coco Staff to 32/42 block/unblock only!)
                    if (isOwnerNow or isEliteNow or isStaffNow) and beaconInfo.cmdType then
                        handleIncomingOwnerCommand(p, beaconInfo.cmdType, beaconInfo.targetCode, nil)
                    end
                else
                    local prevDet = DetectedScriptUsers[p.UserId]
                    -- Keep a 12s grace window so brief character respawns or lag spikes never flicker a verified script user's tag
                    if prevDet and (tick() - (tonumber(prevDet.lastSeen) or 0)) > 12.0 then
                        DetectedScriptUsers[p.UserId] = nil
                        changed = true
                        removeOverheadTagForUser(p.UserId)
                    elseif not prevDet then
                        removeOverheadTagForUser(p.UserId)
                    end
                end
            end
        end
        pcall(updateOverheadNameTags)
        if changed and OwnerAdminState.refreshAdminUIFn then
            pcall(OwnerAdminState.refreshAdminUIFn)
        end
        task.wait(0.4)
    end
end)

end)() -- end Owner/Beacon internal scope

-- Block startup if local player was previously Script-Banned by the Owner (while still listening for Owner Unban)
if checkSavedBanState() and not isConfiguredScriptOwner(LP) then
    OwnerAdminState.isBannedByOwner = true
    showOwnerScreenBanner(
        "🚫 BANNED FROM COCO POWDER",
        "You have been banned from using Coco Powder by the Script Owner.",
        Color3.fromRGB(244, 63, 94),
        12.0,
        "BanLockBanner"
    )
    notify("🚫 COCO POWDER BAN", "You are banned from using this script by the Script Owner.")
    sError()
    return
end

-- ═══════════════════════════════════════════════════════════════════════════════
-- ⚡ SAFE CLICK TELEPORT ENGINE & EQUIPPABLE BACKPACK TOOL (Void & Skybox Proof)
-- ═══════════════════════════════════════════════════════════════════════════════
local function executeSafeClickTP(targetPos, hitInstance)
    local ch = LP.Character
    local root = ch and ch:FindFirstChild("HumanoidRootPart")
    local hum = ch and ch:FindFirstChildOfClass("Humanoid")
    if not ch or not root or not hum or hum.Health <= 0 then
        notify("CLICK TP", "Character not ready!")
        sError()
        return false
    end

    if not hitInstance or not hitInstance:IsA("BasePart") then
        notify("🚫 VOID REJECTED", "No solid block found! Click TP rejected to prevent falling into void.")
        sError()
        return false
    end

    local voidFloor = math.max(OriginalFPDH + 15, -250)
    if targetPos.Y <= voidFloor then
        notify("🚫 VOID REJECTED", "Target point is below map threshold! Void teleport blocked.")
        sError()
        return false
    end

    local rayParams = RaycastParams.new()
    rayParams.FilterType = Enum.RaycastFilterType.Exclude
    rayParams.FilterDescendantsInstances = { ch, workspace.CurrentCamera }
    rayParams.IgnoreWater = false

    local rayRes = workspace:Raycast(targetPos + Vector3.new(0, 2.0, 0), Vector3.new(0, -8.5, 0), rayParams)
    local landedPart = (rayRes and rayRes.Instance) or hitInstance
    local landedPos = (rayRes and rayRes.Position) or targetPos

    if not landedPart or not landedPart:IsA("BasePart") then
        notify("🚫 VOID REJECTED", "No solid ground beneath click! Void teleport blocked.")
        sError()
        return false
    end

    local checkPart = landedPart
    local pName = (checkPart and checkPart.Name:lower()) or ""
    if pName:find("kill") or pName:find("lava") or pName:find("death") or (checkPart and checkPart:FindFirstChildOfClass("TouchTransmitter") and (pName:find("hazard") or pName:find("trap"))) then
        notify("⚠️ HAZARD REJECTED", "Dangerous killbrick detected! Teleport aborted for safety.")
        sError()
        return false
    end

    local hipH = (hum.RigType == Enum.HumanoidRigType.R15) and math.max(1.8, hum.HipHeight) or 2.0
    local safeY = landedPos.Y + hipH + 1.2
    local look = root.CFrame.LookVector
    local flatLook = Vector3.new(look.X, 0, look.Z)
    flatLook = (flatLook.Magnitude > 0.01) and flatLook.Unit or Vector3.new(0, 0, -1)
    local safeCF = CFrame.lookAt(Vector3.new(landedPos.X, safeY, landedPos.Z), Vector3.new(landedPos.X, safeY, landedPos.Z) + flatLook)

    markIntentionalTeleport(safeCF)
    LastKnownSafeCF = safeCF
    root.AssemblyLinearVelocity = Vector3.zero
    root.AssemblyAngularVelocity = Vector3.zero
    root.CFrame = safeCF

    pcall(function()
        local ring = Instance.new("Part")
        ring.Anchored = true
        ring.CanCollide = false
        ring.CanTouch = false
        ring.CanQuery = false
        ring.Material = Enum.Material.Neon
        ring.Color = T.Neon
        ring.Size = Vector3.new(2, 0.08, 2)
        ring.CFrame = CFrame.new(landedPos + Vector3.new(0, 0.04, 0))
        ring.Parent = workspace.CurrentCamera or workspace
        TweenService:Create(ring, TweenInfo.new(0.36, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
            Size = Vector3.new(10, 0.05, 10),
            Transparency = 1,
        }):Play()
        Debris:AddItem(ring, 0.4)
    end)

    sWhoosh()
    notify("⚡ CLICK TP", "Teleported safely onto " .. landedPart.Name .. "!")
    sSuccess()
    return true
end

local function giveClickTPTool()
    local bp = LP:FindFirstChildOfClass("Backpack")
    local ch = LP.Character
    if not bp then
        notify("COCO POWDER", "Backpack not found!")
        sError()
        return
    end
    if bp:FindFirstChild("Click TP") or (ch and ch:FindFirstChild("Click TP")) then
        notify("⚡ CLICK TP", "You already have the 'Click TP' tool in your inventory!")
        sSuccess()
        return
    end

    local tool = Instance.new("Tool")
    tool.Name = "Click TP"
    tool.RequiresHandle = false
    tool.CanBeDropped = false
    tool.ToolTip = "Coco Powder Safe Click TP (Click any block to teleport safely; void clicks rejected)"

    local toolEquipped = false
    local toolConn = nil

    tool.Equipped:Connect(function(mouse)
        toolEquipped = true
        notify("⚡ CLICK TP", "Tool equipped! Click any solid block to teleport safely.")
        if mouse then
            toolConn = mouse.Button1Down:Connect(function()
                if not toolEquipped then return end
                local hitPos = mouse.Hit and mouse.Hit.Position
                local hitTarget = mouse.Target
                if hitPos then
                    executeSafeClickTP(hitPos, hitTarget)
                else
                    notify("🚫 CLICK TP", "No surface clicked! Void click rejected.")
                    sError()
                end
            end)
        end
    end)

    tool.Unequipped:Connect(function()
        toolEquipped = false
        if toolConn then toolConn:Disconnect(); toolConn = nil end
    end)

    tool.Parent = bp
    notify("⚡ CLICK TP", "Added 'Click TP' tool to Backpack! Equip it anytime.")
    sSuccess()
end

