    local g=b:FindFirstChildOfClass('UIGradient');if g then g.Name='Soft'end
    return b
   end
   local b = createInstance('TextButton', {
     Parent = parent,
     Text = '',
     AutoButtonColor = false,
     BorderSizePixel = 0,
     ZIndex = z or R.Z+1,
