    local function setCharacterTransparency(char, transparency)
        if not char then return end
        for _, desc in ipairs(char:GetDescendants()) do
            if desc:IsA("BasePart") or desc:IsA("Decal") then
                desc.Transparency = transparency
            end
        end
    end

    local function cloneCharacterRig(realChar)
        local archivableMap = { [realChar] = realChar.Archivable }
        realChar.Archivable = true
        for _, desc in ipairs(realChar:GetDescendants()) do
            archivableMap[desc] = desc.Archivable
            desc.Archivable = true
        end

        local clone = realChar:Clone()
        for _, desc in ipairs(clone:GetDescendants()) do
            if desc:IsA("BillboardGui") or desc:IsA("SurfaceGui") or desc:IsA("Highlight") or desc:IsA("ParticleEmitter") then
                desc:Destroy()
            end
        end

        for _, desc in ipairs(realChar:GetDescendants()) do
            if desc:IsA("Motor6D") and desc.Part0 and desc.Part1 then
                local part1 = clone:FindFirstChild(desc.Part1.Name, true)
                if part1 and not part1:FindFirstChild(desc.Name) then
                    local part0 = clone:FindFirstChild(desc.Part0.Name, true)
                    if part0 then
                        local m6d = Instance.new("Motor6D")
                        m6d.Name = desc.Name
                        m6d.Part0 = part0
                        m6d.Part1 = part1
                        m6d.C0 = desc.C0
                        m6d.C1 = desc.C1
                        m6d.Parent = part1
                    end
                end
            end
        end

        for inst, wasArchivable in pairs(archivableMap) do
            if inst and inst.Parent then
                inst.Archivable = wasArchivable
            end
        end

        clone.Name = "Reanimation"
        clone.Parent = workspace
        local animate = clone:FindFirstChild("Animate")
        if animate then animate.Disabled = true end

        local cloneHum = clone:FindFirstChildOfClass("Humanoid")
        if cloneHum then
            cloneHum.RequiresNeck = false
            cloneHum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.Viewer
            cloneHum.NameDisplayDistance = 100
            cloneHum.HealthDisplayDistance = 100
            cloneHum.DisplayName = ""
            cloneHum.AutoRotate = true
        end

        local ff = clone:FindFirstChildWhichIsA("ForceField")
        if ff then ff:Destroy() end
        return clone
    end

    local VortexLimbIndex = {
        Head = 1, UpperTorso = 2, LowerTorso = 3, Torso = 2,
        LeftUpperArm = 4, LeftLowerArm = 5, LeftHand = 6, ["Left Arm"] = 4,
        RightUpperArm = 7, RightLowerArm = 8, RightHand = 9, ["Right Arm"] = 7,
        LeftUpperLeg = 10, LeftLowerLeg = 11, LeftFoot = 12, ["Left Leg"] = 10,
        RightUpperLeg = 13, RightLowerLeg = 14, RightFoot = 15, ["Right Leg"] = 13,
    }

    local function computeSkyDestroyerPosition(partName, groundY, skyY, useGround, useSky, useCubes)
        if partName == "HumanoidRootPart" then
            return nil
        end
        local scale = _G._HaloCoverScaleMult or 1.0
        local flashActive = _G._HaloCoverFlashActive == true
        local flashPhase  = _G._HaloCoverFlashPhase ~= false
        local idx = VortexLimbIndex[partName] or 1
        local tNow = os.clock()
        if (_G._HaloCoverBlackholeActive == true) and (not flashActive or flashPhase) then
            local ang = tNow * 3.8 + (idx * 0.65)
            local funnelRatio = (idx / 15)
            local rad = (2000000 + funnelRatio * 18000000) * scale
            local funnelY = groundY + (funnelRatio * ((skyY - groundY) * 2.2 + 25))
            return Vector3.new(math.cos(ang) * rad, funnelY, math.sin(ang) * rad)
        elseif (_G._HaloCoverHaloRingActive == true) and (not flashActive or flashPhase) then
            local ang = tNow * 1.6 + ((idx / 15) * math.pi * 2)
            local rad = 16000000 * scale
            return Vector3.new(math.cos(ang) * rad, skyY + 12, math.sin(ang) * rad)
        elseif (_G._HaloCoverHelixActive == true) and (not flashActive or flashPhase) then
            local strand = (idx % 2 == 0) and 1 or -1
            local ang = tNow * 2.4 + (idx * 0.55) + (strand == -1 and math.pi or 0)
            local rad = 14000000 * scale
            local hY = groundY + (idx * ((_G._HaloCoverCubeSpacing or 2.0) + 2.5))
            return Vector3.new(math.cos(ang) * rad, hY, math.sin(ang) * rad)
        elseif (_G._HaloCoverWallActive == true) and (not flashActive or flashPhase) then
            local col = ((idx - 1) % 5) - 2
            local row = math.floor((idx - 1) / 5)
            local spanX = col * 8500000 * scale
            local wallY = groundY + (row * ((_G._HaloCoverCubeSpacing or 4.0) + 8.0))
            local wallZ = ((idx % 2 == 0) and 18000000 or -18000000) * scale
            return Vector3.new(spanX, wallY, wallZ)
        elseif (_G._HaloCoverTsunamiActive == true) and (not flashActive or flashPhase) then
            local waveX = ((idx - 8) * 3200000) * scale
            local wavePhase = tNow * 4.5 + (idx * 0.45)
            local waveY = groundY + 18 + math.sin(wavePhase) * (14 + (_G._HaloCoverSkyHeight or 15))
            local waveZ = math.cos(wavePhase) * 22000000 * scale
            return Vector3.new(waveX, waveY, waveZ)
        elseif (_G._HaloCoverPrisonBoxActive == true) and (not flashActive or flashPhase) then
            local boxR = 14000000 * scale
            local side = idx % 4
            local tier = math.floor((idx - 1) / 4)
            local boxY = groundY + (tier * ((_G._HaloCoverCubeSpacing or 3.5) + 4.0))
            if side == 0 then
                return Vector3.new(boxR, boxY, -boxR)
            elseif side == 1 then
                return Vector3.new(-boxR, boxY, boxR)
            elseif side == 2 then
                return Vector3.new(boxR, boxY, boxR)
            else
                return Vector3.new(-boxR, boxY, -boxR)
            end
        elseif (_G._HaloCoverVortexActive == true) and (not flashActive or flashPhase) then
            local ang = tNow * (_G._HaloCoverVortexSpeed or 2.2) + (idx * 0.42)
            local rad = 12000000 * scale
            local tierY = groundY + ((idx % 5) * ((_G._HaloCoverCubeSpacing or 2.5) + 3.5))
            return Vector3.new(math.cos(ang) * rad, tierY, math.sin(ang) * rad)
        end

        local rawVec = nil
        if useCubes then
            rawVec = getCubeVector(partName, groundY, _G._HaloCoverCubeSpacing or 0.5)
        elseif useGround and useSky then
            if partName == "LowerTorso" then
                rawVec = Vector3.new(101, groundY + (skyY - groundY) * 0.5, -25000000)
            elseif partName:find("Leg") or partName:find("Foot") then
                rawVec = getGroundVector(partName, groundY)
            else
                rawVec = getSkyVector(partName, skyY)
            end
        elseif useGround then
            rawVec = getGroundVector(partName, groundY)
        elseif useSky then
            rawVec = getSkyVector(partName, skyY)
        end
        if rawVec then
            return Vector3.new(rawVec.X * scale, rawVec.Y, rawVec.Z * scale)
        end
        return nil
    end

    local skyRayParams = RaycastParams.new()
    skyRayParams.FilterType = Enum.RaycastFilterType.Exclude

    local cachedRayClock = 0
    local cachedFloorY = nil
    local cachedUseGround, cachedUseSky, cachedUseCubes = false, false, false

    local function sampleEnvironmentState(realChar, cloneChar)
        local now = os.clock()
        local flashActive = _G._HaloCoverFlashActive == true
        local flashPhase  = _G._HaloCoverFlashPhase ~= false
        local groundOn    = _G._HaloCoverGroundActive == true
        local skyOn       = _G._HaloCoverSkyActive == true
        local cubesOn     = _G._HaloCoverCubeMatrixActive == true
        local specialOn   = _G._HaloCoverVortexActive or _G._HaloCoverBlackholeActive or _G._HaloCoverHaloRingActive or _G._HaloCoverHelixActive or _G._HaloCoverWallActive or _G._HaloCoverTsunamiActive or _G._HaloCoverPrisonBoxActive

        if flashActive and not groundOn and not skyOn and not cubesOn and not specialOn then
            groundOn = true
            skyOn = true
        end

        cachedUseGround = groundOn and (not flashActive or flashPhase)
        cachedUseSky    = skyOn    and (not flashActive or flashPhase)
        cachedUseCubes  = cubesOn  and (not flashActive or flashPhase)

        local groundY = 3
        local skyY = 15
        local refPos = nil
        if _G._HaloCoverTargetCageActive then
            local tgt = resolveActiveTarget and resolveActiveTarget()
            local tChar = tgt and findPlayerCharacterAnywhere and findPlayerCharacterAnywhere(tgt, true)
            local tRoot = tChar and pickTargetRef and pickTargetRef(tChar, "torso")
            if tRoot and tRoot.Parent then
                refPos = tRoot.Position
            end
        end
        if not refPos then
            local cloneHRP = cloneChar and cloneChar:FindFirstChild("HumanoidRootPart")
            if cloneHRP then refPos = cloneHRP.Position end
        end
        if refPos then
            if not cachedFloorY or (now - cachedRayClock) >= 0.004 or not _G._HaloCoverNoDelay then
                cachedRayClock = now
                skyRayParams.FilterDescendantsInstances = { realChar, cloneChar }
                local hit = workspace:Raycast(refPos + Vector3.new(0, 5, 0), Vector3.new(0, -100, 0), skyRayParams)
                cachedFloorY = (hit and hit.Position.Y) or (refPos.Y - 3)
            end
            local floorY = cachedFloorY or (refPos.Y - 3)
            local pulseWave = (_G._HaloCoverPulseActive == true) and (math.sin(now * 3.2) * 8.5) or 0
            groundY = floorY + (_G._HaloCoverGroundHeight or 1.5) + (pulseWave * 0.35)
            skyY    = refPos.Y + (_G._HaloCoverSkyHeight or 3) + pulseWave
        end

        return groundY, skyY, cachedUseGround, cachedUseSky, cachedUseCubes
    end

    function CocaSkyDestroyer.reanimate(enable)
        if ReanimState.is_processing then return end
        ReanimState.is_processing = true

        local ok, err = pcall(function()
            if enable then
                if ReanimState.reanimated then return end

                -- First: power Sky Destroyer WITH the help of Coca Reanim (_G._AngoorZenApi)!
                local zApi = nil
                if type(_G.ensureReanimApiReady) == "function" then
                    pcall(function() zApi = _G.ensureReanimApiReady() end)
                end
                zApi = zApi or _G._AngoorZenApi or _G.UltimateReanimAPI

                local realChar, cloneChar, realHum, realHRP, cloneHum = nil, nil, nil, nil, nil
                local usingZen, ownedZen = false, false

                if zApi and type(zApi.is_reanimated) == "function" and type(zApi.reanimate) == "function" then
                    local wasReanim = false
                    pcall(function() wasReanim = zApi.is_reanimated() == true end)
                    if not wasReanim then
                        pcall(function() zApi.reanimate(true) end)
                        ownedZen = true
                    end
                    local isNowReanim = false
                    pcall(function() isNowReanim = zApi.is_reanimated() == true end)
                    if isNowReanim then
                        if type(zApi.get_real_character) == "function" then
                            pcall(function() realChar = zApi.get_real_character() end)
                        end
                        if type(zApi.get_clone) == "function" then
                            pcall(function() cloneChar = zApi.get_clone(LP) end)
                        end
                        cloneChar = cloneChar or LP.Character
                        if realChar and realChar.Parent and cloneChar and cloneChar.Parent and realChar ~= cloneChar then
                            realHum = realChar:FindFirstChildOfClass("Humanoid")
                            realHRP = realChar:FindFirstChild("HumanoidRootPart")
                            cloneHum = cloneChar:FindFirstChildOfClass("Humanoid")
                            if realHum and realHRP and cloneHum then
                                usingZen = true
                                -- Detach PuppetRoot Motor6D on cloneHRP while Sky Destroyer controls realChar limbs directly
                                local cHRP = cloneChar:FindFirstChild("HumanoidRootPart")
                                local pWeld = cHRP and cHRP:FindFirstChild("PuppetRoot")
                                if pWeld then pcall(function() pWeld.Enabled = false end) end
                            end
                        end
                    end
                end

                local nameDist = 100
                local healthDist = 100

                if not usingZen then
                    -- Fallback standalone clone path if Coca Reanim API is unavailable
                    realChar = LP.Character
                    if not (realChar and realChar.Parent) then return end
                    realHum = realChar:FindFirstChildOfClass("Humanoid")
                    realHRP = realChar:FindFirstChild("HumanoidRootPart")
                    if not (realHum and realHRP) then return end

                    if not realHum:GetAttribute("ZenDefaultHipHeight") then
                        realHum:SetAttribute("ZenDefaultHipHeight", realHum.HipHeight)
                    end
                    nameDist = (realHum.NameDisplayDistance > 0 and realHum.NameDisplayDistance) or 100
                    healthDist = (realHum.HealthDisplayDistance > 0 and realHum.HealthDisplayDistance) or 100

                    cloneChar = cloneCharacterRig(realChar)
                    cloneHum = cloneChar:FindFirstChildOfClass("Humanoid")
                else
                    nameDist = (realHum.NameDisplayDistance > 0 and realHum.NameDisplayDistance) or 100
                    healthDist = (realHum.HealthDisplayDistance > 0 and realHum.HealthDisplayDistance) or 100
                end

                ReanimState.real_char = realChar
                ReanimState.clone_char = cloneChar
                ReanimState.using_zen_reanim = usingZen
                ReanimState.owned_zen_reanim = ownedZen
                ReanimState.saved_name_dist = nameDist
                ReanimState.saved_health_dist = healthDist

                pcall(function()
                    for _, state in ipairs({
                        Enum.HumanoidStateType.Dead, Enum.HumanoidStateType.FallingDown,
                        Enum.HumanoidStateType.Ragdoll, Enum.HumanoidStateType.GettingUp,
                        Enum.HumanoidStateType.Freefall, Enum.HumanoidStateType.Flying,
                        Enum.HumanoidStateType.Landed, Enum.HumanoidStateType.Running,
                        Enum.HumanoidStateType.Climbing, Enum.HumanoidStateType.Swimming,
                    }) do
                        realHum:SetStateEnabled(state, false)
                    end
                    realHum.AutoRotate = false
                    realHum.PlatformStand = true
                    realHum.RequiresNeck = false
                    realHum.BreakJointsOnDeath = false
                    realHum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
                    realHum.NameDisplayDistance = 0
                    realHum.HealthDisplayDistance = 0
                    realHum:ChangeState(Enum.HumanoidStateType.Physics)
                end)

                if cloneHum then
                    pcall(function()
                        cloneHum.PlatformStand = false
                        cloneHum.Sit = false
                        cloneHum.AutoRotate = true
                    end)
                end
                -- Strip WrapLayer from cloneChar so cloneChar doesn't stretch locally, and keep cloneChar visible so you can see where you walk!
                for _, desc in ipairs(cloneChar:GetDescendants()) do
                    if desc:IsA("WrapLayer") or desc:IsA("WrapTarget") then
                        pcall(function() desc:Destroy() end)
                    elseif desc:IsA("BasePart") then
                        desc.Transparency = (desc.Name == "HumanoidRootPart") and 1 or 0.35
                    end
                end

                local physProps = PhysicalProperties.new(0.001, 0, 0, 0, 0)
                for _, part in ipairs(realChar:GetDescendants()) do
                    if part:IsA("BasePart") then
                        pcall(function()
                            part.CanCollide = false
                            part.CanTouch = false
                            part.CanQuery = false
                            part.Massless = true
                            part.CustomPhysicalProperties = physProps
                        end)
                    elseif part:IsA("BillboardGui") or part:IsA("SurfaceGui") then
                        part:Destroy()
                    end
                end

                local limbPairs = {}
                for _, limbName in ipairs(R6_R15_LIMBS) do
                    local realPart = realChar:FindFirstChild(limbName)
                    local fakePart = cloneChar:FindFirstChild(limbName)
                    if realPart and fakePart and realPart:IsA("BasePart") and fakePart:IsA("BasePart") then
                        table.insert(limbPairs, { name = limbName, real = realPart, fake = fakePart })
                    end
                end

                -- CRITICAL FIX FOR 3D LAYERED CLOTHING:
                -- Keep AccessoryWeld ENABLED on any Accessory that has a WrapLayer (3D Layered Clothing) so Roblox's
                -- skinned cage engine stretches the clothing across the deformed R15 limbs! Only detach rigid non-WrapLayer accessories.
                for _, acc in ipairs(realChar:GetDescendants()) do
                    if acc:IsA("Accessory") then
                        local hasWrapLayer = acc:FindFirstChildWhichIsA("WrapLayer", true) ~= nil
                        local realHandle = acc:FindFirstChild("Handle")
                        local cloneAcc = cloneChar:FindFirstChild(acc.Name)
                        local fakeHandle = cloneAcc and cloneAcc:FindFirstChild("Handle")
                        if not hasWrapLayer and realHandle and fakeHandle and realHandle:IsA("BasePart") and fakeHandle:IsA("BasePart") then
                            for _, joint in ipairs(acc:GetDescendants()) do
                                if joint:IsA("Weld") or joint:IsA("WeldConstraint") or joint:IsA("Motor6D") then
                                    joint.Enabled = false
                                end
                            end
                            table.insert(limbPairs, { name = acc.Name, real = realHandle, fake = fakeHandle, isRigidAcc = true })
                        end
                    end
                end

                for i = 1, #limbPairs do
                    pcall(function()
                        local ncc = Instance.new("NoCollisionConstraint")
                        ncc.Name = "ZenNCC_Clone"
                        ncc.Part0 = limbPairs[i].real
                        ncc.Part1 = limbPairs[i].fake
                        ncc.Parent = limbPairs[i].real
                    end)
                end

                if not usingZen then
                    local savedGuis = {}
                    local playerGui = LP:FindFirstChildWhichIsA("PlayerGui")
                    if playerGui then
                        for _, g in ipairs(playerGui:GetChildren()) do
                            if g:IsA("ScreenGui") and g.ResetOnSpawn then
                                savedGuis[g] = true
                                g.ResetOnSpawn = false
                            end
                        end
                    end

                    LP.Character = cloneChar
                    if workspace.CurrentCamera and cloneHum then
                        workspace.CurrentCamera.CameraSubject = cloneHum
                    end
                    for g in pairs(savedGuis) do
                        if g and g.Parent then g.ResetOnSpawn = true end
                    end

                    local cloneAnim = cloneChar:FindFirstChild("Animate")
                    if cloneAnim then cloneAnim.Disabled = false end
                    if cloneHum then cloneHum:ChangeState(Enum.HumanoidStateType.Running) end
                end

                pcall(function()
                    for _, desc in ipairs(realChar:GetDescendants()) do
                        if desc:IsA("Motor6D") then
                            desc.Enabled = false
                        end
                    end
                end)

                pcall(function() workspace.FallenPartsDestroyHeight = 0/0 end)
                pcall(function()
                    settings().Physics.PhysicsEnvironmentalThrottle = Enum.EnviromentalPhysicsThrottle.Disabled
                    settings().Physics.AllowSleep = false
                    if sethiddenproperty then
                        sethiddenproperty(LP, "SimulationRadius", math.huge)
                        sethiddenproperty(LP, "MaxSimulationRadius", math.huge)
                    end
                end)
                local cloneHRPInit = cloneChar:FindFirstChild("HumanoidRootPart")
                if cloneHRPInit then pcall(function() LP.ReplicationFocus = cloneHRPInit end) end

                local realAnim = realChar:FindFirstChild("Animate")
                if realAnim then pcall(function() realAnim.Disabled = true end) end
                for _, track in ipairs(realHum:GetPlayingAnimationTracks()) do
                    if not IsCocoBeaconTrack[track] then
                        track:Stop(0)
                    end
                end

                local function stepCocaSkyDestroyerLimbs(applyVelocity)
                    if not (realChar.Parent and cloneChar.Parent) then return end
                    local groundY, skyY, useGround, useSky, useCubes = sampleEnvironmentState(realChar, cloneChar)
                    local cloneHRP = cloneChar:FindFirstChild("HumanoidRootPart")
                    local linVel = (cloneHRP and cloneHRP.AssemblyLinearVelocity) or Vector3.zero
                    local angVel = (cloneHRP and cloneHRP.AssemblyAngularVelocity) or Vector3.zero
                    local tNow = os.clock()
                    local netlessVel = Vector3.new(0, 25.05, 0) + Vector3.new(math.sin(tNow * 30) * 0.025, 0, math.cos(tNow * 30) * 0.025)
                    for i = 1, #limbPairs do
                        local pair = limbPairs[i]
                        local real_, fake_ = pair.real, pair.fake
                        if real_ and fake_ and real_.Parent and fake_.Parent then
                            if real_.Anchored then real_.Anchored = false end
                            if real_.CanCollide then real_.CanCollide = false end
                            local targetVec = computeSkyDestroyerPosition(pair.name, groundY, skyY, useGround, useSky, useCubes)
                            if targetVec then
                                real_.CFrame = CFrame.new(targetVec)
                                if applyVelocity or _G._HaloCoverNoDelay then
                                    real_.AssemblyLinearVelocity = netlessVel
                                    real_.AssemblyAngularVelocity = Vector3.zero
                                end
                            else
                                real_.CFrame = fake_.CFrame
                                if applyVelocity or _G._HaloCoverNoDelay then
                                    local v = fake_.AssemblyLinearVelocity or linVel
                                    real_.AssemblyLinearVelocity = (v.Magnitude > 0.05 and (v + Vector3.new(0, 25.05, 0))) or netlessVel
                                    real_.AssemblyAngularVelocity = fake_.AssemblyAngularVelocity or angVel
                                end
                            end
                            if applyVelocity and sethiddenproperty then
                                pcall(sethiddenproperty, real_, "NetworkIsSleeping", false)
                            end
                        end
                    end
                end

                CocaSkyDestroyer.sync_now = function(applyVel)
                    if ReanimState.reanimated then
                        stepCocaSkyDestroyerLimbs(applyVel ~= false)
                    end
                end
                CocaSkyDestroyer.get_clone_character = function()
                    return ReanimState.clone_char
                end
                -- ⚡ ZERO-DELAY FRAME-0 EXECUTION + RENDERSTEP LOCK (0.00ms instant mesh deployment!)
                stepCocaSkyDestroyerLimbs(true)
                pcall(function()
                    RunService:BindToRenderStep("CocoSkyDestroyerPreCam", Enum.RenderPriority.Camera.Value, function()
                        stepCocaSkyDestroyerLimbs(false)
                    end)
                    RunService:BindToRenderStep("CocoSkyDestroyerZeroDelay", Enum.RenderPriority.Character.Value + 3, function()
                        stepCocaSkyDestroyerLimbs(false)
                    end)
                end)

                ReanimState.connections.stepped = RunService.Stepped:Connect(function()
                    if not (realChar.Parent and cloneChar.Parent) then return end
                    if realHum.Parent then
                        pcall(function() realHum:ChangeState(Enum.HumanoidStateType.Physics) end)
                    end
                    stepCocaSkyDestroyerLimbs(false)
                end)

                ReanimState.connections.hb = RunService.Heartbeat:Connect(function()
                    if not (realChar.Parent and cloneChar.Parent) then
                        CocaSkyDestroyer.reanimate(false)
                        return
                    end
                    stepCocaSkyDestroyerLimbs(true)
                end)

                ReanimState.connections.render = RunService.RenderStepped:Connect(function()
                    if not (realChar.Parent and cloneChar.Parent) then return end
                    if cloneHum and cloneHum.Parent then
                        cloneHum.DisplayName = ""
                        cloneHum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.Viewer
                        cloneHum.NameDisplayDistance = nameDist
                        cloneHum.HealthDisplayDistance = healthDist
                    end
                    stepCocaSkyDestroyerLimbs(false)
                end)

                ReanimState.reanimated = true
                if WeldIntent.active and WeldIntent.presetKey and WeldIntent.target then
                    task.defer(function()
                        pcall(function() applyWeldPreset(WeldIntent.presetKey, WeldIntent.target) end)
                    end)
                end
            else
                if not ReanimState.reanimated then return end
                pcall(function() RunService:UnbindFromRenderStep("CocoSkyDestroyerPreCam") end)
                pcall(function() RunService:UnbindFromRenderStep("CocoSkyDestroyerZeroDelay") end)
                for k, conn in pairs(ReanimState.connections) do
                    if conn then pcall(function() conn:Disconnect() end) end
                    ReanimState.connections[k] = nil
                end

                local clone = ReanimState.clone_char
                local realChar = ReanimState.real_char
                local usedZen = ReanimState.using_zen_reanim == true
                local ownedZen = ReanimState.owned_zen_reanim == true

                if realChar and realChar.Parent then
                    local realHum = realChar:FindFirstChildWhichIsA("Humanoid")
                    local realHRP = realChar:FindFirstChild("HumanoidRootPart")
                    local cloneHRP = clone and clone:FindFirstChild("HumanoidRootPart")
                    local restoreCF = (cloneHRP and cloneHRP.CFrame) or (realHRP and realHRP.CFrame)

                    if realHRP and restoreCF then
                        markIntentionalTeleport(restoreCF)
                        realHRP.CFrame = restoreCF
                        realHRP.AssemblyLinearVelocity = Vector3.zero
                        realHRP.AssemblyAngularVelocity = Vector3.zero
                    end

                    for _, part in ipairs(realChar:GetDescendants()) do
                        if part:IsA("NoCollisionConstraint") and part.Name == "ZenNCC_Clone" then
                            pcall(function() part:Destroy() end)
                        elseif part:IsA("Motor6D") or part:IsA("Weld") or part:IsA("WeldConstraint") then
                            pcall(function() part.Enabled = true end)
                        elseif part:IsA("BasePart") then
                            pcall(function()
                                part.Massless = false
                                part.CanTouch = true
                                part.CanQuery = true
                                part.CustomPhysicalProperties = nil
                                part.AssemblyLinearVelocity = Vector3.zero
                                part.AssemblyAngularVelocity = Vector3.zero
                                part.Transparency = (part.Name == "HumanoidRootPart") and 1 or 0
                                part.CanCollide = (part.Name == "UpperTorso" or part.Name == "LowerTorso" or part.Name == "Torso")
                            end)
                        end
                    end

                    if realHum then
                        pcall(function()
                            for _, state in ipairs({
                                Enum.HumanoidStateType.Dead, Enum.HumanoidStateType.FallingDown,
                                Enum.HumanoidStateType.Ragdoll, Enum.HumanoidStateType.GettingUp,
                                Enum.HumanoidStateType.Freefall, Enum.HumanoidStateType.Flying,
                                Enum.HumanoidStateType.Landed, Enum.HumanoidStateType.Running,
                                Enum.HumanoidStateType.Climbing, Enum.HumanoidStateType.Swimming,
                            }) do
                                realHum:SetStateEnabled(state, true)
                            end
                            realHum.AutoRotate = true
                            realHum.PlatformStand = false
                            realHum.Sit = false
                            realHum.RequiresNeck = true
                            realHum.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.Viewer
                            realHum.NameDisplayDistance = ReanimState.saved_name_dist or 100
                            realHum.HealthDisplayDistance = ReanimState.saved_health_dist or 100
                            realHum:ChangeState(Enum.HumanoidStateType.GettingUp)
                            realHum:ChangeState(Enum.HumanoidStateType.Running)
                        end)
                    end

                    local realAnim = realChar:FindFirstChild("Animate")
                    if realAnim and (not usedZen or ownedZen) then
                        pcall(function() realAnim.Disabled = false end)
                    end
                end

                if CurrentWeld == nil then
                    pcall(function() LP.ReplicationFocus = nil end)
                end

                if usedZen then
                    local zApi = _G._AngoorZenApi or _G.UltimateReanimAPI
                    if ownedZen and zApi and type(zApi.reanimate) == "function" then
                        pcall(function() zApi.reanimate(false) end)
                    elseif clone and clone.Parent then
                        local cHRP = clone:FindFirstChild("HumanoidRootPart")
                        local pWeld = cHRP and cHRP:FindFirstChild("PuppetRoot")
                        if pWeld then pcall(function() pWeld.Enabled = true end) end
                    end
                else
                    if realChar and realChar.Parent then
                        local realHum = realChar:FindFirstChildWhichIsA("Humanoid")
                        LP.Character = realChar
                        if workspace.CurrentCamera and realHum then
                            workspace.CurrentCamera.CameraSubject = realHum
                        end
                    end
                    if clone and clone.Parent then clone:Destroy() end
                end

                ReanimState.clone_char = nil
                ReanimState.real_char = nil
                ReanimState.using_zen_reanim = false
                ReanimState.owned_zen_reanim = false
                ReanimState.reanimated = false
                if WeldIntent.active and WeldIntent.presetKey and WeldIntent.target then
                    task.defer(function()
                        pcall(function() applyWeldPreset(WeldIntent.presetKey, WeldIntent.target) end)
                    end)
                end
            end
        end)

        ReanimState.is_processing = false
        if not ok then warn("[Coca Sky Destroyer] Reanimation error:", err) end
    end

    function CocaSkyDestroyer.is_reanimated()
        return ReanimState.reanimated == true
    end

    function CocaSkyDestroyer.get_real_character()
        return ReanimState.real_char
    end

    function CocaSkyDestroyer.get_clone()
        return ReanimState.clone_char
    end

    local isTransitioning = false
    local flashThread = nil

    -- ⚡ ZERO-DELAY SYNCHRONOUS REANIMATION DISPATCHER (0.00ms Frame-0 Execution)
    local function warnIfNoLayeredClothing()
        pcall(function()
            local ch = (CocaSkyDestroyer.get_real_character and CocaSkyDestroyer.get_real_character()) or LP.Character
            if not ch then return end
            local count = 0
            for _, acc in ipairs(ch:GetChildren()) do
                if acc:IsA("Accessory") and acc:FindFirstChildWhichIsA("WrapLayer", true) then
                    count = count + 1
                end
            end
            if count == 0 then
                notify("⚠️ NO 3D LAYERED CLOTHING", "0 WrapLayer items equipped! Equip any 3D Layered jacket/pants or Glitch Walker so all players see Sky Destroyer.")
            end
        end)
    end
    _G.WarnIfNoLayeredClothing = warnIfNoLayeredClothing

    local function ensureReanimated()
        if isTransitioning then return end
        warnIfNoLayeredClothing()
        if not CocaSkyDestroyer.is_reanimated() then
            isTransitioning = true
            if CocaSkyDestroyer.engineMode == "CocoSky" and CocaSkyDestroyer.CocoSkyAPI then
                if _G._AngoorZenApi and type(_G._AngoorZenApi.is_reanimated) == "function" and _G._AngoorZenApi.is_reanimated() then
                    pcall(function() _G._AngoorZenApi.reanimate(false) end)
                end
                CocaSkyDestroyer.CocoSkyAPI.reanimate(true)
            elseif CocaSkyDestroyer.engineMode == "EternityV1" and CocaSkyDestroyer.EternityAPI then
                if _G._AngoorZenApi and type(_G._AngoorZenApi.is_reanimated) == "function" and _G._AngoorZenApi.is_reanimated() then
                    pcall(function() _G._AngoorZenApi.reanimate(false) end)
                end
                CocaSkyDestroyer.EternityAPI.reanimate(true)
            else
                -- Coca V2 Sky Destroyer now runs WITH the help of Coca Reanim (_G._AngoorZenApi) instead of disabling it!
                CocaSkyDestroyer.reanimate(true)
            end
            isTransitioning = false
        end
    end

    local function checkAndStopReanimation()
        if not _G._HaloCoverGroundActive
            and not _G._HaloCoverSkyActive
            and not _G._HaloCoverCubeMatrixActive
            and not _G._HaloCoverVortexActive
            and not _G._HaloCoverBlackholeActive
            and not _G._HaloCoverHaloRingActive
            and not _G._HaloCoverHelixActive
            and not _G._HaloCoverWallActive
            and not _G._HaloCoverTsunamiActive
            and not _G._HaloCoverPrisonBoxActive
            and not _G._HaloCoverFlashActive
            and CocaSkyDestroyer.is_reanimated()
            and not isTransitioning
        then
            isTransitioning = true
            if CocaSkyDestroyer.CocoSkyAPI then
                pcall(function() CocaSkyDestroyer.CocoSkyAPI.reanimate(false) end)
            end
            if CocaSkyDestroyer.EternityAPI then
                CocaSkyDestroyer.EternityAPI.reanimate(false)
            end
            CocaSkyDestroyer.reanimate(false)
            isTransitioning = false
        end
        if CocaSkyDestroyer.syncUIFn then pcall(CocaSkyDestroyer.syncUIFn) end
        if syncAllActiveIndicators then pcall(syncAllActiveIndicators) end
    end

    local function startFlashLoop()
        _G._HaloCoverFlashActive = true
        if not flashThread then
            flashThread = task.spawn(function()
                while _G._HaloCoverFlashActive do
                    _G._HaloCoverFlashPhase = not _G._HaloCoverFlashPhase
                    task.wait(_G._HaloCoverFlashSpeed or 0.08)
                end
                _G._HaloCoverFlashPhase = true
                flashThread = nil
            end)
        end
    end

    local function stopFlashLoop()
        _G._HaloCoverFlashActive = false
        _G._HaloCoverFlashPhase = true
        flashThread = nil
    end

    function _G.SetCoverGround(enabled, elevation)
        if elevation ~= nil then _G._HaloCoverGroundHeight = elevation end
        if enabled then
            _G._HaloCoverGroundActive = true
            ensureReanimated()
            notify("💥 COCA SKY DESTROYER", "Cover Ground ACTIVE! (0ms Zero-Delay)")
            sToggleOn()
        else
            _G._HaloCoverGroundActive = false
            notify("💥 COCA SKY DESTROYER", "Cover Ground disabled")
            sToggleOff()
            checkAndStopReanimation()
        end
        if CocaSkyDestroyer.syncUIFn then pcall(CocaSkyDestroyer.syncUIFn) end
        if syncAllActiveIndicators then pcall(syncAllActiveIndicators) end
    end

