        local winRowRefs = {}
        spawnOrToggleMiniWindow = function(winKey, titleText, itemsList, posOffset)
            if UI.miniWindows[winKey] and UI.miniWindows[winKey].Parent then
                UI.miniWindows[winKey]:Destroy()
