        local REMOVE_LOUD_NEUTRAL = {
            {
                name = "distortion",
                props = {
                    { "Level",   0 },
                    { "Enabled", false },
                },
            },
            {
                name = "equalier",
                props = {
                    { "LowGain",  0 },
                    { "MidGain",  0 },
                    { "HighGain", 0 },
                    { "MidRange", { min = 400, max = 4000 } },
                    { "Enabled",  false },
                },
            },
            {
                name = "flter",
                props = {
                    { "FilterType", 0 },
                    { "Frequency",  1000 },
                    { "Gain",       0 },
                    { "Q",          1 },
                    { "Enabled",    false },
                },
            },
            {
                name = "reverb",
                props = {
                    { "DecayTime",          0.1 },
                    { "Density",            0 },
                    { "DecayRatio",         0.5 },
                    { "Diffusion",          0 },
                    { "DryLevel",           0 },
                    { "WetLevel",           -80 },
                    { "EarlyDelayTime",     0 },
                    { "LateDelayTime",      0 },
                    { "LowShelfGain",       0 },
                    { "Enabled",            false },
                },
            },
        }

        local loudState = {
            autoReapply = false,
            busy        = false,
            lastPreset  = "v40",
        }

        local function getLoudRemotes()
            local addEv  = RS:FindFirstChild("event_effect_add") or RS:FindFirstChild("event_effect_add", true)
            local propEv = RS:FindFirstChild("event_effect_property") or RS:FindFirstChild("event_effect_property", true)
            return addEv, propEv
        end

        local function findOptionalRemote(names)
            for _, n in ipairs(names) do
                local ev = RS:FindFirstChild(n) or RS:FindFirstChild(n, true)
                if ev and (ev:IsA("RemoteEvent") or ev:IsA("RemoteFunction")) then
                    return ev
                end
            end
            return nil
        end

        local function scanEffectRemotes()
            local found = {}
            for _, inst in ipairs(RS:GetDescendants()) do
                if inst:IsA("RemoteEvent") or inst:IsA("RemoteFunction") then
                    local lower = string.lower(inst.Name)
                    if string.find(lower, "effect", 1, true)
                        or string.find(lower, "audio", 1, true)
                        or string.find(lower, "voice", 1, true)
                        or string.find(lower, "mic", 1, true)
                        or string.find(lower, "sound", 1, true)
                        or string.find(lower, "loud", 1, true)
                        or string.find(lower, "gain", 1, true)
                        or string.find(lower, "volume", 1, true) then
                        table.insert(found, inst.Name)
                    end
                end
            end
            table.sort(found)
            return found
        end

        local function applyPresetTable(presetTable)
            local addEv, propEv = getLoudRemotes()
            if not addEv or not propEv then
                return false, "remotes missing (event_effect_add / event_effect_property)"
            end

            local applied = {}
            for _, fx in ipairs(presetTable) do
                local okAdd = pcall(function()
                    addEv:FireServer(fx.name)
                end)
                if not okAdd then
                    table.insert(applied, fx.name .. ":add_fail")
                else
                    task.wait(0.05)
                    local okAll = true
                    for _, p in ipairs(fx.props) do
                        local ok = pcall(function()
                            propEv:FireServer(fx.name, p[1], p[2])
                        end)
                        if not ok then okAll = false end
                        task.wait(0.02)
                    end
                    table.insert(applied, fx.name .. (okAll and ":ok" or ":partial"))
                end
                task.wait(0.06)
            end
            return true, table.concat(applied, ", ")
        end

        local function applyMicUpV31Preset()
            return applyPresetTable(MICUP_V31_PRESET)
        end

        local function boostLocalAudioChainV35()
            local emitters, fxBoosted = 0, 0
            local targets = {}
            if LP.Character then table.insert(targets, LP.Character) end
            table.insert(targets, LP)

            for _, root in ipairs(targets) do
                for _, inst in ipairs(root:GetDescendants()) do
                    if inst:IsA("AudioEmitter") then
                        local ok = pcall(function()
                            pcall(function()
                                inst.DistanceAttenuationMode = Enum.DistanceAttenuationMode.Custom
                            end)
                            inst:SetDistanceAttenuation(V35_FLAT_DISTANCE_CURVE)
                            inst:SetAngleAttenuation(V35_FLAT_ANGLE_CURVE)
                            pcall(function()
                                inst.AcousticSimulationEnabled = false
                            end)
                        end)
                        if ok then emitters = emitters + 1 end
                    elseif inst:IsA("AudioDistortion") then
                        if pcall(function()
                            inst.Bypass = false
                            inst.Level = 1
                        end) then fxBoosted = fxBoosted + 1 end
                    elseif inst:IsA("AudioEqualizer") then
                        if pcall(function()
                            inst.Bypass = false
                            inst.LowGain = 10
                            inst.MidGain = 10
                            inst.HighGain = 10
                        end) then fxBoosted = fxBoosted + 1 end
                    elseif inst:IsA("AudioFilter") then
                        if pcall(function()
                            inst.Bypass = false
                            inst.FilterType = Enum.AudioFilterType.LowShelf
                            inst.Frequency = 22000
                            inst.Gain = 30
                        end) then fxBoosted = fxBoosted + 1 end
                    elseif inst:IsA("AudioReverb") then
                        if pcall(function()
                            inst.Bypass = false
                            inst.DryLevel = 20
                            inst.WetLevel = 20
                            inst.LowShelfGain = 12
                            inst.LowShelfFrequency = 20000
                            inst.HighCutFrequency = 20000
                            inst.Density = 1
                            inst.Diffusion = 1
                            inst.DecayTime = 20
                            inst.DecayRatio = 1
                            inst.EarlyDelayTime = 0
                        end) then fxBoosted = fxBoosted + 1 end
                    elseif inst:IsA("AudioFader") then
                        if pcall(function()
                            inst.Bypass = false
                            inst.Volume = 10
                        end) then fxBoosted = fxBoosted + 1 end
                    elseif inst:IsA("AudioCompressor") then
                        if pcall(function()
                            inst.Bypass = false
                            inst.MakeupGain = 30
                        end) then fxBoosted = fxBoosted + 1 end
                    end
                end
            end
            return emitters, fxBoosted
        end

        local function fireFxListV35(addEv, propEv, list, applied)
            for _, fx in ipairs(list) do
                local okAdd = pcall(function()
                    addEv:FireServer(fx.name)
                end)
                if not okAdd then
                    if applied then table.insert(applied, fx.name .. ":add_fail") end
                else
                    task.wait(0.05)
                    local okAll = true
                    for _, p in ipairs(fx.props) do
                        local ok = pcall(function()
                            propEv:FireServer(fx.name, p[1], p[2])
                        end)
                        if not ok then okAll = false end
                        task.wait(0.02)
                    end
                    if applied then
                        table.insert(applied, fx.name .. (okAll and ":ok" or ":partial"))
                    end
                end
                task.wait(0.06)
            end
        end

        local function applyMicUpV35Preset()
            local addEv, propEv = getLoudRemotes()
            if not addEv or not propEv then
                return false, "remotes missing (event_effect_add / event_effect_property)"
            end

            local applied = {}
            -- Pass 1: Gain-staged core chain (EQ -> Filter -> Distortion -> Reverb)
            fireFxListV35(addEv, propEv, MICUP_V35_PRESET, applied)

            -- Pass 2: Reinforce distortion + core properties so none reset during wiring
            for _, fx in ipairs(MICUP_V35_PRESET) do
                for _, p in ipairs(fx.props) do
                    pcall(function()
                        propEv:FireServer(fx.name, p[1], p[2])
                    end)
                    task.wait(0.015)
                end
            end

            -- Pass 3: Optional extra effects (compressor / fader / echo) if server supports them
            fireFxListV35(addEv, propEv, MICUP_V35_EXTRA_PRESET, nil)

            -- Pass 4: Local emitter range + audio chain reinforcement
            local emitterCount, fxCount = boostLocalAudioChainV35()
            table.insert(applied, "range:" .. (emitterCount > 0 and ("ok(" .. emitterCount .. ")") or "none"))
            if fxCount > 0 then
                table.insert(applied, "localfx:" .. fxCount)
            end

            return true, table.concat(applied, ", ")
        end

        local function boostLocalAudioChainV50()
            local emitters, fxBoosted, inputsBoosted = 0, 0, 0
            local targets = {}
            if LP.Character then table.insert(targets, LP.Character) end
            table.insert(targets, LP)

            for _, root in ipairs(targets) do
                for _, inst in ipairs(root:GetDescendants()) do
                    if inst:IsA("AudioDeviceInput") then
                        if pcall(function()
                            inst.Volume = 10 -- clamps to engine maximum mic gain
                        end) then inputsBoosted = inputsBoosted + 1 end
                    elseif inst:IsA("AudioEmitter") then
                        local ok = pcall(function()
                            pcall(function()
                                inst.DistanceAttenuationMode = Enum.DistanceAttenuationMode.Custom
                            end)
                            inst:SetDistanceAttenuation(V50_FLAT_DISTANCE_CURVE)
                            inst:SetAngleAttenuation(V50_FLAT_ANGLE_CURVE)
                            pcall(function()
                                inst.AcousticSimulationEnabled = false
                            end)
                        end)
                        if ok then emitters = emitters + 1 end
                    elseif inst:IsA("AudioDistortion") then
                        if pcall(function()
                            inst.Bypass = false
                            inst.Level = 1
                        end) then fxBoosted = fxBoosted + 1 end
                    elseif inst:IsA("AudioEqualizer") then
                        if pcall(function()
                            inst.Bypass = false
                            inst.HighGain = 10
                            inst.LowGain = 10
                            inst.MidGain = 0
                            inst.MidRange = NumberRange.new(20000, 20000)
                        end) then fxBoosted = fxBoosted + 1 end
                    elseif inst:IsA("AudioFilter") then
                        if pcall(function()
                            inst.Bypass = false
                            inst.FilterType = Enum.AudioFilterType.Peak
                            inst.Frequency = 2000
                            inst.Gain = 30
                            inst.Q = 0.1
                        end) then fxBoosted = fxBoosted + 1 end
                    elseif inst:IsA("AudioReverb") then
                        if pcall(function()
                            inst.Bypass = false
                            inst.DecayRatio = 0.5
                            inst.DecayTime = 1.5
                            inst.Density = 1
                            inst.Diffusion = 1
                            inst.DryLevel = 20
                            inst.EarlyDelayTime = 0.02
                            inst.HighCutFrequency = 5000
                            inst.LateDelayTime = 0.04
                            inst.LowShelfFrequency = 20000
                            inst.LowShelfGain = 12
                            inst.ReferenceFrequency = 20000
                            inst.WetLevel = 20
                        end) then fxBoosted = fxBoosted + 1 end
                    elseif inst:IsA("AudioFader") then
                        if pcall(function()
                            inst.Bypass = false
                            inst.Volume = 10
                        end) then fxBoosted = fxBoosted + 1 end
                    elseif inst:IsA("AudioCompressor") then
                        if pcall(function()
                            inst.Bypass = false
                            inst.Threshold = 0
                            inst.Ratio = 1
                            inst.Attack = 0.001
                            inst.Release = 0.01
                            inst.MakeupGain = 30
                        end) then fxBoosted = fxBoosted + 1 end
                    elseif inst:IsA("AudioEcho") then
                        if pcall(function()
                            inst.Bypass = false
                            inst.DelayTime = 0.001
                            inst.DryLevel = 10
                            inst.WetLevel = -80
                            inst.Feedback = 0
                            inst.RampTime = 0
                        end) then fxBoosted = fxBoosted + 1 end
                    elseif inst:IsA("AudioChorus")
                        or inst:IsA("AudioFlanger")
                        or inst:IsA("AudioTremolo")
                        or inst:IsA("AudioLimiter")
                        or inst:IsA("AudioGate") then
                        pcall(function()
                            inst.Bypass = true
                        end)
                    end
                end
            end
            return emitters, fxBoosted, inputsBoosted
        end

        local function reinforceFxListV50(propEv, list)
            for _, fx in ipairs(list) do
                for _, p in ipairs(fx.props) do
                    pcall(function()
                        propEv:FireServer(fx.name, p[1], p[2])
                    end)
                    task.wait(0.015)
                end
            end
        end

        local v50LocalRespawnHooked = false

        local function applyMicUpV50Preset()
            local addEv, propEv = getLoudRemotes()
            if not addEv or not propEv then
                return false, "remotes missing (event_effect_add / event_effect_property)"
            end

            -- Bypass any hiss/limiting FX if present
            for _, name in ipairs(V50_BYPASS_FX) do
                pcall(function()
                    propEv:FireServer(name, "Bypass", true)
                end)
                task.wait(0.015)
            end

            local applied = {}
            -- Pass 1: Exact Lavinho Mic Up core chain (EQ -> Filter -> Distortion -> Reverb)
            fireFxListV35(addEv, propEv, MICUP_V50_PRESET, applied)

            -- Pass 2: Extra pure-gain attachments (compressor / fader / dry-only echo)
            fireFxListV35(addEv, propEv, MICUP_V50_EXTRA_PRESET, nil)

            -- Pass 3: Reinforce ALL core + extra properties so none reset during server wiring
            reinforceFxListV50(propEv, MICUP_V50_PRESET)
            reinforceFxListV50(propEv, MICUP_V50_EXTRA_PRESET)

            -- Pass 4: Local mic input, emitter range (100k studs), and full audio chain reinforcement
            local emitterCount, fxCount, inputCount = boostLocalAudioChainV50()
            table.insert(applied, "range:" .. (emitterCount > 0 and ("ok(" .. emitterCount .. ")") or "none"))
            if inputCount > 0 then
                table.insert(applied, "mic:" .. inputCount)
            end
            if fxCount > 0 then
                table.insert(applied, "localfx:" .. fxCount)
            end

            -- Keep local mic/emitter/FX chain maxed after respawns when v5.0 is the active preset
            if not v50LocalRespawnHooked then
                v50LocalRespawnHooked = true
                LP.CharacterAdded:Connect(function()
                    if loudState.lastPreset ~= "v40" and loudState.lastPreset ~= "v41" and loudState.lastPreset ~= "v50" then return end
                    task.wait(1)
                    boostLocalAudioChainV50()
                end)
            end

            return true, table.concat(applied, ", ")
        end

