        local v45LocalRespawnHooked = false

        local function applyMicUpV45Preset()
            local addEv, propEv = getLoudRemotes()
            if not addEv or not propEv then
                return false, "remotes missing (event_effect_add / event_effect_property)"
            end

            -- Bypass any limiting/modulation FX that cap volume
            for _, name in ipairs(V45_BYPASS_FX) do
                pcall(function()
                    propEv:FireServer(name, "Bypass", true)
                end)
                task.wait(0.015)
            end

            local applied = {}
            -- Pass 1: Core max-loud chain (distortion -> equalier -> flter -> reverb)
            fireFxListV35(addEv, propEv, MICUP_V45_PRESET, applied)

            -- Pass 2: Extra pure-gain stages (compressor + fader + stacked echo)
            fireFxListV35(addEv, propEv, MICUP_V45_EXTRA_PRESET, nil)

            -- Pass 3: Reinforce ALL core + extra properties so none reset during server wiring
            reinforceFxListV50(propEv, MICUP_V45_PRESET)
            reinforceFxListV50(propEv, MICUP_V45_EXTRA_PRESET)

            -- Pass 4: Local mic input, 100k-stud emitter range, and local audio chain sync
            local emitterCount, fxCount, inputCount = boostLocalAudioChainV45()
            table.insert(applied, "range:" .. (emitterCount > 0 and ("ok(" .. emitterCount .. ")") or "none"))
            if inputCount > 0 then
                table.insert(applied, "mic:" .. inputCount)
            end
            if fxCount > 0 then
                table.insert(applied, "localfx:" .. fxCount)
            end

            -- Keep local mic/emitter/FX chain maxed after respawns when Loud VR 4.5 is active
            if not v45LocalRespawnHooked then
                v45LocalRespawnHooked = true
                LP.CharacterAdded:Connect(function()
                    if loudState.lastPreset ~= "v45" then return end
                    task.wait(1)
                    boostLocalAudioChainV45()
                end)
            end

            return true, table.concat(applied, ", ")
        end

        -- Bulletproof 3-layer One Click Remove Loud:
        --   Layer 1: Clear/Reset-All remotes (known names + dynamic scan)
        --   Layer 2: Per-effect Remove/Delete/Disable remotes for all voice FX
        --   Layer 3: Guaranteed property neutralize via event_effect_property + local Audio* FX cleanup
        local function clearLoudEffects()
            local steps = {}
            local anySuccess = false

            -- Layer 1: Direct Clear / Reset-All remotes
            local clearEv = findOptionalRemote({
                "event_effect_clear",
                "event_effects_clear",
                "event_effect_reset",
                "event_effects_reset",
                "event_effect_remove_all",
                "event_clear_effects",
            })
            if not clearEv then
                for _, inst in ipairs(RS:GetDescendants()) do
                    if inst:IsA("RemoteEvent") or inst:IsA("RemoteFunction") then
                        local ln = string.lower(inst.Name)
                        if string.find(ln, "effect", 1, true) and (string.find(ln, "clear", 1, true) or string.find(ln, "reset", 1, true)) then
                            clearEv = inst
                            break
                        end
                    end
                end
            end
            if clearEv then
                local ok = pcall(function()
                    if clearEv:IsA("RemoteEvent") then
                        clearEv:FireServer()
                    else
                        clearEv:InvokeServer()
                    end
                end)
                if ok then
                    anySuccess = true
                    table.insert(steps, "cleared:" .. clearEv.Name)
                end
                task.wait(0.03)
            end

            -- Layer 2: Per-effect Remove / Delete / Disable remotes
            local removeEv = findOptionalRemote({
                "event_effect_remove",
                "event_effect_delete",
                "event_effect_destroy",
                "event_effect_disable",
                "event_effect_off",
                "event_remove_effect",
            })
            if not removeEv then
                for _, inst in ipairs(RS:GetDescendants()) do
                    if inst:IsA("RemoteEvent") or inst:IsA("RemoteFunction") then
                        local ln = string.lower(inst.Name)
                        if string.find(ln, "effect", 1, true) and (string.find(ln, "remove", 1, true) or string.find(ln, "delete", 1, true) or string.find(ln, "destroy", 1, true)) then
                            removeEv = inst
                            break
                        end
                    end
                end
            end
            local fxNames = { "distortion", "equalier", "flter", "reverb", "chorus", "flanger", "compressor", "fader", "echo", "pitch" }
            if removeEv then
                local removed = 0
                for _, n in ipairs(fxNames) do
                    local ok = pcall(function()
                        if removeEv:IsA("RemoteEvent") then
                            removeEv:FireServer(n)
                        else
                            removeEv:InvokeServer(n)
                        end
                    end)
                    if ok then removed = removed + 1 end
                    task.wait(0.02)
                end
                if removed > 0 then
                    anySuccess = true
                    table.insert(steps, string.format("removed(%d):%s", removed, removeEv.Name))
                end
            end

            -- Layer 3: Guaranteed property neutralize via event_effect_property
            local _, propEv = getLoudRemotes()
            if propEv then
                local resetCount = 0
                for _, fx in ipairs(REMOVE_LOUD_NEUTRAL) do
                    for _, p in ipairs(fx.props) do
                        local ok = pcall(function()
                            propEv:FireServer(fx.name, p[1], p[2])
                        end)
                        if ok then resetCount = resetCount + 1 end
                        task.wait(0.015)
                    end
                end
                if resetCount > 0 then
                    anySuccess = true
                    table.insert(steps, string.format("neutralized(%d props)", resetCount))
                end
            end

            -- Local client Audio* effect cleanup (bypass/disable any client-side audio effects)
            local localReset = 0
            pcall(function()
                local containers = { LP }
                if LP.Character then table.insert(containers, LP.Character) end
                local vcs = game:FindFirstChildOfClass("VoiceChatService")
                if vcs then table.insert(containers, vcs) end
                for _, root in ipairs(containers) do
                    for _, d in ipairs(root:GetDescendants()) do
                        local cn = d.ClassName
                        if cn == "AudioDistortion" or cn == "AudioEqualizer" or cn == "AudioFilter" or cn == "AudioReverb" or cn == "AudioChorus" or cn == "AudioFlanger" or cn == "AudioCompressor" or cn == "AudioEcho" or cn == "AudioFader" then
                            pcall(function() d.Bypass = true end)
                            if cn == "AudioDistortion" then pcall(function() d.Level = 0 end)
                            elseif cn == "AudioEqualizer" then pcall(function() d.LowGain = 0; d.MidGain = 0; d.HighGain = 0 end)
                            elseif cn == "AudioFilter" then pcall(function() d.Gain = 0 end)
                            elseif cn == "AudioReverb" then pcall(function() d.DryLevel = 0; d.WetLevel = -80 end)
                            elseif cn == "AudioCompressor" then pcall(function() d.MakeupGain = 0 end)
                            elseif cn == "AudioFader" then pcall(function() d.Volume = 1 end)
                            elseif cn == "AudioEcho" then pcall(function() d.Feedback = 0; d.DryLevel = 0; d.WetLevel = -80 end)
                            elseif cn == "AudioChorus" or cn == "AudioFlanger" then pcall(function() d.Mix = 0 end) end
                            localReset = localReset + 1
                        elseif cn == "AudioDeviceInput" then
                            pcall(function() d.Volume = 1 end)
                            localReset = localReset + 1
                        end
                    end
                end
            end)
            if localReset > 0 then
                anySuccess = true
                table.insert(steps, string.format("localFX(%d)", localReset))
            end

            if anySuccess then
                return true, table.concat(steps, " · ")
            end
            return false, "no effect remotes or local audio FX found"
        end

        local function applyCocoLoudPreset()
            local addEv, propEv = getLoudRemotes()
            if not addEv or not propEv then
                return false, "remotes missing (event_effect_add / event_effect_property)"
            end

            local applied = {}
            for _, fx in ipairs(COCO_LOUD_PRESET) do
                local okAdd = pcall(function()
                    addEv:FireServer(fx.name)
                end)
                if not okAdd then
                    table.insert(applied, fx.name .. ":add_fail")
                else
                    task.wait(0.05)
                    local okAll = true
                    for _, p in ipairs(fx.props) do
                        local ok = pcall(function()
                            propEv:FireServer(fx.name, p[1], p[2])
                        end)
                        if not ok then okAll = false end
                        task.wait(0.02)
                    end
                    table.insert(applied, fx.name .. (okAll and ":ok" or ":partial"))
                end
                task.wait(0.06)
            end
            return true, table.concat(applied, ", ")
        end

