                local tgt = selectedPlayer or resolveActiveTarget()
                if not tgt or tgt == LP then
                    notify("🛡️ WHITELIST", "Select a player first!")
                    return
                end
                local nowWl = not _G.CocoTargetWhitelist[tgt.UserId]
                _G.CocoTargetWhitelist[tgt.UserId] = nowWl or nil
                pillBtn.Text = nowWl and "Protected" or "Whitelist"
                notify("🛡️ WHITELIST", (nowWl and "Added @" or "Removed @") .. tgt.Name .. (nowWl and " to Protected Whitelist!" or " from Whitelist"))
                if refreshList then pcall(refreshList, true) end
            end,
            function()
                _G.CocoTargetWhitelist = {}
                notify("🛡️ WHITELIST", "Cleared custom target whitelist")
                if refreshList then pcall(refreshList, true) end
            end,
            "↺"
        )

        createActionRow(
            intelGrp,
            6,
            "All Players Auto-Cycle Weld (One-by-One Loop) (NEW)",
            "Automatically attaches to every player in the server one by one and repeats at 0.00ms zero-delay",
            WeldIntent.allMode and "All: ON" or "All: OFF",
            function(pillBtn)
                togglePresetOrAction("all")
                pillBtn.Text = WeldIntent.allMode and "All: ON" or "All: OFF"
            end,
            function()
                if type(_G.CocoAdvanceAllPlayersCycle) == "function" and WeldIntent.allMode then
                    _G.CocoAdvanceAllPlayersCycle(true)
                else
                    togglePresetOrAction("all")
                end
            end,
            "⏭️"
        )

        -- Tap-to-Target Any Player in 3D World (ON by default, toggleable OFF)
        ;(function()
            local tapTargetSwitchRow = nil
            UI.setTapToTargetEnabled = function(st, showToast)
                local enabled = (st == true)
                OwnerAdminState.tapToTargetEnabled = enabled
                if tapTargetSwitchRow and tapTargetSwitchRow.setState then
                    tapTargetSwitchRow.setState(enabled, false)
                end
                if UI.autoSaveConfig and UI.saveConfigToDisk then UI.saveConfigToDisk(false) end
                if showToast ~= false then
                    notify("🎯 TAP-TO-TARGET", enabled and "Tap any player in the world to target them (ON)" or "Tap-to-Target disabled (OFF)")
                end
            end

            tapTargetSwitchRow = createSwitchRow(
                intelGrp,
                7,
                "Tap-to-Target Player (3D World)",
                "Tap or click any player in the world to lock/target them · ON by default",
                OwnerAdminState.tapToTargetEnabled ~= false,
                function(st)
                    UI.setTapToTargetEnabled(st, true)
                end
            )

            -- Disconnect any previous Tap-to-Target listeners on re-execution
            if type(_G.CocoTapToTargetConns) == "table" then
                for _, c in ipairs(_G.CocoTapToTargetConns) do
                    pcall(function() c:Disconnect() end)
                end
            end
            _G.CocoTapToTargetConns = {}

            local tapStartPos = nil
            local tapStartTime = 0
            local tapInputRef = nil

            local function isTappingInteractiveGui(pos)
                local pg = LP:FindFirstChildOfClass("PlayerGui")
                if not pg then return false end
                local ok, objs = pcall(function() return pg:GetGuiObjectsAtPosition(pos.X, pos.Y) end)
                if not ok or type(objs) ~= "table" then return false end
                for _, obj in ipairs(objs) do
                    if obj and obj.Visible then
                        if obj:IsA("GuiButton") or obj:IsA("TextBox") then
                            return true
                        end
                        if sg and obj:IsDescendantOf(sg) and obj.BackgroundTransparency < 0.95 then
                            return true
                        end
                    end
                end
                return false
            end

            local function resolvePlayerFromHitInstance(inst)
                if not inst then return nil end
                local cur = inst
                while cur and cur ~= workspace do
                    if cur:IsA("Model") then
                        local p = Players:GetPlayerFromCharacter(cur)
                        if p and p ~= LP then return p end
                    end
                    cur = cur.Parent
                end
                -- Fallback: check custom/reanim character lookup
                for _, p in ipairs(Players:GetPlayers()) do
                    if p ~= LP then
                        local ch = findPlayerCharacterAnywhere(p, true)
                        if ch and (inst == ch or inst:IsDescendantOf(ch)) then
                            return p
                        end
                    end
                end
                return nil
            end

            local function findTappedPlayerAtScreenPos(screenPos)
                local cam = workspace.CurrentCamera
                if not cam then return nil end
                local ray = cam:ViewportPointToRay(screenPos.X, screenPos.Y)
                local params = RaycastParams.new()
                params.FilterType = Enum.RaycastFilterType.Exclude
                local ignoreList = {}
                if LP.Character then table.insert(ignoreList, LP.Character) end
                params.FilterDescendantsInstances = ignoreList
                local res = workspace:Raycast(ray.Origin, ray.Direction * 650, params)
                if res and res.Instance then
                    local hitPlr = resolvePlayerFromHitInstance(res.Instance)
                    if hitPlr then return hitPlr end
                end
                -- Mobile-friendly proximity fallback: pick closest visible player torso/head within 28px of tap
                local bestPlr = nil
                local bestDistPx = 28
                for _, p in ipairs(Players:GetPlayers()) do
                    if p ~= LP then
                        local ch = findPlayerCharacterAnywhere(p, true)
                        local ref = ch and (ch:FindFirstChild("HumanoidRootPart") or ch:FindFirstChild("Head") or ch:FindFirstChildWhichIsA("BasePart"))
                        if ref and ref.Parent then
                            local vPos, onScreen = cam:WorldToViewportPoint(ref.Position)
                            if onScreen and vPos.Z > 0 and vPos.Z <= 280 then
                                local dPx = (Vector2.new(vPos.X, vPos.Y) - screenPos).Magnitude
                                if dPx < bestDistPx then
                                    bestDistPx = dPx
                                    bestPlr = p
                                end
                            end
                        end
                    end
                end
                return bestPlr
            end

            local function flashTargetHighlight(plr)
                pcall(function()
                    local ch = findPlayerCharacterAnywhere(plr, true)
                    if not ch then return end
                    local oldHl = ch:FindFirstChild("CocoTapTargetHighlight")
                    if oldHl then oldHl:Destroy() end
                    local hl = Instance.new("Highlight")
                    hl.Name = "CocoTapTargetHighlight"
                    hl.FillColor = Color3.fromRGB(168, 85, 247)
                    hl.OutlineColor = Color3.fromRGB(255, 255, 255)
                    hl.FillTransparency = 0.55
                    hl.OutlineTransparency = 0.05
                    hl.Adornee = ch
                    hl.Parent = ch
                    task.delay(0.85, function()
                        if hl and hl.Parent then hl:Destroy() end
                    end)
                end)
            end

            local function lockTappedPlayer(p)
                if not p or p == LP or p.Parent ~= Players then return end
                if WeldIntent.allMode and type(_G.CocoStopAllPlayersCycle) == "function" then
                    _G.CocoStopAllPlayersCycle(true)
                end
                selectedPlayer = p
                CurrentTarget = p
                LastWeldTargetUserId = p.UserId
                WeldIntent.target = p
                WeldIntent.typedUsername = p.Name
                WeldIntent.leftInfo = nil
                WeldIntent.waitingForSpawn = false
                if WeldIntent.setUsernameBoxText then pcall(WeldIntent.setUsernameBoxText, p.Name) end
                if footerLabel then footerLabel.Text = "Target: " .. p.Name end
                if footerSub then footerSub.Text = "tapped & locked" end
                hookTargetRespawn(p)

                local presetToConnect = (WeldIntent.active and WeldIntent.presetKey)
                    or ((AnimCopySys and AnimCopySys.active) and "animcopy")
                    or (CurrentWeld and (WeldIntent.presetKey or LastPresetKey))
                    or (WeldIntent.waitingForSpawn and (WeldIntent.presetKey or LastPresetKey))
                if presetToConnect and WELD_PRESETS[presetToConnect] then
                    applyWeldPreset(presetToConnect, p)
                    if syncAllActiveIndicators then pcall(syncAllActiveIndicators) end
                    notify("🎯 TAP TARGET", "Targeted & connected (" .. (WELD_PRESETS[presetToConnect].label or presetToConnect) .. ") -> @" .. p.Name)
                else
                    notify("🎯 TAP TARGET", "Targeted @" .. p.Name .. " (" .. p.DisplayName .. ")")
                end
                flashTargetHighlight(p)
                pcall(sSuccess)
                if refreshList then pcall(refreshList) end
                if refreshCard then pcall(refreshCard) end
            end

            table.insert(_G.CocoTapToTargetConns, UIS.InputBegan:Connect(function(input, gp)
                if gp or not OwnerAdminState.tapToTargetEnabled or OwnerAdminState.isBannedByOwner then return end
                if UIS:GetFocusedTextBox() then return end
                if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                    tapStartPos = Vector2.new(input.Position.X, input.Position.Y)
                    tapStartTime = os.clock()
                    tapInputRef = input
                end
            end))

            table.insert(_G.CocoTapToTargetConns, UIS.InputEnded:Connect(function(input, gp)
                if not tapStartPos or input ~= tapInputRef then return end
                local startPos = tapStartPos
                local elapsed = os.clock() - tapStartTime
                tapStartPos = nil
                tapInputRef = nil

                if gp or not OwnerAdminState.tapToTargetEnabled or OwnerAdminState.isBannedByOwner then return end
                if UIS:GetFocusedTextBox() then return end
                if os.clock() - (OwnerAdminState.lastOverheadTagTapTick or 0) < 0.40 then return end

                -- Ignore if user is holding Click TP tool
                local myCh = LP.Character
                if myCh and myCh:FindFirstChild("Click TP") then return end

                local endPos = Vector2.new(input.Position.X, input.Position.Y)
                if elapsed > 0.42 or (endPos - startPos).Magnitude > 14 then return end
                if isTappingInteractiveGui(endPos) then return end

                local hitPlr = findTappedPlayerAtScreenPos(endPos)
                if hitPlr then
                    lockTappedPlayer(hitPlr)
                end
            end))
        end)()

        createSectionTitle(targetPage, 3, "Server Players")
        local plrGrp = createGroupCard(targetPage, 4)
        plrGrp:SetAttribute("DynamicList", true)
        local targetListDirty = true

        local function findPlayers(q)
            q = (q or ""):lower()
            local list = {}
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LP then
                    if q == "" or p.Name:lower():find(q, 1, true) or p.DisplayName:lower():find(q, 1, true) then
                        table.insert(list, p)
                    end
                end
            end
            return list
        end

        refreshList = function(forceRebuild)
            local allOtherCount = math.max(0, #Players:GetPlayers() - 1)
            if UI.catCountLabels["Target"] then
                UI.catCountLabels["Target"].Text = tostring(allOtherCount)
            end
            if not forceRebuild and not targetPage.Visible then
                targetListDirty = true
                return
            end
            targetListDirty = false
            for _, c in ipairs(plrGrp:GetChildren()) do
                if c:IsA("Frame") or c:IsA("TextLabel") then c:Destroy() end
            end

            -- Pinned Departed Target Row: If a locked/welded player left the server, keep their name & "HAS LEFT" status in the panel until changed!
            local hasPinnedLeft = (WeldIntent.leftInfo ~= nil and WeldIntent.leftInfo.leftAt ~= nil)
            if hasPinnedLeft then
                local info = WeldIntent.leftInfo
                local leftDisp = info.displayName or info.name or "Unknown"
                local leftName = info.name or "unknown"
                local leftRow = createActionRow(
                    plrGrp,
                    0,
                    leftDisp .. "  [🚨 PLAYER HAS LEFT]",
                    "@" .. leftName .. "  ·  HAS LEFT THE SERVER  ·  Kept in panel until you change target",
                    "Has Left",
                    function()
                        -- Selecting any other player or tapping here when ready clears the departed lock
                        WeldIntent.leftInfo = nil
                        WeldIntent.waitingForSpawn = false
                        WeldIntent.typedUsername = ""
                        if WeldIntent.setUsernameBoxText then pcall(WeldIntent.setUsernameBoxText, "") end
                        refreshList(true)
                        if refreshCard then pcall(refreshCard) end
                        notify("COCO POWDER", "Cleared departed player @" .. leftName .. " from panel")
                    end,
                    function()
                        WeldIntent.leftInfo = nil
                        WeldIntent.waitingForSpawn = false
                        WeldIntent.typedUsername = ""
                        if WeldIntent.setUsernameBoxText then pcall(WeldIntent.setUsernameBoxText, "") end
                        refreshList(true)
                        if refreshCard then pcall(refreshCard) end
                        notify("COCO POWDER", "Cleared departed player @" .. leftName .. " from panel")
                    end,
                    "✕"
                )
                if leftRow and leftRow.pillBtn then
                    BtnColors[leftRow.pillBtn] = T.Danger
                    leftRow.pillBtn.BackgroundColor3 = T.Danger
                    leftRow.pillBtn.TextColor3 = Color3.new(1, 1, 1)
                    if leftRow.pillStroke then leftRow.pillStroke.Color = T.Danger end
                end
            end

            local plrs = findPlayers(searchBox.Text)
            if #plrs == 0 and not hasPinnedLeft then
                local e = Instance.new("TextLabel")
                e.Size = UDim2.new(1, 0, 0, 42)
                e.BackgroundTransparency = 1
                e.Text = "No matching players — Auto-Nearest active"
                e.TextColor3 = T.Muted
                e.Font = Enum.Font.Gotham
                e.TextSize = 10
                e.ZIndex = 9
                e.Parent = plrGrp
                return
            end

            for i, p in ipairs(plrs) do
                local isSel = (selectedPlayer == p)
                local distStr = "hidden / unstreamed"
                local hpStr = "HP: —"
                pcall(function()
                    local myR = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
                    local tCF = getBestTargetCFrame(p)
                    if myR and tCF then
                        distStr = string.format("%d studs", math.floor((tCF.Position - myR.Position).Magnitude))
                    end
                    local tChar = findPlayerCharacterAnywhere(p, true)
                    local tHum = tChar and tChar:FindFirstChildOfClass("Humanoid")
                    if tHum and tHum.MaxHealth > 0 then
                        hpStr = string.format("❤️ %d%%", math.clamp(math.floor((tHum.Health / tHum.MaxHealth) * 100 + 0.5), 0, 100))
                    end
                end)

                local detInfo = DetectedScriptUsers[p.UserId]
                local isExecNow = (p == LP) or (detInfo and detInfo.isScriptUser and (tick() - (detInfo.lastSeen or 0)) < 25)
                local cpTag = ""
                if isExecNow then
                    if isConfiguredScriptOwner(p) then
                        cpTag = "  [👑 OWNER]"
                    elseif isConfiguredEliteUser(p) then
                        cpTag = "  [💎 ELITE]"
                    elseif isConfiguredCocoStaff(p) then
                        cpTag = "  [🛡️ STAFF]"
                    else
                        cpTag = (detInfo and detInfo.isFrozen) and "  [❄️ CP FROZEN]" or "  [⚡ CP USER]"
                    end
                end
                if _G.CocoTargetWhitelist and _G.CocoTargetWhitelist[p.UserId] then
                    cpTag = cpTag .. "  [🛡️ VIP]"
                end
                local rowInfo = createActionRow(
                    plrGrp,
                    i,
                    p.DisplayName .. cpTag .. (isSel and "  [LOCKED]" or ""),
                    "@" .. p.Name .. "  ·  " .. hpStr .. "  ·  " .. distStr,
                    isSel and "Locked" or "Lock",
                    function()
                        if selectedPlayer == p or (WeldIntent.typedUsername ~= "" and WeldIntent.typedUsername:lower() == p.Name:lower()) then
                            stopWeld(false)
                            StateManager:Cleanup(false, false)
                            selectedPlayer = nil
                            CurrentTarget = nil
                            LastWeldTargetUserId = nil
                            LastPresetKey = nil
                            WeldIntent.typedUsername = ""
                            WeldIntent.leftInfo = nil
                            WeldIntent.waitingForSpawn = false
                            if WeldIntent.setUsernameBoxText then pcall(WeldIntent.setUsernameBoxText, "") end
                            footerLabel.Text = "Auto: Nearest"
                            footerSub.Text = "target unlocked & disconnected"
                            syncAllActiveIndicators()
                            notify("COCO POWDER", "Unlocked & disconnected from @" .. p.Name)
                        else
                            if WeldIntent.allMode and type(_G.CocoStopAllPlayersCycle) == "function" then
                                _G.CocoStopAllPlayersCycle(true)
                            end
                            selectedPlayer = p
                            CurrentTarget = p
                            LastWeldTargetUserId = p.UserId
                            WeldIntent.target = p
                            WeldIntent.typedUsername = p.Name
                            WeldIntent.leftInfo = nil
                            WeldIntent.waitingForSpawn = false
                            if WeldIntent.setUsernameBoxText then pcall(WeldIntent.setUsernameBoxText, p.Name) end
                            footerLabel.Text = "Target: " .. p.Name
                            footerSub.Text = "locked (tap again to disconnect)"
                            hookTargetRespawn(p)
                            -- Immediately connect to the newly selected target if a weld/copy/preset is active, waiting, or previously armed!
                            local presetToConnect = (WeldIntent.active and WeldIntent.presetKey)
                                or ((AnimCopySys and AnimCopySys.active) and "animcopy")
                                or (CurrentWeld and (WeldIntent.presetKey or LastPresetKey))
                                or (WeldIntent.waitingForSpawn and (WeldIntent.presetKey or LastPresetKey))
                                or WeldIntent.presetKey
                                or LastPresetKey
                            if presetToConnect and WELD_PRESETS[presetToConnect] then
                                applyWeldPreset(presetToConnect, p)
                                syncAllActiveIndicators()
                                notify("COCO POWDER", "Locked & connected (" .. (WELD_PRESETS[presetToConnect].label or presetToConnect) .. ") -> @" .. p.Name)
                            else
                                notify("COCO POWDER", "Locked onto @" .. p.Name .. " (tap any weld preset to attach)")
                            end
                        end
                        refreshList()
                        if refreshCard then pcall(refreshCard) end
                    end,
                    function()
                        selectedPlayer = p
                        CurrentTarget = p
                        LastWeldTargetUserId = p.UserId
                        WeldIntent.target = p
                        WeldIntent.typedUsername = p.Name
                        WeldIntent.leftInfo = nil
                        WeldIntent.waitingForSpawn = false
                        if WeldIntent.setUsernameBoxText then pcall(WeldIntent.setUsernameBoxText, p.Name) end
                        task.spawn(function()
                            local _, tRef = streamAndTeleportToTarget(p, "root", 1.8, CFrame.new(3.2, 0, 0))
                            if tRef and tRef.Parent then
                                local destCF = getFlatYawCFrame(tRef.CFrame) * CFrame.new(3.2, 0, 0)
                                markIntentionalTeleport(destCF)
                                safeReturnFromVoid(LP.Character, destCF)
                                notify("COCO POWDER", "Teleported side-by-side with " .. p.Name .. "!")
                                sSuccess()
                            else
                                local fallbackCF = getBestTargetCFrame(p)
                                if fallbackCF then
                                    local destCF = getFlatYawCFrame(fallbackCF) * CFrame.new(3.2, 0, 0)
                                    markIntentionalTeleport(destCF)
                                    safeReturnFromVoid(LP.Character, destCF)
                                    notify("COCO POWDER", "Teleported side-by-side to " .. p.Name .. "!")
                                    sSuccess()
                                else
                                    applyWeldPreset("chase", p)
                                    syncAllActiveIndicators()
                                end
                            end
                        end)
                    end,
                    "TP"
                )
                if isSel then
                    BtnColors[rowInfo.pillBtn] = T.Accent2
                    rowInfo.pillBtn.BackgroundColor3 = T.Accent2
                    rowInfo.pillStroke.Color = T.Neon
                end
            end
        end

        clearTgtBtn.MouseButton1Click:Connect(function()
            playClick()
            stopWeld(false)
            StateManager:Cleanup(false, false)
            selectedPlayer = nil
            CurrentTarget = nil
            LastWeldTargetUserId = nil
            LastPresetKey = nil
            WeldIntent.typedUsername = ""
            WeldIntent.leftInfo = nil
            WeldIntent.waitingForSpawn = false
            if WeldIntent.setUsernameBoxText then pcall(WeldIntent.setUsernameBoxText, "") end
            searchBox.Text = ""
            footerLabel.Text = "Auto: Nearest"
            footerSub.Text = "auto-connects to nearest"
            syncAllActiveIndicators()
            pcall(refreshList)
            if refreshCard then pcall(refreshCard) end
            notify("COCO POWDER", "Target cleared — Auto-Nearest active")
        end)

        targetPage:GetPropertyChangedSignal("Visible"):Connect(function()
            if targetPage.Visible and targetListDirty then
                pcall(refreshList, true)
            end
        end)
        searchBox:GetPropertyChangedSignal("Text"):Connect(function() pcall(refreshList, true) end)
        pcall(refreshList, false)

        Players.PlayerAdded:Connect(function(p)
            task.wait(0.25)
            pcall(refreshList)
            local matchesSavedTarget = (LastWeldTargetUserId and p.UserId == LastWeldTargetUserId)
                or (WeldIntent.typedUsername and WeldIntent.typedUsername ~= "" and (p.Name:lower() == WeldIntent.typedUsername:lower() or p.DisplayName:lower() == WeldIntent.typedUsername:lower()))
                or (WeldIntent.leftInfo and WeldIntent.leftInfo.name and p.Name:lower() == WeldIntent.leftInfo.name:lower())

            if matchesSavedTarget and (AutoReweldEnabled or WeldIntent.waitingForSpawn) then
                selectedPlayer = p
                CurrentTarget = p
                LastWeldTargetUserId = p.UserId
                WeldIntent.typedUsername = p.Name
                if WeldIntent.setUsernameBoxText then pcall(WeldIntent.setUsernameBoxText, p.Name) end
                footerLabel.Text = "Target: " .. p.Name
                footerSub.Text = "rejoined · attaching on spawn"
                hookTargetRespawn(p)
                showOwnerScreenBanner(
                    "🎯 TARGET REJOINED SERVER",
                    "@" .. p.Name .. " (" .. (p.DisplayName or p.Name) .. ") is back — attaching on spawn!",
                    T.Success,
                    4.0,
                    "TargetLeftBanner"
                )
                notify("COCO POWDER", "Target @" .. p.Name .. " rejoined — attaching on spawn!")
                task.spawn(function()
                    local char = p.Character or p.CharacterAdded:Wait()
                    if char and p.Parent == Players then
                        if not char:FindFirstChild("HumanoidRootPart") then
                            pcall(function() char:WaitForChild("HumanoidRootPart", 3.0) end)
                        end
                        local presetToUse = WeldIntent.presetKey or (WeldIntent.leftInfo and WeldIntent.leftInfo.presetKey) or LastPresetKey or "facebang"
                        if WELD_PRESETS[presetToUse] then
                            applyWeldPreset(presetToUse, p)
                            pcall(syncAllActiveIndicators)
                            if refreshCard then pcall(refreshCard) end
                        end
                    end
                end)
            end
            if refreshCard then pcall(refreshCard) end
        end)

        Players.PlayerRemoving:Connect(function(p)
            local wasOurTarget = (WeldIntent.target == p)
                or (CurrentTarget == p)
                or (selectedPlayer == p)
                or (LastWeldTargetUserId and p.UserId == LastWeldTargetUserId)
                or (WeldIntent.typedUsername ~= "" and p.Name:lower() == WeldIntent.typedUsername:lower())

            if wasOurTarget then
                local wasWelding = (WeldIntent.active or CurrentWeld ~= nil or (AnimCopySys and AnimCopySys.active) or FlingActive)
                local savedKey = WeldIntent.presetKey or LastPresetKey or "facebang"
                local pDisp = p.DisplayName or p.Name
                local pAge  = tostring(p.AccountAge or "—") .. "d"
                WeldIntent.leftInfo = {
                    userId = p.UserId,
                    name = p.Name,
                    displayName = pDisp,
                    accountAge = pAge,
                    friendsText = "LEFT GAME",
                    leftAt = tick(),
                    wasWelded = wasWelding,
                    presetKey = savedKey,
                }
                if selectedPlayer == p then
                    selectedPlayer = nil
                end

                -- If ALL Players Auto-Cycle is active, immediately switch to the next server player in 0.00ms!
                if WeldIntent.allMode and type(_G.CocoAdvanceAllPlayersCycle) == "function" then
                    local switched = _G.CocoAdvanceAllPlayersCycle(true, p.Name)
                    if switched then
                        notify("🔄 ALL PLAYERS MODE", "@" .. p.Name .. " left — switched to next player (0.00ms)!")
                        task.wait(0.1)
                        pcall(refreshList, true)
                        if refreshCard then pcall(refreshCard) end
                        return
                    end
                end

                LastWeldTargetUserId = p.UserId
                LastPresetKey = savedKey
                WeldIntent.typedUsername = p.Name
                if WeldIntent.setUsernameBoxText then pcall(WeldIntent.setUsernameBoxText, p.Name) end
                WeldIntent.waitingForSpawn = true
                WeldIntent.topStatusText = "target left · @" .. p.Name .. " has left"
                WeldIntent.topStatusColor = T.Danger
                WeldIntent.midStatusText = "🚨 " .. pDisp .. " (@" .. p.Name .. ") has left"
                WeldIntent.midStatusColor = T.Danger
                WeldIntent.bottomStatusText = "name kept in panel until changed · auto-attaches if they rejoin"
                WeldIntent.bottomStatusColor = T.Warning

                stopWeld(true)
                StateManager:Cleanup(true)
                footerLabel.Text = "Left: @" .. p.Name
                footerSub.Text = "player has left · kept until changed"
                footerDot.BackgroundColor3 = T.Danger
                pcall(syncAllActiveIndicators)
                showOwnerScreenBanner(
                    "🚨 TARGET HAS LEFT THE GAME",
                    "@" .. p.Name .. " (" .. pDisp .. ") left — kept in panel until changed",
                    T.Danger,
                    4.5,
                    "TargetLeftBanner"
                )
                notify("COCO POWDER", "Target @" .. p.Name .. " has left — kept in panel until changed!")
            end
            task.wait(0.1)
            pcall(refreshList, true)
            if refreshCard then pcall(refreshCard) end
        end)
    end)()

    -- ═══════════════════════════════════════════════════════════════════════════
    -- CATEGORY 4: PERFORMANCE & MOVE (Chrono-Rewind, WalkSpeed 500, Jump & Flight)
    -- ═══════════════════════════════════════════════════════════════════════════
    ;(function()
        createSectionTitle(movePage, 1, "Chrono-Rewind System (60Hz Precision)")
        local rewGrp = createGroupCard(movePage, 2)

        local rewRowInfo
        rewRowInfo = createActionRow(rewGrp, 1, "Rewind Time Now [Key: R]", "Scrubs CFrame, velocity, camera & animations in reverse", "Rewind", function()
            RewindSys:Start(RewindSys.duration)
        end, function(cBtn)
            RewindSys.duration = (RewindSys.duration == 6.0 and 8.0) or (RewindSys.duration == 8.0 and 10.0) or 6.0
            cBtn.Text = tostring(math.floor(RewindSys.duration)) .. "s"
            notify("COCO POWDER", "Rewind window: " .. tostring(RewindSys.duration) .. "s (60Hz)")
        end, tostring(math.floor(RewindSys.duration)) .. "s")

        createSwitchRow(rewGrp, 2, "Smooth reverse replay", "Disable for instant 1-frame snapback teleport", not RewindSys.instantMode, function(st)
            RewindSys.instantMode = not st
        end)

        createSwitchRow(rewGrp, 3, "Rewind camera angles", "Restores exact look trajectory during rewind", RewindSys.rewindCamera, function(st)
            RewindSys.rewindCamera = st
        end)

        local rewSpdList = { 1.0, 2.0, 3.5 }
        local rewSpdIdx = 1
        createActionRow(rewGrp, 4, "Rewind Scrub Speed", "Cycle reverse replay speed (1.0x, 2.0x, 3.5x)", "1.0x", function(pillBtn)
            rewSpdIdx = (rewSpdIdx % #rewSpdList) + 1
            RewindSys.speedMultiplier = rewSpdList[rewSpdIdx]
            pillBtn.Text = string.format("%.1fx", RewindSys.speedMultiplier)
            notify("⏪ REWIND SPEED", string.format("Reverse scrub speed set to %.1fx", RewindSys.speedMultiplier))
        end, function()
            toggleFloatingPill("rewind")
        end, ActivePills["rewind"] and "✓" or "⦿")

        createSwitchRow(rewGrp, 5, "Chrono-Echo Ghost Trail & FX", "Spawns holographic afterimages & time-warp screen tint", RewindSys.vfxEnabled, function(st)
            RewindSys.vfxEnabled = st
        end)


        createSectionTitle(movePage, 3, "WalkSpeed & Physics (Up to 500)")
        local spdGrp = createGroupCard(movePage, 4)

        local currentSpeed, currentJump = 32, 75
        local function getMoveCharacter()
            local ch = LP.Character
            if not ch then return nil, nil, nil end
            return ch, ch:FindFirstChildOfClass("Humanoid"), ch:FindFirstChild("HumanoidRootPart")
        end
        ;(function() -- Sub-scope for WalkSpeed, Jump, Noclip, Spider-Walk, Air-Walk & Phase Dash
        local defaultWalkSpeed, defaultJumpPower = 16, 50
        local MIN_SPEED, MAX_SPEED = 16, 500
        local MAX_JUMP, JUMP_STEP = 350, 25

        local speedSwitchRef
        local speedPresetRow
        local function applySpeedValue(val)
            currentSpeed = math.clamp(math.floor(val), MIN_SPEED, MAX_SPEED)
            local _, hum = getMoveCharacter()
            if hum and moveState.speed then hum.WalkSpeed = currentSpeed end
            if speedSwitchRef and speedSwitchRef.subLbl then
                speedSwitchRef.subLbl.Text = "Locks WalkSpeed at " .. tostring(currentSpeed) .. " studs/sec"
            end
            if speedPresetRow and speedPresetRow.pillBtn then
                speedPresetRow.pillBtn.Text = tostring(currentSpeed)
            end
        end

        local function setSpeedOverrideEnabled(st, syncSwitch)
            local _, hum = getMoveCharacter()
            moveState.speed = (st == true)
            if hum then hum.WalkSpeed = moveState.speed and currentSpeed or defaultWalkSpeed end
            if moveState.speed then
                if moveState.speedLoopConn then moveState.speedLoopConn:Disconnect() end
                moveState.speedLoopConn = RunService.Heartbeat:Connect(function()
                    if not moveState.speed then return end
                    local _, h = getMoveCharacter()
                    if h and h.WalkSpeed ~= currentSpeed then h.WalkSpeed = currentSpeed end
                end)
            else
                if moveState.speedLoopConn then
                    moveState.speedLoopConn:Disconnect()
                    moveState.speedLoopConn = nil
                end
            end
            if syncSwitch and speedSwitchRef and speedSwitchRef.setState then
                pcall(speedSwitchRef.setState, moveState.speed)
            end
            if syncAllActiveIndicators then pcall(syncAllActiveIndicators) end
        end

        moveState.toggleSpeed = function()
            setSpeedOverrideEnabled(not moveState.speed, true)
            notify("⚡ SPEED", moveState.speed and ("WalkSpeed ON (" .. tostring(currentSpeed) .. " st/s)") or "WalkSpeed OFF (16 st/s)")
        end

        speedSwitchRef = createSwitchRow(spdGrp, 1, "WalkSpeed override", "Locks WalkSpeed at 32 studs/sec", moveState.speed, function(st)
            setSpeedOverrideEnabled(st, false)
        end)

        local speedPinRow = createActionRow(spdGrp, 1, "Speed Quick Pill (Pin Out)", "Tap [Open] to toggle Speed · Tap [⦿] to pop out small floating button", "Open", function()
            togglePresetOrAction("speed")
        end, function()
            toggleFloatingPill("speed")
        end, (ActivePills and ActivePills["speed"]) and "✓" or "⦿")
        if speedPinRow then
            speedPinRow.defaultLabel = "Open"
            presetActionRows["speed"] = speedPinRow
            if updatePinBadgeVisual then updatePinBadgeVisual("speed") end
        end

        local spdCycle = { 16, 32, 60, 120, 250, 500 }
        local spdIdx = 2
        speedPresetRow = createActionRow(spdGrp, 2, "Speed Preset & Step", "Tap pill to cycle preset · Tap + to add 25", "32", function()
            spdIdx = (spdIdx % #spdCycle) + 1
            applySpeedValue(spdCycle[spdIdx])
            notify("Speed", "WalkSpeed set to " .. tostring(currentSpeed))
        end, function()
            applySpeedValue(currentSpeed + 25 > 500 and 16 or currentSpeed + 25)
        end, "+")

        local jumpSwitchRef
        jumpSwitchRef = createSwitchRow(spdGrp, 3, "JumpPower boost", "Enhances jump height (" .. tostring(currentJump) .. " power)", moveState.jump, function(st)
            local _, hum = getMoveCharacter()
            moveState.jump = st
            if hum then
                hum.UseJumpPower = true
                hum.JumpPower = st and currentJump or defaultJumpPower
            end
        end)

        createActionRow(spdGrp, 4, "Adjust JumpPower", "Increments JumpPower by +25 up to 350", "+25", function(pillBtn)
            currentJump = (currentJump + JUMP_STEP > MAX_JUMP) and 50 or (currentJump + JUMP_STEP)
            local _, hum = getMoveCharacter()
            if hum then hum.UseJumpPower = true; if moveState.jump then hum.JumpPower = currentJump end end
            pillBtn.Text = tostring(currentJump)
            if jumpSwitchRef and jumpSwitchRef.subLbl then
                jumpSwitchRef.subLbl.Text = "Enhances jump height (" .. tostring(currentJump) .. " power)"
            end
        end)

        createSwitchRow(spdGrp, 5, "Infinite air jump", "Jump repeatedly in mid-air without ground contact", moveState.infiniteJump, function(st)
            moveState.infiniteJump = st
            if st then
                if moveState.jumpConn then moveState.jumpConn:Disconnect() end
                moveState.jumpConn = UIS.JumpRequest:Connect(function()
                    if not moveState.infiniteJump or moveState.fly or moveState.flyLanding then return end
                    local _, hum, root = getMoveCharacter()
                    if hum and hum.Health > 0 and root then
                        root.AssemblyLinearVelocity = Vector3.new(root.AssemblyLinearVelocity.X, math.max(currentJump, 52), root.AssemblyLinearVelocity.Z)
                        hum:ChangeState(Enum.HumanoidStateType.Jumping)
                    end
                end)
            elseif moveState.jumpConn then
                moveState.jumpConn:Disconnect(); moveState.jumpConn = nil
            end
        end)

        createSwitchRow(spdGrp, 6, "Noclip phase", "Walk effortlessly through walls, doors & obstacles", moveState.noclip, function(st)
            moveState.noclip = st
            if st then
                local noclipChar = nil
                local noclipParts = {}
                local function cacheNoclipChar(c)
                    noclipChar = c
                    table.clear(noclipParts)
                    if not c then return end
                    for _, p in ipairs(c:GetDescendants()) do
                        if p:IsA("BasePart") then
                            p.CanCollide = false
                            noclipParts[#noclipParts + 1] = p
                        end
                    end
                end
                cacheNoclipChar(LP.Character)
                if moveState.noclipConn then moveState.noclipConn:Disconnect() end
                moveState.noclipConn = RunService.Stepped:Connect(function()
                    if not moveState.noclip then return end
                    local c = LP.Character
                    if c ~= noclipChar then cacheNoclipChar(c) end
                    for i = 1, #noclipParts do
                        local p = noclipParts[i]
                        if p and p.Parent and p.CanCollide then
                            p.CanCollide = false
                        end
                    end
                end)
            else
                if moveState.noclipConn then
                    moveState.noclipConn:Disconnect()
                    moveState.noclipConn = nil
                end
                local ch = LP.Character
                if ch then
                    for _, p in ipairs(ch:GetDescendants()) do
                        if p:IsA("BasePart") and (p.Name == "HumanoidRootPart" or p.Name == "Torso" or p.Name == "UpperTorso" or p.Name == "LowerTorso" or p.Name == "Head") then
                            p.CanCollide = true
                        end
                    end
                end
            end
        end)

        -- Spider-Walk / Wall-Climb Mode (Raycast surface-normal wall climbing without full flight)
        createSwitchRow(spdGrp, 7, "Spider-Walk (Wall Climb)", "Walk straight up walls, cliffs & buildings automatically", moveState.spiderWalk, function(st)
            moveState.spiderWalk = st
            if st then
                if moveState.spiderConn then moveState.spiderConn:Disconnect() end
                local climbParams = RaycastParams.new()
                climbParams.FilterType = Enum.RaycastFilterType.Exclude
                climbParams.RespectCanCollide = true
                moveState.spiderConn = RunService.Heartbeat:Connect(function()
                    if not moveState.spiderWalk or moveState.fly or WeldIntent.active then return end
                    local ch, hum, root = getMoveCharacter()
                    if not ch or not hum or not root or hum.Health <= 0 then return end
                    climbParams.FilterDescendantsInstances = { ch, workspace.CurrentCamera }
                    local moveDir = hum.MoveDirection
                    local probeDir = (moveDir.Magnitude > 0.1) and moveDir.Unit or Vector3.new(root.CFrame.LookVector.X, 0, root.CFrame.LookVector.Z)
                    if probeDir.Magnitude < 0.05 then return end
                    probeDir = probeDir.Unit
                    local hit = workspace:Raycast(root.Position, probeDir * 3.6, climbParams)
                        or workspace:Raycast(root.Position - Vector3.new(0, 1.2, 0), probeDir * 3.6, climbParams)
                    if hit and hit.Instance and hit.Normal.Y < 0.55 and moveDir.Magnitude > 0.05 then
                        local climbSpd = math.max(36, currentSpeed * 0.85)
                        root.AssemblyLinearVelocity = Vector3.new(
                            probeDir.X * 14,
                            climbSpd,
                            probeDir.Z * 14
                        )
                    end
                end)
                notify("🕷️ SPIDER-WALK", "Wall-Climb enabled! Walk into any wall or building to climb.")
                sToggleOn()
            else
                if moveState.spiderConn then moveState.spiderConn:Disconnect(); moveState.spiderConn = nil end
                notify("🕷️ SPIDER-WALK", "Wall-Climb disabled")
                sToggleOff()
            end
        end)

        -- Air-Walk / Invisible Sky Platform (Walk & Emote in mid-air at any altitude; Space = Up, Ctrl/C = Down)
        createSwitchRow(spdGrp, 8, "Air-Walk (Sky Platform)", "Walk on air at current altitude (Space = +Up, Ctrl = -Down)", moveState.airWalk, function(st)
            moveState.airWalk = st
