            local tLine2 = makeTeleLine(2, 24, T.Text, false)
            local tLine3 = makeTeleLine(3, 42, T.Muted, false)
            local tLine4 = makeTeleLine(4, 60, Color3.fromRGB(56, 224, 255), false)

            local function updateTelemetryCardNow()
                if not teleBox or not teleBox.Parent then return end
                local info = OwnerAdminState.collectTargetTelemetry()
                if info then
                    tLine1.Text = info.line1
                    tLine2.Text = info.line2
                    tLine3.Text = info.line3
                    tLine4.Text = info.line4
                end
            end
            updateTelemetryCardNow()

            createActionRow(
                teleGrp,
                3,
                "Copy Telemetry Dossier / Teleport to Inspected Player (NEW)",
                "Tap [Copy Info] to copy full telemetry report · Tap [⚡] to teleport to inspected player",
                "Copy Info",
                function(pillBtn)
                    local info = OwnerAdminState.collectTargetTelemetry()
                    if not info then return end
                    local report = table.concat({ info.line1, info.line2, info.line3, info.line4 }, "\n")
                    pcall(function()
                        if typeof(setclipboard) == "function" then setclipboard(report)
                        elseif typeof(toclipboard) == "function" then toclipboard(report) end
                    end)
                    pillBtn.Text = "Copied!"
                    notify("📊 TELEMETRY COPIED", "Copied telemetry dossier for @" .. info.player.Name .. " to clipboard!")
                    sSuccess()
                    task.delay(1.5, function()
                        if pillBtn and pillBtn.Parent then pillBtn.Text = "Copy Info" end
                    end)
                end,
                function()
                    local inspected = OwnerAdminState.telemetryTargetPlr or resolveActiveTarget()
                    if not inspected or inspected == LP then
                        notify("📊 TELEMETRY TP", "Select another player with [Next Player] first!")
                        return
                    end
                    task.spawn(function()
                        streamAndTeleportToTarget(inspected, "torso", 1.8, CFrame.new(0, 1.5, 3))
                        notify("⚡ TELEPORTED", "Teleported to inspected player @" .. inspected.Name .. "!")
                        sWhoosh()
                    end)
                end,
                "⚡"
            )

            createActionRow(
                teleGrp,
                2,
                "Cycle Inspected Player / Refresh Telemetry",
                "Tap [Next Player] to inspect next player in server · Tap [🎯] to lock inspected player",
                "Next Player",
                function()
                    local list = Players:GetPlayers()
                    if #list == 0 then return end
                    local cur = OwnerAdminState.telemetryTargetPlr or resolveActiveTarget() or LP
                    local nextIdx = 1
                    for i, p in ipairs(list) do
                        if p == cur then
                            nextIdx = (i % #list) + 1
                            break
                        end
                    end
                    OwnerAdminState.telemetryTargetPlr = list[nextIdx]
                    updateTelemetryCardNow()
                    notify("📊 TELEMETRY", "Inspecting @" .. OwnerAdminState.telemetryTargetPlr.Name)
                end,
                function()
