        local adminPlrGrp = createGroupCard(adminPage, 25)
        adminPlrGrp:SetAttribute("DynamicList", true)
        local adminListDirty = true

        local function refreshAdminPlayerList(forceRebuild)
            syncAdminTabVisibility()
            local q = (adminSearchBox and adminSearchBox.Text or ""):lower():gsub("^%s+", ""):gsub("%s+$", "")
            local others = {}
            local scriptUserCount = 0
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LP then
                    local det = DetectedScriptUsers[p.UserId]
                    local isUser = (det and det.isScriptUser and (tick() - (det.lastSeen or 0)) < 25.0)
                    if isUser then scriptUserCount = scriptUserCount + 1 end
                    local isFrz = OwnerAdminState.ownerFrozenTargets[p.UserId] or (det and det.isFrozen) or false
                    local isBan = OwnerAdminState.ownerBannedTargets[p.UserId] or false
                    local matchQ = (q == "")
                        or p.Name:lower():find(q, 1, true)
                        or p.DisplayName:lower():find(q, 1, true)
                        or (q == "user" and isUser)
                        or (q == "frozen" and isFrz)
                        or (q == "banned" and isBan)
                    if matchQ then
                        table.insert(others, { player = p, isUser = isUser, det = det })
                    end
                end
            end

            if UI.catCountLabels["Admin Panel"] then
                UI.catCountLabels["Admin Panel"].Text = tostring(scriptUserCount)
            end
            if heroStatsLbl and heroStatsLbl.Parent then
                local frzCnt, banCnt = 0, 0
                for _, _ in pairs(OwnerAdminState.ownerFrozenTargets or {}) do frzCnt = frzCnt + 1 end
                for _, _ in pairs(OwnerAdminState.ownerBannedTargets or {}) do banCnt = banCnt + 1 end
                heroStatsLbl.Text = string.format("● %d Script Users Online  ·  %d Frozen  ·  %d Blocked  ·  %d Total Players", scriptUserCount, frzCnt, banCnt, #Players:GetPlayers())
            end

            if not forceRebuild and not adminPage.Visible then
                adminListDirty = true
                return
            end
            adminListDirty = false

            for _, c in ipairs(adminPlrGrp:GetChildren()) do
                if c:IsA("Frame") or c:IsA("TextLabel") then c:Destroy() end
            end

            table.sort(others, function(a, b)
                if a.isUser ~= b.isUser then
                    return a.isUser and not b.isUser
                end
                return a.player.Name:lower() < b.player.Name:lower()
            end)

            if #others == 0 then
                local emptyLbl = Instance.new("TextLabel")
                emptyLbl.Size = UDim2.new(1, 0, 0, 44)
                emptyLbl.BackgroundTransparency = 1
                emptyLbl.Text = "No other players in server yet — waiting for players..."
                emptyLbl.TextColor3 = T.Muted
                emptyLbl.Font = Enum.Font.Gotham
                emptyLbl.TextSize = 10
                emptyLbl.ZIndex = 9
                emptyLbl.Parent = adminPlrGrp
                return
            end

            for idx, item in ipairs(others) do
                local p = item.player
                local uid = p.UserId
                local pIsOwner = isConfiguredScriptOwner(p)
                local pIsElite = not pIsOwner and isConfiguredEliteUser(p)
                local pIsStaff = not pIsOwner and not pIsElite and isConfiguredCocoStaff(p)
                local isFrozen = OwnerAdminState.ownerFrozenTargets[uid] or (item.det and item.det.isFrozen) or false
                local isBanned = OwnerAdminState.ownerBannedTargets[uid] or false
                local isVanished = (moveState and moveState.Vanish and moveState.Vanish.vanishedTargets and moveState.Vanish.vanishedTargets[uid] ~= nil) or false
                local lpIsStaffOnly = isCocoStaff(LP) and not hasAdminAccess(LP)

                local ownerOpen = pIsOwner and OwnerAdminState.isOwnerImmunityActive and (not OwnerAdminState.isOwnerImmunityActive(p))
                local statusBadge = (item.isUser and pIsOwner) and (ownerOpen and " [👑 OWNER · OPEN]" or " [👑 OWNER]")
                    or ((item.isUser and pIsElite) and " [💎 ELITE USER]")
                    or ((item.isUser and pIsStaff) and " [🛡️ COCO STAFF]")
                    or (item.isUser and " [⚡ SCRIPT USER]" or (pIsOwner and " [👑 OWNER]" or (pIsElite and " [💎 ELITE]" or (pIsStaff and " [🛡️ STAFF]" or " [Server Player]"))))
                if isBanned then
                    statusBadge = " [🚫 BLOCKED]"
                elseif isFrozen then
                    statusBadge = " [❄️ FROZEN]"
                elseif isVanished then
                    statusBadge = " [👻 VANISHED]"
                end

                local rowSubDesc = lpIsStaffOnly
                    and ("@" .. p.Name .. " · [🚫 Block / ✓ Unblock Script Access]")
                    or ("@" .. p.Name .. " · [Freeze] [💬 Say] [👻 Vanish] [💎 Elite] [🚫 Block]")
                -- Build Admin Player Row (Staff sees Block button ONLY; Owner/Elite sees all 5 actions)
                local row, tLbl, sLbl = createGroupRowBase(
                    adminPlrGrp,
                    idx,
                    p.DisplayName .. statusBadge,
                    rowSubDesc,
                    lpIsStaffOnly and 44 or 190,
                    48
                )

                -- 1. Freeze / Unfreeze Pill Button
                local pillBtn = Instance.new("TextButton")
                pillBtn.Name = "ActionFreezePill"
                pillBtn.Size = UDim2.new(0, 58, 0, 26)
                pillBtn.Position = UDim2.new(1, -182, 0.5, -13)
                pillBtn.BackgroundColor3 = isFrozen and Color3.fromRGB(30, 130, 190) or T.BG2
                pillBtn.BorderSizePixel = 0
                pillBtn.Text = isFrozen and "Unfreeze" or "Freeze"
                pillBtn.TextColor3 = T.Text
                pillBtn.Font = Enum.Font.GothamBold
                pillBtn.TextSize = 10
                pillBtn.AutoButtonColor = false
                pillBtn.ZIndex = 9
                pillBtn.Visible = not lpIsStaffOnly
                pillBtn.Parent = row
                Instance.new("UICorner", pillBtn).CornerRadius = UDim.new(1, 0)
                local pStroke = Instance.new("UIStroke", pillBtn)
                pStroke.Color = isFrozen and Color3.fromRGB(86, 204, 255) or T.Border
                pStroke.Thickness = 1.1
                pStroke.Transparency = 0.25
                styleBtn(pillBtn, pillBtn.BackgroundColor3, 0.12)

                pillBtn.MouseButton1Click:Connect(function()
                    playClick()
                    if not hasAdminAccess(LP) then
                        notify("🔒 ACCESS DENIED", "Only Owners & Elite Users can freeze script users!")
                        sError()
                        return
                    end
                    if isProtectedFromLocalPlayer(p) then
                        notify("👑 IMMUNITY", "Cannot freeze the Script Owner!")
                        sError()
                        return
                    end
                    local nextFreeze = not isFrozen
                    OwnerAdminState.ownerFrozenTargets[uid] = nextFreeze or nil
                    if nextFreeze then
                        broadcastOwnerAdminCommand(12, p, "cpfreeze")
                        notify("❄️ FROZEN USER", "Froze @" .. p.Name .. " (" .. p.DisplayName .. ")!")
                        sSuccess()
                    else
                        broadcastOwnerAdminCommand(22, p, "cpunfreeze")
                        notify("✅ UNFROZEN USER", "Unfroze @" .. p.Name .. " (" .. p.DisplayName .. ")!")
                        sSuccess()
                    end
                    pcall(updateOverheadNameTags)
                    pcall(refreshAdminPlayerList)
                end)

                -- 2. Chat Control Circle Button (💬)
                local chatBtn = Instance.new("TextButton")
                chatBtn.Name = "ActionChatBtn"
                chatBtn.Size = UDim2.new(0, 26, 0, 26)
                chatBtn.Position = UDim2.new(1, -118, 0.5, -13)
                chatBtn.BackgroundColor3 = T.BG2
                chatBtn.BorderSizePixel = 0
                chatBtn.Text = "💬"
                chatBtn.TextColor3 = T.Text
                chatBtn.Font = Enum.Font.GothamBold
                chatBtn.TextSize = 11
                chatBtn.AutoButtonColor = false
                chatBtn.ZIndex = 9
                chatBtn.Visible = not lpIsStaffOnly
                chatBtn.Parent = row
                Instance.new("UICorner", chatBtn).CornerRadius = UDim.new(1, 0)
                local cbStroke = Instance.new("UIStroke", chatBtn)
                cbStroke.Color = T.Border
                cbStroke.Thickness = 1.1
                cbStroke.Transparency = 0.25
                styleBtn(chatBtn, T.BG2, 0.12)

                chatBtn.MouseButton1Click:Connect(function()
                    playClick()
                    if not hasAdminAccess(LP) then
                        notify("🔒 ACCESS DENIED", "Only Owners & Elite Users can use Chat Control!")
                        sError()
                        return
                    end
                    if isProtectedFromLocalPlayer(p) then
                        notify("👑 IMMUNITY", "Cannot control the Script Owner's chat!")
                        sError()
                        return
                    end
                    local msg = OwnerAdminState.lastForcedChatMessage or (forcedMsgBox and forcedMsgBox.Text) or "Coco Powder on top! ⚡"
                    OwnerAdminState.broadcastOwnerChatCommand(p, msg)
                end)

                -- 3. Vanish Player Circle Button (👻)
                local vanishBtn = Instance.new("TextButton")
                vanishBtn.Name = "ActionVanishBtn"
                vanishBtn.Size = UDim2.new(0, 26, 0, 26)
                vanishBtn.Position = UDim2.new(1, -88, 0.5, -13)
                vanishBtn.BackgroundColor3 = isVanished and T.Accent or T.BG2
                vanishBtn.BorderSizePixel = 0
                vanishBtn.Text = "👻"
                vanishBtn.TextColor3 = T.Text
                vanishBtn.Font = Enum.Font.GothamBold
                vanishBtn.TextSize = 11
                vanishBtn.AutoButtonColor = false
                vanishBtn.ZIndex = 9
                vanishBtn.Visible = not lpIsStaffOnly
                vanishBtn.Parent = row
                Instance.new("UICorner", vanishBtn).CornerRadius = UDim.new(1, 0)
                local vbStroke = Instance.new("UIStroke", vanishBtn)
                vbStroke.Color = isVanished and T.Neon or T.Border
                vbStroke.Thickness = 1.1
                vbStroke.Transparency = 0.25
                styleBtn(vanishBtn, vanishBtn.BackgroundColor3, 0.12)

                vanishBtn.MouseButton1Click:Connect(function()
                    playClick()
                    if not hasAdminAccess(LP) then
                        notify("🔒 ACCESS DENIED", "Only Owners & Elite Users can vanish players!")
                        sError()
                        return
                    end
                    if isProtectedFromLocalPlayer(p) then
                        notify("👑 IMMUNITY", "Cannot vanish the Script Owner!")
                        sError()
                        return
                    end
                    if moveState and moveState.Vanish then
                        moveState.Vanish:ToggleTargetVanish(p)
                        pcall(refreshAdminPlayerList)
                    end
                end)

                -- 4. Grant / Revoke Session Elite User Circle Button (💎 - Owner Only)
                local hasSessionElite = OwnerAdminState.sessionPremiumUsers[uid] == true
                local premBtn = Instance.new("TextButton")
                premBtn.Name = "ActionPremBtn"
                premBtn.Size = UDim2.new(0, 26, 0, 26)
                premBtn.Position = UDim2.new(1, -58, 0.5, -13)
                premBtn.BackgroundColor3 = (pIsElite or hasSessionElite) and Color3.fromRGB(20, 110, 145) or T.BG2
                premBtn.BorderSizePixel = 0
                premBtn.Text = "💎"
                premBtn.TextColor3 = T.Text
                premBtn.Font = Enum.Font.GothamBold
                premBtn.TextSize = 11
                premBtn.AutoButtonColor = false
                premBtn.ZIndex = 9
                premBtn.Visible = not lpIsStaffOnly
                premBtn.Parent = row
                Instance.new("UICorner", premBtn).CornerRadius = UDim.new(1, 0)
                local pbStroke = Instance.new("UIStroke", premBtn)
                pbStroke.Color = (pIsElite or hasSessionElite) and Color3.fromRGB(56, 224, 255) or T.Border
                pbStroke.Thickness = 1.1
                pbStroke.Transparency = 0.25
                styleBtn(premBtn, premBtn.BackgroundColor3, 0.12)

                premBtn.MouseButton1Click:Connect(function()
                    playClick()
                    notify("🔒 HARDCODED ROLES ONLY", "Elite Users are strictly locked to the ELITE_USERS allowlist in the script!")
                    sError()
                end)

                -- 4. Script Ban Circle Button (🚫 / ✓)
                local banBtn = Instance.new("TextButton")
                banBtn.Name = "ActionBanBtn"
                banBtn.Size = UDim2.new(0, 26, 0, 26)
                banBtn.Position = UDim2.new(1, -26, 0.5, -13)
                banBtn.BackgroundColor3 = isBanned and T.Danger or T.BG2
                banBtn.BorderSizePixel = 0
                banBtn.Text = isBanned and "✓" or "🚫"
                banBtn.TextColor3 = T.Text
                banBtn.Font = Enum.Font.GothamBold
                banBtn.TextSize = 11
                banBtn.AutoButtonColor = false
                banBtn.ZIndex = 9
                banBtn.Parent = row
                Instance.new("UICorner", banBtn).CornerRadius = UDim.new(1, 0)
                local bbStroke = Instance.new("UIStroke", banBtn)
                bbStroke.Color = isBanned and T.Danger or T.Border
                bbStroke.Thickness = 1.1
                bbStroke.Transparency = 0.25
                styleBtn(banBtn, banBtn.BackgroundColor3, 0.12)

                local canBlkRow = canBlockTarget(LP, p)
                if not canBlkRow then
                    banBtn.BackgroundColor3 = Color3.fromRGB(28, 28, 34)
                    banBtn.Text = "🔒"
                    banBtn.TextColor3 = T.Muted
                end

                banBtn.MouseButton1Click:Connect(function()
                    playClick()
                    if not hasStaffBlockAccess(LP) then
                        notify("🔒 ACCESS DENIED", "Only Owners, Elite Users & Coco Staff can block script users!")
                        sError()
                        return
                    end
                    local okBlk, blkReason = canBlockTarget(LP, p)
                    if not okBlk then
                        notify("🛡️ HIERARCHY PROTECTED", blkReason or "You cannot block this player!")
                        sError()
                        return
                    end
                    local nextBan = not isBanned
                    OwnerAdminState.ownerBannedTargets[uid] = nextBan or nil
                    if nextBan then
                        broadcastOwnerAdminCommand(32, p, "cpblock")
                        notify("🚫 SCRIPT BLOCKED", "Blocked @" .. p.Name .. " from using Coco Powder!")
                        sError()
                    else
                        broadcastOwnerAdminCommand(42, p, "cpunblock")
                        notify("✅ SCRIPT UNBLOCKED", "Unblocked @" .. p.Name .. "!")
                        sSuccess()
                    end
                    pcall(updateOverheadNameTags)
                    pcall(refreshAdminPlayerList)
                end)

                if pIsOwner then
                    tLbl.TextColor3 = Color3.fromRGB(255, 215, 70)
                elseif pIsElite then
                    tLbl.TextColor3 = Color3.fromRGB(251, 113, 133)
                elseif pIsStaff then
                    tLbl.TextColor3 = Color3.fromRGB(192, 132, 252)
                elseif item.isUser then
                    tLbl.TextColor3 = Color3.fromRGB(185, 192, 204)
                end
            end
        end

        OwnerAdminState.refreshAdminUIFn = function()
            pcall(refreshAdminPlayerList)
            if refreshList then pcall(refreshList) end
        end

        adminSearchBox:GetPropertyChangedSignal("Text"):Connect(function()
            pcall(refreshAdminPlayerList, true)
        end)
        freezeNonFriendsBtn.MouseButton1Click:Connect(function()
            playClick()
            if not hasAdminAccess(LP) then
                notify("🔒 ACCESS DENIED", "Only Owners & Elite Users can freeze script users!")
                sError()
                return
            end
            local targetsToFreeze = {}
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= LP and not isProtectedFromLocalPlayer(p) then
                    local okFr, isFr = pcall(function() return LP:IsFriendsWith(p.UserId) end)
                    if not (okFr and isFr) and not (_G.CocoTargetWhitelist and _G.CocoTargetWhitelist[p.UserId]) then
                        OwnerAdminState.ownerFrozenTargets[p.UserId] = true
                        table.insert(targetsToFreeze, p)
                    end
                end
            end
            local count = #targetsToFreeze
            if count > 0 then
                task.spawn(function()
                    for idx, p in ipairs(targetsToFreeze) do
                        if p and p.Parent == Players then
                            broadcastOwnerAdminCommand(12, p, "cpfreeze")
                            if idx < count then task.wait(1.0) end
                        end
                    end
                end)
            end
            pcall(updateOverheadNameTags)
            pcall(refreshAdminPlayerList, true)
            notify("❄️ FREEZE NON-FRIENDS", "Froze " .. tostring(count) .. " non-friend player(s) in server!")
            sSuccess()
        end)
        adminPage:GetPropertyChangedSignal("Visible"):Connect(function()
            if adminPage.Visible and adminListDirty then
                pcall(refreshAdminPlayerList, true)
            end
        end)
        if freezeNonFriendsBtn then table.insert(staffHiddenElements, freezeNonFriendsBtn) end
        applyStaffPanelRestrictions()
        pcall(refreshAdminPlayerList, false)
        Players.PlayerAdded:Connect(function()
            task.wait(0.6)
            pcall(refreshAdminPlayerList)
        end)
        Players.PlayerRemoving:Connect(function(remPlr)
            if remPlr then
                local rUid = remPlr.UserId
                OwnerAdminState.ownerFrozenTargets[rUid] = nil
                DetectedScriptUsers[rUid] = nil
                if moveState and moveState.Vanish and moveState.Vanish.vanishedTargets then
                    moveState.Vanish.vanishedTargets[rUid] = nil
                end
                pcall(removeOverheadTagForUser, rUid)
            end
            task.wait(0.15)
            pcall(refreshAdminPlayerList)
        end)
    end)()

