            emoHeaderBtn.TextColor3 = T.Text
            emoHeaderBtn.Font = Enum.Font.GothamBold
            emoHeaderBtn.TextSize = 10
            emoHeaderBtn.TextXAlignment = Enum.TextXAlignment.Left
