            statSymLbl.TextXAlignment = Enum.TextXAlignment.Center
            statSymLbl.ZIndex = 10
            statSymLbl.Parent = statsRow

            onSpamSendUpdate = function(ok)
                if ok then
                    statCntLbl.Text = "Sent: " .. tostring(csCnt)
                    statMtdLbl.Text = "Method: " .. tostring(csMtd)
                    statSymLbl.Text = "Set: " .. tostring(csSym)
                    cocoSpam3StatusLbl.Text = "Status: RUNNING · " .. tostring(csMtd) .. " (" .. string.upper(csMode) .. ")"
                    cocoSpam3StatusLbl.TextColor3 = T.Success
                else
                    cocoSpam3StatusLbl.Text = "Status: FAILED TO SEND"
                    cocoSpam3StatusLbl.TextColor3 = T.Danger
                end
            end

            local function resetCocoSpam3Visual()
                startCocoSpam3Btn.BackgroundColor3 = T.Accent2
                stopCocoSpam3Btn.BackgroundColor3 = T.PanelLt
                stopCocoSpam3Btn.TextColor3 = T.Muted
                cocoSpam3StatusLbl.Text = "Status: IDLE"
                cocoSpam3StatusLbl.TextColor3 = T.Muted
            end

            startCocoSpam3Btn.MouseButton1Click:Connect(function()
                stop()
                local typedTgt = jTargetInput.Text
                local activeTgtPlr = (type(resolveActiveTarget) == "function") and resolveActiveTarget() or nil
                if typedTgt == "" and activeTgtPlr then
                    _G.CocoChatSpam.setPlayer(activeTgtPlr)
                    typedTgt = activeTgtPlr.DisplayName or activeTgtPlr.Name
                    jTargetInput.Text = typedTgt
                elseif activeTgtPlr and (typedTgt == activeTgtPlr.DisplayName or typedTgt == activeTgtPlr.Name) then
                    _G.CocoChatSpam.setPlayer(activeTgtPlr)
                else
                    sel = nil; selDisplay = nil; selName = nil
                end
                local d = math.max(0.5, tonumber(jDelayInput.Text) or 5)
                local okStart, errMsg = start({
                    mode    = csMode,
                    target  = typedTgt,
                    message = jMsgInput.Text,
                    sym     = csSym,
                    emoji   = csEmoji,
                    delay   = d,
                })
                if not okStart then
                    resetCocoSpam3Visual()
                    cocoSpam3StatusLbl.Text = "Status: " .. tostring(errMsg or "Enter target/message!")
                    cocoSpam3StatusLbl.TextColor3 = T.Danger
                    return
                end
                startCocoSpam3Btn.BackgroundColor3 = T.Success
                stopCocoSpam3Btn.BackgroundColor3 = T.Danger
                stopCocoSpam3Btn.TextColor3 = Color3.fromRGB(255, 255, 255)
                statSymLbl.Text = "Set: " .. tostring(csSym)
                cocoSpam3StatusLbl.Text = string.format("Status: SPAMMING (%s · %.1fs)", string.upper(csMode), d)
                cocoSpam3StatusLbl.TextColor3 = T.Success
            end)

            stopCocoSpam3Btn.MouseButton1Click:Connect(function()
                stop()
                resetCocoSpam3Visual()
            end)

            cocoSpam3StopFn = function()
                stop()
                resetCocoSpam3Visual()
            end

            -- Auto-fill active Target Player name directly into both Chat Spam target boxes
            local chatTargetSyncAlive = true
            local lastSyncedPlr = nil
            local lastSyncedTyped = ""
            local function syncTargetNameIntoChatBoxes()
                local tgtPlr = (type(resolveActiveTarget) == "function" and resolveActiveTarget())
                    or selectedPlayer or CurrentTarget or (WeldIntent and WeldIntent.target)
                if tgtPlr and tgtPlr:IsA("Player") then
                    if tgtPlr ~= lastSyncedPlr then
                        lastSyncedPlr = tgtPlr
                        local nameToFill = (tgtPlr.DisplayName and tgtPlr.DisplayName ~= "" and tgtPlr.DisplayName) or tgtPlr.Name
                        if targetInput and targetInput.Parent and not targetInput:IsFocused() then
                            targetInput.Text = nameToFill
                        end
                        if jTargetInput and jTargetInput.Parent and not jTargetInput:IsFocused() then
                            jTargetInput.Text = nameToFill
                        end
                        _G.CocoChatSpam.setPlayer(tgtPlr)
                    end
                elseif WeldIntent and WeldIntent.typedUsername and WeldIntent.typedUsername ~= "" and WeldIntent.typedUsername ~= lastSyncedTyped then
                    lastSyncedTyped = WeldIntent.typedUsername
                    if targetInput and targetInput.Parent and not targetInput:IsFocused() then
                        targetInput.Text = lastSyncedTyped
                    end
                    if jTargetInput and jTargetInput.Parent and not jTargetInput:IsFocused() then
                        jTargetInput.Text = lastSyncedTyped
                    end
                end
            end
            task.spawn(function()
                while chatTargetSyncAlive and gui and gui.Parent do
                    pcall(syncTargetNameIntoChatBoxes)
                    task.wait(0.35)
                end
            end)
            local prevStop = cocoSpam3StopFn
            cocoSpam3StopFn = function()
                if prevStop then prevStop() end
            end
            gui.Destroying:Connect(function()
                chatTargetSyncAlive = false
            end)
        end
        _G.CocoChatStopAll = function()
            stopNormalSpam()
            stopRoastSpam()
            if type(cocoSpam3StopFn) == "function" then pcall(cocoSpam3StopFn) end
        end
    end)()

    -- FOOTER UNWELD, MINIMIZE, SETTINGS DIALOG & KEYBINDS
    -- ═══════════════════════════════════════════════════════════════════════════
    btnUnweld.MouseButton1Click:Connect(function()
        playClick()
        stopWeld(false)
        StateManager:Cleanup(false, false)
        selectedPlayer = nil
        CurrentTarget = nil
        LastWeldTargetUserId = nil
        LastPresetKey = nil
        WeldIntent.typedUsername = ""
        WeldIntent.leftInfo = nil
        WeldIntent.waitingForSpawn = false
        if WeldIntent.setUsernameBoxText then pcall(WeldIntent.setUsernameBoxText, "") end
        footerLabel.Text = "Auto: Nearest"
        footerSub.Text = "stopped & disconnected"
        syncAllActiveIndicators()
        if refreshList then pcall(refreshList) end
        if refreshCard then pcall(refreshCard) end
        local reanimOnNow = (_G.CocaSkyDestroyer and (_G.CocaSkyDestroyer.isAnyActive() or _G.CocaSkyDestroyer.is_reanimated()))
